    if (value === undefined || value === null || value === '') {
        return '';
    }
    const num = Number(value);
    return !isNaN(num) ? num : '';
};

const TdCell: React.FC<{ 
    children?: React.ReactNode, 
    className?: string, 
    colSpan?: number, 
    rowSpan?: number, 
    text?: string 
}> = ({ children, className = '', colSpan, rowSpan, text }) => (
    <td 
        className={`border border-black dark:border-gray-600 p-0.5 text-center align-middle text-base font-medium ${className}`} // Text base for normal cells
        colSpan={colSpan} 
        rowSpan={rowSpan}
    >
        {children || text}
    </td>
);

const FormInput = React.forwardRef<HTMLInputElement | HTMLTextAreaElement, { 
    type: 'number' | 'text' | 'textarea', 
    name: string, 
    value: any, 
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void, 
    placeholder?: string, 
    'data-local-row': number,
    'data-local-col': number,
    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => void,
    readOnly?: boolean,
    className?: string
}>(({ type, name, value, onChange, placeholder, onKeyDown, readOnly, className = '', ...props }, ref) => {
    const handleFocus = (event: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => event.target.select();

    const finalPlaceholder = placeholder !== undefined ? placeholder : '';

    const commonProps = {
        ref,
        name,
        value: value || '',
        onChange,
        onFocus: handleFocus,
        onKeyDown,
        placeholder: readOnly ? '' : finalPlaceholder,
        readOnly,
        // Text lg for inputs
        className: `w-full h-full text-center outline-none border-none p-1 focus:bg-yellow-100 dark:focus:bg-yellow-900/50 text-lg font-bold dark:text-gray-200 ${readOnly ? 'bg-gray-100 dark:bg-gray-700' : 'bg-white dark:bg-gray-800'} ${className}`,
        autoComplete: 'off' as const,
        ...props
    };

    if (type === 'textarea') {
        return (
            <textarea
                {...commonProps}
                ref={ref as React.Ref<HTMLTextAreaElement>}
                rows={3}
                className={`${commonProps.className} resize-y`}
            />
        );
    }

    return (
        <input
            {...commonProps}
            ref={ref as React.Ref<HTMLInputElement>}
            type={type}
        />
    );
});

FormInput.displayName = 'FormInput';

const DisabledCell: React.FC<{ text?: string | number, className?: string }> = ({ text = '', className = '' }) => (
    <div className={`w-full h-full bg-gray-200 dark:bg-gray-700/50 flex items-center justify-center p-1 text-sm font-bold ${className}`}>
        {text}
    </div>
);

// --- Simple Rich Text Editor Component ---
const SimpleRichTextEditor: React.FC<{ value: string; onChange: (val: string) => void }> = ({ value, onChange }) => {
    const editorRef = useRef<HTMLDivElement>(null);

    const handleCommand = (command: string, value: string | undefined = undefined) => {
        document.execCommand(command, false, value);
        if (editorRef.current) {
            editorRef.current.focus();
            onChange(editorRef.current.innerHTML);
        }
    };

    const handleInput = () => {
        if (editorRef.current) {
            onChange(editorRef.current.innerHTML);
        }
    };

    useEffect(() => {
        if (editorRef.current && editorRef.current.innerHTML !== value) {
             if (document.activeElement !== editorRef.current) {
                 editorRef.current.innerHTML = value || '';
             }
        }
    }, [value]);

    return (
        <div className="border border-gray-300 dark:border-gray-600 rounded-md overflow-hidden bg-white dark:bg-gray-800 w-full h-full flex flex-col">
            <div className="flex gap-1 bg-gray-100 dark:bg-gray-700 p-1 border-b dark:border-gray-600 no-print">
                <button type="button" onClick={() => handleCommand('bold')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded font-bold" title="Bold">B</button>
                <button type="button" onClick={() => handleCommand('italic')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded italic" title="Italic">I</button>
                <button type="button" onClick={() => handleCommand('underline')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded underline" title="Underline">U</button>
                <div className="w-[1px] bg-gray-300 dark:bg-gray-500 mx-1"></div>
                <button type="button" onClick={() => handleCommand('insertUnorderedList')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded" title="Bullet List">• List</button>
                <button type="button" onClick={() => handleCommand('insertOrderedList')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded" title="Number List">1. List</button>
            </div>
            <div
                ref={editorRef}
                contentEditable
                className="p-2 outline-none flex-grow overflow-y-auto text-left min-h-[100px] text-base text-gray-800 dark:text-gray-200"
                onInput={handleInput}
                onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                        e.stopPropagation(); // Allow Enter to create new line, don't trigger form navigation
                    }
                }}
                style={{ direction: 'ltr' }}
            />
        </div>
    );
};

interface MonthlyEntryFormProps {
  institutionId?: number; // Made optional to handle Immunization Dept case where it's selected dynamically
  allowInstitutionSelection?: boolean; // New prop to enable dropdown
}

export const MonthlyEntryForm: React.FC<MonthlyEntryFormProps> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { reports, addReport, updateReport, users, setHasUnsavedChanges } = context;

    // Manage active institution ID locally (prop or selected from dropdown)
    const [activeInstitutionId, setActiveInstitutionId] = useState<number | undefined>(institutionId);

    // Dropdown search state
    const [instSearchTerm, setInstSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);

    // Track locally if an item was just deleted to prevent ghost reload
    const [justDeletedId, setJustDeletedId] = useState<number | null>(null);

    // Initial load sync
    useEffect(() => {
        if (!allowInstitutionSelection && institutionId) {
            setActiveInstitutionId(institutionId);
        }
    }, [institutionId, allowInstitutionSelection]);

    const activeInstitution = useMemo(() => users.find(u => u.id === activeInstitutionId), [users, activeInstitutionId]);

    const availableInstitutions = useMemo(() => {
        return users
            .filter(u => u.role === UserRole.INSTITUTION)
            .filter(u => isSmartMatch(u.name, instSearchTerm))
            .sort((a, b) => a.name.localeCompare(b.name, 'en'));
    }, [users, instSearchTerm]);

    // Select Month/Year State
    const now = new Date();
    // Default to previous month
    const [selectedYear, setSelectedYear] = useState<number>(() => {
        return now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
    });
    const [selectedMonth, setSelectedMonth] = useState<number>(() => {
        return now.getMonth() === 0 ? 12 : now.getMonth();
    });

    const [formData, setFormData] = useState<Record<string, string | number>>({});
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [activeTab, setActiveTab] = useState(1);
    const formRef = useRef<HTMLDivElement>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitMessage, setSubmitMessage] = useState<string | null>(null);

    const [hasUserTypedNumber, setHasUserTypedNumber] = useState(false);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [isFormLoaded, setIsFormLoaded] = useState(false);

    const autoCalculatedFields = useMemo(() => new Set([
        'target_population',
        'tp_bcg', 'tp_hbv1', 'tp_hexa1', 'tp_rota1', 'tp_pcv1',
        'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2',
        'tp_penta1', 'tp_opv2',
        'defaulter_incorrect_address',
        'defaulter_not_found',
        'defaulter_refused',
        'tp_fully_immunized',
// FIX: The properties 'count' and 'prefix' do not exist on elements of 'page2Groups'.
// Using 'items.length' and 'monthKey' to correctly reference the properties and resolve the error.
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length - 1 }, (_, i) => `${g.monthKey}_${i + 1}_target`)),
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length - 1 }, (_, i) => `${g.monthKey}_${i + 1}_vaccinated`))
    ]), []);

    const [confirmationModal, setConfirmationModal] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
    }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const currentReport = useMemo(() => {
        if (!activeInstitutionId) return undefined;
        return reports.find(r => r.institutionId === activeInstitutionId && r.year === selectedYear && r.month === selectedMonth);
    }, [reports, activeInstitutionId, selectedYear, selectedMonth]);

    // Calculate target month string
    const targetMonth = useMemo(() => {
        const reportingDate = new Date(selectedYear, selectedMonth - 1, 1);
        reportingDate.setMonth(reportingDate.getMonth() - 8);
        return `${MONTHS_AR[reportingDate.getMonth()]} ${reportingDate.getFullYear()}`;
    }, [selectedYear, selectedMonth]);

    // Check if the user has entered any data but not the recorder name
    const isNavigationBlocked = useMemo(() => {
        // Block if user has typed a number AND recorder name is missing
        return hasUserTypedNumber && !formData.recorder_name;
    }, [hasUserTypedNumber, formData.recorder_name]);

    // Update global unsaved changes state & protect against browser closing
    useEffect(() => {
        // Update global state for logout blocking
        setHasUnsavedChanges(isNavigationBlocked);

        // Native browser beforeunload event
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isNavigationBlocked) {
                const message = 'لديك بيانات غير محفوظة. الرجاء إدخال "اسم المُسجل" للحفظ قبل الخروج.';
                e.preventDefault();
                e.returnValue = message;
                return message;
            }
        };

        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isNavigationBlocked, setHasUnsavedChanges]);

    // Load initial data
    useEffect(() => {
        setIsFormLoaded(false);

        if (!activeInstitutionId) {
            setFormData({});
            setManuallyEditedFields(new Set());
            setHasUserTypedNumber(false);
            setIsFormLoaded(true);
            return;
        }

        if (justDeletedId && currentReport && currentReport.id === justDeletedId) return;
        if (justDeletedId && (!currentReport || currentReport.id !== justDeletedId)) setJustDeletedId(null);

        if (currentReport) {
            setFormData({
                ...currentReport,
                institution_name: activeInstitution?.name || '',
                target_month: currentReport.targetMonth || targetMonth,
                recorder_name: currentReport.entryPerson,
            });
            setManuallyEditedFields(new Set(currentReport.manuallyEditedFields || []));
            setHasUserTypedNumber(Object.keys(currentReport).length > 10);
        } else {
            setHasUserTypedNumber(false);
            setManuallyEditedFields(new Set()); 
            setFormData({
                institution_name: activeInstitution?.name || '',
                target_month: targetMonth,
                recorder_name: '',
            });
        }

        const timer = setTimeout(() => setIsFormLoaded(true), 0);
        return () => clearTimeout(timer);
    }, [currentReport, activeInstitution, targetMonth, activeInstitutionId, justDeletedId]);

    // Get all focusable inputs for navigation
    const getAllFocusableInputs = useCallback((): Array<HasDataset> => {
        if (!formRef.current) return [];

        const visibleContainer = activeTab === 1 ? 
            document.getElementById('page-1-content') : 
            document.getElementById('page-2-content');
        if (!visibleContainer) return [];

        const selector = 'input[data-local-row][data-local-col]:not([readonly]), textarea[data-local-row][data-local-col]:not([readonly])';
        let allInputs: Array<HasDataset> = 
            Array.from(visibleContainer.querySelectorAll(selector)) as Array<HasDataset>;

        allInputs.sort((a, b) => {
            const aRow = parseInt(a.dataset.localRow || '0');
            const aCol = parseInt(a.dataset.localCol || '0');
            const bRow = parseInt(b.dataset.localRow || '0');
            const bCol = parseInt(b.dataset.localCol || '0');

            if (activeTab === 2) {
                if (aRow !== bRow) return aRow - bRow;
                return aCol - bCol;
            }

            const aMajorColElement = a.closest('[data-major-col]');
            const aMajorCol = aMajorColElement ? 
                ((aMajorColElement as HasDataset).dataset.majorCol === 'left' ? 0 : 1) : -1;
            const bMajorColElement = b.closest('[data-major-col]');
            const bMajorCol = bMajorColElement ? 
                ((bMajorColElement as HasDataset).dataset.majorCol === 'left' ? 0 : 1) : -1;

            if (aMajorCol !== bMajorCol) return aMajorCol - bMajorCol;

            if (aMajorCol === 0) {
                if (aRow !== bRow) return aRow - bRow;
                return aCol - bCol;
            }

            if (aCol !== bCol) return aCol - bCol;
            return aRow - bRow;
        });

        return allInputs;
    }, [activeTab]);

    // Auto-calculate target population
    useEffect(() => {
        if (!isFormLoaded || manuallyEditedFields.has('target_population')) return;

        const totalOnRegister = normalizeValueForComparison(formData.total_on_register);
        const childrenDied = normalizeValueForComparison(formData.children_died);
        const childrenTransferred = normalizeValueForComparison(formData.children_transferred);
        const childrenLeftCountry = normalizeValueForComparison(formData.children_left_country);

        const newTargetPopulation = Math.max(0, 
            (typeof totalOnRegister === 'number' ? totalOnRegister : 0) - 
            (typeof childrenDied === 'number' ? childrenDied : 0) - 
            (typeof childrenTransferred === 'number' ? childrenTransferred : 0) - 
            (typeof childrenLeftCountry === 'number' ? childrenLeftCountry : 0)
        );

        if (normalizeValueForComparison(formData.target_population) !== newTargetPopulation) {
            setFormData(prev => ({ ...prev, target_population: newTargetPopulation }));
        }
    }, [
        isFormLoaded,
        formData.total_on_register, 
        formData.children_died, 
        formData.children_transferred, 
        formData.children_left_country,
        manuallyEditedFields
    ]);

    // Auto-fill vaccine targets
    useEffect(() => {
        if (!isFormLoaded) return;

        const totalOnRegister = normalizeValueForComparison(formData.total_on_register);
        const mainTarget = normalizeValueForComparison(formData.target_population);

        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;

            const birthKeys = ['tp_bcg', 'tp_hbv1'];
            birthKeys.forEach(key => {
                if (!manuallyEditedFields.has(key) && normalizeValueForComparison(updated[key]) !== totalOnRegister) {
                    updated[key] = totalOnRegister;
                    changed = true;
                }
            });

            const targetPopKeys = [
                'tp_hexa1', 'tp_rota1', 'tp_pcv1',
                'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2',
                'tp_penta1', 'tp_opv2'
            ];

            targetPopKeys.forEach(key => {
                if (!manuallyEditedFields.has(key) && normalizeValueForComparison(updated[key]) !== mainTarget) {
                    updated[key] = mainTarget;
                    changed = true;
                }
            });

            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    // Auto-fill defaulters and fully immunized
    useEffect(() => {
        if (!isFormLoaded) return;

        const mainTarget = normalizeValueForComparison(formData.target_population);
        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;

            const keysToSyncWithTarget = [
                'defaulter_incorrect_address',
                'defaulter_not_found',
                'defaulter_refused',
                'tp_fully_immunized'
            ];

            keysToSyncWithTarget.forEach(key => {
                if (!manuallyEditedFields.has(key) && normalizeValueForComparison(updated[key]) !== mainTarget) {
                    updated[key] = mainTarget;
                    changed = true;
                }
            });

            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData.target_population, manuallyEditedFields]);

    // Auto-fill group tables
    useEffect(() => {
        if (!isFormLoaded) return;

        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;

            const groups = [
                { prefix: '14m', count: 5 },
                { prefix: '20m', count: 4 },
                { prefix: '26m', count: 2 }
            ];

            groups.forEach(group => {
                const targetSource = normalizeValueForComparison(prev[`${group.prefix}_0_target`]);
                const vaccSource = normalizeValueForComparison(prev[`${group.prefix}_0_vaccinated`]);

                for (let i = 1; i < group.count; i++) {
                    const targetKey = `${group.prefix}_${i}_target`;
                    const vaccKey = `${group.prefix}_${i}_vaccinated`;

                    if (!manuallyEditedFields.has(targetKey) && normalizeValueForComparison(updated[targetKey]) !== targetSource) {
                        updated[targetKey] = targetSource;
                        changed = true;
                    }

                    if (!manuallyEditedFields.has(vaccKey) && normalizeValueForComparison(updated[vaccKey]) !== vaccSource) {
                        updated[vaccKey] = vaccSource;
                        changed = true;
                    }
                }
            });

            return changed ? updated : prev;
        });
    }, [
        isFormLoaded,
        formData['14m_0_target'], formData['14m_0_vaccinated'],
        formData['20m_0_target'], formData['20m_0_vaccinated'],
        formData['26m_0_target'], formData['26m_0_vaccinated'],
        manuallyEditedFields
    ]);

    // Auto-calculate Tdap totals
    useEffect(() => {
        if (!isFormLoaded) return;

        const tOmani = Number(formData.p4_tdap_target_omani_pregnant || 0);
        const tNon = Number(formData.p4_tdap_target_non_omani_pregnant || 0);
        const gOmani = Number(formData.p4_tdap_given_omani_pregnant || 0);
        const gNon = Number(formData.p4_tdap_given_non_omani_pregnant || 0);

        setFormData(prev => {
            const updated = {...prev};
            let changed = false;

            if (updated.p4_tdap_target_total_pregnant !== tOmani + tNon) { 
                updated.p4_tdap_target_total_pregnant = tOmani + tNon; 
                changed = true; 
            }

            if (updated.p4_tdap_given_total_pregnant !== gOmani + gNon) { 
                updated.p4_tdap_given_total_pregnant = gOmani + gNon; 
                changed = true; 
            }

            return changed ? updated : prev;
        });
    }, [
        isFormLoaded,
        formData.p4_tdap_target_omani_pregnant, 
        formData.p4_tdap_target_non_omani_pregnant,
        formData.p4_tdap_given_omani_pregnant, 
        formData.p4_tdap_given_non_omani_pregnant
    ]);

    // Auto-calculate Influenza totals and Coverage with %
    useEffect(() => {
        if (!isFormLoaded) return;

        setFormData(prev => {
            const updated = {...prev};
            let changed = false;

            influenzaCriteria.forEach((_, idx) => {
                const tO = Number(updated[`p4_flu_target_omani_${idx}`] || 0);
                const tN = Number(updated[`p4_flu_target_non_omani_${idx}`] || 0);
                const gO = Number(updated[`p4_flu_given_omani_${idx}`] || 0);
                const gN = Number(updated[`p4_flu_given_non_omani_${idx}`] || 0);

                const totalTarget = tO + tN;
                const totalGiven = gO + gN;

                if (updated[`p4_flu_target_total_${idx}`] !== totalTarget) { 
                    updated[`p4_flu_target_total_${idx}`] = totalTarget; 
                    changed = true; 
                }

                if (updated[`p4_flu_given_total_${idx}`] !== totalGiven) { 
                    updated[`p4_flu_given_total_${idx}`] = totalGiven; 
                    changed = true; 
                }

                // Coverage Calculation with %
                let coverage = '';
                if (totalTarget > 0) {
                    coverage = ((totalGiven / totalTarget) * 100).toFixed(1) + '%';
                }

                if (updated[`p4_flu_coverage_${idx}`] !== coverage) {
                    updated[`p4_flu_coverage_${idx}`] = coverage;
                    changed = true;
                }
            });

            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    // Used Vials Auto-Calculation
    useEffect(() => {
        if (!isFormLoaded) return;

        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;

            usedVialsVaccines.forEach(v => {
                const mono = Number(prev[`p4_used_vials_${v}_0`] || 0);
                const dose10 = Number(prev[`p4_used_vials_${v}_1`] || 0);
                const dose20 = Number(prev[`p4_used_vials_${v}_2`] || 0);
                const sum = (mono * 1) + (dose10 * 10) + (dose20 * 20);

                if (sum > 0) {
                    const targetKey = `p4_used_vials_doses_used_${v}`;
                    if (updated[targetKey] !== sum) {
                        updated[targetKey] = sum;
                        changed = true;
                    }
                }
            });

            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;

        if (autoCalculatedFields.has(name)) {
            setManuallyEditedFields(prev => new Set(prev).add(name));
        }

        if ((e.target as HTMLInputElement).type === 'number' && value.trim() !== '') {
            setHasUserTypedNumber(true);
        }
        setFormData(prev => ({ 
            ...prev, 
            [name]: type === 'number' ? normalizeValueForComparison(value) : value 
        }));
        setSaveStatus('idle');
    };

    // Auto-Save Logic using AppContext (Fixed for Delete)
    useEffect(() => {
        if (justDeletedId) return;

        const timer = setTimeout(() => {
            if (saveStatus === 'idle' && Object.keys(formData).length > 3 && activeInstitutionId && formData.recorder_name) {
                setSaveStatus('saving');

                if (currentReport) {
                    const reportToSave: MonthlyReport = {
                        id: currentReport.id,
                        institutionId: activeInstitutionId,
                        year: selectedYear,
                        month: selectedMonth,
                        entryPerson: formData.recorder_name as string || '',
                        updatedAt: Date.now(),
                        targetMonth,
                        ...formData,
                        manuallyEditedFields: Array.from(manuallyEditedFields)
                    };
                    updateReport(reportToSave);
                } else {
                    const reportToSave: Omit<MonthlyReport, 'id' | 'updatedAt'> = {
                        institutionId: activeInstitutionId,
                        year: selectedYear,
                        month: selectedMonth,
                        entryPerson: formData.recorder_name as string || '',
                        targetMonth,
                        ...formData,
                        manuallyEditedFields: Array.from(manuallyEditedFields)
                    };
                    addReport(reportToSave);
                }

                setSaveStatus('saved');
            }
        }, 2000);

        return () => clearTimeout(timer);
    }, [formData, saveStatus, currentReport, addReport, updateReport, activeInstitutionId, selectedYear, selectedMonth, targetMonth, justDeletedId, manuallyEditedFields]);

    const handleInputKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const currentTarget = e.target as HasDataset;
            const inputs = getAllFocusableInputs();
            const currentIndex = inputs.indexOf(currentTarget);

            if (currentIndex === -1) return;

            const nextInput = inputs[currentIndex + 1] || inputs[0];
            if (nextInput) {
                nextInput.focus();
            }
        }
    }, [getAllFocusableInputs]);

    const handleExportExcel = () => {
        const data = { 
            ...formData, 
            institution_name: activeInstitution?.name, 
            reporting_month: `${MONTHS_AR[selectedMonth - 1]} ${selectedYear}` 
        };

        const ws = XLSX.utils.json_to_sheet([data]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, `Report`);
        XLSX.writeFile(wb, `EPI_${activeInstitution?.name}_${selectedMonth}_${selectedYear}.xlsx`);
    };

    const handlePrint = () => {
        const originalPage1Content = document.getElementById('page-1-content');
        const originalPage2Content = document.getElementById('page-2-content');

        if (!originalPage1Content || !originalPage2Content) return;

        const createPrintableClone = (sourceId: string) => {
            const source = document.getElementById(sourceId);
            if (!source) return null;

            const clone = source.cloneNode(true) as HTMLElement;
            clone.style.display = 'block'; 

            const sourceInputs = source.querySelectorAll('input, textarea, select');
            const cloneInputs = clone.querySelectorAll('input, textarea, select');

            for(let i=0; i<sourceInputs.length; i++) {
                const s = sourceInputs[i] as HTMLInputElement;
                const c = cloneInputs[i] as HTMLInputElement;

                const span = document.createElement('span');
