    if (selectedInstitutionId !== 'all') {
        list = list.filter(u => u.id.toString() === selectedInstitutionId);
    }
    return list;
  }, [users, selectedState, selectedInstitutionId]);

  const aggregatedData = useMemo(() => {
    const targetInstitutions = getFilteredInstitutions;
    const states = Array.from(new Set(targetInstitutions.map(u => u.state).filter(s => s))).sort();
    if (targetInstitutions.some(u => !u.state)) states.push('Unspecified');
    const dataRows: any[] = [];
    const createEmptyRow = () => ({
        totalPopulation: 0, total_on_register: 0, target_population: 0,
        tp_bcg: 0, tp_opv1: 0, tp_opv2: 0, tp_hexa1: 0, tp_hexa2: 0, tp_penta1: 0, tp_pcv1: 0, tp_rota1: 0, tp_rota2: 0, tp_pcv2: 0,
        '14m_0_target': 0, '14m_1_vaccinated': 0, '14m_0_vaccinated': 0, '14m_2_vaccinated': 0,
        '14m_3_target': 0, '14m_3_vaccinated': 0, '14m_4_vaccinated': 0,
        '20m_0_target': 0, '20m_0_vaccinated': 0, '20m_3_vaccinated': 0, '20m_2_vaccinated': 0, '20m_1_vaccinated': 0,
        '26m_0_target': 0, '26m_1_vaccinated': 0, '26m_0_vaccinated': 0
    });
    let grandTotals: any = createEmptyRow();
    states.forEach(state => {
        const stateInstitutions = targetInstitutions.filter(u => (u.state || 'Unspecified') === state);
        const stateInstIds = stateInstitutions.map(u => u.id);
        const stateReports = reports.filter(r => 
            stateInstIds.includes(r.institutionId) &&
            r.year === parseInt(selectedYear) &&
            selectedMonths.includes(r.month)
        );
        const statePopulation = stateInstitutions.reduce((sum, inst) => sum + (inst.population?.[parseInt(selectedYear)] || 0), 0);
        const row: any = { stateName: state, ...createEmptyRow(), totalPopulation: statePopulation };
        stateReports.forEach(r => {
            row.total_on_register += Number(r.total_on_register || 0);
            row.target_population += Number(r.target_population || 0);
            ['tp_bcg', 'tp_opv1', 'tp_opv2', 'tp_hexa1', 'tp_hexa2', 'tp_penta1', 'tp_pcv1', 'tp_rota1', 'tp_rota2', 'tp_pcv2'].forEach(k => {
                row[k] += Number(r[k] || 0);
            });
            ['14m_0_target', '14m_1_vaccinated', '14m_0_vaccinated', '14m_2_vaccinated', '14m_3_target', '14m_3_vaccinated', '14m_4_vaccinated',
             '20m_0_target', '20m_0_vaccinated', '20m_3_vaccinated', '20m_2_vaccinated', '20m_1_vaccinated',
             '26m_0_target', '26m_1_vaccinated', '26m_0_vaccinated'
            ].forEach(k => { row[k] += Number(r[k] || 0); });
        });
        Object.keys(grandTotals).forEach(key => { grandTotals[key] += row[key]; });
        dataRows.push(row);
    });
    return { rows: dataRows, totals: grandTotals };
  }, [getFilteredInstitutions, reports, selectedYear, selectedMonths]);

  const influenzaAggregatedData = useMemo(() => {
        const targetInstIds = getFilteredInstitutions.map(u => u.id);
        const filteredReports = reports.filter(r =>
            targetInstIds.includes(r.institutionId) &&
            r.year === parseInt(selectedYear) &&
            selectedMonths.includes(r.month)
        );
        return influenzaCriteria.map((label, idx) => {
            let tOmani = 0, tNon = 0, gOmani = 0, gNon = 0;
            filteredReports.forEach(r => {
                tOmani += Number(r[`p4_flu_target_omani_${idx}`] || 0);
                tNon += Number(r[`p4_flu_target_non_omani_${idx}`] || 0);
                gOmani += Number(r[`p4_flu_given_omani_${idx}`] || 0);
                gNon += Number(r[`p4_flu_given_non_omani_${idx}`] || 0);
            });
            const tTotal = tOmani + tNon;
            const gTotal = gOmani + gNon;
            const percent = tTotal > 0 ? Math.round((gTotal / tTotal) * 100) : 0;
            return { label, tOmani, tNon, tTotal, gOmani, gNon, gTotal, percent };
        });
  }, [getFilteredInstitutions, reports, selectedYear, selectedMonths]);

  const tdapAggregatedData = useMemo(() => {
        const targetInstIds = getFilteredInstitutions.map(u => u.id);
        const filteredReports = reports.filter(r =>
            targetInstIds.includes(r.institutionId) &&
            r.year === parseInt(selectedYear) &&
            selectedMonths.includes(r.month)
        );
        let tOmani = 0, tNon = 0, gOmani = 0, gNon = 0, pregnantCol1Total = 0;
        filteredReports.forEach(r => {
            tOmani += Number(r.p4_tdap_target_omani_pregnant || 0);
            tNon += Number(r.p4_tdap_target_non_omani_pregnant || 0);
            gOmani += Number(r.p4_tdap_given_omani_pregnant || 0);
            gNon += Number(r.p4_tdap_given_non_omani_pregnant || 0);
            pregnantCol1Total += Number(r.p4_tdap_pregnant_col1 || 0);
        });
        return { label: 'Pregnant', pregnantCol1Total, tOmani, tNon, tTotal: tOmani + tNon, gOmani, gNon, gTotal: gOmani + gNon };
  }, [getFilteredInstitutions, reports, selectedYear, selectedMonths]);

  const otherEpiAggregatedData = useMemo(() => {
    const targetInstIds = getFilteredInstitutions.map(u => u.id);
    const filteredReports = reports.filter(r =>
        targetInstIds.includes(r.institutionId) &&
        r.year === parseInt(selectedYear) &&
        selectedMonths.includes(r.month)
    );
    const result: any = { admin: {}, usable: {}, doses: {} };
    otherEpiColumnInputKeys.forEach(k => { result.admin[k] = 0; result.usable[k] = 0; result.doses[k] = 0; });
    filteredReports.forEach(r => {
        otherEpiColumnInputKeys.forEach(k => {
            result.admin[k] += Number(r[`p4_other_${k}_admin`] || 0);
            result.usable[k] += Number(r[`p4_other_${k}_usable`] || 0);
            result.doses[k] += Number(r[`p4_other_${k}_doses`] || 0);
        });
    });
    return result;
  }, [getFilteredInstitutions, reports, selectedYear, selectedMonths]);

  const calcPerc = (num: number, den: number) => (!den || den === 0) ? 0 : Math.round((num / den) * 100);

  const renderDataCells = (data: any, isTotal: boolean = false) => {
      const cellClass = `border border-gray-400 p-1 text-center text-[10px] sm:text-xs ${isTotal ? 'font-bold bg-green-total theme-green-light' : 'bg-white dark:bg-gray-800'}`;
      const highlightClass = `border border-gray-400 p-1 text-center text-[10px] sm:text-xs bg-yellow-highlight dark:bg-yellow-900/10`;
      const renderPair = (numKey: string, denKey: string) => {
          const num = data[numKey];
          const den = data[denKey];
          const perc = calcPerc(num, den);
          return (
              <React.Fragment key={numKey}>
                  <td className={cellClass}>{num}</td>
                  <td className={`${cellClass} ${perc > 100 ? 'text-red-600 font-bold' : 'text-blue-700 font-bold'}`}>{perc}%</td>
              </React.Fragment>
          );
      };
      return (
          <>
              {isTotal && <td className="border border-gray-400 p-2 font-bold bg-green-total theme-green-light text-center">TOTAL</td>}
              <td className={cellClass}>{data.totalPopulation.toLocaleString()}</td>
              <td className={cellClass}>{data.total_on_register}</td>
              <td className={cellClass}>{data.target_population}</td>
              {renderPair('tp_bcg', 'total_on_register')}
              {renderPair('tp_opv1', 'target_population')}
              {renderPair('tp_opv2', 'target_population')}
              {renderPair('tp_hexa1', 'target_population')}
              {renderPair('tp_hexa2', 'target_population')}
              {renderPair('tp_penta1', 'target_population')}
              {renderPair('tp_pcv1', 'target_population')}
              {renderPair('tp_rota1', 'target_population')}
              {renderPair('tp_rota2', 'target_population')}
              {renderPair('tp_pcv2', 'target_population')}
              <td className={highlightClass}>{data['14m_0_target']}</td>
              {renderPair('14m_1_vaccinated', '14m_0_target')}
              {renderPair('14m_0_vaccinated', '14m_0_target')}
              {renderPair('14m_2_vaccinated', '14m_0_target')}
              <td className={highlightClass}>{data['14m_3_target']}</td>
              {renderPair('14m_3_vaccinated', '14m_3_target')}
              {renderPair('14m_4_vaccinated', '14m_3_target')}
              <td className={highlightClass}>{data['20m_0_target']}</td>
              {renderPair('20m_0_vaccinated', '20m_0_target')}
              {renderPair('20m_3_vaccinated', '20m_0_target')}
              {renderPair('20m_2_vaccinated', '20m_0_target')}
              {renderPair('20m_1_vaccinated', '20m_0_target')}
              <td className={highlightClass}>{data['26m_0_target']}</td>
              {renderPair('26m_1_vaccinated', '26m_0_target')}
              {renderPair('26m_0_vaccinated', '26m_0_target')}
          </>
      );
  };

  return (
    <div className="bg-white p-4 sm:p-6 rounded-2xl shadow-xl dark:bg-gray-800 border border-gray-100 dark:border-gray-700" ref={containerRef}>
      <div className="no-print space-y-6 mb-6">
          <div className="flex flex-col sm:flex-row justify-between items-center gap-4 border-b pb-4 dark:border-gray-700">
            <h3 className="text-xl font-bold text-green-900 dark:text-green-300">Reports</h3>
            <div className="flex gap-2">
                <button onClick={handleExportExcel} className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition">Export Excel</button>
                <button onClick={handlePrint} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition">Print Preview / PDF</button>
            </div>
          </div>
          <div className="bg-gray-50 dark:bg-gray-700 p-4 rounded-xl border border-gray-200 dark:border-gray-600">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-4">
                  <div>
                      <label className="block text-xs font-bold text-gray-500 mb-1">Year</label>
                      <select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)} className="input-style py-1 text-sm">
                          {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                      </select>
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-500 mb-1">State / Wilayah</label>
                      <select value={selectedState} onChange={(e) => { setSelectedState(e.target.value); setSelectedInstitutionId('all'); }} className="input-style py-1 text-sm">
                          <option value="all">All Willayats</option>
                          {availableStates.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-gray-500 mb-1">Institution</label>
                      <select value={selectedInstitutionId} onChange={(e) => setSelectedInstitutionId(e.target.value)} className="input-style py-1 text-sm">
                          <option value="all">All Institutions</option>
                          {users
                            .filter(u => u.role === UserRole.INSTITUTION && (selectedState === 'all' || u.state === selectedState))
                            .sort((a,b) => a.name.localeCompare(b.name, 'en'))
                            .map(u => (
                              <option key={u.id} value={u.id}>{u.name}</option>
                          ))}
                      </select>
                  </div>
                  <div className="lg:col-span-2">
                      <label className="block text-xs font-bold text-gray-500 mb-1">Timeframe Mode</label>
                      <div className="flex bg-white dark:bg-gray-800 rounded-lg border border-gray-300 dark:border-gray-600 p-1">
                          <button onClick={() => setTimeframeMode('months')} className={`flex-1 py-1 text-xs font-bold rounded ${timeframeMode === 'months' ? 'bg-green-100 text-green-800' : 'text-gray-500'}`}>Monthly</button>
                          <button onClick={() => setTimeframeMode('quarters')} className={`flex-1 py-1 text-xs font-bold rounded ${timeframeMode === 'quarters' ? 'bg-green-100 text-green-800' : 'text-gray-500'}`}>Quarterly</button>
                          <button onClick={() => setTimeframeMode('halves')} className={`flex-1 py-1 text-xs font-bold rounded ${timeframeMode === 'halves' ? 'bg-green-100 text-green-800' : 'text-gray-500'}`}>Half-Yearly</button>
                      </div>
                  </div>
              </div>

              <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-600">
                  <div className="flex items-center justify-between mb-3">
                      <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider">Select Period(s):</label>
                      {timeframeMode === 'months' && (
                          <div className="flex gap-2">
                              <button onClick={selectAllMonths} className="px-3 py-1 bg-green-50 text-green-700 border border-green-200 rounded text-[10px] font-bold hover:bg-green-100 transition-colors">Select All</button>
                              <button onClick={clearAllMonths} className="px-3 py-1 bg-gray-50 text-gray-700 border border-gray-200 rounded text-[10px] font-bold hover:bg-gray-100 transition-colors">Clear All</button>
                          </div>
                      )}
                  </div>

                  {timeframeMode === 'months' && (
                      <div className="flex flex-wrap gap-2 animate-fade-in">
                          {ENGLISH_MONTHS.map((m, idx) => (
                              <button key={idx} onClick={() => toggleMonth(idx + 1)} className={`px-3 py-1.5 rounded-md text-xs font-bold border transition-colors ${selectedMonths.includes(idx + 1) ? 'bg-green-600 text-white border-green-700' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-100'}`}>{m}</button>
                          ))}
                      </div>
                  )}
                  {timeframeMode === 'quarters' && (
                      <div className="flex gap-3 animate-fade-in">
                          {QUARTERS.map(q => (
                              <button key={q.id} onClick={() => selectQuarter(q.id)} className={`flex-1 py-2 rounded-lg text-sm font-bold border transition-all ${JSON.stringify(selectedMonths) === JSON.stringify(q.months) ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-100'}`}>{q.label}</button>
                          ))}
                      </div>
                  )}
                  {timeframeMode === 'halves' && (
                      <div className="flex gap-4 animate-fade-in">
                          {HALVES.map(h => (
                              <button key={h.id} onClick={() => selectHalf(h.id)} className={`flex-1 py-3 rounded-lg text-sm font-bold border transition-all ${JSON.stringify(selectedMonths) === JSON.stringify(h.months) ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-100'}`}>{h.label}</button>
                          ))}
                      </div>
                  )}
              </div>
          </div>
      </div>

      <div id="print-wrapper" className="space-y-10">
        {/* Main EPI Report */}
        <div className="overflow-x-auto rounded-xl border border-gray-400 dark:border-gray-600 shadow-sm" id="epi-report-container">
            <table id="epi-report-table" className="min-w-full border-collapse border border-gray-400 dark:border-gray-600 text-[9px]">
            <thead>
                <tr>
                    <th colSpan={51} className="border border-gray-400 p-3 text-lg font-bold text-center theme-green-header bg-emerald-800 text-white dark:bg-green-900 uppercase tracking-widest">
                        Main EPI Report
                    </th>
                </tr>
                <tr className="theme-green-header bg-emerald-800 text-white dark:bg-green-900">
                    <th rowSpan={2} className="border border-gray-400 p-2 w-24">DISTRICT</th>
                    <th rowSpan={2} className="border border-gray-400 p-1">Total Pop.</th>
                    <th rowSpan={2} className="border border-gray-400 p-1 w-20">Live Birth</th>
                    <th rowSpan={2} className="border border-gray-400 p-1 w-20">Surv. Infants</th>
                    {['BCG','OPV1','OPV2','Hexa 1','Hexa 2','Penta 3','PCV-1','Rota 1','Rota 2','PCV-2'].map(v => (
                        <th key={v} colSpan={2} className="border border-gray-400 p-1">{v}</th>
                    ))}
                    <th rowSpan={2} className="border border-gray-400 p-1 theme-green-sub bg-emerald-600 dark:bg-green-800">MMR1 Tgt</th>
                    <th colSpan={2} className="border border-gray-400 p-1">Varic.</th>
                    <th colSpan={2} className="border border-gray-400 p-1">MMR1</th>
                    <th colSpan={2} className="border border-gray-400 p-1">Vit.A1</th>
                    <th rowSpan={2} className="border border-gray-400 p-1 theme-green-sub bg-emerald-600 dark:bg-green-800">PCV Tgt</th>
                    <th colSpan={2} className="border border-gray-400 p-1">PCV B.</th>
                    <th colSpan={2} className="border border-gray-400 p-1">Penta B.</th>
                    <th rowSpan={2} className="border border-gray-400 p-1 theme-green-sub bg-emerald-600 dark:bg-green-800">MMR2 Tgt</th>
                    <th colSpan={2} className="border border-gray-400 p-1">MMR-2</th>
                    <th colSpan={2} className="border border-gray-400 p-1">Vit.A2</th>
                    <th colSpan={2} className="border border-gray-400 p-1">OPV B.</th>
                    <th colSpan={2} className="border border-gray-400 p-1">HAV-1</th>
                    <th rowSpan={2} className="border border-gray-400 p-1 theme-green-sub bg-emerald-600 dark:bg-green-800">HepA2 Tgt</th>
                    <th colSpan={2} className="border border-gray-400 p-1">Flu</th>
                    <th colSpan={2} className="border border-gray-400 p-1">HepA2</th>
                </tr>
                <tr className="theme-green-header bg-emerald-800 text-white dark:bg-green-900">
                {Array.from({ length: 21 }).map((_, i) => (
                    <React.Fragment key={i}>
                        <th className="border border-gray-400 p-0.5 min-w-[20px] theme-green-light bg-emerald-100 text-black">V</th>
                        <th className="border border-gray-400 p-0.5 min-w-[20px] theme-green-light bg-emerald-100 text-black">%</th>
                    </React.Fragment>
                ))}
                </tr>
            </thead>
            <tbody>
                {aggregatedData.rows.map((row: any) => (
                <tr key={row.stateName}>
                    <td className="border border-gray-400 p-1 font-bold text-center bg-gray-label dark:bg-gray-800 dark:text-white">{row.stateName}</td>
                    {renderDataCells(row)}
                </tr>
                ))}
                <tr className="bg-green-total theme-green-light bg-emerald-100 dark:bg-green-900 border-t-2 border-black">
                    {renderDataCells(aggregatedData.totals, true)}
                </tr>
            </tbody>
            </table>
        </div>

        {/* Influenza doses report - Centered Container, Table Fills Container */}
        <div className="w-full max-w-5xl mx-auto overflow-x-auto rounded-xl border border-gray-300 dark:border-gray-600 shadow-sm" id="flu-report-container">
            <table id="flu-report-table" className="w-full border-collapse border-none text-xs table-fixed">
                <colgroup>
                    {Array.from({ length: 8 }).map((_, i) => (
                        <col key={i} style={{ width: '12.5%' }} />
                    ))}
                </colgroup>
                <thead>
                    <tr>
                        <th colSpan={8} className="theme-orange-header bg-orange-700 dark:bg-orange-800 p-2 border-b border-black font-bold text-white text-lg text-center uppercase tracking-wide">
                            Influenza doses given in the reporting month
                        </th>
                    </tr>
                    <tr>
                        <th rowSpan={2} className="theme-orange-sub bg-orange-200 dark:bg-orange-900/50 p-1 border-r border-b border-black font-bold text-black dark:text-gray-200 text-center align-middle">Criteria</th>
                        <th colSpan={3} className="theme-orange-sub bg-orange-200 dark:bg-orange-900/50 p-1 border-r border-b border-black font-bold text-black dark:text-gray-200 text-center">Target</th>
                        <th colSpan={3} className="theme-orange-sub bg-orange-200 dark:bg-orange-900/50 p-1 border-r border-b border-black font-bold text-black dark:text-gray-200 text-center">Doses Given</th>
                        <th rowSpan={2} className="theme-orange-sub bg-orange-200 dark:bg-orange-900/50 p-1 border-b border-black font-bold text-black dark:text-gray-200 align-middle text-center">Cov %</th>
                    </tr>
                    <tr>
                        <th className="theme-orange-light bg-orange-50 dark:bg-orange-900/30 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Omani</th>
                        <th className="theme-orange-light bg-orange-50 dark:bg-orange-900/30 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Non-Omani</th>
                        <th className="theme-orange-sub bg-orange-200 dark:bg-orange-800 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Total</th>
                        <th className="theme-orange-light bg-orange-50 dark:bg-orange-900/30 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Omani</th>
                        <th className="theme-orange-light bg-orange-50 dark:bg-orange-900/30 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Non-Omani</th>
                        <th className="theme-orange-sub bg-orange-200 dark:bg-orange-800 border-r border-b border-black font-bold text-black dark:text-gray-200 text-[10px] p-0.5 text-center">Total</th>
                    </tr>
                </thead>
                <tbody>
                    {influenzaAggregatedData.map((row, index) => (
                        <tr key={index} className="bg-white dark:bg-gray-800">
                            <td className="border-r border-b border-black p-1 font-bold text-black dark:text-white text-center">{row.label}</td>
                            <td className="border-r border-b border-black p-1 text-center dark:text-gray-200">{row.tOmani}</td>
                            <td className="border-r border-b border-black p-1 text-center dark:text-gray-200">{row.tNon}</td>
                            <td className="border-r border-b border-black p-1 text-center font-bold bg-gray-label dark:bg-gray-700 dark:text-white">{row.tTotal}</td>
                            <td className="border-r border-b border-black p-1 text-center dark:text-gray-200">{row.gOmani}</td>
                            <td className="border-r border-b border-black p-1 text-center dark:text-gray-200">{row.gNon}</td>
                            <td className="border-r border-b border-black p-1 text-center font-bold bg-gray-label dark:bg-gray-700 dark:text-white">{row.gTotal}</td>
                            <td className={`border-b border-black p-1 text-center font-bold ${row.percent >= 100 ? 'text-green-700' : 'text-blue-700'}`}>{row.percent}%</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>

        {/* T-dap doses report - Centered Container, Table Fills Container */}
        <div className="w-full max-w-3xl mx-auto overflow-x-auto rounded-xl border border-gray-300 dark:border-gray-600 shadow-sm" id="tdap-report-container">
            <table id="tdap-report-table" className="w-full border-collapse border-none text-xs table-fixed">
                <colgroup>
                    {Array.from({ length: 7 }).map((_, i) => (
                        <col key={i} style={{ width: `${100 / 7}%` }} />
                    ))}
                </colgroup>
                <thead>
                    <tr>
                        <th colSpan={7} className="theme-blue-header bg-blue-800 dark:bg-blue-800 p-2 border-b border-black font-bold text-white text-lg text-center uppercase tracking-wide">
                            T-dap doses given in the reporting month
                        </th>
                    </tr>
                    <tr>
