import React, { useState, createContext, useEffect, useCallback } from 'react';
import { User, MonthlyReport, UserRole, FullBackupData, DeletedItem, Student, Halaqa, Evaluation, MaghribAttendance } from './types';
import { INITIAL_USERS, DEFAULT_APP_NAME, CURRENT_USER_KEY } from './constants';
import LoginScreen from './components/LoginScreen';
import SupervisorDashboard from './components/SupervisorDashboard';
import InstitutionDashboard from './components/InstitutionDashboard';
import { ImmunizationDashboard } from './components/ImmunizationDashboard';
import Header from './components/Header';
import { HelpModal } from './components/HelpModal';
import MobileInstallModal from './components/MobileInstallModal';
import ChangePasswordModal from './components/ChangePasswordModal';
import { initializeFirebase, getDb, disconnectFirebase, HARDCODED_FIREBASE_CONFIG } from './utils/firebase';
import { FirebaseSetupWizard } from './components/FirebaseSetupWizard';

interface AppContextType {
  users: User[];
  reports: MonthlyReport[];
  addReport: (report: Omit<MonthlyReport, 'id' | 'updatedAt'>) => void;
  updateReport: (report: MonthlyReport) => void;
  deleteReport: (reportId: number) => void;
  deleteAllReports: () => Promise<void>;
  deleteAllData: () => Promise<void>;
  loadMockData: () => void;
  customLogo: string | null;
  setCustomLogo: (logo: string | null) => void;
  addInstitution: (name: string, state?: string, population?: { [year: number]: number }) => void;
  updateInstitution: (institution: User) => void;
  deleteInstitution: (institutionId: number) => void;
  importFullBackup: (data: FullBackupData) => void;
  supervisorPassword: string;
  setSupervisorPassword: (password: string) => void;
  logout: () => void;
  isLoading: boolean;
  initiateLogoutCheck: () => void;
  appName: string;
  setAppName: (name: string) => void;
  darkMode: boolean;
  toggleDarkMode: () => void;
  firebaseConnectionStatus: 'connected' | 'disconnected' | 'error' | 'connecting';
  firebaseConfig: any;
  setFirebaseConfig: (config: any) => void;
  isDistributable: boolean;
  isPublishedConnected: boolean;
  currentUser: User | null;

  students: Student[];
  halaqas: Halaqa[];
  evaluations: Evaluation[];
  updateEvaluation: (e: any) => void;
  deleteEvaluation: (id: number) => void;
  addEvaluation: (e: any) => void;
  setLastUsedWeek: (week: number | null) => void;

  maghribAttendances: MaghribAttendance[];
  addMaghribAttendance: (att: any) => void;
  deleteMaghribAttendance: (id: number) => void;
  maghribPassword: string;
  setMaghribPassword: (p: string) => void;

  immunizationPassword: string;
  setImmunizationPassword: (p: string) => void;

  setHasUnsavedChanges: (hasChanges: boolean) => void;
}

export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          return savedUser ? JSON.parse(savedUser) : null;
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS, 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);
  const [lastUsedWeek, setLastUsedWeek] = useState<number | null>(null);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const getNextId = (collection: any[], startingId: number = 1) => {
      if (!collection || collection.length === 0) {
          return startingId;
      }
      const maxId = collection.reduce((max, item) => (item.id > max ? item.id : max), 0);
      return Math.max(maxId + 1, startingId);
  };

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).embeddedAppData) {
       try {
           loadedConfig = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob((window as any).embeddedAppData), c => c.charCodeAt(0))));
       } catch(e) { console.error("Failed to parse embedded data", e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: loadedConfig.users || INITIAL_USERS,
        reports: loadedConfig.reports || [],
        students: loadedConfig.students || [],
        halaqas: loadedConfig.halaqas || [],
        evaluations: loadedConfig.evaluations || [],
        maghribAttendances: loadedConfig.maghribAttendances || [],
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setMaghribPasswordState(loadedConfig.maghribPassword || '123456');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          if (loadedConfig.firebaseConfig) {
              setFirebaseConfigState(loadedConfig.firebaseConfig);
          } else {
              setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
          }
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: data.students,
            halaqas: data.halaqas,
            evaluations: data.evaluations,
            maghribAttendances: data.maghribAttendances,
            customLogo, supervisorPassword, maghribPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, maghribPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            setData({
              users: val.users ? Object.values(val.users) : INITIAL_USERS,
              reports: val.reports ? Object.values(val.reports) : [],
              students: val.students ? Object.values(val.students) : [],
              halaqas: val.halaqas ? Object.values(val.halaqas) : [],
              evaluations: val.evaluations ? Object.values(val.evaluations) : [],
              maghribAttendances: val.maghribAttendances ? Object.values(val.maghribAttendances) : [],
              deletedItems: [],
            });
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.maghribPassword) setMaghribPasswordState(val.maghribPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    if (firebaseConnectionStatus !== 'connected') {
        const updateLocalData = (collection: keyof typeof data, item: any, isDelete: boolean = false) => {
             setData(prev => {
                 const list = prev[collection] as any[];
                 if (isDelete) {
                     return { ...prev, [collection]: list.filter(i => i.id !== item.id) };
                 }
                 const index = list.findIndex(i => i.id === item.id);
                 if (index >= 0) {
                     const newList = [...list];
                     newList[index] = item;
                     return { ...prev, [collection]: newList };
                 } else {
                     return { ...prev, [collection]: [...list, item] };
                 }
             });
        };

        if (path.startsWith('data/reports/')) {
            const id = parseInt(path.split('/').pop()!);
            if (value === null) updateLocalData('reports', { id }, true);
            else updateLocalData('reports', value);
        } else if (path.startsWith('data/users/')) {
            const id = parseInt(path.split('/').pop()!);
            if (value === null) updateLocalData('users', { id }, true);
            else updateLocalData('users', value);
        }
    }
  };

  const addReport = (rep: any) => {
      const newId = getNextId(data.reports);
      writeData(`data/reports/${newId}`, { ...rep, id: newId, updatedAt: Date.now() });
  };
  const updateReport = (rep: any) => writeData(`data/reports/${rep.id}`, { ...rep, updatedAt: Date.now() });
  const deleteReport = (id: number) => writeData(`data/reports/${id}`, null);

  const addInstitution = (n: string, state?: string, population?: { [year: number]: number }) => {
      const newId = getNextId(data.users, 2); // Supervisor is 1
      writeData(`data/users/${newId}`, { 
          id: newId, 
          name: n, 
          state: state || null,
          role: UserRole.INSTITUTION, 
          pin: '123',
          isDefaultPin: true,
          population: population || {},
          updatedAt: Date.now() 
      });
  };
  const updateInstitution = (u: User) => writeData(`data/users/${u.id}`, { ...u, updatedAt: Date.now() });
  const deleteInstitution = (institutionId: number) => writeData(`data/users/${institutionId}`, null);

  const addEvaluation = (e: any) => {
      const newId = getNextId(data.evaluations);
      writeData(`data/evaluations/${newId}`, { ...e, id: newId, updatedAt: Date.now() });
  };
  const updateEvaluation = (e: any) => writeData(`data/evaluations/${e.id}`, { ...e, updatedAt: Date.now() });
  const deleteEvaluation = (id: number) => writeData(`data/evaluations/${id}`, null);

  const addMaghribAttendance = (att: any) => {
      const id = att.id || getNextId(data.maghribAttendances);
      writeData(`data/maghribAttendances/${id}`, { ...att, id, updatedAt: Date.now() });
  };
  const deleteMaghribAttendance = (id: number) => writeData(`data/maghribAttendances/${id}`, null);

  const handleLogout = () => { 
      if (hasUnsavedChanges) {
          alert('⚠️ Warning: You have unsaved changes.');
          return;
      }
      setCurrentUser(null); 
      setHasUnsavedChanges(false);
      localStorage.removeItem(CURRENT_USER_KEY); 
  };

  const initiateLogoutCheck = () => { handleLogout(); };
  const handleLogin = (user: User) => { setCurrentUser(user); localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user)); };
  const handleSaveFirebaseConfig = (config: any) => { setFirebaseConfigState(config); };

  const showSetupWizard = isDistributable && !firebaseConfigState && !isPublishedConnected;

  return (
    <AppContext.Provider value={{
      users: data.users, reports: data.reports,
      addReport, updateReport, deleteReport, 
      deleteAllReports: async () => { writeData('data/reports', null); },
      deleteAllData: async () => writeData('data', { users: { '1': INITIAL_USERS[0] } }),
      loadMockData: () => {},
      customLogo, setCustomLogo: (l) => { setCustomLogoState(l); writeData('config/customLogo', l); },
      addInstitution, updateInstitution, deleteInstitution, importFullBackup: (d) => writeData('data', d),
      supervisorPassword, setSupervisorPassword: (p) => { setSupervisorPasswordState(p); writeData('config/supervisorPassword', p); },
      logout: handleLogout, isLoading, initiateLogoutCheck, appName, setAppName: (n) => { setAppNameState(n); writeData('config/appName', n); },
      darkMode, toggleDarkMode: () => setDarkMode(!darkMode), 
      firebaseConnectionStatus, 
      firebaseConfig: firebaseConfigState, 
      setFirebaseConfig: handleSaveFirebaseConfig,
      isDistributable, isPublishedConnected, currentUser,
      students: data.students, 
      halaqas: data.halaqas, 
      evaluations: data.evaluations,
      updateEvaluation, deleteEvaluation, addEvaluation,
      setLastUsedWeek,
      maghribAttendances: data.maghribAttendances,
      addMaghribAttendance,
      deleteMaghribAttendance,
      maghribPassword, 
      setMaghribPassword: (p) => { setMaghribPasswordState(p); writeData('config/maghribPassword', p); },
      immunizationPassword,
      setImmunizationPassword: (p) => { setImmunizationPasswordState(p); writeData('config/immunizationPassword', p); },
      setHasUnsavedChanges
    }}>
      <div className={`h-screen flex flex-col transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-green-50 text-gray-900'}`}>
          {showSetupWizard && <FirebaseSetupWizard onConfigSave={handleSaveFirebaseConfig} />}
          {!currentUser ? (
              <LoginScreen onLogin={handleLogin} />
          ) : (
              <div className="flex flex-col h-full">
                  <Header 
                      user={currentUser} 
                      onShowHelp={() => setShowHelpModal(true)} 
                      onInitiateLogoutCheck={initiateLogoutCheck} 
                      onShowMobileInstallModal={() => setShowMobileInstallModal(true)} 
                      onShowChangePassword={() => setShowChangePasswordModal(true)} 
                  />
                  <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                      {currentUser.role === UserRole.SUPERVISOR && <SupervisorDashboard />}
                      {currentUser.role === UserRole.IMMUNIZATION && <ImmunizationDashboard />}
                      {currentUser.role === UserRole.INSTITUTION && <InstitutionDashboard institutionId={currentUser.id} />}
                  </main>
              </div>
          )}
          {showHelpModal && <HelpModal onClose={() => setShowHelpModal(false)} />}
          {showMobileInstallModal && <MobileInstallModal onClose={() => setShowMobileInstallModal(false)} />}
          {showChangePasswordModal && currentUser && (
            <ChangePasswordModal 
                onClose={() => setShowChangePasswordModal(false)} 
                currentStoredPassword={
                    currentUser.role === UserRole.SUPERVISOR ? supervisorPassword : 
                    currentUser.role === UserRole.IMMUNIZATION ? immunizationPassword :
                    (currentUser.pin || '123')
                }
                onSave={(p) => {
                    if (currentUser.role === UserRole.SUPERVISOR) {
                        setSupervisorPasswordState(p); 
                        writeData('config/supervisorPassword', p);
                    } else if (currentUser.role === UserRole.IMMUNIZATION) {
                        setImmunizationPasswordState(p);
                        writeData('config/immunizationPassword', p);
                    } else if (currentUser.role === UserRole.INSTITUTION) {
                        const updatedUser = { ...currentUser, pin: p, isDefaultPin: false, updatedAt: Date.now() };
                        updateInstitution(updatedUser);
                        setCurrentUser(updatedUser);
                        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updatedUser));
                    }
                }} 
            />
          )}
      </div>
    </AppContext.Provider>
  );
};

export default App;

