        );
    };

    const handleSaveFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        try {
            const parsedConfig = JSON.parse(firebaseConfigInput);
            if (!parsedConfig.apiKey || !parsedConfig.databaseURL || !parsedConfig.projectId || !parsedConfig.authDomain) {
                setMessage({ type: 'error', text: 'Ensure Firebase config is correct and contains apiKey, databaseURL, projectId, authDomain.' });
                return;
            }
            setFirebaseConfig(parsedConfig);
            setMessage({ type: 'success', text: 'Firebase config saved successfully. Reconnecting now.' });
        } catch (e) {
            setMessage({ type: 'error', text: 'Invalid JSON format for Firebase config. Please check the text.' });
        }
    };

    const handleClearFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        confirmAction('Confirm Clearing Firebase Config', 'Are you sure you want to clear Firebase settings? The app will switch to local mode and will not connect to the cloud database.',
            async () => {
                setFirebaseConfig(null);
                setMessage({ type: 'success', text: 'Firebase config cleared. The app is now in local mode.' });
            }
        );
    };

    const handleDownloadDistributableEmpty = async () => {
        try {
            setMessage({ 
                type: 'success', 
                text: '✅ Blank version (HTML file) downloaded. This version works locally and does not connect to any cloud database.\n\nTo connect it to your own Firebase:\n1. Open the downloaded HTML file in your browser.\n2. Go to "Settings" > "Main Settings" > "Firebase Configuration".\n3. Paste your project\'s Firebase config object there.' 
            });
            await generateAndDownloadDistributableHtml({ ...context, users: context.users, reports: [], students: [], halaqas: [], evaluations: [], firebaseConfig: null }, 'empty');
            setTimeout(() => setMessage(null), 15000);
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleDownloadDistributableConnected = async () => {
        if (isDistributable && !isPublishedConnected && !firebaseConfig?.apiKey) {
            setMessage({ type: 'warning', text: '⚠️ Firebase has not yet been configured in this version. Please enter the Firebase settings first before downloading a connected version.' });
            setTimeout(() => setMessage(null), 8000);
            return;
        }

        try {
            setMessage({ type: 'success', text: 'Preparing connected version...' });
            await generateAndDownloadDistributableZip({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: firebaseConfig }, 'snapshot');
            setMessage({ type: 'success', text: '✅ Connected version (ZIP file) downloaded. Upload it directly to Netlify Drop.' });
            setTimeout(() => setMessage(null), 8000);
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleCopyHtml = async (type: 'empty' | 'connected') => {
        try {
            const config = type === 'empty' ? null : firebaseConfig;
            const htmlString = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
            const success = await copyToClipboard(htmlString);
            if (success) {
                setCopyState(type);
                setTimeout(() => setCopyState('idle'), 3000);
                setMessage({ type: 'success', text: `✅ HTML code for the ${type === 'empty' ? 'blank' : 'connected'} version copied successfully.` });
            }
        } catch (e) {
            setMessage({ type: 'error', text: 'Failed to copy code.' });
        }
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    return (
        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={handleCancel} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200">{confirmationModal.message}</p>
                    <div className="flex justify-end gap-4 mt-6">
                        <button onClick={handleCancel} disabled={isProcessing} className={`px-4 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>Cancel</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className={`px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
