const resizeImage = (
    file: File, 
    maxWidth: number, 
    maxHeight: number, 
    quality: number, 
    callback: (dataUrl: string | null) => void
) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
        const image = new Image();
        image.onload = () => {
            const canvas = document.createElement('canvas');
            let width = image.width;
            let height = image.height;

            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(image, 0, 0, width, height);
                const dataUrl = canvas.toDataURL(file.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', quality);
                callback(dataUrl);
            } else {
                callback(null);
            }
        };
        image.src = readerEvent.target?.result as string;
    };
    reader.readAsDataURL(file);
};


export const Settings: React.FC = () => {
    const context = useContext(AppContext);

    if (!context) return null;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{
      isOpen: boolean;
      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        users,
        addInstitution, updateInstitution,
        importFullBackup: handleImportFullBackupFile,
        appName, setAppName,
        isDistributable, isPublishedConnected, 
        firebaseConfig, setFirebaseConfig,
        firebaseConnectionStatus
    } = context; 

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(
        firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''
    );

    const firebaseConfigTextAreaRef = useRef<HTMLTextAreaElement>(null);
    const appNameInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => { setAppNameInput(appName); }, [appName]);
    useEffect(() => {
        setFirebaseConfigInput(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : '');
    }, [firebaseConfig]);

    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => { 
      setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const handleCancel = () => {
      if (!isProcessing) {
          setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try {
          await navigator.clipboard.writeText(text);
          return true;
        } catch (err) { console.error("Clipboard API failed:", err); }
      }
      try {
        const textArea = document.createElement("textarea");
        textArea.value = text;
        textArea.style.position = "fixed";
        textArea.style.left = "-9999px";
        textArea.style.top = "0";
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        const successful = document.execCommand('copy');
        document.body.removeChild(textArea);
        return successful;
      } catch (err) {
        console.error("Fallback copy failed:", err);
        return false;
      }
    };

    const handleDeleteReports = () => {
        confirmAction('Confirm Deleting Reports', 'Are you sure you want to delete all monthly reports? A full backup will be automatically downloaded before deletion.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllReports();
                setMessage({ type: 'success', text: 'All reports have been deleted successfully.' });
            }
        );
    }

    const handleDeleteAllData = () => {
        confirmAction('Confirm Program Reset', 'Warning: This action will download a backup and then delete all institution and report data. This action cannot be undone.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllData();
                setMessage({ type: 'success', text: 'The program has been reset successfully.' });
            }
        );
    }

    const handleLoadMockData = () => {
        confirmAction('Confirm Loading Mock Data', 'Warning: This will replace all current data. Are you sure?',
            async () => { 
                loadMockData();
                setMessage({ type: 'success', text: 'Mock data loaded successfully.' });
            }
        );
    };

    const handleDownloadImportTemplate = () => {
        exportSheetTemplate('Institutions_Import_Template');
        setMessage({ type: 'success', text: '✅ Template download has started.' });
    };

    const handleExportInstitutionsForPopulation = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);
        const currentYear = new Date().getFullYear();

        const dataRows: any[] = [];
        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);

            if (years.length > 0) {
                years.forEach(y => {
                    dataRows.push([
                        inst.state || '',
                        inst.name,
                        y,
                        populations[y] || ''
                    ]);
                });
            } else {
                // If no pop data, export one row with current year placeholder
                dataRows.push([
                    inst.state || '',
                    inst.name,
                    currentYear,
                    ''
                ]);
            }
        });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet([['State', 'Institution', 'Year', 'Population'], ...dataRows]);
        XLSX.utils.book_append_sheet(wb, ws, 'Population');
        XLSX.writeFile(wb, `Institutions_All_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ The full list (all years) has been exported.' });
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !setCustomLogo) return;
        setMessage({ type: 'success', text: 'Processing logo...' });
        resizeImage(file, 200, 200, 0.9, (dataUrl) => {
            if (dataUrl) {
                setCustomLogo(dataUrl);
                setMessage({ type: 'success', text: 'Logo updated successfully.' });
            } else {
                setMessage({ type: 'error', text: 'Failed to process logo.' });
            }
        });
        e.target.value = '';
    };

    const handleResetLogo = () => {
        if (setCustomLogo) {
            confirmAction('Confirm Resetting to Default Logo', 'Are you sure you want to revert to the default logo?',
                async () => {
                    setCustomLogo(null);
                    setMessage({ type: 'success', text: 'Default logo has been restored.' });
                }
            );
        }
    }

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Institution Import', 'This will add or update institutions and population data for all specified years. Are you sure?',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const json = XLSX.utils.sheet_to_json(worksheet);

                        // Local Map to consolidate data from Excel grouped by Institution Name
                        const excelDataMap = new Map<string, { state?: string, populations: Record<number, number> }>();

                        json.forEach((row: any) => {
                            const name = (row['Institution'] || row['Name'])?.toString().trim();
                            const state = (row['State'])?.toString().trim();
                            const year = parseInt(row['Year']);
                            const population = parseInt(row['Population']);

                            if (name) {
                                if (!excelDataMap.has(name)) {
                                    excelDataMap.set(name, { state, populations: {} });
                                }
                                const entry = excelDataMap.get(name)!;
                                if (!isNaN(year) && !isNaN(population)) {
                                    entry.populations[year] = population;
                                }
                                if (state && !entry.state) {
                                    entry.state = state;
                                }
                            }
                        });

                        let addedCount = 0;
                        let updatedCount = 0;

                        excelDataMap.forEach((val, name) => {
                            const existingInst = users.find(u => u.role === UserRole.INSTITUTION && u.name === name);

                            if (existingInst) {
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    state: val.state || existingInst.state,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else {
                                // Add as new institution with merged populations
                                addInstitution(name, val.state, val.populations);
                                addedCount++;
                            }
                        });

                        let resultMsg = '';
                        if (addedCount > 0) resultMsg += `✅ Added ${addedCount} institution(s). `;
                        if (updatedCount > 0) resultMsg += `🔄 Updated data for ${updatedCount} institution(s).`;
                        if (!resultMsg) resultMsg = '⚠️ No valid changes found in file.';

                        setMessage({ type: 'success', text: resultMsg });

                    } catch (error) {
                        setMessage({ type: 'error', text: 'Failed to process file contents.' });
                    }
                };
                reader.readAsBinaryString(file);
            }
        );
        e.target.value = '';
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        if(!isSilent) setMessage({ type: 'success', text: 'Exporting full backup...' });
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: context.firebaseConfig }, 'EPI_Full_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ Full backup exported.' });
    };

    const handleImportFullBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !handleImportFullBackupFile) return;

        confirmAction('Confirm Full Backup Restore', 'Warning: This will replace all current program data. This action cannot be undone.',
            async () => { 
                try {
                    setMessage({ type: 'success', text: 'Importing data...' });
                    const importedData = await importFullBackup(file);
                    handleImportFullBackupFile(importedData);
                    setMessage({ type: 'success', text: 'Full backup imported successfully.' });
                } catch (error: any) {
                    setMessage({ type: 'error', text: error.message || 'Failed to import file.' });
                }
                e.target.value = '';
            }
        );
    };

    const handleSaveAppName = () => {
        if (!appNameInput.trim()) {
            setMessage({ type: 'error', text: 'Program name cannot be empty.' });
            return;
        }
        setAppName(appNameInput.trim());
        setMessage({ type: 'success', text: 'Program name saved successfully.' });
    };

    const handleResetAppName = () => {
        confirmAction('Confirm Resetting Program Name', 'Are you sure you want to reset the program name to its default?',
            async () => { 
                setAppName(DEFAULT_APP_NAME);
                setMessage({ type: 'success', text: 'Default program name has been restored.' });
            }
        );
    };

    const handleSaveFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        try {
            const parsedConfig = JSON.parse(firebaseConfigInput);
            if (!parsedConfig.apiKey || !parsedConfig.databaseURL || !parsedConfig.projectId || !parsedConfig.authDomain) {
                setMessage({ type: 'error', text: 'Ensure Firebase config is correct and contains apiKey, databaseURL, projectId, authDomain.' });
                return;
            }
            setFirebaseConfig(parsedConfig);
            setMessage({ type: 'success', text: 'Firebase config saved successfully. Reconnecting now.' });
        } catch (e) {
            setMessage({ type: 'error', text: 'Invalid JSON format for Firebase config. Please check the text.' });
        }
    };

    const handleClearFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        confirmAction('Confirm Clearing Firebase Config', 'Are you sure you want to clear Firebase settings? The app will switch to local mode and will not connect to the cloud database.',
            async () => {
                setFirebaseConfig(null);
                setMessage({ type: 'success', text: 'Firebase config cleared. The app is now in local mode.' });
            }
        );
    };

    const handleDownloadDistributableEmpty = async () => {
        try {
            setMessage({ 
                type: 'success', 
                text: '✅ Blank version (HTML file) downloaded. This version works locally and does not connect to any cloud database.\n\nTo connect it to your own Firebase:\n1. Open the downloaded HTML file in your browser.\n2. Go to "Settings" > "Main Settings" > "Firebase Configuration".\n3. Paste your project\'s Firebase config object there.' 
            });
            await generateAndDownloadDistributableHtml({ ...context, users: context.users, reports: [], students: [], halaqas: [], evaluations: [], firebaseConfig: null }, 'empty');
            setTimeout(() => setMessage(null), 15000);
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleDownloadDistributableConnected = async () => {
        if (isDistributable && !isPublishedConnected && !firebaseConfig?.apiKey) {
            setMessage({ type: 'warning', text: '⚠️ Firebase has not yet been configured in this version. Please enter the Firebase settings first before downloading a connected version.' });
            setTimeout(() => setMessage(null), 8000);
            return;
        }

        try {
            setMessage({ type: 'success', text: 'Preparing connected version...' });
            await generateAndDownloadDistributableZip({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: firebaseConfig }, 'snapshot');
            setMessage({ type: 'success', text: '✅ Connected version (ZIP file) downloaded. Upload it directly to Netlify Drop.' });
            setTimeout(() => setMessage(null), 8000);
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleCopyHtml = async (type: 'empty' | 'connected') => {
        try {
            const config = type === 'empty' ? null : firebaseConfig;
            const htmlString = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
            const success = await copyToClipboard(htmlString);
            if (success) {
                setCopyState(type);
                setTimeout(() => setCopyState('idle'), 3000);
                setMessage({ type: 'success', text: `✅ HTML code for the ${type === 'empty' ? 'blank' : 'connected'} version copied successfully.` });
            }
        } catch (e) {
            setMessage({ type: 'error', text: 'Failed to copy code.' });
        }
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    return (
        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={handleCancel} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-lg font-medium py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4 pt-4 border-t dark:border-gray-700">
                        <button onClick={handleCancel} disabled={isProcessing} className={`px-4 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>Cancel</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className={`px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300">Settings</h3>

            <div className="flex flex-wrap border-b border-gray-200 mb-6 dark:border-gray-700">
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('main')}>Main Settings</button>
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('customization')}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg whitespace-pre-line ${message.type === 'success' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' : message.type === 'error' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200'}`}>{message.text}</div>}

            {activeSettingsView === 'main' && (
                <div className="space-y-8 animate-fade-in">
                    {isDistributable && !isPublishedConnected && (
                         <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                            <h4 className="text-lg font-semibold text-indigo-900 mb-4 dark:text-indigo-200">Firebase Configuration (for your cloud database)</h4>
                            <p className="text-sm text-indigo-700 mb-4 dark:text-indigo-300">
                                To link this app to your own Firebase database (to enable cloud sync and data sharing), follow these steps:
                            </p>
                            <ol className="list-decimal pl-6 text-sm text-indigo-700 mb-4 dark:text-indigo-300 space-y-2">
                                <li>Go to the <a href="https://console.firebase.google.com/" target="_blank" className="text-blue-600 hover:underline dark:text-blue-400">Firebase Console</a> and sign in.</li>
                                <li>Select your existing Firebase project, or create a new one.</li>
                                <li>From the side menu, select "Project settings".</li>
                                <li>On the settings page, scroll down to the "Your apps" section.</li>
                                <li>If you don't have a web app, click "Add app" and choose the Web icon (<span className="font-bold">&lt;/&gt;</span>).</li>
                                <li>Follow the instructions until you reach the "Add Firebase SDK" step, where you will find the <span className="font-bold">Firebase config object</span> that starts with <code className="bg-gray-100 p-1 rounded font-mono text-xs dark:bg-gray-600 dark:text-gray-200">const firebaseConfig = &#123; ... &#125;</code>.</li>
                                <li>Copy only the object <code className="bg-gray-100 p-1 rounded font-mono text-xs dark:bg-gray-600 dark:text-gray-200">&#123; ... &#125;</code> (make sure to copy the curly braces &#123;&#125;) and paste it into the text box below.</li>
                                <li>Click "Save Firebase Config".</li>
                            </ol>
                            <label htmlFor="firebase-config" className="block text-sm font-medium text-gray-700 mb-1 dark:text-gray-200">Firebase Config (JSON Object)</label>
                            <textarea
                                id="firebase-config"
                                ref={firebaseConfigTextAreaRef}
                                value={firebaseConfigInput}
                                onChange={(e) => setFirebaseConfigInput(e.target.value)}
