import React, { useState, useContext, useMemo, useRef } from 'react';
import { AppContext } from '../App';
import { UserRole, User } from '../types';
import Modal from './Modal';
import { isSmartMatch } from '../utils/searchUtils';

const StudentManagement: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { users, addInstitution, updateInstitution, deleteInstitution } = context;

    const [newInstitutionName, setNewInstitutionName] = useState('');
    const [newStateName, setNewStateName] = useState(''); 
    const [editingInstitution, setEditingInstitution] = useState<User | null>(null);
    const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

    // Population Modal State
    const [selectedInstitutionForPop, setSelectedInstitutionForPop] = useState<User | null>(null);
    const [popYear, setPopYear] = useState<number>(new Date().getFullYear());
    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    // Aggregation Logic
    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();

        if (!newStateName.trim()) {
            showMessage('⚠️ Please enter the Wilayat name.', true);
            return;
        }

        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                // Note: We keep the state name for easier bulk adding if needed, or clear it? 
                // Usually better to clear to prevent accidental wrong assignments.
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) to ${stateToSave} successfully.`);
            }
        } else {
            showMessage('⚠️ Please enter at least one institution name.', true);
        }
    };

    const handleUpdateInstitution = (institution: User, newName: string, newState: string) => {
        if (!newState.trim()) {
            showMessage('⚠️ Wilayat name cannot be empty.', true);
            return;
        }
        if (newName.trim()) {
            updateInstitution({ 
                ...institution, 
                name: newName.trim(), 
                state: newState.trim(),
                updatedAt: Date.now() 
            });
        }
        setEditingInstitution(null);
        showMessage('✅ Institution data updated successfully.');
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Institution Deletion',
            message: `Warning: Are you sure you want to delete "${institution.name}"? This will permanently delete all associated reports.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted successfully.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;
        const updatedPopulation = {
            ...(selectedInstitutionForPop.population || {}),
            [popYear]: Number(popCount)
        };
        updateInstitution({ 
            ...selectedInstitutionForPop, 
            population: updatedPopulation,
            updatedAt: Date.now()
        });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population data updated successfully.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-8 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-4 text-lg font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md transition-all active:scale-95">Confirm Delete</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Manage Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-4">
                        <div className="flex gap-2 items-end">
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Population Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-2 px-4 bg-green-600 text-white rounded-lg font-bold h-[46px]">Save</button>
                        </div>

                        <div className="mt-4 border-t pt-4 dark:border-gray-700">
                            <h4 className="font-bold text-gray-700 dark:text-gray-300 mb-2">Recorded Population Log:</h4>
                            <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-3 max-h-40 overflow-y-auto">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-sm">
                                        <thead><tr className="text-gray-500 border-b dark:border-gray-600"><th className="text-left py-2">Year</th><th className="text-right py-2">Count</th></tr></thead>
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b border-gray-200 dark:border-gray-600 last:border-0">
                                                    <td className="py-2 font-bold">{year}</td>
                                                    <td className="py-2 text-right font-mono">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-sm text-center">No data recorded</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print min-h-[48px]">
                <h3 className="text-2xl font-extrabold text-green-900 dark:text-green-300">Institution & Population Management</h3>
                {message && (
                    <span className={`text-sm font-bold px-4 py-2 rounded-full animate-pulse ${message.isError ? 'bg-red-50 text-red-700 dark:bg-red-900 dark:text-red-200' : 'bg-green-50 text-green-700 dark:bg-green-900 dark:text-green-200'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 space-y-6">
                    <div className="bg-white rounded-2xl shadow-md border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-6 border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                            <h4 className="text-lg font-bold text-gray-800 dark:text-gray-200 mb-4">Add New Institutions</h4>
                            <form onSubmit={handleAddInstitution} className="flex flex-col gap-3">
                                <div className="flex flex-col sm:flex-row gap-3">
                                    <div className="sm:w-1/3">
                                        <input 
                                            type="text" 
                                            value={newStateName} 
                                            onChange={(e) => setNewStateName(e.target.value)} 
                                            placeholder="Wilayat Name *" 
                                            className={`input-style w-full ${!newStateName.trim() && 'border-red-300'}`} 
                                            list="states-list"
                                            required
                                        />
                                        <datalist id="states-list">
                                            {uniqueStates.map(s => <option key={s} value={s} />)}
                                        </datalist>
                                    </div>
                                    <textarea 
                                        ref={newInstitutionInputRef}
                                        value={newInstitutionName} 
                                        onChange={(e) => setNewInstitutionName(e.target.value)} 
                                        placeholder="Enter institution names (one per line)..." 
                                        className="input-style flex-grow py-3" 
                                        rows={1}
                                        onFocus={handleInputFocus}
                                        required
                                    />
                                </div>
                                <button type="submit" className="self-end px-8 py-2.5 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95 whitespace-nowrap">Add Institutions</button>
                            </form>
                        </div>

                        <div className="p-6 bg-white dark:bg-gray-800 border-t dark:border-gray-700 animate-fade-in">
                            <div className="relative mb-6">
                                <input 
                                    ref={institutionSearchInputRef}
                                    type="text" 
                                    placeholder="Search for an institution by name or Wilayat..." 
                                    value={institutionSearchTerm} 
                                    onChange={(e) => setInstitutionSearchTerm(e.target.value)} 
                                    className="input-style w-full pl-10" 
                                    onFocus={handleInputFocus}
                                />
                                <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[600px] overflow-y-auto custom-scrollbar">
                                {filteredInstitutions.map(institution => {
                                    const isEditing = editingInstitution?.id === institution.id;
                                    return (
                                        <div key={institution.id} className="p-5 bg-gray-50 rounded-2xl border border-gray-200 dark:bg-gray-700 dark:border-gray-600 hover:shadow-lg transition-all group flex flex-col justify-between">
                                            {isEditing ? (
                                                <div className="space-y-3 animate-fade-in">
                                                    <div>
                                                        <label className="text-[10px] font-bold text-gray-500 mb-1 block">Edit Wilayat:</label>
                                                        <input type="text" defaultValue={institution.state || ''} placeholder="Wilayat" id={`edit-state-${institution.id}`} className="input-style text-sm py-2" required />
                                                    </div>
                                                    <div>
                                                        <label className="text-[10px] font-bold text-gray-500 mb-1 block">Edit Name:</label>
                                                        <input type="text" defaultValue={institution.name} id={`edit-name-${institution.id}`} className="input-style py-2" required />
                                                    </div>
                                                    <div className="flex gap-2">
                                                        <button onClick={() => {
                                                            const nameVal = (document.getElementById(`edit-name-${institution.id}`) as HTMLInputElement).value;
                                                            const stateVal = (document.getElementById(`edit-state-${institution.id}`) as HTMLInputElement).value;
                                                            handleUpdateInstitution(institution, nameVal, stateVal);
                                                        }} className="flex-1 bg-green-600 text-white py-2 rounded-lg font-bold text-sm shadow-sm hover:bg-green-700">Save Changes</button>
                                                        <button onClick={() => setEditingInstitution(null)} className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg font-bold text-sm hover:bg-gray-300">Cancel</button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <>
                                                    <div className="mb-4">
                                                        <p className="text-[10px] text-indigo-600 dark:text-indigo-400 mb-1 font-black bg-indigo-50 dark:bg-indigo-900/30 px-2 py-0.5 rounded inline-block">{institution.state || 'No Wilayat'}</p>
                                                        <p className="font-extrabold text-gray-800 dark:text-gray-100 text-lg leading-tight">{institution.name}</p>
                                                    </div>
                                                    <div className="flex justify-between items-center mt-3 pt-4 border-t dark:border-gray-600">
                                                        <button onClick={() => setSelectedInstitutionForPop(institution)} className="text-[11px] font-bold bg-white text-green-700 border border-green-200 px-3 py-1.5 rounded-lg hover:bg-green-50 transition-colors dark:bg-gray-800 dark:border-green-800 dark:text-green-400">
                                                            👥 Population ({institution.population?.[new Date().getFullYear()]?.toLocaleString() || 0})
                                                        </button>
                                                        <div className="flex gap-2">
                                                            <button 
                                                                onClick={() => setEditingInstitution(institution)} 
                                                                className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-all active:scale-90 dark:bg-blue-900/30 dark:text-blue-400"
                                                                title="Edit institution name"
                                                            >
                                                                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                                                                </svg>
                                                            </button>
                                                            <button 
                                                                onClick={() => handleInstitutionDelete(institution)} 
                                                                className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-all active:scale-90 dark:bg-red-900/30 dark:text-red-400"
                                                                title="Permanently delete institution"
                                                            >
                                                                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                                                </svg>
                                                            </button>
                                                        </div>
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                    );
                                })}
                                {filteredInstitutions.length === 0 && <p className="text-center text-gray-400 py-10 col-span-full">No institutions found.</p>}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-2xl shadow-md border border-gray-100 dark:bg-gray-800 dark:border-gray-700 p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h4 className="text-lg font-bold text-gray-800 dark:text-gray-200">Wilayat Population Stats</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-1 text-xs">
                            {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                    <div className="space-y-3 max-h-[600px] overflow-y-auto">
                        {stateStatistics.map(([state, count], index) => (
                            <div key={state} className={`p-3 rounded-lg flex justify-between items-center ${index % 2 === 0 ? 'bg-green-50 dark:bg-green-900/30' : 'bg-gray-50 dark:bg-gray-700'}`}>
                                <span className="font-bold text-gray-700 dark:text-gray-200">{state}</span>
                                <span className="font-mono font-black text-green-800 dark:text-green-300 text-lg">{count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

