                        <button onClick={confirmationModal.onConfirm} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 shadow-md">Confirm Reset</button>
                    </div>
                </Modal>
            )}

            <div className="bg-white p-6 rounded-2xl shadow-lg dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
                <h3 className="text-xl font-bold text-green-900 dark:text-green-300 mb-4 border-b pb-2 dark:border-gray-700">Immunization Department</h3>
                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 bg-gray-50 dark:bg-gray-700/50 p-4 rounded-xl">
                    <div>
                        <p className="font-bold text-gray-700 dark:text-gray-200">Current Password:</p>
