                    >
                        Reset to "123"
                    </button>
                </div>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-lg dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
                <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
                    <h3 className="text-xl font-bold text-green-900 dark:text-green-300">Institutions PIN Management</h3>
