import React, { useState, useContext, useMemo, useRef } from 'react';
import { AppContext } from '../App';
import { UserRole, User } from '../types';
import Modal from './Modal';
import { isSmartMatch } from '../utils/searchUtils';

const StudentManagement: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { users, addInstitution, updateInstitution, deleteInstitution } = context;

    const [newInstitutionName, setNewInstitutionName] = useState('');
    const [newStateName, setNewStateName] = useState(''); 
    const [editingInstitution, setEditingInstitution] = useState<User | null>(null);
    const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

    // Population Modal State
    const [selectedInstitutionForPop, setSelectedInstitutionForPop] = useState<User | null>(null);
    const [popYear, setPopYear] = useState<number>(new Date().getFullYear());
    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    // Aggregation Logic
    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();

        if (!newStateName.trim()) {
            showMessage('⚠️ Please enter the Wilayat name.', true);
            return;
        }

        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) to ${stateToSave} successfully.`);
            }
        } else {
            showMessage('⚠️ Please enter at least one institution name.', true);
        }
    };

    const handleUpdateInstitution = (institution: User, newName: string, newState: string) => {
        if (!newState.trim()) {
            showMessage('⚠️ Wilayat name cannot be empty.', true);
            return;
        }
        if (newName.trim()) {
            updateInstitution({ 
                ...institution, 
                name: newName.trim(), 
                state: newState.trim(),
                updatedAt: Date.now() 
            });
        }
        setEditingInstitution(null);
        showMessage('✅ Institution data updated successfully.');
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Institution Deletion',
            message: `Warning: Are you sure you want to delete "${institution.name}"? This will permanently delete all associated reports.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted successfully.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;
        const updatedPopulation = {
            ...(selectedInstitutionForPop.population || {}),
            [popYear]: Number(popCount)
        };
        updateInstitution({ 
            ...selectedInstitutionForPop, 
            population: updatedPopulation,
            updatedAt: Date.now()
        });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population data updated successfully.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-6 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-4 text-lg font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md transition-all active:scale-95">Confirm Delete</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Manage Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-4">
                        <div className="flex gap-2 items-end">
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Population Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-2 px-4 bg-green-600 text-white rounded-lg font-bold h-[46px]">Save</button>
                        </div>

                        <div className="mt-4 border-t pt-4 dark:border-gray-700">
                            <h4 className="font-bold text-gray-700 dark:text-gray-300 mb-2">Recorded Population Log:</h4>
                            <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-3 max-h-40 overflow-y-auto">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-sm">
                                        <thead><tr className="text-gray-500 border-b dark:border-gray-600"><th className="text-left py-2">Year</th><th className="text-right py-2">Count</th></tr></thead>
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b border-gray-200 dark:border-gray-600 last:border-0">
                                                    <td className="py-2 font-bold">{year}</td>
                                                    <td className="py-2 text-right font-mono">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-sm text-center">No data recorded</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print min-h-[40px]">
                <h3 className="text-xl font-extrabold text-green-900 dark:text-green-300">Institutions & Population</h3>
                {message && (
                    <span className={`text-xs font-bold px-3 py-1.5 rounded-full animate-pulse ${message.isError ? 'bg-red-50 text-red-700 dark:bg-red-900 dark:text-red-200' : 'bg-green-50 text-green-700 dark:bg-green-900 dark:text-green-200'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
                <div className="lg:col-span-2 space-y-4">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-4 border-b dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50">
                            <h4 className="text-sm font-bold text-gray-800 dark:text-gray-200 mb-3">Add New Institutions</h4>
                            <form onSubmit={handleAddInstitution} className="flex flex-col gap-2">
                                <div className="flex flex-col sm:flex-row gap-2">
                                    <div className="sm:w-1/3">
                                        <input 
                                            type="text" 
                                            value={newStateName} 
                                            onChange={(e) => setNewStateName(e.target.value)} 
                                            placeholder="Wilayat Name *" 
                                            className="input-style w-full py-2 text-sm" 
                                            list="states-list"
                                            required
                                        />
                                        <datalist id="states-list">
                                            {uniqueStates.map(s => <option key={s} value={s} />)}
                                        </datalist>
                                    </div>
                                    <textarea 
                                        ref={newInstitutionInputRef}
                                        value={newInstitutionName} 
                                        onChange={(e) => setNewInstitutionName(e.target.value)} 
                                        placeholder="Institution names (one per line)..." 
                                        className="input-style flex-grow py-2 text-sm" 
                                        rows={1}
                                        onFocus={handleInputFocus}
                                        required
                                    />
                                </div>
                                <button type="submit" className="self-end px-6 py-2 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 text-xs shadow-sm active:scale-95 transition-all">Add Institutions</button>
                            </form>
                        </div>

                        <div className="p-4 bg-white dark:bg-gray-800 border-t dark:border-gray-700 animate-fade-in">
                            <div className="relative mb-4">
                                <input 
                                    ref={institutionSearchInputRef}
                                    type="text" 
                                    placeholder="Search by name or Wilayat..." 
                                    value={institutionSearchTerm} 
                                    onChange={(e) => setInstitutionSearchTerm(e.target.value)} 
                                    className="input-style w-full pl-9 py-2 text-sm" 
                                    onFocus={handleInputFocus}
                                />
                                <svg className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-[500px] overflow-y-auto custom-scrollbar">
                                {filteredInstitutions.map(institution => {
                                    const isEditing = editingInstitution?.id === institution.id;
                                    return (
                                        <div key={institution.id} className="p-3 bg-gray-50 rounded-xl border border-gray-200 dark:bg-gray-700/50 dark:border-gray-600 hover:shadow-md transition-all group flex flex-col justify-between">
                                            {isEditing ? (
                                                <div className="space-y-2 animate-fade-in">
                                                    <div>
                                                        <input type="text" defaultValue={institution.state || ''} placeholder="Wilayat" id={`edit-state-${institution.id}`} className="input-style text-xs py-1.5" required />
                                                    </div>
                                                    <div>
                                                        <input type="text" defaultValue={institution.name} id={`edit-name-${institution.id}`} className="input-style text-xs py-1.5" required />
                                                    </div>
                                                    <div className="flex gap-2">
                                                        <button onClick={() => {
                                                            const nameVal = (document.getElementById(`edit-name-${institution.id}`) as HTMLInputElement).value;
                                                            const stateVal = (document.getElementById(`edit-state-${institution.id}`) as HTMLInputElement).value;
                                                            handleUpdateInstitution(institution, nameVal, stateVal);
                                                        }} className="flex-1 bg-green-600 text-white py-1.5 rounded-lg font-bold text-xs shadow-sm hover:bg-green-700">Save</button>
                                                        <button onClick={() => setEditingInstitution(null)} className="flex-1 bg-gray-200 text-gray-700 py-1.5 rounded-lg font-bold text-xs hover:bg-gray-300">Cancel</button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <>
                                                    <div className="mb-2">
                                                        <p className="text-[9px] text-indigo-600 dark:text-indigo-400 mb-0.5 font-black bg-indigo-50 dark:bg-indigo-900/30 px-1.5 py-0.5 rounded inline-block">{institution.state || 'No Wilayat'}</p>
                                                        <p className="font-bold text-gray-800 dark:text-gray-100 text-sm leading-tight truncate">{institution.name}</p>
                                                    </div>
                                                    <div className="flex justify-between items-center mt-2 pt-2 border-t dark:border-gray-600">
                                                        <button onClick={() => setSelectedInstitutionForPop(institution)} className="text-[10px] font-bold bg-white text-green-700 border border-green-200 px-2 py-1 rounded-lg hover:bg-green-50 transition-colors dark:bg-gray-800 dark:border-green-800 dark:text-green-400">
                                                            👥 Pop ({institution.population?.[new Date().getFullYear()]?.toLocaleString() || 0})
                                                        </button>
                                                        <div className="flex gap-1.5">
                                                            <button 
                                                                onClick={() => setEditingInstitution(institution)} 
                                                                className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-md transition-all dark:text-blue-400 dark:hover:bg-blue-900/20"
                                                                title="Edit"
                                                            >
                                                                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                                                                </svg>
                                                            </button>
                                                            <button 
                                                                onClick={() => handleInstitutionDelete(institution)} 
                                                                className="p-1.5 text-red-600 hover:bg-red-50 rounded-md transition-all dark:text-red-400 dark:hover:bg-red-900/20"
                                                                title="Delete"
                                                            >
                                                                <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                                                </svg>
                                                            </button>
                                                        </div>
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                    );
                                })}
                                {filteredInstitutions.length === 0 && <p className="text-center text-gray-400 py-6 col-span-full text-xs">No results found.</p>}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-gray-100 dark:bg-gray-800 dark:border-gray-700 p-4">
                    <div className="flex justify-between items-center mb-3">
                        <h4 className="text-sm font-bold text-gray-800 dark:text-gray-200">State Statistics</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-1 text-[10px] w-auto">
                            {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                    <div className="space-y-2 max-h-[500px] overflow-y-auto">
                        {stateStatistics.map(([state, count], index) => (
                            <div key={state} className={`p-2 rounded-lg flex justify-between items-center ${index % 2 === 0 ? 'bg-green-50 dark:bg-green-900/20' : 'bg-gray-50 dark:bg-gray-700'}`}>
                                <span className="font-bold text-gray-700 dark:text-gray-200 text-xs truncate max-w-[120px]">{state}</span>
                                <span className="font-mono font-black text-green-800 dark:text-green-300 text-sm">{count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StudentManagement;

import React, { useState, useContext, useMemo, useEffect, useRef } from 'react';
import { User, UserRole } from '../types';
import Logo from './Logo';
import { AppContext } from '../App';
import { isSmartMatch } from '../utils/searchUtils';
import Modal from './Modal';

interface LoginScreenProps {
  onLogin: (user: User) => void;
}

const REMEMBER_SUPERVISOR_KEY = 'hafiz_rem_sup';
const REMEMBER_IMMUNIZATION_KEY = 'hafiz_rem_imm';
const REMEMBER_INSTITUTION_PREFIX = 'hafiz_rem_inst_';

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const context = useContext(AppContext);
  if (!context) return null;

  const { users, supervisorPassword, immunizationPassword, appName, darkMode, toggleDarkMode, updateInstitution } = context;

  const [mode, setMode] = useState<'initial' | 'supervisor' | 'institution' | 'immunization'>('initial');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState('');
  const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

  // Institution Login State
  const [selectedInstitution, setSelectedInstitution] = useState<User | null>(null);
  const [pinInput, setPinInput] = useState('');
  const [rememberPin, setRememberPin] = useState(false);
  const [showPinChangeModal, setShowPinChangeModal] = useState(false);
  const [newPin, setNewPin] = useState('');
  const [confirmNewPin, setConfirmNewPin] = useState('');
  const [pinChangeError, setPinChangeError] = useState('');

  const passwordInputRef = useRef<HTMLInputElement>(null);
  const pinInputRef = useRef<HTMLInputElement>(null);
  const newPinInputRef = useRef<HTMLInputElement>(null);
  const confirmNewPinInputRef = useRef<HTMLInputElement>(null);

  // Filter users by INSTITUTION role
  const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

  useEffect(() => {
    if (mode === 'supervisor') {
      const saved = localStorage.getItem(REMEMBER_SUPERVISOR_KEY);
      if (saved) {
        setPassword(saved);
        setRememberMe(true);
        if (passwordInputRef.current) passwordInputRef.current.blur();
      } else {
        setPassword('');
        setRememberMe(false);
        setTimeout(() => {
            if (passwordInputRef.current) passwordInputRef.current.focus();
        }, 50);
      }
    } else if (mode === 'immunization') {
      const saved = localStorage.getItem(REMEMBER_IMMUNIZATION_KEY);
      if (saved) {
        setPassword(saved);
        setRememberMe(true);
        if (passwordInputRef.current) passwordInputRef.current.blur();
      } else {
        setPassword('');
        setRememberMe(false);
        setTimeout(() => {
            if (passwordInputRef.current) passwordInputRef.current.focus();
        }, 50);
      }
    }
  }, [mode]);

  useEffect(() => {
    if (selectedInstitution) {
        const savedPin = localStorage.getItem(`${REMEMBER_INSTITUTION_PREFIX}${selectedInstitution.id}`);
        if (savedPin) {
            setPinInput(savedPin);
            setRememberPin(true);
        } else {
            setPinInput('');
            setRememberPin(false);
        }

        if (pinInputRef.current) {
            setTimeout(() => pinInputRef.current?.focus(), 50);
        }
    }
  }, [selectedInstitution]);

  const handleLoginAttempt = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (mode === 'supervisor') {
      if (password === supervisorPassword) {
        if (rememberMe) {
          localStorage.setItem(REMEMBER_SUPERVISOR_KEY, password);
        } else {
          localStorage.removeItem(REMEMBER_SUPERVISOR_KEY);
        }

        const supervisor = users.find(u => u.role === UserRole.SUPERVISOR);
        if (supervisor) {
            onLogin(supervisor);
        } else {
            onLogin({
                id: 1,
                name: 'Main Supervisor',
                role: UserRole.SUPERVISOR,
                updatedAt: Date.now()
            });
        }
      } else setError('Incorrect supervisor password');
    } else if (mode === 'immunization') {
        if (password === immunizationPassword) {
            if (rememberMe) {
                localStorage.setItem(REMEMBER_IMMUNIZATION_KEY, password);
            } else {
                localStorage.removeItem(REMEMBER_IMMUNIZATION_KEY);
            }

            const immunizationUser: User = {
                id: 999,
                name: 'Immunization Dept. Manager',
                role: UserRole.IMMUNIZATION,
                updatedAt: Date.now()
            };
            onLogin(immunizationUser);
        } else setError('Incorrect Immunization Dept. password');
    }
  };

  const handleInstitutionSelect = (institution: User) => {
      setSelectedInstitution(institution);
      setError('');
  };

  const handleInstitutionPinSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!selectedInstitution) return;

      const userPin = selectedInstitution.pin || '123';

      if (pinInput === userPin) {
          const key = `${REMEMBER_INSTITUTION_PREFIX}${selectedInstitution.id}`;
          if (rememberPin) {
              localStorage.setItem(key, pinInput);
          } else {
              localStorage.removeItem(key);
          }

          if (selectedInstitution.isDefaultPin) {
              setShowPinChangeModal(true);
          } else {
              onLogin(selectedInstitution);
          }
      } else {
          setError('Incorrect PIN');
      }
  };

  const handlePinChangeSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!selectedInstitution) return;

      if (newPin.length < 3) {
          setPinChangeError('PIN must be at least 3 digits');
          return;
      }
      if (newPin !== confirmNewPin) {
          setPinChangeError('PINs do not match');
          return;
      }
      if (newPin === '123') {
          setPinChangeError('Cannot use the default PIN');
          return;
      }

      const updatedUser = {
          ...selectedInstitution,
          pin: newPin,
          isDefaultPin: false,
          updatedAt: Date.now()
      };

      updateInstitution(updatedUser);
      setShowPinChangeModal(false);
      onLogin(updatedUser);
  };

  const handleNewPinKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
        e.preventDefault();
        confirmNewPinInputRef.current?.focus();
    }
  };

  const filteredInstitutions = useMemo(() => {
    return institutions
      .filter(t => isSmartMatch(t.name, institutionSearchTerm))
      .sort((a, b) => a.name.localeCompare(b.name, 'en'));
  }, [institutions, institutionSearchTerm]);

  return (
    <div className="flex flex-col items-center justify-center flex-1 p-4">
      <button 
        onClick={toggleDarkMode} 
        className="absolute top-6 left-6 p-3 rounded-full bg-white shadow-xl dark:bg-gray-800 dark:text-yellow-400 border-2 border-gray-200 dark:border-gray-700 transition-all active:scale-90 z-50 text-xl"
      >
        {darkMode ? '☀️' : '🌙'}
      </button>

      {showPinChangeModal && (
          <Modal title="Change PIN" onClose={() => setShowPinChangeModal(false)} hideDefaultCloseButton={true}>
              <form onSubmit={handlePinChangeSubmit} className="space-y-4">
                  <div className="bg-yellow-50 text-yellow-800 p-3 rounded-lg text-sm mb-4">
                      <strong>Notice:</strong> This is your first login. You must change the default PIN (123) for security.
                  </div>
                  {pinChangeError && <p className="text-red-600 text-sm font-bold">{pinChangeError}</p>}
                  <div>
                      <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">New PIN</label>
                      <input 
                        ref={newPinInputRef}
                        type="password" 
                        value={newPin} 
                        onChange={e => setNewPin(e.target.value)} 
                        className="input-style" 
                        placeholder="****" 
                        onKeyDown={handleNewPinKeyDown}
                        autoFocus 
                      />
                  </div>
                  <div>
                      <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">Confirm PIN</label>
                      <input 
                        ref={confirmNewPinInputRef}
                        type="password" 
                        value={confirmNewPin} 
                        onChange={e => setConfirmNewPin(e.target.value)} 
                        className="input-style" 
                        placeholder="****" 
                      />
                  </div>
                  <button type="submit" className="w-full py-3 bg-green-700 text-white rounded-xl font-bold hover:bg-green-800">Save & Login</button>
              </form>
          </Modal>
      )}

      <div className="w-full max-w-md p-10 bg-white rounded-[2.5rem] text-center golden-frame dark:bg-slate-900 animate-fade-in relative">
        <Logo className="h-28 w-28 mx-auto mb-6 drop-shadow-lg" />
        <h1 className="text-4xl font-extrabold text-green-900 dark:text-green-400 mb-10">{appName}</h1>

        {mode === 'initial' && (
          <div className="space-y-5">
            <button onClick={() => setMode('supervisor')} className="w-full py-5 text-xl font-extrabold text-white bg-green-700 rounded-2xl hover:bg-green-800 transition-all shadow-[0_8px_0_rgb(5,150,105)] active:translate-y-1 active:shadow-none">Supervisor</button>
            <button onClick={() => setMode('institution')} className="w-full py-5 text-xl font-extrabold text-green-800 bg-white rounded-2xl border-4 border-green-700 hover:bg-green-50 transition-all dark:bg-slate-800 dark:text-green-300 dark:border-green-600">Institution</button>
            <button onClick={() => setMode('immunization')} className="w-full py-5 text-xl font-extrabold text-white bg-blue-600 rounded-2xl hover:bg-blue-700 transition-all shadow-md active:translate-y-1 active:shadow-none">Immunization Dept</button>
          </div>
        )}

        {(mode === 'supervisor' || mode === 'immunization') && (
          <form onSubmit={handleLoginAttempt} className="space-y-6">
            <h3 className="text-2xl font-bold text-gray-800 dark:text-white underline decoration-gold-light underline-offset-8 decoration-4">
                {mode === 'supervisor' ? 'Supervisor Login' : 'Immunization Dept. Login'}
            </h3>

            <div className="space-y-4 text-left">
              <input
                ref={passwordInputRef}
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Enter password"
                className="input-style text-center text-3xl tracking-[0.5rem] font-bold placeholder:text-xl"
              />

              <label className="flex items-center gap-3 cursor-pointer p-1">
                <input 
                  type="checkbox" 
                  checked={rememberMe} 
                  onChange={e => setRememberMe(e.target.checked)}
                  className="w-6 h-6 rounded border-gray-300 text-green-700 focus:ring-green-500 dark:bg-gray-700 dark:border-gray-600"
                />
                <span className="text-lg font-bold text-gray-700 dark:text-gray-300">Remember Password</span>
              </label>
            </div>

            {error && <p className="text-red-600 dark:text-red-400 text-base font-black animate-pulse">{error}</p>}

            <div className="flex gap-3">
              <button type="button" onClick={() => {setMode('initial'); setError(''); setPassword('');}} className="flex-1 py-4 text-lg font-bold bg-gray-200 dark:bg-gray-700 dark:text-white rounded-2xl hover:bg-gray-300 transition-all">Back</button>
              <button type="submit" className="flex-[2] py-4 text-lg font-bold text-white bg-green-700 rounded-2xl hover:bg-green-800 shadow-lg transition-all">Login</button>
            </div>
          </form>
        )}

        {mode === 'institution' && !selectedInstitution && (
          <div className="space-y-4">
            <div className="relative">
              <input type="text" placeholder="Search institution..." value={institutionSearchTerm} onChange={e => setInstitutionSearchTerm(e.target.value)} className="input-style pl-12 py-3" />
              <svg className="absolute left-4 top-4 h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
            <div className="max-h-[300px] overflow-y-auto border-2 border-gray-100 rounded-2xl p-1 bg-gray-50 dark:bg-slate-800 dark:border-slate-700 custom-scrollbar">
              {filteredInstitutions.map(t => (
                <button key={t.id} onClick={() => handleInstitutionSelect(t)} className="w-full text-left p-2.5 px-4 hover:bg-green-600 hover:text-white dark:hover:bg-green-700 rounded-xl border-b dark:border-slate-700 last:border-0 font-bold text-lg transition-colors truncate">{t.name}</button>
              ))}
              {filteredInstitutions.length === 0 && <p className="p-10 text-gray-400">No institution with this name</p>}
            </div>
            <button onClick={() => setMode('initial')} className="w-full py-4 text-lg font-bold bg-gray-200 dark:bg-gray-700 dark:text-white rounded-2xl">Back</button>
          </div>
        )}

        {mode === 'institution' && selectedInstitution && (
             <form onSubmit={handleInstitutionPinSubmit} className="space-y-6">
                <h3 className="text-xl font-bold text-gray-800 dark:text-white">Login: <br/><span className="text-green-700 dark:text-green-400">{selectedInstitution.name}</span></h3>

                <div className="space-y-2">
                    <input
                        ref={pinInputRef}
                        type="password"
                        value={pinInput}
                        onChange={e => setPinInput(e.target.value)}
                        placeholder="Enter PIN"
                        className="input-style text-center text-xl tracking-[0.5rem] font-bold"
                    />
                    <div className="flex justify-start items-center text-sm mt-2">
                        <label className="flex items-center gap-2 cursor-pointer p-1">
                            <input 
                                type="checkbox" 
                                checked={rememberPin} 
                                onChange={e => setRememberPin(e.target.checked)}
                                className="w-5 h-5 rounded border-gray-300 text-green-700 focus:ring-green-500 dark:bg-gray-700 dark:border-gray-600"
                            />
                            <span className="font-bold text-gray-700 dark:text-gray-300">Remember PIN</span>
                        </label>
                    </div>
                </div>

                {error && <p className="text-red-600 dark:text-red-400 text-base font-black animate-pulse">{error}</p>}

                <div className="flex gap-3">
                    <button type="button" onClick={() => setSelectedInstitution(null)} className="flex-1 py-4 text-lg font-bold bg-gray-200 dark:bg-gray-700 dark:text-white rounded-2xl hover:bg-gray-300 transition-all">Change</button>
                    <button type="submit" className="flex-[2] py-4 text-lg font-bold text-white bg-green-700 rounded-2xl hover:bg-green-800 shadow-lg transition-all">Login</button>
                </div>
             </form>
        )}
      </div>

      <div className="mt-8 text-[11px] font-bold text-gray-400/80 dark:text-gray-600 select-none text-center">
        Designed by: Health Information Management Department - Ad Dhahirah
      </div>
    </div>
  );
};

