                    </div>
                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Customize Logo</h4>
                        <div className="flex flex-col items-center gap-4">
                            {customLogo ? (
                                <div className="relative group">
                                    <img src={customLogo} alt="Logo" className="h-32 w-32 object-contain border rounded-lg bg-white" />
