                                    No Logo
                                </div>
                            )}
                            <label className="cursor-pointer bg-blue-50 text-blue-700 px-4 py-2 rounded-lg hover:bg-blue-100 transition-colors font-semibold dark:bg-blue-900/30 dark:text-blue-200">
                                Upload New Logo
                                <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
