    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    // Aggregation Logic
    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();

        if (!newStateName.trim()) {
            showMessage('⚠️ Please enter the Wilayat name.', true);
            return;
        }

        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) successfully.`);
            }
        } else {
            showMessage('⚠️ Please enter at least one institution name.', true);
        }
    };

    const handleUpdateInstitution = (institution: User, newName: string, newState: string) => {
        if (!newState.trim()) {
            showMessage('⚠️ Wilayat name cannot be empty.', true);
            return;
        }
        if (newName.trim()) {
            updateInstitution({ 
                ...institution, 
                name: newName.trim(), 
                state: newState.trim(),
                updatedAt: Date.now() 
            });
        }
        setEditingInstitution(null);
        showMessage('✅ Updated successfully.');
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Deletion',
            message: `Are you sure you want to delete "${institution.name}"? This action is permanent.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;
        const updatedPopulation = {
            ...(selectedInstitutionForPop.population || {}),
            [popYear]: Number(popCount)
        };
        updateInstitution({ 
            ...selectedInstitutionForPop, 
            population: updatedPopulation,
            updatedAt: Date.now()
        });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population saved.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-4 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-4 text-base font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-5 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-5 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700">Confirm</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-3">
                        <div className="flex gap-2 items-end">
                            <div className="flex-1">
                                <label className="block text-[10px] font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style py-1 text-sm">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-[10px] font-bold mb-1">Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style py-1 text-sm" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-1 px-4 bg-green-600 text-white rounded-lg font-bold h-[38px] text-xs">Save</button>
                        </div>
                        <div className="mt-2 border-t pt-2 dark:border-gray-700">
                            <div className="max-h-32 overflow-y-auto">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-[11px]">
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b dark:border-gray-600 last:border-0">
                                                    <td className="py-1 font-bold">{year}</td>
                                                    <td className="py-1 text-right font-mono">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-xs text-center">No data</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print min-h-[32px]">
                <h3 className="text-lg font-extrabold text-green-900 dark:text-green-300">Institutions List</h3>
                {message && (
                    <span className={`text-[10px] font-bold px-2 py-1 rounded-full animate-pulse ${message.isError ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-3">
                <div className="lg:col-span-3 space-y-3">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-3 border-b dark:border-gray-700 bg-gray-50/50">
                            <form onSubmit={handleAddInstitution} className="flex flex-col sm:flex-row gap-2">
                                <input type="text" value={newStateName} onChange={(e) => setNewStateName(e.target.value)} placeholder="Wilayat Name *" className="input-style sm:w-1/4 py-1.5 text-xs" list="states-list" required />
                                <datalist id="states-list">{uniqueStates.map(s => <option key={s} value={s} />)}</datalist>
                                <textarea ref={newInstitutionInputRef} value={newInstitutionName} onChange={(e) => setNewInstitutionName(e.target.value)} placeholder="Institutions (one per line)..." className="input-style flex-grow py-1.5 text-xs" rows={1} onFocus={handleInputFocus} required />
                                <button type="submit" className="px-4 py-1.5 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 text-[11px] whitespace-nowrap">Add New</button>
                            </form>
                        </div>

                        <div className="p-3 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
                            <div className="relative mb-3">
                                <input ref={institutionSearchInputRef} type="text" placeholder="Search..." value={institutionSearchTerm} onChange={(e) => setInstitutionSearchTerm(e.target.value)} className="input-style w-full pl-8 py-1.5 text-xs" onFocus={handleInputFocus} />
                                <svg className="absolute left-2.5 top-2 h-3.5 w-3.5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-1.5 max-h-[400px] overflow-y-auto custom-scrollbar">
                                {filteredInstitutions.map(institution => {
                                    const isEditing = editingInstitution?.id === institution.id;
                                    return (
                                        <div key={institution.id} className="p-2 bg-gray-50/50 rounded-lg border border-gray-100 dark:bg-gray-700/30 dark:border-gray-600 hover:border-green-300 transition-all group">
                                            {isEditing ? (
                                                <div className="space-y-1 animate-fade-in">
                                                    <input type="text" defaultValue={institution.state || ''} placeholder="State" id={`edit-state-${institution.id}`} className="input-style text-[10px] py-1" />
                                                    <input type="text" defaultValue={institution.name} id={`edit-name-${institution.id}`} className="input-style text-[10px] py-1" />
                                                    <div className="flex gap-1">
                                                        <button onClick={() => {
                                                            const nameVal = (document.getElementById(`edit-name-${institution.id}`) as HTMLInputElement).value;
                                                            const stateVal = (document.getElementById(`edit-state-${institution.id}`) as HTMLInputElement).value;
                                                            handleUpdateInstitution(institution, nameVal, stateVal);
                                                        }} className="flex-1 bg-green-600 text-white py-1 rounded font-bold text-[9px]">OK</button>
                                                        <button onClick={() => setEditingInstitution(null)} className="flex-1 bg-gray-200 text-gray-700 py-1 rounded font-bold text-[9px]">X</button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex flex-col h-full justify-between gap-1">
                                                    <div>
                                                        <span className="text-[8px] text-indigo-600 dark:text-indigo-400 font-black bg-indigo-50 dark:bg-indigo-900/40 px-1 rounded block w-fit mb-0.5">{institution.state || '—'}</span>
                                                        <p className="font-bold text-gray-800 dark:text-gray-100 text-[11px] leading-tight truncate" title={institution.name}>{institution.name}</p>
                                                    </div>
                                                    <div className="flex justify-between items-center pt-1 mt-1 border-t border-gray-100 dark:border-gray-600">
                                                        <button onClick={() => setSelectedInstitutionForPop(institution)} className="text-[9px] font-bold text-green-700 hover:underline">
                                                            👥 {institution.population?.[new Date().getFullYear()] || 0}
                                                        </button>
                                                        <div className="flex gap-1">
                                                            <button onClick={() => setEditingInstitution(institution)} className="p-1 text-blue-500 hover:bg-blue-50 rounded transition-all"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button>
                                                            <button onClick={() => handleInstitutionDelete(institution)} className="p-1 text-red-500 hover:bg-red-50 rounded transition-all"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-gray-100 dark:bg-gray-800 p-3">
                    <div className="flex justify-between items-center mb-2">
                        <h4 className="text-xs font-bold text-gray-800 dark:text-gray-200">Stats</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-0.5 px-1 text-[9px] w-auto">
                            {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                    <div className="space-y-1 max-h-[400px] overflow-y-auto">
                        {stateStatistics.map(([state, count], idx) => (
                            <div key={state} className={`p-1.5 rounded flex justify-between items-center ${idx % 2 === 0 ? 'bg-green-50/50' : 'bg-transparent'}`}>
                                <span className="font-bold text-gray-700 dark:text-gray-300 text-[10px] truncate max-w-[80px]">{state}</span>
                                <span className="font-mono font-black text-green-800 text-[10px]">{count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

