                            </div>
                        </div>
                    )}

                     <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Data Management</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2 dark:border-gray-500">Import & Export Institutions & Population</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={handleDownloadImportTemplate} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors dark:bg-gray-600 dark:border-gray-500 dark:text-gray-200 dark:hover:bg-gray-500">📄 Download Blank Template (Excel)</button>
                                    <button onClick={handleExportInstitutionsForPopulation} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors dark:bg-gray-600 dark:border-gray-500 dark:text-gray-200 dark:hover:bg-gray-500">📤 Export All Population (All Years)</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-green-50 border border-green-300 rounded-md hover:bg-green-100 transition-colors dark:bg-green-900/30 dark:border-green-800 dark:text-green-200 dark:hover:bg-green-800">📥 Import/Update from Excel File<input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" /></label>
                                </div>
                            </div>
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2 dark:border-gray-500">Full Backup</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => handleExportFullBackup(false)} className="w-full text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 transition-colors dark:bg-blue-900 dark:border-blue-800 dark:text-blue-200 dark:hover:bg-blue-800">💾 Export Full Backup</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 transition-colors dark:bg-blue-900 dark:border-blue-800 dark:text-blue-200 dark:hover:bg-blue-800">📂 Restore from Full Backup<input type="file" accept=".xlsx" onChange={handleImportFullBackup} className="hidden" /></label>
                                     {(!isPublishedConnected && !firebaseConfig) && (
                                         <button onClick={handleLoadMockData} className="w-full text-left px-4 py-2 bg-yellow-50 border border-yellow-200 text-yellow-800 rounded-md hover:bg-yellow-100 transition-colors dark:bg-yellow-900 dark:border-yellow-800 dark:text-yellow-200 dark:hover:bg-yellow-800">
                                            🧪 Load Mock Data (for testing)
                                         </button>
                                     )}
                                </div>
                            </div>
                         </div>
                        <div className="mt-8 pt-6 border-t border-gray-300 dark:border-gray-500">
                            <h5 className="font-medium text-red-700 mb-4 dark:text-red-400 text-center">Danger Zone</h5>
                            <div className="flex flex-col sm:flex-row gap-4">
                                <button onClick={handleDeleteReports} className="flex-1 px-4 py-3 bg-red-100 text-red-700 border border-red-200 rounded-md hover:bg-red-200 transition-colors font-semibold dark:bg-red-900 dark:border-red-800 dark:text-red-200 dark:hover:bg-red-800">🗑️ Delete All Reports Only</button>
                                <button onClick={handleDeleteAllData} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors font-semibold shadow-sm">⚠️ Reset Entire Program</button>
                            </div>
                        </div>
                    </div>

                    <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                        <h4 className="text-lg font-semibold text-indigo-900 mb-2 dark:text-indigo-200">Distribute a Copy of the App</h4>
                        <p className="text-sm text-indigo-700 mb-6 dark:text-indigo-300">You can download a standalone HTML copy or copy the code to send to others or run on other devices.</p>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300 border-b border-indigo-100 pb-2">Blank Version (New App)</p>
                                <div className="flex flex-col gap-3">
                                    <button onClick={handleDownloadDistributableEmpty} className="w-full px-4 py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl hover:bg-indigo-50 transition-all font-bold shadow-sm flex items-center justify-center gap-2">
                                        ⬇️ Download Version
                                    </button>
                                    <button onClick={() => handleCopyHtml('empty')} className={`w-full px-4 py-3 border rounded-xl transition-all font-bold flex items-center justify-center gap-2 ${copyState === 'empty' ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-indigo-600 text-white border-indigo-700 hover:bg-indigo-700 shadow-sm'}`}>
                                        {copyState === 'empty' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                    </button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300 border-b border-indigo-100 pb-2">Connected Version (with your data)</p>
                                <div className="flex flex-col gap-3">
                                    <button onClick={handleDownloadDistributableConnected} className="w-full px-4 py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl hover:bg-indigo-50 transition-all font-bold shadow-sm flex items-center justify-center gap-2">
                                        ⬇️ Download Version (ZIP)
                                    </button>
                                    <button onClick={() => handleCopyHtml('connected')} className={`w-full px-4 py-3 border rounded-xl transition-all font-bold flex items-center justify-center gap-2 ${copyState === 'connected' ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-indigo-600 text-white border-indigo-700 hover:bg-indigo-700 shadow-sm'}`}>
                                        {copyState === 'connected' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                    </button>
                                </div>
                            </div>
                        </div>
                        <p className="text-[11px] text-indigo-600 mt-6 dark:text-indigo-400 bg-white/50 dark:bg-gray-800/50 p-3 rounded-lg border border-indigo-100 dark:border-indigo-900">
                            * <strong>Blank Version:</strong> A brand new app for standalone use or connecting to a new database.<br/>
                            * <strong>Connected Version:</strong> Updated code containing your current data and connected to your database (suitable for publishing on Google Sites).
