    const { users, addInstitution, updateInstitution, deleteInstitution } = context;

    const [newInstitutionName, setNewInstitutionName] = useState('');
    const [newStateName, setNewStateName] = useState(''); 
    const [editingInstitution, setEditingInstitution] = useState<User | null>(null);
    const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

    // Population Modal State
    const [selectedInstitutionForPop, setSelectedInstitutionForPop] = useState<User | null>(null);
    const [popYear, setPopYear] = useState<number>(new Date().getFullYear());
    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    // Aggregation Logic
    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newStateName.trim()) { showMessage('⚠️ Please enter the Wilayat name.', true); return; }
        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) successfully.`);
            }
        } else { showMessage('⚠️ Please enter at least one institution name.', true); }
    };

    const handleUpdateInstitution = (institution: User, newName: string, newState: string) => {
        if (!newState.trim()) { showMessage('⚠️ Wilayat name cannot be empty.', true); return; }
        if (newName.trim()) { updateInstitution({ ...institution, name: newName.trim(), state: newState.trim(), updatedAt: Date.now() }); }
        setEditingInstitution(null);
        showMessage('✅ Updated successfully.');
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Deletion',
            message: `Are you sure you want to delete "${institution.name}"? This action is permanent.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;
        const updatedPopulation = { ...(selectedInstitutionForPop.population || {}), [popYear]: Number(popCount) };
        updateInstitution({ ...selectedInstitutionForPop, population: updatedPopulation, updatedAt: Date.now() });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population saved.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { setTimeout(() => { e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 250); }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-6 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-6 text-xl font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 pt-6 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-8 py-3 bg-gray-200 text-gray-800 rounded-xl font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-8 py-3 bg-red-600 text-white rounded-xl font-bold hover:bg-red-700 shadow-lg">Confirm</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-4">
                        <div className="flex gap-3 items-end">
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style py-2">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-sm font-bold mb-1">Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style py-2" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-2 px-6 bg-green-600 text-white rounded-xl font-bold h-[50px] shadow-md">Save</button>
                        </div>
                        <div className="mt-2 border-t pt-4 dark:border-gray-700">
                            <div className="max-h-48 overflow-y-auto custom-scrollbar">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-base">
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b dark:border-gray-600 last:border-0">
                                                    <td className="py-3 font-bold">{year}</td>
                                                    <td className="py-3 text-right font-mono font-bold text-green-700 dark:text-green-400">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-center py-4">No data recorded</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print">
                <h3 className="text-3xl font-black text-green-900 dark:text-green-300">Management</h3>
                {message && (
                    <span className={`text-sm font-bold px-4 py-2 rounded-full animate-pulse shadow-sm ${message.isError ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                <div className="lg:col-span-3 space-y-6">
                    <div className="bg-white rounded-3xl shadow-xl border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-8 border-b dark:border-gray-700 bg-gray-50/50">
                            <form onSubmit={handleAddInstitution} className="flex flex-col gap-5">
                                <div className="flex flex-col sm:flex-row gap-4">
                                    <input type="text" value={newStateName} onChange={(e) => setNewStateName(e.target.value)} placeholder="Wilayat Name *" className="input-style sm:w-1/3 text-lg" list="states-list" required />
                                    <datalist id="states-list">{uniqueStates.map(s => <option key={s} value={s} />)}</datalist>
                                    <textarea ref={newInstitutionInputRef} value={newInstitutionName} onChange={(e) => setNewInstitutionName(e.target.value)} placeholder="Enter institution names (one per line)..." className="input-style flex-grow text-lg" rows={1} onFocus={handleInputFocus} required />
                                </div>
                                <button type="submit" className="self-end px-10 py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 transition-all shadow-lg active:scale-95 text-lg">Add New Institutions</button>
                            </form>
                        </div>

                        <div className="p-8 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
                            <div className="relative mb-8">
                                <input ref={institutionSearchInputRef} type="text" placeholder="Search institutions..." value={institutionSearchTerm} onChange={(e) => setInstitutionSearchTerm(e.target.value)} className="input-style w-full pl-14 py-4 text-xl" onFocus={handleInputFocus} />
                                <svg className="absolute left-5 top-5 h-8 w-8 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[700px] overflow-y-auto custom-scrollbar p-1">
                                {filteredInstitutions.map(institution => {
                                    const isEditing = editingInstitution?.id === institution.id;
                                    return (
                                        <div key={institution.id} className="p-8 bg-gray-50/50 rounded-[2rem] border-2 border-gray-100 dark:bg-gray-700/40 dark:border-gray-600 hover:border-green-400 dark:hover:border-green-500 transition-all group flex flex-col justify-between shadow-sm hover:shadow-xl">
                                            {isEditing ? (
                                                <div className="space-y-4 animate-fade-in">
                                                    <input type="text" defaultValue={institution.state || ''} placeholder="Wilayat" id={`edit-state-${institution.id}`} className="input-style text-lg py-3" />
                                                    <input type="text" defaultValue={institution.name} id={`edit-name-${institution.id}`} className="input-style text-lg py-3 font-bold" />
                                                    <div className="flex gap-3">
                                                        <button onClick={() => {
                                                            const nameVal = (document.getElementById(`edit-name-${institution.id}`) as HTMLInputElement).value;
                                                            const stateVal = (document.getElementById(`edit-state-${institution.id}`) as HTMLInputElement).value;
                                                            handleUpdateInstitution(institution, nameVal, stateVal);
                                                        }} className="flex-1 bg-green-600 text-white py-3 rounded-xl font-black text-base shadow-md">SAVE</button>
                                                        <button onClick={() => setEditingInstitution(null)} className="flex-1 bg-gray-200 text-gray-700 py-3 rounded-xl font-black text-base">CANCEL</button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <div className="flex flex-col h-full justify-between gap-6">
                                                    <div>
                                                        <span className="text-xs text-indigo-700 dark:text-indigo-300 font-black bg-indigo-100 dark:bg-indigo-900/60 px-3 py-1 rounded-full inline-block mb-3 uppercase tracking-wider">{institution.state || '—'}</span>
                                                        <h4 className="font-black text-gray-900 dark:text-gray-100 text-2xl leading-tight" title={institution.name}>{institution.name}</h4>
                                                    </div>
                                                    <div className="flex justify-between items-center pt-6 mt-2 border-t-2 border-gray-100 dark:border-gray-600">
                                                        <button onClick={() => setSelectedInstitutionForPop(institution)} className="text-sm font-black text-green-700 dark:text-green-400 bg-green-50 dark:bg-green-900/30 px-4 py-2 rounded-xl hover:bg-green-100 transition-all border border-green-200 dark:border-green-800">
                                                            👥 Pop: {institution.population?.[new Date().getFullYear()]?.toLocaleString() || 0}
                                                        </button>
                                                        <div className="flex gap-3">
                                                            <button onClick={() => setEditingInstitution(institution)} className="p-3 text-blue-600 hover:bg-blue-50 dark:text-blue-400 dark:hover:bg-blue-900/30 rounded-2xl transition-all shadow-sm"><svg className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button>
                                                            <button onClick={() => handleInstitutionDelete(institution)} className="p-3 text-red-600 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/30 rounded-2xl transition-all shadow-sm"><svg className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {filteredInstitutions.length === 0 && <p className="text-center text-gray-400 py-20 col-span-full text-xl font-bold">No results found.</p>}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-3xl shadow-xl border border-gray-100 dark:bg-gray-800 p-6 self-start">
                    <div className="flex justify-between items-center mb-6">
                        <h4 className="text-xl font-black text-gray-900 dark:text-gray-100">Statistics</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-1 px-2 text-sm w-auto font-bold">
                            {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                    <div className="space-y-2 max-h-[600px] overflow-y-auto custom-scrollbar">
                        {stateStatistics.map(([state, count], idx) => (
                            <div key={state} className={`p-4 rounded-2xl flex justify-between items-center transition-colors ${idx % 2 === 0 ? 'bg-green-50/50 dark:bg-green-900/20' : 'bg-transparent'}`}>
                                <span className="font-black text-gray-700 dark:text-gray-300 text-sm truncate max-w-[120px]">{state}</span>
                                <span className="font-mono font-black text-green-800 dark:text-green-400 text-lg">{count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

