const resizeImage = (file: File, maxWidth: number, maxHeight: number, quality: number, callback: (dataUrl: string | null) => void) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
        const image = new Image();
        image.onload = () => {
            const canvas = document.createElement('canvas');
            let width = image.width; let height = image.height;
            if (width > height) { if (width > maxWidth) { height *= maxWidth / width; width = maxWidth; } }
            else { if (height > maxHeight) { width *= maxHeight / height; height = maxHeight; } }
            canvas.width = width; canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(image, 0, 0, width, height);
                const dataUrl = canvas.toDataURL(file.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', quality);
                callback(dataUrl);
            } else callback(null);
        };
        image.src = readerEvent.target?.result as string;
    };
    reader.readAsDataURL(file);
};

