    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => { 
      setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const handleCancel = () => { if (!isProcessing) setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} }); };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try { await navigator.clipboard.writeText(text); return true; } catch (err) { console.error(err); }
      }
      try {
        const textArea = document.createElement("textarea");
        textArea.value = text; textArea.style.position = "fixed"; textArea.style.left = "-9999px";
        document.body.appendChild(textArea); textArea.select();
        const successful = document.execCommand('copy'); document.body.removeChild(textArea);
        return successful;
      } catch (err) { return false; }
    };

    const handleDeleteReports = () => {
        confirmAction('Delete Reports', 'Are you sure you want to delete all reports? A full backup will be downloaded first.',
            async () => { await handleExportFullBackup(true); await deleteAllReports(); setMessage({ type: 'success', text: 'All reports deleted.' }); }
        );
    };

    const handleDeleteAllData = () => {
        confirmAction('Reset App', 'Warning: This will delete EVERYTHING. A backup will be downloaded first.',
            async () => { await handleExportFullBackup(true); await deleteAllData(); setMessage({ type: 'success', text: 'Program reset successfully.' }); }
        );
    };

    const handleLoadMockData = () => {
        confirmAction('Load Test Data', 'This will replace all current data with mock records. Are you sure?',
            async () => { loadMockData(); setMessage({ type: 'success', text: 'Mock data loaded. Please refresh if not visible.' }); }
        );
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        if(!isSilent) setMessage({ type: 'success', text: 'Exporting full backup...' });
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: context.firebaseConfig }, 'EPI_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ Backup exported.' });
    };

    const handleImportFullBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]; if (!file || !handleImportFullBackupFile) return;
        confirmAction('Restore Backup', 'Warning: This will replace all current data.',
            async () => { 
                try {
                    const importedData = await importFullBackup(file);
                    handleImportFullBackupFile(importedData);
                    setMessage({ type: 'success', text: 'Backup restored successfully.' });
                } catch (error: any) { setMessage({ type: 'error', text: error.message || 'Failed to import.' }); }
