                <Modal title={confirmationModal.title} onClose={handleCancel} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-xl font-bold py-8">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-6 mt-6 pt-6 border-t dark:border-gray-700">
                        <button onClick={handleCancel} disabled={isProcessing} className="px-10 py-3 bg-gray-200 text-gray-800 rounded-2xl font-black hover:bg-gray-300">CANCEL</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className="px-10 py-3 bg-red-600 text-white rounded-2xl font-black hover:bg-red-700 shadow-lg">{isProcessing ? 'Wait...' : 'CONFIRM'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-3xl font-black text-green-900 mb-8 dark:text-green-300">Settings</h3>

            <div className="flex flex-wrap border-b-2 border-gray-100 mb-8 dark:border-gray-700">
                <button className={`px-6 py-4 font-bold text-lg transition-all ${activeSettingsView === 'main' ? 'text-green-700 border-b-4 border-green-700' : 'text-gray-400'}`} onClick={() => setActiveSettingsView('main')}>General</button>
