export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    const docClone = document.documentElement.cloneNode(true) as HTMLElement;

    // --- Critical Step for Google Sites: Clean the DOM ---
    // 1. Empty the React root to remove all rendered components, drastically reducing size.
    const rootElement = docClone.querySelector('#root');
    if (rootElement) {
        rootElement.innerHTML = '';
    }

    // 2. Remove any modal/portal elements that React may have added outside the root.
    const modals = docClone.querySelectorAll('[role="dialog"], .fixed.inset-0.z-50');
    modals.forEach(m => m.remove());

    // 3. Remove any old data or service worker registration scripts to prevent conflicts.
    const oldScripts = docClone.querySelectorAll('script');
    oldScripts.forEach(s => {
        if (s.textContent?.includes('window.embeddedAppData') || s.textContent?.includes('serviceWorker.register')) {
            s.remove();
        }
    });

    const head = docClone.querySelector('head');
    if (head) {
        if (appData.customLogo) {
            let favicon = head.querySelector('link[rel="icon"]');
            if (!favicon) { favicon = document.createElement('link'); favicon.setAttribute('rel', 'icon'); head.appendChild(favicon); }
            favicon.setAttribute('href', appData.customLogo);
        }

        let manifestLink = head.querySelector('link[rel="manifest"]');
        if (!manifestLink) { manifestLink = document.createElement('link'); manifestLink.setAttribute('rel', 'manifest'); head.appendChild(manifestLink); }
        manifestLink.setAttribute('href', 'manifest.json');
        head.insertAdjacentHTML('beforeend', `<meta name="apple-mobile-web-app-title" content="${appData.appName || 'EPI'}">`);
    }

    const swRegistrationScript = `if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>{});});}`;

    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS,
        reports: [],
        students: [], halaqas: [], evaluations: [],
        customLogo: null,
        supervisorPassword: '123',
        immunizationPassword: '12345',
        appName: appData.appName,
        isDistributable: true,
        isPublishedConnected: false,
        firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { ...appData, isDistributable: true, isPublishedConnected: true };
    }

    const encodedData = utf8ToBase64(JSON.stringify(appDataForEmbedding));
    const dataScript = `\n<script type="text/javascript">window.embeddedAppData = '${encodedData}'; ${swRegistrationScript}</script>\n`;

    let finalHtml = docClone.outerHTML;
    if (!finalHtml.trim().toLowerCase().startsWith('<!doctype html>')) {
        finalHtml = '<!DOCTYPE html>\n' + finalHtml;
    }

    const bodyEnd = '</body>';
    const index = finalHtml.toLowerCase().lastIndexOf(bodyEnd);
    if (index !== -1) {
        return finalHtml.slice(0, index) + dataScript + finalHtml.slice(index);
    }
    return finalHtml + dataScript;
};

export const generateAndDownloadDistributableZip = async (appData: FullBackupData, exportType: 'empty' | 'snapshot') => {
    try {
        const zip = new JSZip();
        let localIconPath = "icon.png";
        if (appData.customLogo?.startsWith('data:image')) {
            const parts = appData.customLogo.split(',');
            if (parts.length > 1) zip.file("icon.png", parts[1], {base64: true});
        }
        const html = await getDistributableHtmlString(appData, exportType);
        zip.file("index.html", html);
        zip.file("manifest.json", JSON.stringify(generateManifest(appData.appName || "EPI", localIconPath), null, 2));
        zip.file("sw.js", serviceWorkerCode);
        const content = await zip.generateAsync({ type: "blob" });
        const url = window.URL.createObjectURL(content);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${appData.appName || 'EPI'}_${exportType}.zip`;
        a.click();
    } catch (e: any) { alert("Error: " + e.message); }
};

export const generateAndDownloadDistributableHtml = async (appData: FullBackupData, exportType: 'empty' | 'snapshot') => {
    try {
        const htmlRaw = await getDistributableHtmlString(appData, exportType);
        const manifestObj = generateManifest(appData.appName || "EPI", appData.customLogo);
        const manifestDataUrl = `data:application/manifest+json;base64,${utf8ToBase64(JSON.stringify(manifestObj))}`;
        let html = htmlRaw.replace('href="manifest.json"', `href="${manifestDataUrl}"`);
        const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${appData.appName || 'EPI'}_${exportType}.html`;
        a.click();
    } catch (e) { alert("Error generating HTML"); }
};

