export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    // --- NEW ROBUST METHOD ---
    // Fetch the original, clean index.html to use as a template.
    // This avoids all runtime modifications from React, Tailwind, etc.
    const response = await fetch(window.location.origin + '/index.html');
    if (!response.ok) {
        throw new Error('Could not fetch the base index.html file to create distributable version.');
    }
    let htmlString = await response.text();

    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS,
        reports: [],
        students: [], halaqas: [], evaluations: [],
        customLogo: null,
        supervisorPassword: '123',
        immunizationPassword: '12345',
        appName: appData.appName,
        isDistributable: true,
        isPublishedConnected: false,
        firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { ...appData, isDistributable: true, isPublishedConnected: true };
    }

    const encodedData = utf8ToBase64(JSON.stringify(appDataForEmbedding));
    // The data script is the only thing we need to inject.
    // The service worker script is already in the fetched index.html.
    const dataScript = `<script type="text/javascript">window.embeddedAppData = '${encodedData}';</script>`;

    // Inject the data script just before the closing </body> tag.
    const bodyEndTag = '</body>';
    if (htmlString.includes(bodyEndTag)) {
        htmlString = htmlString.replace(bodyEndTag, `${dataScript}\n${bodyEndTag}`);
    } else {
        // Fallback if body tag is not found for some reason
        htmlString += dataScript;
    }

    // Update title and favicon in the clean HTML string
    if (appData.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appData.appName}</title>`);
    }
    if (appData.customLogo) {
        // This regex is safer and will replace both icon and apple-touch-icon links if they use the default data URI
        htmlString = htmlString.replace(/<link rel="(icon|apple-touch-icon)".*?>/g, (match) => {
             if (match.includes('data:image/svg+xml')) {
                 return match.replace(/href=".*?"/, `href="${appData.customLogo}"`);
             }
             return match;
        });
    }

    return htmlString;
};

