const resizeImage = (
    file: File, 
    maxWidth: number, 
    maxHeight: number, 
    quality: number, 
    callback: (dataUrl: string | null) => void
) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
        const image = new Image();
        image.onload = () => {
            const canvas = document.createElement('canvas');
            let width = image.width;
            let height = image.height;

            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(image, 0, 0, width, height);
                const dataUrl = canvas.toDataURL(file.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', quality);
                callback(dataUrl);
            } else {
                callback(null);
            }
        };
        image.src = readerEvent.target?.result as string;
    };
    reader.readAsDataURL(file);
};


export const Settings: React.FC = () => {
    const context = useContext(AppContext);

    if (!context) return null;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{
      isOpen: boolean;
      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        users,
        addInstitution, updateInstitution,
        importFullBackup: handleImportFullBackupFile,
        appName, setAppName,
        isDistributable, isPublishedConnected, 
        firebaseConfig, setFirebaseConfig,
        firebaseConnectionStatus
    } = context; 

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(
        firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''
    );

    const firebaseConfigTextAreaRef = useRef<HTMLTextAreaElement>(null);
    const appNameInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => { setAppNameInput(appName); }, [appName]);
    useEffect(() => {
        setFirebaseConfigInput(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : '');
    }, [firebaseConfig]);

    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => { 
      setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const handleCancel = () => {
      if (!isProcessing) {
          setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try {
          await navigator.clipboard.writeText(text);
          return true;
        } catch (err) { console.error("Clipboard API failed:", err); }
      }
      try {
        const textArea = document.createElement("textarea");
        textArea.value = text;
        textArea.style.position = "fixed";
        textArea.style.left = "-9999px";
        textArea.style.top = "0";
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        const successful = document.execCommand('copy');
        document.body.removeChild(textArea);
        return successful;
      } catch (err) {
        console.error("Fallback copy failed:", err);
        return false;
      }
    };

    const handleDeleteReports = () => {
        confirmAction('Confirm Deleting Reports', 'Are you sure you want to delete all monthly reports? A full backup will be automatically downloaded before deletion.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllReports();
                setMessage({ type: 'success', text: 'All reports have been deleted successfully.' });
            }
        );
    }

    const handleDeleteAllData = () => {
        confirmAction('Confirm Program Reset', 'Warning: This action will download a backup and then delete all institution and report data. This action cannot be undone.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllData();
                setMessage({ type: 'success', text: 'The program has been reset successfully.' });
            }
        );
    }

    const handleLoadMockData = () => {
        confirmAction('Confirm Loading Mock Data', 'Warning: This will replace all current data with test data. Are you sure?',
            async () => { 
                loadMockData();
                setMessage({ type: 'success', text: 'Mock data loaded successfully. Refreshing list...' });
            }
        );
    };

    const handleDownloadImportTemplate = () => {
        exportSheetTemplate('Institutions_Import_Template');
        setMessage({ type: 'success', text: '✅ Template download has started.' });
    };

    const handleExportInstitutionsForPopulation = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

        const dataRows: any[] = [];
        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);

            if (years.length > 0) {
                years.forEach(y => {
                    dataRows.push({
                        institutionId: inst.id,
                        year: y,
                        population: populations[y]
                    });
                });
            } else {
                // If no pop data, export one row with current year placeholder
                dataRows.push({
                    institutionId: inst.id,
                    year: new Date().getFullYear(),
                    population: 0
                });
            }
        });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(dataRows, { header: ['institutionId', 'year', 'population'] });
        XLSX.utils.book_append_sheet(wb, ws, 'Population');
        XLSX.writeFile(wb, `Institutions_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ The population list has been exported.' });
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !setCustomLogo) return;
        setMessage({ type: 'success', text: 'Processing logo...' });
        resizeImage(file, 200, 200, 0.9, (dataUrl) => {
            if (dataUrl) {
                setCustomLogo(dataUrl);
                setMessage({ type: 'success', text: 'Logo updated successfully.' });
            } else {
                setMessage({ type: 'error', text: 'Failed to process logo.' });
            }
        });
        e.target.value = '';
    };

    const handleResetLogo = () => {
        if (setCustomLogo) {
            confirmAction('Confirm Resetting to Default Logo', 'Are you sure you want to revert to the default logo?',
                async () => {
                    setCustomLogo(null);
                    setMessage({ type: 'success', text: 'Default logo has been restored.' });
                }
            );
        }
    }

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Institution Import', 'This will add or update institutions and population data for all specified years. Are you sure?',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const json = XLSX.utils.sheet_to_json(worksheet);

                        // Local Map to consolidate data from Excel grouped by Institution Name
                        const excelDataMap = new Map<string, { state?: string, id?: number, populations: Record<number, number> }>();

                        json.forEach((row: any) => {
                            const name = (row['Institution'] || row['Name'])?.toString().trim();
                            const instId = row['institutionId'] ? Number(row['institutionId']) : undefined;
                            const state = (row['State'])?.toString().trim();
                            const year = Number(row['Year'] || row['year']);
                            const population = Number(row['Population'] || row['population']);

                            // Case 1: Search by ID if exists (preferred)
                            if (instId) {
                                const key = `id_${instId}`;
                                if (!excelDataMap.has(key)) {
                                    excelDataMap.set(key, { id: instId, populations: {} });
                                }
                                const entry = excelDataMap.get(key)!;
                                if (!isNaN(year) && !isNaN(population)) entry.populations[year] = population;
                            } 
                            // Case 2: Search by Name
                            else if (name) {
                                if (!excelDataMap.has(name)) {
                                    excelDataMap.set(name, { state, populations: {} });
                                }
                                const entry = excelDataMap.get(name)!;
                                if (!isNaN(year) && !isNaN(population)) entry.populations[year] = population;
                                if (state && !entry.state) entry.state = state;
                            }
                        });

                        let addedCount = 0;
                        let updatedCount = 0;

                        excelDataMap.forEach((val, key) => {
                            let existingInst;
                            if (val.id) {
                                existingInst = users.find(u => u.id === val.id);
                            } else {
                                existingInst = users.find(u => u.role === UserRole.INSTITUTION && u.name === key);
                            }

                            if (existingInst) {
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    state: val.state || existingInst.state,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else if (!val.id) {
                                // Add as new institution (only if ID was not provided or not found, using name as key)
                                addInstitution(key, val.state, val.populations);
                                addedCount++;
                            }
                        });

                        let resultMsg = '';
                        if (addedCount > 0) resultMsg += `✅ Added ${addedCount} institution(s). `;
                        if (updatedCount > 0) resultMsg += `🔄 Updated data for ${updatedCount} institution(s).`;
                        if (!resultMsg) resultMsg = '⚠️ No valid changes found in file.';

                        setMessage({ type: 'success', text: resultMsg });

                    } catch (error) {
                        setMessage({ type: 'error', text: 'Failed to process file contents.' });
                    }
                };
                reader.readAsBinaryString(file);
            }
        );
        e.target.value = '';
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        if(!isSilent) setMessage({ type: 'success', text: 'Exporting full backup...' });
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: context.firebaseConfig }, 'EPI_Full_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ Full backup exported.' });
    };

    const handleImportFullBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !handleImportFullBackupFile) return;

        confirmAction('Confirm Full Backup Restore', 'Warning: This will replace all current program data. This action cannot be undone.',
