        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={handleCancel} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-lg font-bold py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4 pt-4 border-t dark:border-gray-700">
                        <button onClick={handleCancel} disabled={isProcessing} className={`px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>Cancel</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className={`px-6 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300">Settings</h3>

            <div className="flex flex-wrap border-b border-gray-200 mb-6 dark:border-gray-700">
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('main')}>Main Settings</button>
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('customization')}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg whitespace-pre-line text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' : message.type === 'error' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200'}`}>{message.text}</div>}

