export const Settings: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{
      isOpen: boolean;
      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        users, addInstitution, updateInstitution,
        importFullBackup: handleImportFullBackupFile,
        appName, setAppName, firebaseConfig, setFirebaseConfig,
        isDistributable, isPublishedConnected
    } = context; 

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(
        firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''
    );

    useEffect(() => { setAppNameInput(appName); }, [appName]);
    useEffect(() => { setFirebaseConfigInput(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''); }, [firebaseConfig]);

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try { await navigator.clipboard.writeText(text); return true; } catch (err) {}
      }
      return false;
    };

    const handleExportInstitutionsForPopulation = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);
        const dataRows: any[] = [];

        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);

            if (years.length > 0) {
                years.forEach(y => {
                    dataRows.push({
                        institutionId: inst.id,
                        year: y,
                        population: populations[y]
                    });
                });
            } else {
                dataRows.push({ institutionId: inst.id, year: new Date().getFullYear(), population: 0 });
            }
        });

        const wb = XLSX.utils.book_new();
        // تصدير الأعمدة المطلوبة فقط: institutionId, year, population
        const ws = XLSX.utils.json_to_sheet(dataRows, { header: ['institutionId', 'year', 'population'] });
        XLSX.utils.book_append_sheet(wb, ws, 'Population');
        XLSX.writeFile(wb, `EPI_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ تم تصدير بيانات السكان بنجاح.' });
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setConfirmationModal({
            isOpen: true,
            title: 'تأكيد استيراد البيانات',
            message: 'سيتم تحديث بيانات المؤسسات والسكان. في حال وجود مؤسسة بنفس الاسم أو المعرف، سيتم تحديث بياناتها فقط ولن يتكرر الاسم.',
            onConfirm: async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const json = XLSX.utils.sheet_to_json(worksheet);

                        // تجميع البيانات من إكسل لمنع التكرار
                        const excelDataMap = new Map<string, { state?: string, id?: number, populations: Record<number, number>, pin?: string }>();

                        json.forEach((row: any) => {
                            const name = (row['Institution'] || row['Name'] || row['name'])?.toString().trim();
                            const instId = row['institutionId'] || row['id'] ? Number(row['institutionId'] || row['id']) : undefined;
                            const state = (row['State'] || row['state'])?.toString().trim();
                            const year = Number(row['Year'] || row['year']);
                            const population = Number(row['Population'] || row['population']);
                            const pin = row['PIN'] || row['pin'] ? row['PIN'] || row['pin'] : undefined;

                            const key = instId ? `id_${instId}` : name;
                            if (!key) return;

                            if (!excelDataMap.has(key)) {
                                excelDataMap.set(key, { id: instId, state, populations: {}, pin });
                            }
                            const entry = excelDataMap.get(key)!;
                            if (!isNaN(year) && !isNaN(population)) entry.populations[year] = population;
                            if (state && !entry.state) entry.state = state;
                            if (pin && !entry.pin) entry.pin = pin;
                        });

                        let addedCount = 0;
                        let updatedCount = 0;

                        excelDataMap.forEach((val, key) => {
                            let existingInst;
                            // البحث أولاً عن طريق المعرف الرقمي إذا وجد
                            if (val.id) {
                                existingInst = users.find(u => u.id === val.id);
                            } 
                            // إذا لم يوجد، البحث عن طريق الاسم لمنع التكرار
                            if (!existingInst && !val.id) {
                                existingInst = users.find(u => u.role === UserRole.INSTITUTION && u.name === key);
                            }

                            if (existingInst) {
                                // تحديث المؤسسة الحالية (منع التكرار)
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    state: val.state || existingInst.state,
                                    pin: val.pin || existingInst.pin,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else if (!val.id) {
                                // إضافة مؤسسة جديدة فقط إذا لم تكن موجودة مسبقاً
                                addInstitution(key as string, val.state, val.populations);
                                addedCount++;
                            }
                        });

                        setMessage({ type: 'success', text: `✅ تم تحديث ${updatedCount} مؤسسة وإضافة ${addedCount} مؤسسة جديدة.` });
                    } catch (error) {
                        setMessage({ type: 'error', text: 'فشل في معالجة الملف.' });
                    }
                };
                reader.readAsBinaryString(file);
            }
        });
        e.target.value = '';
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [] }, 'EPI_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ تم تصدير النسخة الاحتياطية.' });
    };

    return (
        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-lg font-bold py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} disabled={isProcessing} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold">إلغاء</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold">{isProcessing ? 'جاري التنفيذ...' : 'تأكيد'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300">Settings / الإعدادات</h3>

            <div className="flex flex-wrap border-b border-gray-200 mb-6 dark:border-gray-700">
                <button className={`px-4 py-2 font-medium transition-colors ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300' : 'text-gray-500'}`} onClick={() => setActiveSettingsView('main')}>Main Settings</button>
                <button className={`px-4 py-2 font-medium transition-colors ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300' : 'text-gray-500'}`} onClick={() => setActiveSettingsView('customization')}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{message.text}</div>}

            {activeSettingsView === 'main' && (
                <div className="space-y-8 animate-fade-in">
                     <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Data Management / إدارة البيانات</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2">Import & Export Population</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={handleExportInstitutionsForPopulation} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 dark:bg-gray-600 dark:text-gray-200">📤 Export All Population (ID/Year/Pop)</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-green-50 border border-green-300 rounded-md hover:bg-green-100 dark:bg-green-900/30 dark:text-green-200">📥 Import/Update Data (ID or Name)<input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" /></label>
                                </div>
                            </div>
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2">Full Backup</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => handleExportFullBackup(false)} className="w-full text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 dark:bg-blue-900 dark:text-blue-200">💾 Export Full Backup</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 dark:bg-blue-900 dark:text-blue-200">📂 Restore from Full Backup<input type="file" accept=".xlsx" onChange={(e) => {
                                        const file = e.target.files?.[0];
                                        if (file) {
                                            importFullBackup(file).then(data => {
                                                handleImportFullBackupFile(data);
                                                setMessage({ type: 'success', text: '✅ تم استعادة النسخة الاحتياطية بنجاح.' });
                                            });
