    // --- Distribution Handlers ---

    const handleCopyHtml = async (type: 'empty' | 'snapshot') => {
        try {
            const config = type === 'empty' ? null : firebaseConfig;
            const htmlString = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
