    };

    const handleDownloadEmpty = async () => {
        await generateAndDownloadDistributableHtml({ ...context, users: context.users, reports: [], students: [], halaqas: [], evaluations: [], firebaseConfig: null }, 'empty');
    };

    const handleDownloadConnected = async () => {
        await generateAndDownloadDistributableZip({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: firebaseConfig }, 'snapshot');
    };

    return (
