                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600 text-center">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Customize Logo / تخصيص الشعار</h4>
                        <div className="flex flex-col items-center gap-4">
