declare const XLSX: any;

const resizeImage = (
    file: File, 
    maxWidth: number, 
    maxHeight: number, 
    quality: number, 
    callback: (dataUrl: string | null) => void
) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
        const image = new Image();
        image.onload = () => {
            const canvas = document.createElement('canvas');
            let width = image.width;
            let height = image.height;
            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(image, 0, 0, width, height);
                const dataUrl = canvas.toDataURL(file.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', quality);
                callback(dataUrl);
            } else {
                callback(null);
            }
        };
        image.src = readerEvent.target?.result as string;
    };
    reader.readAsDataURL(file);
};

export const Settings: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{
      isOpen: boolean;
      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        users, addInstitution, updateInstitution,
        importFullBackup: handleImportFullBackupFile,
        appName, setAppName, firebaseConfig, setFirebaseConfig,
        isDistributable, isPublishedConnected
    } = context; 

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(
        firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''
    );

    const firebaseConfigTextAreaRef = useRef<HTMLTextAreaElement>(null);
    const appNameInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => { setAppNameInput(appName); }, [appName]);
    useEffect(() => { setFirebaseConfigInput(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''); }, [firebaseConfig]);

    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => { 
      setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try { await navigator.clipboard.writeText(text); return true; } catch (err) {}
      }
      return false;
    };

    const handleExportInstitutionsForPopulation = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);
        const dataRows: any[] = [];
        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);
            if (years.length > 0) {
                years.forEach(y => {
                    dataRows.push({ institutionId: inst.id, year: y, population: populations[y] });
                });
            } else {
                dataRows.push({ institutionId: inst.id, year: new Date().getFullYear(), population: 0 });
            }
        });
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(dataRows, { header: ['institutionId', 'year', 'population'] });
        XLSX.utils.book_append_sheet(wb, ws, 'Population');
        XLSX.writeFile(wb, `EPI_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ Population data exported.' });
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        confirmAction('Confirm Data Import', 'This will update institutions and population data. Existing names or IDs will be updated to prevent duplication.',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const json = XLSX.utils.sheet_to_json(worksheet);
                        const excelDataMap = new Map<string, { state?: string, id?: number, populations: Record<number, number>, pin?: string }>();

                        json.forEach((row: any) => {
                            const name = (row['Institution'] || row['Name'] || row['name'])?.toString().trim();
                            const instId = row['institutionId'] || row['id'] ? Number(row['institutionId'] || row['id']) : undefined;
                            const state = (row['State'] || row['state'])?.toString().trim();
                            const year = Number(row['Year'] || row['year']);
                            const population = Number(row['Population'] || row['population']);
                            const pin = row['PIN'] || row['pin'] ? String(row['PIN'] || row['pin']) : undefined;

                            const key = instId ? `id_${instId}` : name;
                            if (!key) return;

                            if (!excelDataMap.has(key)) {
                                excelDataMap.set(key, { id: instId, state, populations: {}, pin });
                            }
                            const entry = excelDataMap.get(key)!;
                            if (!isNaN(year) && !isNaN(population)) entry.populations[year] = population;
                            if (state && !entry.state) entry.state = state;
                            if (pin && !entry.pin) entry.pin = pin;
                        });

                        let addedCount = 0; let updatedCount = 0;
                        excelDataMap.forEach((val, key) => {
                            let existingInst = val.id ? users.find(u => u.id === val.id) : users.find(u => u.role === UserRole.INSTITUTION && u.name === key);
                            if (existingInst) {
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    state: val.state || existingInst.state,
                                    pin: val.pin || existingInst.pin,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else if (!val.id && key) {
                                addInstitution(key as string, val.state, val.populations);
                                addedCount++;
                            }
                        });
                        setMessage({ type: 'success', text: `✅ Updated ${updatedCount} and added ${addedCount} institutions.` });
                    } catch (error) { setMessage({ type: 'error', text: 'Failed to process file.' }); }
                };
                reader.readAsBinaryString(file);
            }
        );
        e.target.value = '';
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [] }, 'EPI_Full_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ Full backup exported.' });
    };

    const handleSaveFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        try {
            const parsedConfig = JSON.parse(firebaseConfigInput);
            if (!parsedConfig.apiKey || !parsedConfig.databaseURL) {
                setMessage({ type: 'error', text: 'Invalid config. At least apiKey and databaseURL are required.' });
                return;
            }
            setFirebaseConfig(parsedConfig);
            setMessage({ type: 'success', text: '✅ Firebase settings saved.' });
        } catch (e) { setMessage({ type: 'error', text: 'Invalid JSON format.' }); }
    };

    const handleCopyHtml = async (type: 'empty' | 'connected') => {
        try {
            const config = type === 'empty' ? null : firebaseConfig;
            const htmlString = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
            const success = await copyToClipboard(htmlString);
            if (success) {
                setCopyState(type);
                setTimeout(() => setCopyState('idle'), 3000);
                setMessage({ type: 'success', text: `✅ ${type === 'empty' ? 'Blank' : 'Connected'} code copied.` });
            }
        } catch (e) { setMessage({ type: 'error', text: 'Failed to copy.' }); }
    };

    return (
        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-lg font-bold py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} disabled={isProcessing} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold">Cancel</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold">{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300">Settings</h3>

            <div className="flex flex-wrap border-b border-gray-200 mb-6 dark:border-gray-700">
                <button className={`px-4 py-2 font-medium transition-colors ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300' : 'text-gray-500'}`} onClick={() => setActiveSettingsView('main')}>Main Settings</button>
                <button className={`px-4 py-2 font-medium transition-colors ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300' : 'text-gray-500'}`} onClick={() => setActiveSettingsView('customization')}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{message.text}</div>}

            {activeSettingsView === 'main' && (
                <div className="space-y-8 animate-fade-in">
                    {/* Only show Firebase Config if NOT in a published/connected version */}
                    {!isPublishedConnected && (
                        <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                            <h4 className="text-lg font-semibold text-indigo-900 mb-4 dark:text-indigo-200">Firebase Configuration</h4>
                            <textarea
                                ref={firebaseConfigTextAreaRef}
                                value={firebaseConfigInput}
                                onChange={(e) => setFirebaseConfigInput(e.target.value)}
                                className="input-style w-full font-mono text-xs"
                                rows={5}
                                placeholder='{"apiKey": "...", "databaseURL": "...", ...}'
                            ></textarea>
                            <div className="flex gap-3 mt-4">
                                <button onClick={handleSaveFirebaseConfig} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700">Save Config</button>
                                <button onClick={() => setFirebaseConfig(null)} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700">Clear Config (Local Mode)</button>
                            </div>
                        </div>
                    )}

                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Data Management</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2">Import & Export Institutions</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => exportSheetTemplate('Institutions_Template')} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 dark:bg-gray-600">📄 Download Import Template</button>
                                    <button onClick={handleExportInstitutionsForPopulation} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 dark:bg-gray-600">📤 Export Population Data (ID/Year/Pop)</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-green-50 border border-green-300 rounded-md hover:bg-green-100 dark:bg-green-900/30 dark:text-green-200">📥 Import Data from Excel<input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" /></label>
                                </div>
                            </div>
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2">Full Backup</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => handleExportFullBackup(false)} className="w-full text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 dark:bg-blue-900 dark:text-blue-200">💾 Export Full Backup</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 dark:bg-blue-900 dark:text-blue-200">📂 Restore from Backup<input type="file" accept=".xlsx" onChange={(e) => {
                                        const file = e.target.files?.[0];
                                        if (file) importFullBackup(file).then(data => handleImportFullBackupFile(data));
                                    }} className="hidden" /></label>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                        <h4 className="text-lg font-semibold text-indigo-900 mb-4 dark:text-indigo-200">Distribute Versions</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300">Blank Version (New App)</p>
                                <button onClick={() => generateAndDownloadDistributableHtml({ ...context, users: [], reports: [], students: [], halaqas: [], evaluations: [], firebaseConfig: null }, 'empty')} className="w-full py-2 bg-white border border-indigo-300 rounded-lg font-bold">⬇️ Download HTML</button>
                                <button onClick={() => handleCopyHtml('empty')} className={`w-full py-2 rounded-lg font-bold text-white transition-all ${copyState === 'empty' ? 'bg-green-600' : 'bg-indigo-600'}`}>📋 {copyState === 'empty' ? 'Copied!' : 'Copy HTML Code'}</button>
                            </div>
                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300">Connected Version (Snapshot)</p>
                                <button onClick={() => generateAndDownloadDistributableZip({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: firebaseConfig }, 'snapshot')} className="w-full py-2 bg-white border border-indigo-300 rounded-lg font-bold">⬇️ Download ZIP</button>
                                <button onClick={() => handleCopyHtml('connected')} className={`w-full py-2 rounded-lg font-bold text-white transition-all ${copyState === 'connected' ? 'bg-green-600' : 'bg-indigo-600'}`}>📋 {copyState === 'connected' ? 'Copied!' : 'Copy Embed Code'}</button>
                            </div>
                        </div>
                    </div>

                    <div className="pt-6 border-t border-gray-200 dark:border-gray-700">
                        <div className="flex flex-col sm:flex-row gap-4">
                            <button onClick={() => confirmAction('Delete Reports', 'Are you sure you want to delete all reports?', deleteAllReports)} className="flex-1 px-4 py-3 bg-red-100 text-red-700 border border-red-200 rounded-md hover:bg-red-200 transition-colors font-semibold dark:bg-red-900 dark:text-red-200">🗑️ Delete All Reports</button>
                            <button onClick={() => confirmAction('Reset App', 'Warning: This deletes all data and users!', deleteAllData)} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors font-semibold shadow-sm">⚠️ Reset Entire Program</button>
                        </div>
                    </div>
                </div>
            )}

            {activeSettingsView === 'customization' && (
                <div className="animate-fade-in space-y-8">
                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Program Name</h4>
                        <div className="flex flex-col sm:flex-row gap-3">
                            <input ref={appNameInputRef} type="text" value={appNameInput} onChange={(e) => setAppNameInput(e.target.value)} className="input-style flex-grow" />
                            <button onClick={() => { setAppName(appNameInput.trim()); setMessage({type: 'success', text: '✅ Name saved.'}); }} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700">Save</button>
                            <button onClick={() => setAppName(DEFAULT_APP_NAME)} className="px-6 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold hover:bg-gray-300 dark:bg-gray-600 dark:text-gray-200">Default</button>
                        </div>
                    </div>
                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600 text-center">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Customize Logo</h4>
                        <div className="flex flex-col items-center gap-4">
                            {customLogo ? (
                                <img src={customLogo} alt="Logo" className="h-32 w-32 object-contain border rounded-lg bg-white" />
                            ) : (
                                <div className="h-32 w-32 bg-gray-200 rounded-lg border-2 border-dashed border-gray-300 flex items-center justify-center text-gray-400">No Logo</div>
                            )}
                            <div className="flex gap-2">
                                <label className="cursor-pointer bg-blue-600 text-white px-6 py-2 rounded-lg font-bold">Upload New Logo<input type="file" accept="image/*" onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if(file) resizeImage(file, 200, 200, 0.9, (url) => { if(url) setCustomLogo(url); });
                                }} className="hidden" /></label>
                                {customLogo && <button onClick={() => setCustomLogo(null)} className="bg-red-600 text-white px-6 py-2 rounded-lg font-bold">Delete Logo</button>}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useContext, useMemo, useEffect, useRef } from 'react';
import Modal from './Modal';
import { AppContext } from '../App';
import { QURAN_SURAHS } from '../constants';
import { AttendanceStatus, AbsenceReason, EvaluationType, PerformanceLevel, PeriodicReviewStatus, Evaluation, Student, Halaqa } from '../types';
import { translationMap } from '../utils/exportWord';
import { isSmartMatch } from '../utils/searchUtils';

interface EvaluationEditFormProps {
  initialEvaluation: Evaluation;
  student: Student;
  halaqa?: Halaqa;
  onClose: () => void;
  onSave: (updatedEvaluation: Evaluation) => void;
  onDelete: (evaluationId: number) => void;
}

const mapOldPerformanceToNew = (oldPerf?: string): PerformanceLevel | undefined => {
  if (!oldPerf) return undefined;
  const valid = Object.values(PerformanceLevel).includes(oldPerf as PerformanceLevel);
  if (valid) return oldPerf as PerformanceLevel;
  if (oldPerf === 'very_good') return PerformanceLevel.ONE_ERROR;
  if (oldPerf === 'good') return PerformanceLevel.THREE_ERRORS;
  if (oldPerf === 'did_not_memorize') return PerformanceLevel.MORE_THAN_FIVE_ERRORS;
  return undefined;
};

const EvaluationEditForm: React.FC<EvaluationEditFormProps> = ({
  initialEvaluation,
  student,
  halaqa,
  onClose,
  onSave,
  onDelete,
}) => {
  const context = useContext(AppContext);
  if (!context) return null;

  const [attendance, setAttendance] = useState<AttendanceStatus>(initialEvaluation.attendance);
  const [absenceReason, setAbsenceReason] = useState<AbsenceReason | undefined>(initialEvaluation.absenceReason);
  const [evaluationType, setEvaluationType] = useState<EvaluationType | undefined>(initialEvaluation.evaluationType);
  const [pages, setPages] = useState<number | ''>(initialEvaluation.pages ?? '');
  const [ayahRange, setAyahRange] = useState<string>(() => {
    if (initialEvaluation.fromAyah && initialEvaluation.toAyah) {
      return initialEvaluation.fromAyah === initialEvaluation.toAyah ? initialEvaluation.fromAyah.toString() : `${initialEvaluation.fromAyah}-${initialEvaluation.toAyah}`;
    }
    return initialEvaluation.fromAyah ? initialEvaluation.fromAyah.toString() : '';
  });
  const [selectedSurahs, setSelectedSurahs] = useState<string[]>(initialEvaluation.surahs ?? []);
  const [performance, setPerformance] = useState<PerformanceLevel | undefined>(mapOldPerformanceToNew(initialEvaluation.performance as string));
  const [periodicReview, setPeriodicReview] = useState<PeriodicReviewStatus | undefined>(initialEvaluation.periodicReview);
  const [notes, setNotes] = useState(initialEvaluation.notes ?? '');

  const [surahSearchTerm, setSurahSearchTerm] = useState('');
  const [isSurahOpen, setIsSurahOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!attendance) return setError('Please select attendance status.');
    if (attendance === AttendanceStatus.ABSENT && !absenceReason) return setError('Please select an absence reason.');
    if (attendance === AttendanceStatus.PRESENT) {
        if (!evaluationType) return setError('Please select evaluation type.');
        if (evaluationType === EvaluationType.MEMORIZATION) {
            if (!pages || Number(pages) <= 0) return setError('Please enter number of pages.');
            if (selectedSurahs.length === 0) return setError('Please select at least one surah.');
            if (!performance) return setError('Please select performance level.');
        }
    }
    const range = ayahRange.split('-').map(n => parseInt(n.trim())).filter(n => !isNaN(n));
    const updated: any = {
      ...initialEvaluation,
      attendance,
      absenceReason: attendance === AttendanceStatus.ABSENT ? absenceReason : null,
      evaluationType: attendance === AttendanceStatus.PRESENT ? evaluationType : null,
      pages: (attendance === AttendanceStatus.PRESENT && evaluationType === EvaluationType.MEMORIZATION) ? Number(pages) : null,
      fromAyah: range[0] || null,
      toAyah: (range[1] || range[0]) || null,
      surahs: (attendance === AttendanceStatus.PRESENT && evaluationType === EvaluationType.MEMORIZATION) ? selectedSurahs : null,
      performance: (attendance === AttendanceStatus.PRESENT && evaluationType === EvaluationType.MEMORIZATION) ? performance : null,
      periodicReview: (attendance === AttendanceStatus.PRESENT) ? (periodicReview || null) : null,
      notes: notes || null,
      updatedAt: Date.now()
    };
    onSave(updated);
  };

  return (
    <Modal title={`Edit Evaluation: ${student.name}`} onClose={onClose} hideDefaultCloseButton={true}>
      <form onSubmit={handleSave} className="flex flex-col gap-5 min-h-[400px]">
        {error && <div className="bg-red-50 text-red-700 p-3 rounded-lg border-l-4 border-red-500 text-sm animate-fade-in">{error}</div>}

        <div className="flex justify-between items-center bg-gray-50 p-3 rounded-lg dark:bg-gray-700/50 border border-gray-100 dark:border-gray-600">
            <span className="text-xs font-bold text-gray-500">Week: <span className="text-green-700 dark:text-green-400">{initialEvaluation.weekNumber}</span></span>
            <span className="text-[10px] text-gray-400 font-medium">{halaqa?.name}</span>
        </div>

        <div className="space-y-2">
          <label className="text-[11px] font-bold text-gray-600 dark:text-gray-400">Attendance Status:</label>
          <div className="flex gap-2">
            <button type="button" onClick={() => setAttendance(AttendanceStatus.PRESENT)} className={`flex-1 py-3 rounded-xl font-bold border-2 transition-all flex items-center justify-center gap-2 ${attendance === AttendanceStatus.PRESENT ? 'bg-green-50 border-green-600 text-green-800 shadow-sm' : 'bg-white border-gray-100 dark:bg-gray-700 dark:border-gray-600'}`}>
              Present
            </button>
            <button type="button" onClick={() => setAttendance(AttendanceStatus.ABSENT)} className={`flex-1 py-3 rounded-xl font-bold border-2 transition-all flex items-center justify-center gap-2 ${attendance === AttendanceStatus.ABSENT ? 'bg-red-50 border-red-600 text-red-800 shadow-sm' : 'bg-white border-gray-100 dark:bg-gray-700 dark:border-gray-600'}`}>
              Absent
            </button>
          </div>
        </div>

        <div className="flex-grow">
          {attendance === AttendanceStatus.ABSENT ? (
            <div className="animate-fade-in space-y-3">
              <label className="text-[11px] font-bold text-gray-600 dark:text-gray-400">Absence Reason:</label>
              <div className="flex gap-2">
                  <button type="button" onClick={() => setAbsenceReason(AbsenceReason.WITH_EXCUSE)} className={`flex-1 py-2 rounded-lg text-sm font-bold border-2 transition-all ${absenceReason === AbsenceReason.WITH_EXCUSE ? 'bg-yellow-50 border-yellow-500 text-yellow-800' : 'bg-gray-50 border-transparent dark:bg-gray-700 dark:text-gray-300'}`}>With Excuse</button>
                  <button type="button" onClick={() => setAbsenceReason(AbsenceReason.WITHOUT_EXCUSE)} className={`flex-1 py-2 rounded-lg text-sm font-bold border-2 transition-all ${absenceReason === AbsenceReason.WITHOUT_EXCUSE ? 'bg-gray-100 border-gray-400 text-gray-700' : 'bg-gray-50 border-transparent dark:bg-gray-700 dark:text-gray-300'}`}>Without Excuse</button>
              </div>
            </div>
          ) : (
            <div className="space-y-4 animate-fade-in">
              <div className="space-y-2">
                  <label className="text-[11px] font-bold text-gray-600 dark:text-gray-400">Achievement Type:</label>
                  <div className="flex gap-2">
                      <button type="button" onClick={() => setEvaluationType(EvaluationType.MEMORIZATION)} className={`flex-1 py-2 rounded-lg text-sm font-bold border-2 transition-all ${evaluationType === EvaluationType.MEMORIZATION ? 'bg-green-50 border-green-500 text-green-800' : 'bg-gray-50 border-transparent dark:bg-gray-700 dark:text-gray-300'}`}>Memorization</button>
                      <button type="button" onClick={() => setEvaluationType(EvaluationType.REVIEW)} className={`flex-1 py-2 rounded-lg text-sm font-bold border-2 transition-all ${evaluationType === EvaluationType.REVIEW ? 'bg-blue-50 border-blue-500 text-blue-800' : 'bg-gray-50 border-transparent dark:bg-gray-700 dark:text-gray-300'}`}>Review</button>
                  </div>
              </div>

              {evaluationType === EvaluationType.MEMORIZATION && (
                  <div className="space-y-4 animate-fade-in">
                      <div className="grid grid-cols-2 gap-3">
                          <div><label className="text-[10px] text-gray-400">Pages</label><input type="number" min="1" value={pages} onChange={e => setPages(e.target.value === '' ? '' : Number(e.target.value))} className="input-style text-center py-2 text-sm font-bold"/></div>
                          <div><label className="text-[10px] text-gray-400">Ayahs</label><input type="text" value={ayahRange} onChange={e => setAyahRange(e.target.value)} className="input-style text-center py-2 text-sm" placeholder="e.g. 1-15"/></div>
                      </div>
                      <div className="relative">
                          <label className="text-[10px] text-gray-400">Surahs</label>
                          <button type="button" onClick={() => setIsSurahOpen(!isSurahOpen)} className="dropdown-button py-2 text-xs font-bold w-full text-left">{selectedSurahs.length > 0 ? `Selected: ${selectedSurahs.length}` : 'Select surahs...'}</button>
                          {isSurahOpen && (
                              <div className="absolute z-50 w-full mt-1 bg-white shadow-2xl border rounded-lg dark:bg-gray-800 p-2 animate-fade-in ring-1 ring-black ring-opacity-5 flex flex-col">
                                  <input type="text" placeholder="Search surah..." value={surahSearchTerm} onChange={e => setSurahSearchTerm(e.target.value)} className="w-full p-2 border-b text-[10px] mb-2 dark:bg-gray-700 dark:border-gray-600"/>
                                  <div className="max-h-40 overflow-auto">
                                      {QURAN_SURAHS.filter(s => isSmartMatch(s, surahSearchTerm)).map(s => (
                                          <label key={s} className="flex items-center p-2 hover:bg-green-50 dark:hover:bg-green-900/20 rounded cursor-pointer transition-colors">
                                              <input type="checkbox" checked={selectedSurahs.includes(s)} onChange={() => setSelectedSurahs(prev => prev.includes(s) ? prev.filter(x => x !== s) : [...prev, s])} className="mr-2 h-3.5 w-3.5 text-green-600 rounded border-gray-300" />
                                              <span className="text-[11px] dark:text-gray-300 font-medium">{s}</span>
                                          </label>
                                      ))}
                                  </div>
                                  <button type="button" onClick={() => setIsSurahOpen(false)} className="w-full mt-2 py-1.5 bg-green-600 text-white text-[10px] font-bold rounded-lg">Done</button>
                              </div>
                          )}
                      </div>
                      <div className="space-y-2">
                          <label className="text-[10px] text-gray-400">Performance Level:</label>
                          <div className="grid grid-cols-2 gap-2">
                              {Object.values(PerformanceLevel).map(l => (
                                  <button key={l} type="button" onClick={() => setPerformance(l)} className={`py-2 px-1 rounded-lg text-[10px] font-bold border-2 transition-all ${performance === l ? 'bg-green-600 text-white border-green-700 shadow-sm' : 'bg-gray-50 dark:bg-gray-700 border-transparent dark:text-gray-300'}`}>{translationMap[l]}</button>
                              ))}
                          </div>
                      </div>
                  </div>
              )}
            </div>
          )}
        </div>

        <div className="space-y-1">
          <label className="text-[11px] font-bold text-gray-600 dark:text-gray-400">Additional Notes:</label>
          <textarea value={notes} onChange={e => setNotes(e.target.value)} className="input-style h-20 text-xs py-2" placeholder="Write any additional student notes here..."/>
        </div>

        <div className="flex flex-col gap-2 pt-5 border-t dark:border-gray-700 mt-2">
          <button type="submit" className="w-full py-3.5 bg-green-700 text-white rounded-2xl font-bold shadow-lg hover:bg-green-800 active:scale-95 transition-all">
            Save Changes
          </button>
          <div className="flex gap-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold dark:bg-gray-700 dark:text-gray-300 hover:bg-gray-200 transition-colors">Cancel</button>
            <button type="button" onClick={() => { if(window.confirm('Delete this evaluation?')) onDelete(initialEvaluation.id); }} className="px-5 py-3 bg-red-50 text-red-600 rounded-xl font-bold hover:bg-red-100 dark:bg-red-900/20 transition-all">Delete</button>
          </div>
        </div>
      </form>
    </Modal>
  );
};

