import React, { useState, useContext, useMemo, useRef, useEffect } from 'react';
import { AppContext } from './App';
import { Evaluation, AttendanceStatus, PerformanceLevel, UserRole } from './types';
import { renderCell, translationMap, exportToWord } from './utils/exportWord';
import { exportToExcel } from './utils/exportExcel';
import { exportToPdf } from './utils/exportPdf';
import { isSmartMatch } from './utils/searchUtils';
import EvaluationEditForm from './components/EvaluationEditForm';

const NOT_RECORDED = 'not_recorded';
const LOCAL_STORAGE_REPORT_COLUMNS_KEY = 'halaqaReportSelectedColumns';

const isValueEffectivelyEmpty = (value: any, type?: string): boolean => {
  if (value === undefined || value === null) return true;
  if (Array.isArray(value) && value.length === 0) return true;
  let stringValue = String(value).trim();
  if (stringValue === '' || stringValue === '—') return true; 
  return false;
};

interface FilterItemProps {
  id: string;
  title: string;
  value?: string; 
  options: any[];
  onSelect: (val: any) => void;
  search: string;
  setSearch: (val: string) => void;
  isMulti?: boolean;
  selectedValues?: string[]; 
  openDropdown: string | null;
  setOpenDropdown: (id: string | null) => void;
}

const FilterItem: React.FC<FilterItemProps> = ({ 
  id, title, value, options, onSelect, search, setSearch, 
  isMulti = false, selectedValues = [], openDropdown, setOpenDropdown 
}) => {
  const isOpen = openDropdown === id;
  let displayLabel = '';
  if (isMulti) {
      if (selectedValues.length === 0) displayLabel = 'All';
      else if (selectedValues.length === 1) displayLabel = options.find((o: any) => o.id === selectedValues[0])?.name || selectedValues[0];
      else displayLabel = `${selectedValues.length} selected`;
  } else {
      displayLabel = value === 'all' ? 'All' : (options.find((o: any) => o.id.toString() === value)?.name || value);
  }

  return (
    <div className="relative w-full">
      <label className="text-[10px] mb-1 block font-bold text-gray-500 dark:text-gray-400">{title}:</label>
      <button onClick={() => setOpenDropdown(isOpen ? null : id)} className="dropdown-button py-2 text-xs h-10 w-full flex justify-between items-center bg-gray-50 dark:bg-gray-700/50 rounded-lg border-gray-200 dark:border-gray-600 dark:text-gray-200 px-2">
        <span className="truncate">{displayLabel}</span>
        <svg className={`h-3 w-3 transition-transform ${isOpen ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
      </button>
      {isOpen && (
        <div className="absolute z-50 mt-1 w-full bg-white shadow-2xl border rounded-xl dark:bg-gray-800 p-2 animate-fade-in ring-1 ring-black/5 dark:ring-white/10 dark:border-gray-700">
          <input type="text" placeholder="Search..." value={search} onChange={e => setSearch(e.target.value)} className="w-full p-2 mb-2 text-[10px] rounded-lg border-gray-200 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-200" />
          <ul className="max-h-48 overflow-y-auto">
            {!isMulti && (
                <li onClick={() => { onSelect('all'); setOpenDropdown(null); setSearch(''); }} className={`p-2 text-[10px] cursor-pointer rounded mb-0.5 hover:bg-gray-100 dark:hover:bg-gray-700 ${value === 'all' ? 'bg-green-100 dark:bg-green-900/40 font-bold' : ''}`}>All</li>
            )}
            {options.filter((o: any) => isSmartMatch(o.name, search)).map((o: any) => (
              <li key={o.id} 
                onClick={() => { 
                  if (isMulti) {
                      const newVals = selectedValues.includes(o.id) ? selectedValues.filter((v: any) => v !== o.id) : [...selectedValues, o.id];
                      onSelect(newVals);
                  } else {
                      onSelect(o.id.toString()); setOpenDropdown(null); setSearch(''); 
                  }
                }} 
                className={`p-2 text-[10px] cursor-pointer rounded mb-0.5 flex items-center gap-2 hover:bg-gray-100 dark:hover:bg-gray-700 ${(!isMulti && value === o.id.toString()) || (isMulti && selectedValues.includes(o.id)) ? 'bg-green-100 dark:bg-green-900/40 text-green-800 font-bold' : ''}`}
              >
                {isMulti && <input type="checkbox" checked={selectedValues.includes(o.id)} readOnly className="h-3 h-3 text-green-600 rounded" />}
                <span className="truncate">{o.name}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export const ReportsTable: React.FC = () => {
  const context = useContext(AppContext);
  const [filterWeek, setFilterWeek] = useState<string>('all');
  const [filterStudentId, setFilterStudentId] = useState<string>('all');
  const [filterHalaqaId, setFilterHalaqaId] = useState<string>('all');
  const [filterInstitutionId, setFilterInstitutionId] = useState<string>('all');
  const [selectedAttendance, setSelectedAttendance] = useState<string[]>([]);
  const [selectedPerformance, setSelectedPerformance] = useState<string[]>([]);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'ascending' | 'descending' } | null>(null);
  const [studentSearch, setStudentSearch] = useState('');
  const [halaqaSearch, setHalaqaSearch] = useState('');
  const [institutionSearch, setInstitutionSearch] = useState('');
  const [attendanceSearch, setAttendanceSearch] = useState('');
  const [performanceSearch, setPerformanceSearch] = useState('');
  const [weekSearch, setWeekSearch] = useState('');
  const [openDropdown, setOpenDropdown] = useState<string | null>(null);
  const [selectedColumnKeys, setSelectedColumnKeys] = useState<string[]>([]);
  const [editingEvaluation, setEditingEvaluation] = useState<Evaluation | null>(null);

  if (!context) return null;
  const { evaluations, students, halaqas, users, updateEvaluation, deleteEvaluation } = context;

  const allHeaders = useMemo(() => [
    { key: 'studentName', label: 'Student' },
    { key: 'halaqaName', label: 'Unit' },
    { key: 'evaluatorName', label: 'Recorded By' },
    { key: 'weekNumber', label: 'Week' },
    { key: 'attendance', label: 'Attendance', type: 'translation' },
    { key: 'absenceReason', label: 'Absence Reason', type: 'translation' },
    { key: 'evaluationType', label: 'Type', type: 'translation' },
    { key: 'pages', label: 'Pages' },
    { key: 'ayahRangeDisplay', label: 'Ayahs', type: 'text' },
    { key: 'surahs', label: 'Surahs', type: 'array' },
    { key: 'performance', label: 'Performance', type: 'translation' },
    { key: 'periodicReview', label: 'Periodic Review', type: 'translation' },
    { key: 'notes', label: 'Notes' },
  ], []);

  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_REPORT_COLUMNS_KEY);
    if (saved) {
      try { setSelectedColumnKeys(JSON.parse(saved)); } catch (e) { setSelectedColumnKeys(allHeaders.map(h => h.key)); }
    } else { setSelectedColumnKeys(allHeaders.map(h => h.key)); }
  }, [allHeaders]);

  const evaluationData = useMemo(() => {
    return evaluations.map(e => {
      const student = students.find(s => s.id === e.studentId);
      const studentOriginalHalaqa = student ? halaqas.find(h => h.id === student.halaqaId) : undefined;
      const evaluatorName = users.find(u => u.id === e.institutionId)?.name || '—';
      const isGuestEvaluation = studentOriginalHalaqa && e.institutionId ? studentOriginalHalaqa.institutionId !== e.institutionId : false;
      return { 
        ...e, 
        studentName: student?.name || 'Unknown', 
        halaqaName: studentOriginalHalaqa?.name || '-', 
        evaluatorName,
        isGuestEvaluation,
        ayahRangeDisplay: (e.fromAyah && e.toAyah) ? (e.fromAyah === e.toAyah ? e.fromAyah.toString() : `${e.fromAyah}-${e.toAyah}`) : (e.fromAyah ? e.fromAyah.toString() : '—'),
      };
    });
  }, [evaluations, students, halaqas, users]);

  const allWeeks = useMemo(() => ['all', ...Array.from(new Set(evaluations.map(e => e.weekNumber))).sort((a: any, b: any) => a - b).map(String)], [evaluations]);
  const attendanceOptions = [{id: AttendanceStatus.PRESENT, name: 'Present'}, {id: AttendanceStatus.ABSENT, name: 'Absent'}, {id: NOT_RECORDED, name: 'Not Recorded'}];
  const performanceOptions = Object.values(PerformanceLevel).map(level => ({ id: level, name: translationMap[level] }));

  const sortedAndFilteredData = useMemo(() => {
    let items = (filterWeek !== 'all') ? 
        students.map(s => {
            const ev = evaluationData.find(e => e.studentId === s.id && e.weekNumber === parseInt(filterWeek));
            const sHalaqa = halaqas.find(h => h.id === s.halaqaId);
            return ev || { 
                id: `p-${s.id}`, studentId: s.id, studentName: s.name, halaqaId: s.halaqaId, halaqaName: sHalaqa?.name || '-', 
                institutionId: sHalaqa?.institutionId, weekNumber: parseInt(filterWeek), attendance: NOT_RECORDED, 
                evaluatorName: '—', isGuestEvaluation: false, ayahRangeDisplay: '—' 
            };
        }) : [...evaluationData];

    if (filterStudentId !== 'all') items = items.filter(i => i.studentId === parseInt(filterStudentId));
    if (filterHalaqaId !== 'all') items = items.filter(i => students.find(s => s.id === i.studentId)?.halaqaId === parseInt(filterHalaqaId));
    if (filterInstitutionId !== 'all') items = items.filter(i => i.institutionId === parseInt(filterInstitutionId));
    if (selectedAttendance.length > 0) items = items.filter(i => selectedAttendance.includes(i.attendance));
    if (selectedPerformance.length > 0) items = items.filter(i => (i as any).performance && selectedPerformance.includes((i as any).performance));

    if (sortConfig) {
      items.sort((a, b) => {
        const vA = (a as any)[sortConfig.key];
        const vB = (b as any)[sortConfig.key];
        if (vA < vB) return sortConfig.direction === 'ascending' ? -1 : 1;
        if (vA > vB) return sortConfig.direction === 'ascending' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [evaluationData, students, halaqas, filterWeek, filterStudentId, filterHalaqaId, filterInstitutionId, selectedAttendance, selectedPerformance, sortConfig]);

  const dynamicHeaders = useMemo(() => {
    const always = new Set(['studentName', 'halaqaName', 'weekNumber', 'attendance']);
    return allHeaders.filter(h => selectedColumnKeys.includes(h.key) && (always.has(h.key) || sortedAndFilteredData.some(i => !isValueEffectivelyEmpty((i as any)[h.key], h.type))));
  }, [allHeaders, selectedColumnKeys, sortedAndFilteredData]);

  return (
    <div className="bg-white p-4 sm:p-6 rounded-2xl shadow-xl dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
      {editingEvaluation && (
          <EvaluationEditForm 
            initialEvaluation={editingEvaluation}
            student={students.find(s => s.id === editingEvaluation.studentId)!}
            halaqa={halaqas.find(h => h.id === editingEvaluation.halaqaId)}
            onClose={() => setEditingEvaluation(null)}
            onSave={(v) => { updateEvaluation(v); setEditingEvaluation(null); }}
            onDelete={() => { deleteEvaluation(editingEvaluation.id); setEditingEvaluation(null); }}
          />
      )}

      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-bold text-green-900 dark:text-green-300">Filter Reports</h3>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 mb-8 no-print">
          <FilterItem id="student" title="Student" value={filterStudentId} options={students.map(s => ({id: s.id, name: s.name}))} onSelect={setFilterStudentId} search={studentSearch} setSearch={setStudentSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
          <FilterItem id="halaqa" title="Unit" value={filterHalaqaId} options={halaqas.map(h => ({id: h.id, name: h.name}))} onSelect={setFilterHalaqaId} search={halaqaSearch} setSearch={setHalaqaSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
          <FilterItem id="institution" title="Institution" value={filterInstitutionId} options={users.filter(u => u.role === UserRole.INSTITUTION).map(t => ({id: t.id, name: t.name}))} onSelect={setFilterInstitutionId} search={institutionSearch} setSearch={setInstitutionSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
          <FilterItem id="week" title="Week" value={filterWeek} options={allWeeks.filter(w => w !== 'all').map(w => ({id: w, name: `Week ${w}`}))} onSelect={setFilterWeek} search={weekSearch} setSearch={setWeekSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
          <FilterItem id="attendance" title="Attendance" isMulti={true} selectedValues={selectedAttendance} options={attendanceOptions} onSelect={setSelectedAttendance} search={attendanceSearch} setSearch={setAttendanceSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
          <FilterItem id="performance" title="Performance" isMulti={true} selectedValues={selectedPerformance} options={performanceOptions} onSelect={setSelectedPerformance} search={performanceSearch} setSearch={setPerformanceSearch} openDropdown={openDropdown} setOpenDropdown={setOpenDropdown} />
      </div>

      <div className="flex flex-wrap items-center gap-2 mb-6 no-print border-t border-gray-100 dark:border-gray-700 pt-5">
          <button onClick={() => exportToExcel(dynamicHeaders, sortedAndFilteredData, 'Evaluation_Report')} className="px-3 py-2 text-[10px] font-bold text-white bg-green-600 rounded-lg">Excel</button>
          <button onClick={() => exportToWord(dynamicHeaders, sortedAndFilteredData, 'Evaluation_Report')} className="px-3 py-2 text-[10px] font-bold text-white bg-blue-600 rounded-lg">Word</button>
          <button onClick={() => exportToPdf(dynamicHeaders, sortedAndFilteredData, 'Evaluation_Report', 'Evaluations')} className="px-3 py-2 text-[10px] font-bold text-white bg-red-600 rounded-lg">PDF</button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-gray-100 dark:border-gray-700">
        <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
          <thead className="bg-gray-50 dark:bg-gray-700/50">
            <tr>
              {dynamicHeaders.map(h => (
                 <th key={h.key} onClick={() => setSortConfig({ key: h.key, direction: sortConfig?.key === h.key && sortConfig.direction === 'ascending' ? 'descending' : 'ascending' })} className="px-3 py-4 text-left text-[10px] font-bold text-gray-500 uppercase cursor-pointer">
                   {h.label}
                 </th>
              ))}
              <th className="px-3 py-4 text-center text-[10px] font-bold text-gray-500 no-print">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-100 dark:bg-gray-800 dark:divide-gray-700">
            {sortedAndFilteredData.map((item: any, idx: number) => (
              <tr key={item.id} className={`${idx % 2 === 0 ? "" : "bg-gray-50/20"} hover:bg-green-50/30 transition-colors`}>
                {dynamicHeaders.map(h => (
                  <td key={h.key} className={`px-3 py-3.5 whitespace-nowrap text-[10px] sm:text-xs ${item.isGuestEvaluation ? 'text-red-700 font-semibold' : 'text-gray-700 dark:text-gray-200'}`}>
                    {renderCell(item[h.key], h.type)}
                  </td>
                ))}
                <td className="px-3 py-3.5 whitespace-nowrap text-center no-print">
                    <div className="flex justify-center gap-2">
                        <button onClick={() => setEditingEvaluation(item)} disabled={item.attendance === NOT_RECORDED} className={`p-1.5 rounded-lg ${item.attendance === NOT_RECORDED ? 'text-gray-300' : 'text-blue-600 hover:bg-blue-50'}`} title="Edit">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                        </button>
                        <button onClick={() => { if(window.confirm('Delete this evaluation?')) deleteEvaluation(item.id); }} disabled={item.attendance === NOT_RECORDED} className={`p-1.5 rounded-lg ${item.attendance === NOT_RECORDED ? 'text-gray-300' : 'text-red-600 hover:bg-red-50'}`} title="Delete">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                    </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

