            }
        };
        reader.readAsBinaryString(file);
    });
};

import { FullBackupData, UserRole, MonthlyReport } from '../types';
declare const XLSX: any;

const getUniqueKeys = (data: any[], preferredOrder: string[] = []) => {
    const keys = new Set<string>();
    data.forEach(item => {
        Object.keys(item).forEach(k => keys.add(k));
    });
    const sortedKeys: string[] = [];
    preferredOrder.forEach(k => {
        if (keys.has(k)) {
            sortedKeys.push(k);
            keys.delete(k);
        }
    });
    return [...sortedKeys, ...Array.from(keys).sort()];
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    // 1. ورقة المؤسسات (بدون بيانات السكان المدمجة لتقليل الحجم)
    const userKeys = ['id', 'name', 'role', 'state', 'pin', 'isDefaultPin'];
    const usersHeaders = getUniqueKeys(data.users, userKeys).filter(h => h !== 'population');
    const usersData = data.users.map(u => {
        const row: any = {};
        usersHeaders.forEach(h => {
            row[h] = (u as any)[h] ?? '';
        });
        return row;
    });
    const wsUsers = XLSX.utils.json_to_sheet(usersData, { header: usersHeaders });
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Users_Institutions');

    // 2. ورقة بيانات السكان المستقلة (الأعمدة المطلوبة: institutionId, year, population)
    const popRows: any[] = [];
    data.users.filter(u => u.role === UserRole.INSTITUTION).forEach(inst => {
        const populations = inst.population || {};
        Object.entries(populations).forEach(([year, count]) => {
            popRows.push({
                institutionId: inst.id,
                year: Number(year),
                population: Number(count)
            });
        });
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows, { header: ['institutionId', 'year', 'population'] });
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. ورقة التقارير الشهرية
    if (data.reports && data.reports.length > 0) {
        const reportPreferredKeys = ['id', 'institutionId', 'year', 'month', 'entryPerson', 'updatedAt'];
        const reportHeaders = getUniqueKeys(data.reports, reportPreferredKeys);
        const wsReports = XLSX.utils.json_to_sheet(data.reports, { header: reportHeaders });
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. ورقة الإعدادات
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Supervisor Password', data.supervisorPassword || ''],
        ['Immunization Dept Password', data.immunizationPassword || ''],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().split('T')[0]}.xlsx`);
};

