                            <textarea
                                ref={firebaseConfigTextAreaRef}
                                value={firebaseConfigInput}
                                onChange={(e) => setFirebaseConfigInput(e.target.value)}
                                className="input-style w-full font-mono text-xs"
                                rows={5}
                                placeholder='{"apiKey": "...", "databaseURL": "...", ...}'
                            ></textarea>
                            <div className="flex gap-3 mt-4">
                                <button onClick={handleSaveFirebaseConfig} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700">Save Config</button>
                                <button onClick={() => setFirebaseConfig(null)} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700">Clear Config (Local Mode)</button>
