declare const JSZip: any;

const base64ToBytes = (base64: string): Uint8Array => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

interface AppContextType {
  users: User[];
  reports: MonthlyReport[];
  addReport: (report: Omit<MonthlyReport, 'id' | 'updatedAt'>) => void;
  updateReport: (report: MonthlyReport) => void;
  deleteReport: (reportId: number) => void;
  deleteAllReports: () => Promise<void>;
  deleteAllData: () => Promise<void>;
  loadMockData: () => void;
  customLogo: string | null;
  setCustomLogo: (logo: string | null) => void;
  addInstitution: (name: string, state?: string, population?: { [year: number]: number }) => void;
  updateInstitution: (institution: User) => void;
  deleteInstitution: (institutionId: number) => void;
  importFullBackup: (data: FullBackupData) => void;
  supervisorPassword: string;
  setSupervisorPassword: (password: string) => void;
  logout: () => void;
  isLoading: boolean;
  initiateLogoutCheck: () => void;
  appName: string;
  setAppName: (name: string) => void;
  darkMode: boolean;
  toggleDarkMode: () => void;
  firebaseConnectionStatus: 'connected' | 'disconnected' | 'error' | 'connecting';
  firebaseConfig: any;
  setFirebaseConfig: (config: any) => void;
  isDistributable: boolean;
  isPublishedConnected: boolean;
  currentUser: User | null;

  students: Student[];
  halaqas: Halaqa[];
  evaluations: Evaluation[];
  updateEvaluation: (e: any) => void;
  deleteEvaluation: (id: number) => void;
  addEvaluation: (e: any) => void;
  setLastUsedWeek: (week: number | null) => void;

  maghribAttendances: MaghribAttendance[];
  addMaghribAttendance: (att: any) => void;
  deleteMaghribAttendance: (id: number) => void;
  maghribPassword: string;
  setMaghribPassword: (p: string) => void;

  immunizationPassword: string;
  setImmunizationPassword: (p: string) => void;

  setHasUnsavedChanges: (hasChanges: boolean) => void;
}

export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          return savedUser ? JSON.parse(savedUser) : null;
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS, 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);
  const [lastUsedWeek, setLastUsedWeek] = useState<number | null>(null);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const getNextId = (collection: any[], startingId: number = 1) => {
      if (!collection || collection.length === 0) {
          return startingId;
      }
      const maxId = collection.reduce((max, item) => (Number(item.id) > max ? Number(item.id) : max), 0);
      return Math.max(maxId + 1, startingId);
  };

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).compressedEmbeddedAppData) {
      try {
        const compressedBytes = base64ToBytes((window as any).compressedEmbeddedAppData);
        const zip = await JSZip.loadAsync(compressedBytes);
        const file = zip.file("data.json");
        if (file) {
          const jsonString = await file.async('string');
          loadedConfig = JSON.parse(jsonString);
        } else {
          throw new Error("data.json not found in compressed payload");
        }
      } catch (e) {
        console.error("Failed to decompress embedded data", e);
      }
    } else if ((window as any).embeddedAppData) {
       try {
           loadedConfig = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob((window as any).embeddedAppData), c => c.charCodeAt(0))));
       } catch(e) { console.error("Failed to parse embedded data", e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: loadedConfig.users || INITIAL_USERS,
        reports: loadedConfig.reports || [],
        students: loadedConfig.students || [],
        halaqas: loadedConfig.halaqas || [],
        evaluations: loadedConfig.evaluations || [],
        maghribAttendances: loadedConfig.maghribAttendances || [],
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setMaghribPasswordState(loadedConfig.maghribPassword || '123456');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          if (loadedConfig.firebaseConfig) {
              setFirebaseConfigState(loadedConfig.firebaseConfig);
          } else {
              setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
          }
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: data.students,
            halaqas: data.halaqas,
            evaluations: data.evaluations,
            maghribAttendances: data.maghribAttendances,
            customLogo, supervisorPassword, maghribPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, maghribPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            setData({
              users: val.users ? Object.values(val.users) : INITIAL_USERS,
              reports: val.reports ? Object.values(val.reports) : [],
              students: val.students ? Object.values(val.students) : [],
              halaqas: val.halaqas ? Object.values(val.halaqas) : [],
              evaluations: val.evaluations ? Object.values(val.evaluations) : [],
              maghribAttendances: val.maghribAttendances ? Object.values(val.maghribAttendances) : [],
              deletedItems: [],
            });
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.maghribPassword) setMaghribPasswordState(val.maghribPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    if (firebaseConnectionStatus !== 'connected') {
        const updateLocalData = (collection: keyof typeof data, item: any, isDelete: boolean = false) => {
             setData(prev => {
                 const list = prev[collection] as any[];
                 const itemId = Number(item.id);
                 if (isDelete) {
                     return { ...prev, [collection]: list.filter(i => Number(i.id) !== itemId) };
                 }
                 const index = list.findIndex(i => Number(i.id) === itemId);
                 if (index >= 0) {
                     const newList = [...list];
                     newList[index] = { ...item, id: itemId };
                     return { ...prev, [collection]: newList };
                 } else {
                     return { ...prev, [collection]: [...list, { ...item, id: itemId }] };
                 }
             });
        };

        if (path.startsWith('data/reports/')) {
            const id = parseInt(path.split('/').pop()!);
            if (value === null) updateLocalData('reports', { id }, true);
            else updateLocalData('reports', value);
        } else if (path.startsWith('data/users/')) {
            const id = parseInt(path.split('/').pop()!);
            if (value === null) updateLocalData('users', { id }, true);
            else updateLocalData('users', value);
        } else if (path === 'data' && value) {
            setData(prev => ({
                ...prev,
                users: value.users ? (Array.isArray(value.users) ? value.users : Object.values(value.users)) : prev.users,
                reports: value.reports ? (Array.isArray(value.reports) ? value.reports : Object.values(value.reports)) : prev.reports
            }));
        }
    }
  };

  const addReport = (rep: any) => {
      const newId = getNextId(data.reports);
      writeData(`data/reports/${newId}`, { ...rep, id: newId, updatedAt: Date.now() });
  };
  const updateReport = (rep: any) => writeData(`data/reports/${rep.id}`, { ...rep, updatedAt: Date.now() });
  const deleteReport = (id: number) => writeData(`data/reports/${id}`, null);

  const addInstitution = (n: string, state?: string, population?: { [year: number]: number }) => {
      const newId = getNextId(data.users, 2); // Supervisor is 1
      writeData(`data/users/${newId}`, { 
          id: newId, 
          name: n, 
          state: state || null,
          role: UserRole.INSTITUTION, 
          pin: '123',
          isDefaultPin: true,
          population: population || {},
          updatedAt: Date.now() 
      });
  };
  const updateInstitution = (u: User) => writeData(`data/users/${u.id}`, { ...u, updatedAt: Date.now() });
  const deleteInstitution = (institutionId: number) => writeData(`data/users/${institutionId}`, null);

  const addEvaluation = (e: any) => {
      const newId = getNextId(data.evaluations);
      writeData(`data/evaluations/${newId}`, { ...e, id: newId, updatedAt: Date.now() });
  };
  const updateEvaluation = (e: any) => writeData(`data/evaluations/${e.id}`, { ...e, updatedAt: Date.now() });
  const deleteEvaluation = (id: number) => writeData(`data/evaluations/${id}`, null);

  const addMaghribAttendance = (att: any) => {
      const id = att.id || getNextId(data.maghribAttendances);
      writeData(`data/maghribAttendances/${id}`, { ...att, id, updatedAt: Date.now() });
  };
  const deleteMaghribAttendance = (id: number) => writeData(`data/maghribAttendances/${id}`, null);

  const handleLogout = () => { 
      if (hasUnsavedChanges) {
          alert('⚠️ Warning: You have unsaved changes.');
          return;
      }
      setCurrentUser(null); 
      setHasUnsavedChanges(false);
      localStorage.removeItem(CURRENT_USER_KEY); 
  };

  const initiateLogoutCheck = () => { handleLogout(); };
  const handleLogin = (user: User) => { setCurrentUser(user); localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user)); };
  const handleSaveFirebaseConfig = (config: any) => { setFirebaseConfigState(config); };

  const showSetupWizard = isDistributable && !firebaseConfigState && !isPublishedConnected;

  return (
    <AppContext.Provider value={{
      users: data.users, reports: data.reports,
      addReport, updateReport, deleteReport, 
      deleteAllReports: async () => { writeData('data/reports', null); },
      deleteAllData: async () => writeData('data', { users: { '1': INITIAL_USERS[0] } }),
      loadMockData: () => {
          writeData('data', { users: MOCK_USERS, reports: MOCK_REPORTS });
      },
      customLogo, setCustomLogo: (l) => { setCustomLogoState(l); writeData('config/customLogo', l); },
      addInstitution, updateInstitution, deleteInstitution, importFullBackup: (d) => writeData('data', d),
      supervisorPassword, setSupervisorPassword: (p) => { setSupervisorPasswordState(p); writeData('config/supervisorPassword', p); },
      logout: handleLogout, isLoading, initiateLogoutCheck, appName, setAppName: (n) => { setAppNameState(n); writeData('config/appName', n); },
      darkMode, toggleDarkMode: () => setDarkMode(!darkMode), 
      firebaseConnectionStatus, 
      firebaseConfig: firebaseConfigState, 
      setFirebaseConfig: handleSaveFirebaseConfig,
      isDistributable, isPublishedConnected, currentUser,
      students: data.students, 
      halaqas: data.halaqas, 
      evaluations: data.evaluations,
      updateEvaluation, deleteEvaluation, addEvaluation,
      setLastUsedWeek,
      maghribAttendances: data.maghribAttendances,
      addMaghribAttendance,
      deleteMaghribAttendance,
      maghribPassword, 
      setMaghribPassword: (p) => { setMaghribPasswordState(p); writeData('config/maghribPassword', p); },
      immunizationPassword,
      setImmunizationPassword: (p) => { setImmunizationPasswordState(p); writeData('config/immunizationPassword', p); },
      setHasUnsavedChanges
    }}>
      <div className={`h-screen flex flex-col transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-green-50 text-gray-900'}`}>
          {showSetupWizard && <FirebaseSetupWizard onConfigSave={handleSaveFirebaseConfig} />}
          {!currentUser ? (
              <LoginScreen onLogin={handleLogin} />
          ) : (
              <div className="flex flex-col h-full">
                  <Header 
                      user={currentUser} 
                      onShowHelp={() => setShowHelpModal(true)} 
                      onInitiateLogoutCheck={initiateLogoutCheck} 
                      onShowMobileInstallModal={() => setShowMobileInstallModal(true)} 
                      onShowChangePassword={() => setShowChangePasswordModal(true)} 
                  />
                  <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                      {currentUser.role === UserRole.SUPERVISOR && <SupervisorDashboard />}
                      {currentUser.role === UserRole.IMMUNIZATION && <ImmunizationDashboard />}
                      {currentUser.role === UserRole.INSTITUTION && <InstitutionDashboard institutionId={currentUser.id} />}
                  </main>
              </div>
          )}
          {showHelpModal && <HelpModal onClose={() => setShowHelpModal(false)} />}
          {showMobileInstallModal && <MobileInstallModal onClose={() => setShowMobileInstallModal(false)} />}
          {showChangePasswordModal && currentUser && (
            <ChangePasswordModal 
                onClose={() => setShowChangePasswordModal(false)} 
                currentStoredPassword={
                    currentUser.role === UserRole.SUPERVISOR ? supervisorPassword : 
                    currentUser.role === UserRole.IMMUNIZATION ? immunizationPassword :
                    (currentUser.pin || '123')
                }
                onSave={(p) => {
                    if (currentUser.role === UserRole.SUPERVISOR) {
                        setSupervisorPasswordState(p); 
                        writeData('config/supervisorPassword', p);
                    } else if (currentUser.role === UserRole.IMMUNIZATION) {
                        setImmunizationPasswordState(p);
                        writeData('config/immunizationPassword', p);
                    } else if (currentUser.role === UserRole.INSTITUTION) {
                        const updatedUser = { ...currentUser, id: Number(currentUser.id), pin: p, isDefaultPin: false, updatedAt: Date.now() };
                        updateInstitution(updatedUser);
                        setCurrentUser(updatedUser);
                        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updatedUser));
                    }
                }} 
            />
          )}
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState, useContext, useEffect, useRef } from 'react';
import { AppContext } from '../App';
import { exportSheetTemplate } from '../utils/exportSheetTemplate';
import { exportFullBackup, importFullBackup } from '../utils/fullBackup';
import { FullBackupData, UserRole } from '../types';
import Modal from './Modal';
import { generateAndDownloadDistributableHtml, generateAndDownloadDistributableZip, getDistributableHtmlString } from '../utils/distributableApp';
import { DEFAULT_APP_NAME } from '../constants';

declare const XLSX: any;

const resizeImage = (
    file: File, 
    maxWidth: number, 
    maxHeight: number, 
    quality: number, 
    callback: (dataUrl: string | null) => void
) => {
    const reader = new FileReader();
    reader.onload = (readerEvent) => {
        const image = new Image();
        image.onload = () => {
            const canvas = document.createElement('canvas');
            let width = image.width;
            let height = image.height;

            if (width > height) {
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
            } else {
                if (height > maxHeight) {
                    width *= maxHeight / height;
                    height = maxHeight;
                }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(image, 0, 0, width, height);
                const dataUrl = canvas.toDataURL(file.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', quality);
                callback(dataUrl);
            } else {
                callback(null);
            }
        };
        image.src = readerEvent.target?.result as string;
    };
    reader.readAsDataURL(file);
};


export const Settings: React.FC = () => {
    const context = useContext(AppContext);

    if (!context) return null;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{
      isOpen: boolean;
      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        users,
        addInstitution, updateInstitution,
        importFullBackup: handleImportFullBackupFile,
        appName, setAppName,
        isDistributable, isPublishedConnected, 
        firebaseConfig, setFirebaseConfig,
        firebaseConnectionStatus
    } = context; 

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(
        firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : ''
    );

    const firebaseConfigTextAreaRef = useRef<HTMLTextAreaElement>(null);
    const appNameInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => { setAppNameInput(appName); }, [appName]);
    useEffect(() => {
        setFirebaseConfigInput(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : '');
    }, [firebaseConfig]);

    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => { 
      setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => { 
      if (isProcessing) return; 
      setIsProcessing(true); 
      try { await confirmationModal.onConfirm(); } 
      finally {
        setIsProcessing(false); 
        setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const handleCancel = () => {
      if (!isProcessing) {
          setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
      }
    };

    const copyToClipboard = async (text: string) => {
      if (navigator.clipboard && window.isSecureContext) {
        try {
          await navigator.clipboard.writeText(text);
          return true;
        } catch (err) { console.error("Clipboard API failed:", err); }
      }
      try {
        const textArea = document.createElement("textarea");
        textArea.value = text;
        textArea.style.position = "fixed";
        textArea.style.left = "-9999px";
        textArea.style.top = "0";
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        const successful = document.execCommand('copy');
        document.body.removeChild(textArea);
        return successful;
      } catch (err) {
        console.error("Fallback copy failed:", err);
        return false;
      }
    };

    const handleDeleteReports = () => {
        confirmAction('Confirm Deleting Reports', 'Are you sure you want to delete all monthly reports? A full backup will be automatically downloaded before deletion.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllReports();
                setMessage({ type: 'success', text: 'All reports have been deleted successfully.' });
            }
        );
    }

    const handleDeleteAllData = () => {
        confirmAction('Confirm Program Reset', 'Warning: This action will download a backup and then delete all institution and report data. This action cannot be undone.',
            async () => {
                setMessage({ type: 'success', text: 'Downloading backup...' });
                await handleExportFullBackup(true);
                await deleteAllData();
                setMessage({ type: 'success', text: 'The program has been reset successfully.' });
            }
        );
    }

    const handleLoadMockData = () => {
        confirmAction('Confirm Loading Mock Data', 'Warning: This will replace all current data with test data. Are you sure?',
            async () => { 
                loadMockData();
                setMessage({ type: 'success', text: 'Mock data loaded successfully. Refreshing list...' });
            }
        );
    };

    const handleDownloadImportTemplate = () => {
        exportSheetTemplate('Institutions_Import_Template');
        setMessage({ type: 'success', text: '✅ Template download has started.' });
    };

    const handleExportInstitutionsForPopulation = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

        const dataRows: any[] = [];
        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);

            if (years.length > 0) {
                years.forEach(y => {
                    dataRows.push({
                        institutionId: inst.id,
                        year: y,
                        population: populations[y]
                    });
                });
            } else {
                dataRows.push({
                    institutionId: inst.id,
                    year: new Date().getFullYear(),
                    population: 0
                });
            }
        });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(dataRows, { header: ['institutionId', 'year', 'population'] });
        XLSX.utils.book_append_sheet(wb, ws, 'Population');
        XLSX.writeFile(wb, `Institutions_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ The population list has been exported.' });
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !setCustomLogo) return;
        setMessage({ type: 'success', text: 'Processing logo...' });
        resizeImage(file, 200, 200, 0.9, (dataUrl) => {
            if (dataUrl) {
                setCustomLogo(dataUrl);
                setMessage({ type: 'success', text: 'Logo updated successfully.' });
            } else {
                setMessage({ type: 'error', text: 'Failed to process logo.' });
            }
        });
        e.target.value = '';
    };

    const handleResetLogo = () => {
        if (setCustomLogo) {
            confirmAction('Confirm Resetting to Default Logo', 'Are you sure you want to revert to the default logo?',
                async () => {
                    setCustomLogo(null);
                    setMessage({ type: 'success', text: 'Default logo has been restored.' });
                }
            );
        }
    }

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Institution Import', 'This will add or update institutions and population data. Existing names or IDs will be updated to prevent duplication.',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });
                        const sheetName = workbook.SheetNames[0];
                        const worksheet = workbook.Sheets[sheetName];
                        const json = XLSX.utils.sheet_to_json(worksheet);

                        // Map to consolidate data from Excel
                        // We map by Name to handle duplicates in the Excel file itself, but we also track IDs
                        const excelDataMap = new Map<string, { state?: string, id?: number, populations: Record<number, number>, pin?: string }>();

                        json.forEach((row: any) => {
                            const name = (row['Institution'] || row['Name'] || row['name'])?.toString().trim();
                            const instId = (row['institutionId'] || row['id']) ? Number(row['institutionId'] || row['id']) : undefined;
                            const state = (row['State'] || row['state'])?.toString().trim();
                            const year = Number(row['Year'] || row['year']);
                            const population = Number(row['Population'] || row['population']);
                            const pin = (row['PIN'] || row['pin']) ? String(row['PIN'] || row['pin']) : undefined;

                            if (!name && !instId) return;

                            // Consolidate logic: group by Name if available, otherwise by ID
                            const mapKey = name || `id_${instId}`;
                            if (!excelDataMap.has(mapKey)) {
                                excelDataMap.set(mapKey, { state, id: instId, populations: {}, pin });
                            }
                            const entry = excelDataMap.get(mapKey)!;
                            if (!isNaN(year) && !isNaN(population)) entry.populations[year] = population;
                            if (state && !entry.state) entry.state = state;
                            if (pin && !entry.pin) entry.pin = pin;
                            if (instId && !entry.id) entry.id = instId;
                        });

                        let addedCount = 0;
                        let updatedCount = 0;

                        excelDataMap.forEach((val, nameKey) => {
                            let existingInst;

                            // 1. First, try to match by ID
                            if (val.id) {
                                existingInst = users.find(u => Number(u.id) === Number(val.id));
                            }

                            // 2. If no ID match or no ID provided, try matching by Name (Normalized)
                            if (!existingInst && !nameKey.startsWith('id_')) {
                                const normalizedSearchName = nameKey.toLowerCase().trim();
                                existingInst = users.find(u => 
                                    u.role === UserRole.INSTITUTION && 
                                    u.name.toLowerCase().trim() === normalizedSearchName
                                );
                            }

                            if (existingInst) {
                                // Update existing record
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    id: Number(existingInst.id),
                                    state: val.state || existingInst.state,
                                    pin: val.pin || existingInst.pin, // Update password if provided in Excel
                                    isDefaultPin: val.pin ? false : existingInst.isDefaultPin,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else if (!nameKey.startsWith('id_')) {
                                // Add as new record only if Name is provided and not found
                                addInstitution(nameKey, val.state, val.populations);
                                addedCount++;
                            }
                        });

                        let resultMsg = '';
                        if (addedCount > 0) resultMsg += `✅ Added ${addedCount} institution(s). `;
                        if (updatedCount > 0) resultMsg += `🔄 Updated data for ${updatedCount} institution(s).`;
                        if (!resultMsg) resultMsg = '⚠️ No valid changes found in file.';

                        setMessage({ type: 'success', text: resultMsg });

                    } catch (error) {
                        setMessage({ type: 'error', text: 'Failed to process file contents.' });
                    }
                };
                reader.readAsBinaryString(file);
            }
        );
        e.target.value = '';
    };

    const handleExportFullBackup = async (isSilent: boolean = false) => { 
        if (!context) return;
        if(!isSilent) setMessage({ type: 'success', text: 'Exporting full backup...' });
        exportFullBackup({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: context.firebaseConfig }, 'EPI_Full_Backup'); 
        if(!isSilent) setMessage({ type: 'success', text: '✅ Full backup exported.' });
    };

    const handleImportFullBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file || !handleImportFullBackupFile) return;

        confirmAction('Confirm Full Backup Restore', 'Warning: This will replace all current program data. This action cannot be undone.',
            async () => { 
                try {
                    setMessage({ type: 'success', text: 'Importing data...' });
                    const importedData = await importFullBackup(file);
                    handleImportFullBackupFile(importedData);
                    setMessage({ type: 'success', text: 'Full backup imported successfully.' });
                } catch (error: any) {
                    setMessage({ type: 'error', text: error.message || 'Failed to import file.' });
                }
                e.target.value = '';
            }
        );
    };

    const handleSaveAppName = () => {
        if (!appNameInput.trim()) {
