                  {pinChangeError && <p className="text-red-600 text-sm font-bold">{pinChangeError}</p>}
                  <div>
                      <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">الرمز السري الجديد</label>
                      <input 
                        ref={newPinInputRef}
                        type="password" 
                        value={newPin} 
                        onChange={e => setNewPin(e.target.value)} 
                        className="input-style" 
                        placeholder="****" 
                        onKeyDown={handleNewPinKeyDown}
                        autoFocus 
                      />
                  </div>
                  <div>
                      <label className="block text-sm font-bold text-gray-700 dark:text-gray-300">تأكيد الرمز السري</label>
                      <input 
                        ref={confirmNewPinInputRef}
                        type="password" 
                        value={confirmNewPin} 
                        onChange={e => setConfirmNewPin(e.target.value)} 
                        className="input-style" 
                        placeholder="****" 
                      />
                  </div>
                  <button type="submit" className="w-full py-3 bg-green-700 text-white rounded-xl font-bold hover:bg-green-800 transition-all shadow-md active:scale-95">حفظ وتدقيق الدخول</button>
              </form>
          </Modal>
      )}

      <div className="w-full max-w-md p-10 bg-white rounded-[2.5rem] text-center golden-frame dark:bg-slate-900 animate-fade-in relative">
