        <h1 className="text-3xl font-extrabold text-green-900 dark:text-green-400 mb-10">{appName}</h1>

        {mode === 'initial' && (
          <div className="space-y-5">
            <button onClick={() => setMode('supervisor')} className="w-full py-5 text-xl font-extrabold text-white bg-green-700 rounded-2xl hover:bg-green-800 transition-all shadow-[0_8px_0_rgb(5,150,105)] active:translate-y-1 active:shadow-none">المشرف</button>
            <button onClick={() => setMode('institution')} className="w-full py-5 text-xl font-extrabold text-green-800 bg-white rounded-2xl border-4 border-green-700 hover:bg-green-50 transition-all dark:bg-slate-800 dark:text-green-300 dark:border-green-600">المؤسسة الصحية</button>
            <button onClick={() => setMode('immunization')} className="w-full py-5 text-xl font-extrabold text-white bg-blue-600 rounded-2xl hover:bg-blue-700 transition-all shadow-md active:translate-y-1 active:shadow-none">قسم التحصين</button>
          </div>
        )}

        {(mode === 'supervisor' || mode === 'immunization') && (
