  firebaseConfig: any;
  setFirebaseConfig: (config: any) => void;
  isDistributable: boolean;
  isPublishedConnected: boolean;
  currentUser: User | null;

  students: Student[];
  halaqas: Halaqa[];
  evaluations: Evaluation[];
  updateEvaluation: (e: any) => void;
  deleteEvaluation: (id: number) => void;
  addEvaluation: (e: any) => void;
  setLastUsedWeek: (week: number | null) => void;

  maghribAttendances: MaghribAttendance[];
  addMaghribAttendance: (att: any) => void;
  deleteMaghribAttendance: (id: number) => void;
  maghribPassword: string;
  setMaghribPassword: (p: string) => void;

  immunizationPassword: string;
  setImmunizationPassword: (p: string) => void;

  setHasUnsavedChanges: (hasChanges: boolean) => void;
}

export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          return savedUser ? JSON.parse(savedUser) : null;
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS, 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);
  const [lastUsedWeek, setLastUsedWeek] = useState<number | null>(null);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const getNextId = (collection: any[], startingId: number = 1) => {
      if (!collection || collection.length === 0) {
          return startingId;
      }
      const maxId = collection.reduce((max, item) => (Number(item.id) > max ? Number(item.id) : max), 0);
      return Math.max(maxId + 1, startingId);
  };

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).compressedEmbeddedAppData) {
      try {
        const compressedBytes = base64ToBytes((window as any).compressedEmbeddedAppData);
        const zip = await JSZip.loadAsync(compressedBytes);
        const file = zip.file("data.json");
        if (file) {
          const jsonString = await file.async('string');
          loadedConfig = JSON.parse(jsonString);
        } else {
          throw new Error("data.json not found in compressed payload");
        }
      } catch (e) {
        console.error("Failed to decompress embedded data", e);
      }
    } else if ((window as any).embeddedAppData) {
       try {
           loadedConfig = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob((window as any).embeddedAppData), c => c.charCodeAt(0))));
       } catch(e) { console.error("Failed to parse embedded data", e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: (loadedConfig.users || INITIAL_USERS).map(u => ({ ...u, id: Number(u.id) })),
        reports: (loadedConfig.reports || []).map(r => ({ ...r, id: Number(r.id), institutionId: Number(r.institutionId) })),
        students: (loadedConfig.students || []).map(s => ({ ...s, id: Number(s.id), halaqaId: Number(s.halaqaId) })),
        halaqas: (loadedConfig.halaqas || []).map(h => ({ ...h, id: Number(h.id), institutionId: Number(h.institutionId) })),
        evaluations: (loadedConfig.evaluations || []).map(ev => ({ ...ev, id: Number(ev.id), studentId: Number(ev.studentId) })),
        maghribAttendances: (loadedConfig.maghribAttendances || []).map(m => ({ ...m, id: Number(m.id) })),
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setMaghribPasswordState(loadedConfig.maghribPassword || '123456');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          if (loadedConfig.firebaseConfig) {
              setFirebaseConfigState(loadedConfig.firebaseConfig);
          } else {
              setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
          }
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: data.students,
            halaqas: data.halaqas,
            evaluations: data.evaluations,
            maghribAttendances: data.maghribAttendances,
            customLogo, supervisorPassword, maghribPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, maghribPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            setData({
              users: val.users ? Object.values(val.users).map((u:any) => ({...u, id: Number(u.id)})) : INITIAL_USERS,
              reports: val.reports ? Object.values(val.reports).map((r:any) => ({...r, id: Number(r.id)})) : [],
              students: val.students ? Object.values(val.students).map((s:any) => ({...s, id: Number(s.id)})) : [],
              halaqas: val.halaqas ? Object.values(val.halaqas).map((h:any) => ({...h, id: Number(h.id)})) : [],
              evaluations: val.evaluations ? Object.values(val.evaluations).map((e:any) => ({...e, id: Number(e.id)})) : [],
              maghribAttendances: val.maghribAttendances ? Object.values(val.maghribAttendances).map((m:any) => ({...m, id: Number(m.id)})) : [],
              deletedItems: [],
            });
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.maghribPassword) setMaghribPasswordState(val.maghribPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    if (firebaseConnectionStatus !== 'connected') {
        const parts = path.split('/');
        // Format should be data/collectionName/id
        if (parts.length === 3 && parts[0] === 'data') {
            const collection = parts[1] as keyof typeof data;
            const itemId = Number(parts[2]);

            setData(prev => {
                const list = [...(prev[collection] as any[])];
                if (value === null) {
                    return { ...prev, [collection]: list.filter(i => Number(i.id) !== itemId) };
                }

                const index = list.findIndex(i => Number(i.id) === itemId);
                const newItem = { ...value, id: itemId };

                if (index > -1) {
                    list[index] = newItem;
                    return { ...prev, [collection]: list };
                } else {
                    return { ...prev, [collection]: [...list, newItem] };
                }
            });
        } else if (path === 'data' && value) {
            setData(prev => ({
                ...prev,
                users: value.users ? (Array.isArray(value.users) ? value.users : Object.values(value.users)).map((u:any) => ({...u, id: Number(u.id)})) : prev.users,
                reports: value.reports ? (Array.isArray(value.reports) ? value.reports : Object.values(value.reports)).map((r:any) => ({...r, id: Number(r.id)})) : prev.reports
            }));
        }
    }
  };

  const addReport = (rep: any) => {
      const newId = getNextId(data.reports);
      writeData(`data/reports/${newId}`, { ...rep, id: newId, updatedAt: Date.now() });
  };
  const updateReport = (rep: any) => writeData(`data/reports/${Number(rep.id)}`, { ...rep, id: Number(rep.id), updatedAt: Date.now() });
  const deleteReport = (id: number) => writeData(`data/reports/${Number(id)}`, null);

  const addInstitution = (n: string, state?: string, population?: { [year: number]: number }) => {
      const newId = getNextId(data.users, 2); 
      writeData(`data/users/${newId}`, { 
          id: newId, 
          name: n, 
          state: state || null,
          role: UserRole.INSTITUTION, 
          pin: '1234', // Mapped initial pin
          population: population || {},
          updatedAt: Date.now() 
      });
  };
  const updateInstitution = (u: User) => writeData(`data/users/${Number(u.id)}`, { ...u, id: Number(u.id), updatedAt: Date.now() });
  const deleteInstitution = (institutionId: number) => writeData(`data/users/${Number(institutionId)}`, null);

  const addEvaluation = (e: any) => {
      const newId = getNextId(data.evaluations);
      writeData(`data/evaluations/${newId}`, { ...e, id: newId, updatedAt: Date.now() });
  };
  const updateEvaluation = (e: any) => writeData(`data/evaluations/${Number(e.id)}`, { ...e, id: Number(e.id), updatedAt: Date.now() });
  const deleteEvaluation = (id: number) => writeData(`data/evaluations/${Number(id)}`, null);

  const addMaghribAttendance = (att: any) => {
      const id = att.id || getNextId(data.maghribAttendances);
      writeData(`data/maghribAttendances/${Number(id)}`, { ...att, id: Number(id), updatedAt: Date.now() });
  };
  const deleteMaghribAttendance = (id: number) => writeData(`data/maghribAttendances/${Number(id)}`, null);

  const handleLogout = () => { 
      if (hasUnsavedChanges) {
          alert('⚠️ تحذير: لديك تغييرات غير محفوظة.');
          return;
      }
      setCurrentUser(null); 
      setHasUnsavedChanges(false);
      localStorage.removeItem(CURRENT_USER_KEY); 
  };

  const initiateLogoutCheck = () => { handleLogout(); };
  const handleLogin = (user: User) => { setCurrentUser(user); localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user)); };
  const handleSaveFirebaseConfig = (config: any) => { setFirebaseConfigState(config); };

  const showSetupWizard = isDistributable && !firebaseConfigState && !isPublishedConnected;

  return (
    <AppContext.Provider value={{
      users: data.users, reports: data.reports,
      addReport, updateReport, deleteReport, 
      deleteAllReports: async () => { writeData('data/reports', null); },
      deleteAllData: async () => writeData('data', { users: { '1': { ...INITIAL_USERS[0], id: 1 } } }),
      loadMockData: () => {
          writeData('data', { users: MOCK_USERS, reports: MOCK_REPORTS });
      },
      customLogo, setCustomLogo: (l) => { setCustomLogoState(l); writeData('config/customLogo', l); },
      addInstitution, updateInstitution, deleteInstitution, importFullBackup: (d) => writeData('data', d),
      supervisorPassword, setSupervisorPassword: (p) => { setSupervisorPasswordState(p); writeData('config/supervisorPassword', p); },
      logout: handleLogout, isLoading, initiateLogoutCheck, appName, setAppName: (n) => { setAppNameState(n); writeData('config/appName', n); },
      darkMode, toggleDarkMode: () => setDarkMode(!darkMode), 
      firebaseConnectionStatus, 
      firebaseConfig: firebaseConfigState, 
      setFirebaseConfig: handleSaveFirebaseConfig,
      isDistributable, isPublishedConnected, currentUser,
      students: data.students, 
      halaqas: data.halaqas, 
      evaluations: data.evaluations,
      updateEvaluation, deleteEvaluation, addEvaluation,
      setLastUsedWeek,
      maghribAttendances: data.maghribAttendances,
      addMaghribAttendance,
      deleteMaghribAttendance,
      maghribPassword, 
      setMaghribPassword: (p) => { setMaghribPasswordState(p); writeData('config/maghribPassword', p); },
      immunizationPassword,
      setImmunizationPassword: (p) => { setImmunizationPasswordState(p); writeData('config/immunizationPassword', p); },
      setHasUnsavedChanges
    }}>
      <div className={`h-screen flex flex-col transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-green-50 text-gray-900'}`}>
          {showSetupWizard && <FirebaseSetupWizard onConfigSave={handleSaveFirebaseConfig} />}
          {!currentUser ? (
              <LoginScreen onLogin={handleLogin} />
          ) : (
              <div className="flex flex-col h-full">
                  <Header 
                      user={currentUser} 
                      onShowHelp={() => setShowHelpModal(true)} 
                      onInitiateLogoutCheck={initiateLogoutCheck} 
                      onShowMobileInstallModal={() => setShowMobileInstallModal(true)} 
                      onShowChangePassword={() => setShowChangePasswordModal(true)} 
                  />
                  <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                      {currentUser.role === UserRole.SUPERVISOR && <SupervisorDashboard />}
                      {currentUser.role === UserRole.IMMUNIZATION && <ImmunizationDashboard />}
                      {currentUser.role === UserRole.INSTITUTION && <InstitutionDashboard institutionId={currentUser.id} />}
                  </main>
              </div>
          )}
          {showHelpModal && <HelpModal onClose={() => setShowHelpModal(false)} />}
          {showMobileInstallModal && <MobileInstallModal onClose={() => setShowMobileInstallModal(false)} />}
          {showChangePasswordModal && currentUser && (
            <ChangePasswordModal 
                onClose={() => setShowChangePasswordModal(false)} 
                currentStoredPassword={
                    currentUser.role === UserRole.SUPERVISOR ? supervisorPassword : 
                    currentUser.role === UserRole.IMMUNIZATION ? immunizationPassword :
                    (currentUser.pin || '1234')
                }
                onSave={(p) => {
                    if (currentUser.role === UserRole.SUPERVISOR) {
                        setSupervisorPasswordState(p); 
                        writeData('config/supervisorPassword', p);
                    } else if (currentUser.role === UserRole.IMMUNIZATION) {
                        setImmunizationPasswordState(p);
                        writeData('config/immunizationPassword', p);
                    } else if (currentUser.role === UserRole.INSTITUTION) {
                        const updatedUser = { ...currentUser, id: Number(currentUser.id), pin: p, updatedAt: Date.now() };
                        updateInstitution(updatedUser);
                        setCurrentUser(updatedUser);
                        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updatedUser));
                    }
                }} 
            />
          )}
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState, useContext, useMemo, useEffect, useRef } from 'react';
import { User, UserRole } from '../types';
import Logo from './Logo';
import { AppContext } from '../App';
import { isSmartMatch } from '../utils/searchUtils';
import Modal from './Modal';

interface LoginScreenProps {
  onLogin: (user: User) => void;
}

const REMEMBER_SUPERVISOR_KEY = 'hafiz_rem_sup';
const REMEMBER_IMMUNIZATION_KEY = 'hafiz_rem_imm';
const REMEMBER_INSTITUTION_PREFIX = 'hafiz_rem_inst_';

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const context = useContext(AppContext);
  if (!context) return null;

  const { users, supervisorPassword, immunizationPassword, appName, darkMode, toggleDarkMode, updateInstitution } = context;

  const [mode, setMode] = useState<'initial' | 'supervisor' | 'institution' | 'immunization'>('initial');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState('');
  const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

  // Institution Login State
  const [selectedInstitution, setSelectedInstitution] = useState<User | null>(null);
  const [pinInput, setPinInput] = useState('');
  const [rememberPin, setRememberPin] = useState(false);

  const passwordInputRef = useRef<HTMLInputElement>(null);
  const pinInputRef = useRef<HTMLInputElement>(null);

  // Filter users by INSTITUTION role
  const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

  useEffect(() => {
    if (mode === 'supervisor') {
      const saved = localStorage.getItem(REMEMBER_SUPERVISOR_KEY);
      if (saved) {
        setPassword(saved);
        setRememberMe(true);
        if (passwordInputRef.current) passwordInputRef.current.blur();
      } else {
        setPassword('');
        setRememberMe(false);
        setTimeout(() => {
            if (passwordInputRef.current) passwordInputRef.current.focus();
        }, 50);
      }
    } else if (mode === 'immunization') {
      const saved = localStorage.getItem(REMEMBER_IMMUNIZATION_KEY);
      if (saved) {
        setPassword(saved);
        setRememberMe(true);
        if (passwordInputRef.current) passwordInputRef.current.blur();
      } else {
        setPassword('');
        setRememberMe(false);
        setTimeout(() => {
            if (passwordInputRef.current) passwordInputRef.current.focus();
        }, 50);
      }
    }
  }, [mode]);

  useEffect(() => {
    if (selectedInstitution) {
        const savedPin = localStorage.getItem(`${REMEMBER_INSTITUTION_PREFIX}${selectedInstitution.id}`);
        if (savedPin) {
            setPinInput(savedPin);
            setRememberPin(true);
        } else {
            setPinInput('');
            setRememberPin(false);
        }

        if (pinInputRef.current) {
            setTimeout(() => pinInputRef.current?.focus(), 50);
        }
    }
  }, [selectedInstitution]);

  const handleLoginAttempt = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (mode === 'supervisor') {
      if (password === supervisorPassword) {
        if (rememberMe) {
          localStorage.setItem(REMEMBER_SUPERVISOR_KEY, password);
        } else {
          localStorage.removeItem(REMEMBER_SUPERVISOR_KEY);
        }

        const supervisor = users.find(u => u.role === UserRole.SUPERVISOR);
        if (supervisor) {
            onLogin(supervisor);
        } else {
            onLogin({
                id: 1,
                name: 'Main Supervisor',
                role: UserRole.SUPERVISOR,
                updatedAt: Date.now()
            });
        }
      } else setError('Incorrect supervisor password');
    } else if (mode === 'immunization') {
        if (password === immunizationPassword) {
            if (rememberMe) {
                localStorage.setItem(REMEMBER_IMMUNIZATION_KEY, password);
            } else {
                localStorage.removeItem(REMEMBER_IMMUNIZATION_KEY);
            }

            const immunizationUser: User = {
                id: 999,
                name: 'Immunization Dept. Manager',
                role: UserRole.IMMUNIZATION,
                updatedAt: Date.now()
            };
            onLogin(immunizationUser);
        } else setError('Incorrect Immunization Dept. password');
    }
  };

  const handleInstitutionSelect = (institution: User) => {
      setSelectedInstitution(institution);
      setError('');
  };

  const handleInstitutionPinSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!selectedInstitution) return;

      const userPin = selectedInstitution.pin || '1234';

      if (pinInput === userPin) {
          const key = `${REMEMBER_INSTITUTION_PREFIX}${selectedInstitution.id}`;
          if (rememberPin) {
              localStorage.setItem(key, pinInput);
          } else {
              localStorage.removeItem(key);
          }
          // Direct login, no more mandatory change on first login
          onLogin(selectedInstitution);
      } else {
          setError('Incorrect PIN');
      }
  };

  const filteredInstitutions = useMemo(() => {
    return institutions
      .filter(t => isSmartMatch(t.name, institutionSearchTerm))
      .sort((a, b) => a.name.localeCompare(b.name, 'en'));
  }, [institutions, institutionSearchTerm]);

  return (
    <div className="flex flex-col items-center justify-center flex-1 p-4">
      <button 
        onClick={toggleDarkMode} 
        className="absolute top-6 left-6 p-3 rounded-full bg-white shadow-xl dark:bg-gray-800 dark:text-yellow-400 border-2 border-gray-200 dark:border-gray-700 transition-all active:scale-90 z-50 text-xl"
      >
        {darkMode ? '☀️' : '🌙'}
      </button>

      <div className="w-full max-w-md p-10 bg-white rounded-[2.5rem] text-center golden-frame dark:bg-slate-900 animate-fade-in relative">
        <Logo className="h-28 w-28 mx-auto mb-6 drop-shadow-lg" />
        <h1 className="text-4xl font-extrabold text-green-900 dark:text-green-400 mb-10">{appName}</h1>

        {mode === 'initial' && (
          <div className="space-y-5">
            <button onClick={() => setMode('supervisor')} className="w-full py-5 text-xl font-extrabold text-white bg-green-700 rounded-2xl hover:bg-green-800 transition-all shadow-[0_8px_0_rgb(5,150,105)] active:translate-y-1 active:shadow-none">Supervisor</button>
            <button onClick={() => setMode('institution')} className="w-full py-5 text-xl font-extrabold text-green-800 bg-white rounded-2xl border-4 border-green-700 hover:bg-green-50 transition-all dark:bg-slate-800 dark:text-green-300 dark:border-green-600">Institution</button>
            <button onClick={() => setMode('immunization')} className="w-full py-5 text-xl font-extrabold text-white bg-blue-600 rounded-2xl hover:bg-blue-700 transition-all shadow-md active:translate-y-1 active:shadow-none">Immunization Dept</button>
          </div>
        )}

        {(mode === 'supervisor' || mode === 'immunization') && (
          <form onSubmit={handleLoginAttempt} className="space-y-6">
            <h3 className="text-2xl font-bold text-gray-800 dark:text-white underline decoration-gold-light underline-offset-8 decoration-4">
                {mode === 'supervisor' ? 'Supervisor Login' : 'Immunization Dept. Login'}
            </h3>

            <div className="space-y-4 text-left">
              <input
                ref={passwordInputRef}
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Enter password"
                className="input-style text-center text-3xl tracking-[0.5rem] font-bold placeholder:text-xl"
              />

              <label className="flex items-center gap-3 cursor-pointer p-1">
                <input 
                  type="checkbox" 
                  checked={rememberMe} 
                  onChange={e => setRememberMe(e.target.checked)}
                  className="w-6 h-6 rounded border-gray-300 text-green-700 focus:ring-green-500 dark:bg-gray-700 dark:border-gray-600"
                />
                <span className="text-lg font-bold text-gray-700 dark:text-gray-300">Remember Password</span>
              </label>
            </div>

