import React, { useState, useEffect, useRef } from 'react';
import Modal from './Modal';

interface ChangePasswordModalProps {
  onClose: () => void;
  currentStoredPassword: string;
  onSave: (password: string) => void;
  isMandatory?: boolean; // Prop to force password change
}

const ChangePasswordModal: React.FC<ChangePasswordModalProps> = ({ onClose, currentStoredPassword, onSave, isMandatory = false }) => {
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const oldPasswordInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (oldPasswordInputRef.current && window.innerWidth >= 768) {
      oldPasswordInputRef.current.focus();
    }
  }, []);

  useEffect(() => {
    if (message) {
      setMessage(null);
    }
  }, [oldPassword, newPassword, confirmPassword]);

  const handleSubmitPassword = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);

    if (oldPassword !== currentStoredPassword) {
      setMessage({ type: 'error', text: 'الرقم السري الحالي غير صحيح.' });
      return;
    }
    if (newPassword.length < 3) {
      setMessage({ type: 'error', text: 'يجب أن يتكون الرقم السري الجديد من 3 خانات على الأقل.' });
      return;
    }
    if (newPassword === '123') {
        setMessage({ type: 'error', text: 'لا يمكن استخدام الرقم السري الافتراضي "123". الرجاء اختيار رقم آخر.' });
        return;
    }
    if (newPassword !== confirmPassword) {
      setMessage({ type: 'error', text: 'الرقم السري الجديد وتأكيده غير متطابقين.' });
      return;
    }

    onSave(newPassword);
    setMessage({ type: 'success', text: 'تم تغيير الرقم السري بنجاح.' });

    setTimeout(() => {
        setOldPassword('');
        setNewPassword('');
        setConfirmPassword('');
        onClose();
    }, 1500);
  };

  const handleInputFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    if (window.innerWidth < 768) {
        setTimeout(() => {
            e.target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 250);
    }
  };

  return (
    <Modal title={isMandatory ? "إعداد الرقم السري لأول مرة" : "تغيير الرقم السري"} onClose={onClose} hideDefaultCloseButton={true}>
      <form onSubmit={handleSubmitPassword} className="space-y-4">
