export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    // We use the current document's HTML as a base
    let htmlString = document.documentElement.outerHTML;

    // Remove existing embedded data scripts to avoid duplicates
    htmlString = htmlString.replace(/<script type="text\/javascript">window\.compressedEmbeddedAppData = '.*?';<\/script>/g, '');
    htmlString = htmlString.replace(/<script type="text\/javascript">window\.embeddedAppData = '.*?';<\/script>/g, '');

    // Remove development-only scripts like React Error Overlay
    htmlString = htmlString.replace(/<script src="\/@react-refresh".*?><\/script>/g, '');
    htmlString = htmlString.replace(/<script type="module" src="\/@vite\/client"><\/script>/g, '');

    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS, reports: [], students: [], halaqas: [], evaluations: [],
        customLogo: null, supervisorPassword: '123', immunizationPassword: '12345',
        appName: appData.appName, isDistributable: true, isPublishedConnected: false, firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { ...appData, isDistributable: true, isPublishedConnected: true };
    }

    const jsonDataString = JSON.stringify(appDataForEmbedding);
    const zip = new JSZip();
    zip.file("data.json", jsonDataString);
    const compressedBytes = await zip.generateAsync({ type: "uint8array", compression: "DEFLATE", compressionOptions: { level: 9 } });
    const encodedCompressedData = bytesToBase64(compressedBytes);

    const dataScript = `<script type="text/javascript">window.compressedEmbeddedAppData = '${encodedCompressedData}';</script>`;

    // Insert the data script before the closing body tag
    const bodyEndTag = '</body>';
    if (htmlString.includes(bodyEndTag)) {
        htmlString = htmlString.replace(bodyEndTag, `${dataScript}\n${bodyEndTag}`);
    } else {
        htmlString += dataScript;
    }

    // Update the title
    if (appData.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appData.appName}</title>`);
    }

    // Ensure we use a browser-side loader for TSX if running standalone
    // We replace the standard index.tsx module script with a loader-friendly version
    htmlString = htmlString.replace(
        '<script type="module" src="index.tsx"></script>',
        '<script type="module" src="https://esm.sh/run"></script>\n<script type="text/babel" src="index.tsx" data-type="module"></script>'
    );

    return htmlString;
};

