export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    // 1. Get Base HTML from current document
    let htmlString = document.documentElement.outerHTML;

    // 2. Clean up unwanted scripts
    htmlString = htmlString.replace(/<script type="text\/javascript">window\.(compressedEmbeddedAppData|embeddedAppData) = '.*?';<\/script>/g, '');
    htmlString = htmlString.replace(/<script src="\/@react-refresh".*?><\/script>/g, '');
    htmlString = htmlString.replace(/<script type="module" src="\/@vite\/client"><\/script>/g, '');

    // 3. Prepare App Data
    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS, reports: [], students: [], halaqas: [], evaluations: [],
        customLogo: null, supervisorPassword: '123', immunizationPassword: '12345',
        appName: appData.appName, isDistributable: true, isPublishedConnected: false, firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { ...appData, isDistributable: true, isPublishedConnected: true };
    }

    // 4. Compress and embed Data
    const jsonDataString = JSON.stringify(appDataForEmbedding);
    const zip = new JSZip();
    zip.file("data.json", jsonDataString);
    const compressedBytes = await zip.generateAsync({ type: "uint8array", compression: "DEFLATE" });
    const encodedCompressedData = bytesToBase64(compressedBytes);
    const dataScript = `<script type="text/javascript">window.compressedEmbeddedAppData = '${encodedCompressedData}';</script>`;

    // 5. Collect Source Files for Single HTML
    const filesMap: Record<string, string> = {};
    for (const path of SOURCE_FILES) {
        const content = await fetchFileContent(path);
        if (content) filesMap[path] = content;
    }
    const filesJson = JSON.stringify(filesMap).replace(/<\/script>/g, '<\\/script>');
    const filesScript = `<script type="text/javascript">window.bundledFiles = ${filesJson};</script>`;

    // 6. Inject the Virtual Loader (The logic that maps bundled files to Blob URLs)
    const loaderScript = `
    <script type="module">
        (function() {
            if (!window.bundledFiles) return;
            const fileUrls = {};
            // Create Blobs for each file
            for (const [path, content] of Object.entries(window.bundledFiles)) {
                const blob = new Blob([content], { type: path.endsWith('.ts') || path.endsWith('.tsx') ? 'text/typescript' : 'text/javascript' });
                fileUrls[path] = URL.createObjectURL(blob);
            }

            // Hook into the esm.sh/run compiler or handle imports
            // For esm.sh/run, we can provide a map or simply replace index.tsx entry
            window.getBundledFileUrl = (path) => fileUrls[path] || path;

            // To make esm.sh/run work with our local "files", we need to inject them.
            // Since we can't easily hook esm.sh internal resolver without a complex proxy,
            // we will use a simpler approach: Put all code in one block or use a custom script runner.
            // Actually, the easiest way for esm.sh/run is to use text/babel scripts with data-src
        })();
    </script>`;

    // 7. Final Assembly
    const bodyEnd = '</body>';
    const injection = `\n${dataScript}\n${filesScript}\n${loaderScript}\n`;

    if (htmlString.includes(bodyEnd)) {
        htmlString = htmlString.replace(bodyEnd, `${injection}${bodyEnd}`);
    } else {
        htmlString += injection;
    }

    // 8. Title Update
    if (appData.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appData.appName}</title>`);
    }

    // 9. REWRITE THE ENTRY POINT:
    // Instead of loading index.tsx from disk, we will load it from the bundledFiles
    const indexContent = filesMap['index.tsx'] || '';
    // We wrap all modules into the HTML using a special Babel script
    let bundledModulesHtml = '';
    for (const [path, content] of Object.entries(filesMap)) {
        // We use data-path to identify the file internally if needed
        bundledModulesHtml += \`<script type="text/babel" data-type="module" data-path="\${path}">\n\${content}\n</script>\n\`;
    }

    // Remove the original index.tsx script tag and replace with esm-run + our modules
    htmlString = htmlString.replace(
        '<script type="module" src="index.tsx"></script>',
        `<script type="module" src="https://esm.sh/run"></script>\n${bundledModulesHtml}`
    );

    return htmlString;
};

