            for (const [path, content] of Object.entries(window.bundledFiles)) {
                const blob = new Blob([content], { type: path.endsWith('.ts') || path.endsWith('.tsx') ? 'text/typescript' : 'text/javascript' });
                fileUrls[path] = URL.createObjectURL(blob);
            }

            // Hook into the esm.sh/run compiler or handle imports
            // For esm.sh/run, we can provide a map or simply replace index.tsx entry
            window.getBundledFileUrl = (path) => fileUrls[path] || path;

            // To make esm.sh/run work with our local "files", we need to inject them.
            // Since we can't easily hook esm.sh internal resolver without a complex proxy,
            // we will use a simpler approach: Put all code in one block or use a custom script runner.
            // Actually, the easiest way for esm.sh/run is to use text/babel scripts with data-src
        })();
    </script>`;

    // 7. Final Assembly
    const bodyEnd = '</body>';
    const injection = `\n${dataScript}\n${filesScript}\n${loaderScript}\n`;

    if (htmlString.includes(bodyEnd)) {
        htmlString = htmlString.replace(bodyEnd, `${injection}${bodyEnd}`);
    } else {
        htmlString += injection;
    }

    // 8. Title Update
    if (appData.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appData.appName}</title>`);
    }

    // 9. REWRITE THE ENTRY POINT:
    // Instead of loading index.tsx from disk, we will load it from the bundledFiles
    const indexContent = filesMap['index.tsx'] || '';
    // We wrap all modules into the HTML using a special Babel script
    let bundledModulesHtml = '';
    for (const [path, content] of Object.entries(filesMap)) {
        // We use data-path to identify the file internally if needed
        // Removed backslashes that were incorrectly escaping backticks and interpolation
        bundledModulesHtml += `<script type="text/babel" data-type="module" data-path="${path}">\n${content}\n</script>\n`;
    }

    // Remove the original index.tsx script tag and replace with esm-run + our modules
    htmlString = htmlString.replace(
        '<script type="module" src="index.tsx"></script>',
        `<script type="module" src="https://esm.sh/run"></script>\n${bundledModulesHtml}`
    );

    return htmlString;
};

