import { FullBackupData } from '../types';
import { INITIAL_USERS } from '../constants';

declare const JSZip: any;

/**
 * وظيفة لتنظيف نصوص الكود البرمجي قبل دمجها لضمان عدم كسر هيكل HTML
 */
const escapeScriptTags = (code: string) => {
  return code.replace(/<\/script>/g, '<\\/script>').replace(/<\/style>/g, '<\\/style>');
};

export const utf8ToBase64 = (str: string): string => {
  try {
    const bytes = new TextEncoder().encode(str);
    let binary = "";
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  } catch (e) {
    console.error("Base64 Encoding Error:", e);
    return "";
  }
};

const bytesToBase64 = (bytes: Uint8Array): string => {
  let binary = "";
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
};

const SOURCE_FILES = [
    'index.tsx', 'App.tsx', 'types.ts', 'constants.ts',
    'components/LoginScreen.tsx', 'components/Header.tsx', 'components/InstitutionDashboard.tsx',
    'components/SupervisorDashboard.tsx', 'components/DashboardStats.tsx', 'components/ReportsTable.tsx',
    'components/InstitutionManagement.tsx', 'components/Settings.tsx', 'components/Logo.tsx',
    'components/HelpModal.tsx', 'components/OverviewTable.tsx', 'components/ChangePasswordModal.tsx',
    'components/EvaluationEditForm.tsx', 'components/FirebaseSetupWizard.tsx', 'components/MonthlyEntryForm.tsx',
    'components/ImmunizationDashboard.tsx', 'components/PasswordManagement.tsx', 'components/Modal.tsx',
    'components/MobileInstallModal.tsx',
    'utils/firebase.ts', 'utils/exportWord.ts', 'utils/exportExcel.ts', 'utils/exportPdf.ts',
    'utils/searchUtils.ts', 'utils/fullBackup.ts', 'utils/distributableApp.ts', 'utils/exportSheetTemplate.ts'
];

const fetchFileContent = async (path: string): Promise<string> => {
    try {
        const response = await fetch(path);
        if (!response.ok) return '';
        return await response.text();
    } catch (e) {
        return '';
    }
};

export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    // 1. جلب هيكل الصفحة الحالي
    let htmlString = document.documentElement.outerHTML;

    // 2. تنظيف الصفحة من السكربتات المدمجة سابقاً ومن مخلفات التطوير
    htmlString = htmlString.replace(/<script type="text\/javascript">window\.(compressedEmbeddedAppData|embeddedAppData|bundledFiles) = '.*?';<\/script>/g, '');
    htmlString = htmlString.replace(/<script src="\/@react-refresh".*?><\/script>/g, '');
    htmlString = htmlString.replace(/<script type="module" src="\/@vite\/client"><\/script>/g, '');
    htmlString = htmlString.replace(/<div id="react-error-overlay">.*?<\/div>/g, ''); // تنظيف أخطاء التطوير إن وجدت

    // 3. تجهيز بيانات التطبيق
    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS, reports: [], students: [], halaqas: [], evaluations: [],
        customLogo: null, supervisorPassword: '123', immunizationPassword: '12345',
        appName: appData.appName, isDistributable: true, isPublishedConnected: false, firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { ...appData, isDistributable: true, isPublishedConnected: true };
    }

    // 4. ضغط البيانات ودمجها كـ Base64
    const jsonDataString = JSON.stringify(appDataForEmbedding);
    const zip = new JSZip();
    zip.file("data.json", jsonDataString);
    const compressedBytes = await zip.generateAsync({ type: "uint8array", compression: "DEFLATE", compressionOptions: { level: 9 } });
    const encodedCompressedData = bytesToBase64(compressedBytes);
    const dataScript = `<script type="text/javascript">window.compressedEmbeddedAppData = '${encodedCompressedData}';</script>`;

    // 5. جمع كافة ملفات المصدر (TSX/TS) وتشفيرها لمنع تداخلها مع المتصفح
    let bundledModulesHtml = '';
    for (const path of SOURCE_FILES) {
        const content = await fetchFileContent(path);
        if (content) {
            // نستخدم سمة data-path للتعرف على الملف داخلياً
            bundledModulesHtml += `<script type="text/babel" data-type="module" data-path="${path}">\n${escapeScriptTags(content)}\n</script>\n`;
        }
    }

    // 6. حقن البيانات والسكربتات قبل نهاية وسم الجسم
    const bodyEnd = '</body>';
    const injection = `\n${dataScript}\n${bundledModulesHtml}\n`;

    if (htmlString.includes(bodyEnd)) {
        htmlString = htmlString.replace(bodyEnd, `${injection}${bodyEnd}`);
    } else {
        htmlString += injection;
    }

    // 7. تحديث عنوان الصفحة
    if (appData.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appData.appName}</title>`);
    }

    // 8. استبدال نقطة الدخول (Entry Point) بمحمل Babel (esm.sh/run)
    // هذا سيقوم بتشغيل كافة السكربتات من نوع text/babel التي قمنا بحقنها
    htmlString = htmlString.replace(
        /<script type="module" src="index.tsx"><\/script>/,
        `<script type="module" src="https://esm.sh/run"></script>`
    );

    return htmlString;
};

export const generateAndDownloadDistributableHtml = async (appData: FullBackupData, exportType: 'empty' | 'snapshot') => {
    try {
        const html = await getDistributableHtmlString(appData, exportType);

        // إنشاء Blob بصيغة HTML
        const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);

        // إنشاء رابط تحميل مخفي
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        const fileName = `${appData.appName || 'EPI'}_${exportType === 'empty' ? 'Setup' : 'Snapshot'}.html`.replace(/\s+/g, '_');
        a.download = fileName;

        document.body.appendChild(a);
        a.click();

        // تنظيف الذاكرة بعد قليل
        setTimeout(() => {
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
        }, 100);

        return true;
    } catch (e: any) { 
        console.error("HTML Generation Error:", e);
        alert("Error generating Single HTML file: " + e.message);
        return false;
    }
};

/**
 * توحيد الوظيفة لتقوم دائماً بتنزيل HTML واحد حتى لو تم استدعاء ZIP
 */
export const generateAndDownloadDistributableZip = async (appData: FullBackupData, exportType: 'empty' | 'snapshot') => {
    await generateAndDownloadDistributableHtml(appData, exportType);
};

