import React, { useState, useEffect, useRef } from 'react';
import Modal from './Modal';

interface ChangePasswordModalProps {
  onClose: () => void;
  currentStoredPassword: string;
  onSave: (password: string) => void;
  isMandatory?: boolean; 
}

const ChangePasswordModal: React.FC<ChangePasswordModalProps> = ({ onClose, currentStoredPassword, onSave, isMandatory = false }) => {
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const oldPasswordInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (oldPasswordInputRef.current && window.innerWidth >= 768) {
      oldPasswordInputRef.current.focus();
    }
  }, []);

  useEffect(() => {
    if (message) {
      setMessage(null);
    }
  }, [oldPassword, newPassword, confirmPassword]);

  const handleSubmitPassword = (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);

    if (oldPassword !== currentStoredPassword) {
      setMessage({ type: 'error', text: 'Incorrect current password.' });
      return;
    }
    if (newPassword.length < 6) {
      setMessage({ type: 'error', text: 'New password must be at least 6 characters long (letters or numbers).' });
      return;
    }
    if (newPassword === '123' || newPassword === '123456') {
        setMessage({ type: 'error', text: 'For security, please do not use simple sequences like "123" or "123456".' });
        return;
    }
    if (newPassword !== confirmPassword) {
      setMessage({ type: 'error', text: 'New password and confirmation do not match.' });
      return;
    }

    onSave(newPassword);
    setMessage({ type: 'success', text: 'Password updated successfully.' });

    setTimeout(() => {
        setOldPassword('');
        setNewPassword('');
        setConfirmPassword('');
        onClose();
    }, 1500);
  };

  const handleInputFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    if (window.innerWidth < 768) {
        setTimeout(() => {
            e.target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 250);
    }
  };

  return (
    <Modal title={isMandatory ? "Security Setup" : "Change Password"} onClose={onClose} hideDefaultCloseButton={true}>
      <form onSubmit={handleSubmitPassword} className="space-y-4">
        <div className="p-3 bg-amber-50 text-amber-800 dark:bg-amber-900/30 dark:text-amber-200 rounded-lg text-xs font-bold border border-amber-100">
            🔒 Requirement: The new password must be at least 6 characters (letters or numbers).
        </div>

        {isMandatory && (
            <div className="p-3 bg-blue-50 text-blue-800 dark:bg-blue-900/30 dark:text-blue-200 rounded-lg text-sm font-bold border border-blue-100 mb-2">
                ⚠️ For security, please change your default password before using the system.
            </div>
        )}

        {message && (
          <div className={`p-3 rounded-md text-center mb-4 text-sm font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'}`}>
            <p>{message.text}</p>
          </div>
        )}
        <div>
          <label htmlFor="old-password-modal" className="block text-sm font-medium text-gray-700 mb-1 dark:text-gray-200">Current Password</label>
          <input
            id="old-password-modal"
            type="password"
            value={oldPassword}
            onChange={(e) => setOldPassword(e.target.value)}
            className="input-style"
            required
            ref={oldPasswordInputRef}
            aria-label="Current Password"
            onFocus={handleInputFocus}
          />
        </div>
        <div>
          <label htmlFor="new-password-modal" className="block text-sm font-medium text-gray-700 mb-1 dark:text-gray-200">New Password (Min 6 chars)</label>
          <input
            id="new-password-modal"
            type="password"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            className="input-style"
            minLength={6}
            required
            placeholder="Min 6 characters..."
            aria-label="New Password"
            onFocus={handleInputFocus}
          />
        </div>
        <div>
          <label htmlFor="confirm-password-modal" className="block text-sm font-medium text-gray-700 mb-1 dark:text-gray-200">Confirm New Password</label>
          <input
            id="confirm-password-modal"
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className="input-style"
            minLength={6}
            required
            aria-label="Confirm New Password"
            onFocus={handleInputFocus}
          />
        </div>
        <div className="flex justify-end gap-4 mt-6 pt-4 border-t dark:border-gray-700">
            {!isMandatory && (
                <button
                    type="button"
                    onClick={onClose}
                    className="px-6 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors text-lg font-semibold focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600"
                >
                    Cancel
                </button>
            )}
            <button type="submit" className={`px-6 py-2 text-lg font-semibold text-white bg-green-700 rounded-lg hover:bg-green-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors ${isMandatory ? 'w-full' : ''}`}>
                Save New Password
            </button>
        </div>
      </form>
    </Modal>
  );
};

export default ChangePasswordModal;

