          {children}
        </div>

        {/* Footer الافتراضي إذا لم يتم إخفاؤه */}
        {!hideDefaultCloseButton && (
            <div className="flex justify-end px-6 py-4 bg-gray-50 dark:bg-gray-700/30 border-t dark:border-gray-700">
                <button
                    onClick={onClose}
                    className="px-6 py-2 bg-white text-gray-700 border border-gray-300 rounded-xl hover:bg-gray-50 transition-all text-sm font-bold shadow-sm dark:bg-gray-700 dark:text-gray-200 dark:border-gray-600 dark:hover:bg-gray-600"
                >
                    Close
                </button>
            </div>
        )}
      </div>
    </div>
  );
};

export default Modal;

import React, { useState, createContext, useEffect, useCallback } from 'react';
