        return row;
    });
    const wsUsers = XLSX.utils.json_to_sheet(usersData, { header: usersHeaders });
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions');

    // 2. Population Data Sheet
    const popRows: any[] = [];
    data.users.filter(u => u.role === UserRole.INSTITUTION).forEach(inst => {
        const populations = inst.population || {};
        Object.entries(populations).forEach(([year, count]) => {
            popRows.push({
                institutionId: Number(inst.id),
                year: Number(year),
                population: Number(count)
            });
        });
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows, { header: ['institutionId', 'year', 'population'] });
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. Monthly Reports Sheet
    if (data.reports && data.reports.length > 0) {
        const reportPreferredKeys = ['id', 'institutionId', 'year', 'month', 'entryPerson', 'updatedAt'];
        const reportHeaders = getUniqueKeys(data.reports, reportPreferredKeys);
        const wsReports = XLSX.utils.json_to_sheet(data.reports, { header: reportHeaders });
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    } else {
        const wsReports = XLSX.utils.aoa_to_sheet([['No reports recorded']]);
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. Settings Sheet
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Supervisor Password', data.supervisorPassword || ''],
        ['Immunization Dept Password', data.immunizationPassword || ''],
        ['Maghrib Password', data.maghribPassword || ''],
        ['Custom Logo (Base64)', data.customLogo || ''],
        ['Firebase Config (JSON)', data.firebaseConfig ? JSON.stringify(data.firebaseConfig) : ''],
        ['Is Distributable', data.isDistributable ? 'Yes' : 'No'],
        ['Is Published Connected', data.isPublishedConnected ? 'Yes' : 'No'],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'binary' });
                const imported: Partial<FullBackupData> = { 
                    users: [], reports: [], students: [], halaqas: [], evaluations: [] 
                };

                // Import Users (Institutions) - STRICT ID Conversion
                if (workbook.Sheets['Institutions'] || workbook.Sheets['Users_Institutions']) {
                    const sheetName = workbook.Sheets['Institutions'] ? 'Institutions' : 'Users_Institutions';
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);
                    imported.users = rows.map((r: any) => ({
                        ...r,
                        id: Number(r.id),
                        name: String(r.name || '').trim(),
                        role: (r.role === UserRole.SUPERVISOR || r.role === 'supervisor') ? UserRole.SUPERVISOR : UserRole.INSTITUTION,
                        updatedAt: r.updatedAt ? Number(r.updatedAt) : Date.now(),
                        pin: r.pin ? String(r.pin) : '123',
                        population: {},
                    })).filter(u => !isNaN(u.id));
                }

                // Import Population - STRICT conversion
                if (workbook.Sheets['Population_Data'] && imported.users) {
                    const popRows = XLSX.utils.sheet_to_json(workbook.Sheets['Population_Data']);
                    popRows.forEach((row: any) => {
                        const instId = Number(row.institutionId || row.id);
                        const year = Number(row.year);
                        const count = Number(row.population || row.count);
                        const user = imported.users?.find(u => Number(u.id) === instId);
                        if (user && !isNaN(year) && !isNaN(count)) {
                            if (!user.population) user.population = {};
                            user.population[year] = count;
                        }
                    });
                }

                // Import Reports - STRICT conversion
                if (workbook.Sheets['Monthly_Reports']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Monthly_Reports']);
                    imported.reports = rows.map((r: any) => {
                        const report = { ...r };
                        if (report.id) report.id = Number(report.id);
                        if (report.institutionId) report.institutionId = Number(report.institutionId);
                        if (report.year) report.year = Number(report.year);
                        if (report.month) report.month = Number(report.month);
                        if (report.updatedAt) report.updatedAt = Number(report.updatedAt);
                        return report as MonthlyReport;
                    }).filter(r => !isNaN(Number(r.id)));
                }

                // Settings
                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    const settingsMap: Record<string, any> = {};
                    rows.forEach(row => {
                        if (row && row[0]) settingsMap[row[0]] = row[1];
                    });

                    if (settingsMap['Application Name']) imported.appName = settingsMap['Application Name'];
                    if (settingsMap['Custom Logo (Base64)']) imported.customLogo = settingsMap['Custom Logo (Base64)'];
                    if (settingsMap['Supervisor Password']) imported.supervisorPassword = String(settingsMap['Supervisor Password']);
                    if (settingsMap['Immunization Dept Password']) imported.immunizationPassword = String(settingsMap['Immunization Dept Password']);

                    if (settingsMap['Firebase Config (JSON)']) {
                        try {
                            imported.firebaseConfig = JSON.parse(settingsMap['Firebase Config (JSON)']);
                        } catch (err) { console.error("Firebase config parse failed"); }
                    }
                }

                if (!imported.supervisorPassword) imported.supervisorPassword = '123';

                resolve(imported as FullBackupData);
            } catch (err) { 
                console.error("Backup Import Error:", err);
                reject(new Error("Failed to import backup. Please ensure the file is valid.")); 
            }
        };
        reader.readAsBinaryString(file);
    });
};

import React, { useState, createContext, useEffect, useCallback } from 'react';
import { User, MonthlyReport, UserRole, FullBackupData, DeletedItem, Student, Halaqa, Evaluation, MaghribAttendance } from './types';
import { INITIAL_USERS, DEFAULT_APP_NAME, CURRENT_USER_KEY, MOCK_USERS, MOCK_REPORTS } from './constants';
import LoginScreen from './components/LoginScreen';
import SupervisorDashboard from './components/SupervisorDashboard';
import InstitutionDashboard from './components/InstitutionDashboard';
import { ImmunizationDashboard } from './components/ImmunizationDashboard';
import Header from './components/Header';
import { HelpModal } from './components/HelpModal';
import MobileInstallModal from './components/MobileInstallModal';
import ChangePasswordModal from './components/ChangePasswordModal';
import { initializeFirebase, getDb, disconnectFirebase, HARDCODED_FIREBASE_CONFIG } from './utils/firebase';
import { FirebaseSetupWizard } from './components/FirebaseSetupWizard';

declare const JSZip: any;

const base64ToBytes = (base64: string): Uint8Array => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

// Robust deduplication that strictly converts IDs to Numbers
const deduplicateById = <T extends { id: number | string; updatedAt?: number }>(items: T[]): T[] => {
  const map = new Map<number, T>();
  items.forEach(item => {
    if (!item) return;
    const numericId = Number(item.id);
    if (isNaN(numericId)) return;

    const existing = map.get(numericId);
    // Keep the one with the latest updatedAt timestamp
    if (!existing || (item.updatedAt || 0) >= (existing.updatedAt || 0)) {
      map.set(numericId, { ...item, id: numericId });
    }
  });
  return Array.from(map.values()).sort((a, b) => Number(a.id) - Number(b.id));
};

interface AppContextType {
  users: User[];
  reports: MonthlyReport[];
  addReport: (report: Omit<MonthlyReport, 'id' | 'updatedAt'>) => void;
  updateReport: (report: MonthlyReport) => void;
  deleteReport: (reportId: number) => void;
  deleteAllReports: () => Promise<void>;
  deleteAllData: () => Promise<void>;
  loadMockData: () => void;
  customLogo: string | null;
  setCustomLogo: (logo: string | null) => void;
  addInstitution: (name: string, state?: string, population?: { [year: number]: number }) => void;
  updateInstitution: (institution: User) => void;
  deleteInstitution: (institutionId: number) => void;
  importFullBackup: (data: FullBackupData) => void;
  supervisorPassword: string;
  setSupervisorPassword: (password: string) => void;
  logout: () => void;
  isLoading: boolean;
  initiateLogoutCheck: () => void;
  appName: string;
  setAppName: (name: string) => void;
  darkMode: boolean;
  toggleDarkMode: () => void;
  firebaseConnectionStatus: 'connected' | 'disconnected' | 'error' | 'connecting';
  firebaseConfig: any;
  setFirebaseConfig: (config: any) => void;
  isDistributable: boolean;
  isPublishedConnected: boolean;
  currentUser: User | null;

  students: Student[];
  halaqas: Halaqa[];
  evaluations: Evaluation[];
  updateEvaluation: (e: any) => void;
  deleteEvaluation: (id: number) => void;
  addEvaluation: (e: any) => void;
  setLastUsedWeek: (week: number | null) => void;

  maghribAttendances: MaghribAttendance[];
  addMaghribAttendance: (att: any) => void;
  deleteMaghribAttendance: (id: number) => void;
  maghribPassword: string;
  setMaghribPassword: (p: string) => void;

  immunizationPassword: string;
  setImmunizationPassword: (p: string) => void;

  setHasUnsavedChanges: (hasChanges: boolean) => void;
}

export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          if (!savedUser) return null;
          const user = JSON.parse(savedUser);
          return { ...user, id: Number(user.id) }; 
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS.map(u => ({ ...u, id: Number(u.id) })), 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);
  const [lastUsedWeek, setLastUsedWeek] = useState<number | null>(null);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  const getNextId = (collection: any[], startingId: number = 1) => {
      if (!collection || collection.length === 0) return startingId;
      const maxId = collection.reduce((max, item) => (item && Number(item.id) > max ? Number(item.id) : max), 0);
      return Math.max(maxId + 1, startingId);
  };

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).compressedEmbeddedAppData) {
      try {
        const compressedBytes = base64ToBytes((window as any).compressedEmbeddedAppData);
        const zip = await JSZip.loadAsync(compressedBytes);
        const file = zip.file("data.json");
        if (file) {
          const jsonString = await file.async('string');
          loadedConfig = JSON.parse(jsonString);
        }
      } catch (e) { console.error(e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: deduplicateById([...INITIAL_USERS, ...(loadedConfig.users || [])]),
        reports: deduplicateById(loadedConfig.reports || []),
        students: deduplicateById(loadedConfig.students || []),
        halaqas: deduplicateById(loadedConfig.halaqas || []),
        evaluations: deduplicateById(loadedConfig.evaluations || []),
        maghribAttendances: deduplicateById(loadedConfig.maghribAttendances || []),
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setMaghribPasswordState(loadedConfig.maghribPassword || '123456');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          setFirebaseConfigState(loadedConfig.firebaseConfig || HARDCODED_FIREBASE_CONFIG);
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: data.students,
            halaqas: data.halaqas,
            evaluations: data.evaluations,
            maghribAttendances: data.maghribAttendances,
            customLogo, supervisorPassword, maghribPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, maghribPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            const processCol = (col: any) => {
                if (!col) return [];
                // Filter out null values (common in Firebase arrays with ID gaps)
                return Object.entries(col)
                    .filter(([_, v]) => v !== null)
                    .map(([key, v]: [string, any]) => ({ ...v, id: Number(v.id || key) }));
            };

            setData(prev => ({
              users: deduplicateById([...INITIAL_USERS, ...processCol(val.users)]),
              reports: deduplicateById(processCol(val.reports)),
              students: deduplicateById(processCol(val.students)),
              halaqas: deduplicateById(processCol(val.halaqas)),
              evaluations: deduplicateById(processCol(val.evaluations)),
              maghribAttendances: deduplicateById(processCol(val.maghribAttendances)),
              deletedItems: [],
            }));
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.maghribPassword) setMaghribPasswordState(val.maghribPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    // SAFE SURGICAL UPDATE: Apply changes to local state immediately
    const parts = path.split('/');
    if (parts.length === 3 && parts[0] === 'data') {
        const collection = parts[1] as keyof typeof data;
        const itemId = Number(parts[2]);

        setData(prev => {
            const list = [...(prev[collection] as any[])];
            if (value === null) {
                // Delete
                const filtered = list.filter(i => Number(i.id) !== itemId);
                return { ...prev, [collection]: collection === 'users' ? deduplicateById([...INITIAL_USERS, ...filtered]) : filtered };
            }

            // Add or Update
            const index = list.findIndex(i => Number(i.id) === itemId);
            const newItem = { ...value, id: itemId };

            if (index > -1) {
                list[index] = newItem;
            } else {
                list.push(newItem);
            }

            const finalList = collection === 'users' ? deduplicateById([...INITIAL_USERS, ...list]) : deduplicateById(list);
            return { ...prev, [collection]: finalList };
        });
    } else if (path === 'data' && value) {
        // Bulk overwrite
        setData(prev => ({
            ...prev,
            users: value.users ? deduplicateById([...INITIAL_USERS, ...Object.values(value.users).filter(Boolean).map((u:any) => ({...u, id: Number(u.id)}))]) : prev.users,
            reports: value.reports ? deduplicateById(Object.values(value.reports).filter(Boolean).map((r:any) => ({...r, id: Number(r.id)}))) : prev.reports
        }));
    }
  };

  const addReport = (rep: any) => {
      const newId = getNextId(data.reports);
      writeData(`data/reports/${newId}`, { ...rep, id: newId, updatedAt: Date.now() });
  };
  const updateReport = (rep: any) => writeData(`data/reports/${Number(rep.id)}`, { ...rep, id: Number(rep.id), updatedAt: Date.now() });
  const deleteReport = (id: number) => writeData(`data/reports/${Number(id)}`, null);

  const addInstitution = (n: string, state?: string, population?: { [year: number]: number }) => {
      const newId = getNextId(data.users, 2);
      const newUser = { id: newId, name: n, state: state || null, role: UserRole.INSTITUTION, pin: '123', population: population || {}, updatedAt: Date.now() };
      writeData(`data/users/${newId}`, newUser);
  };

  const updateInstitution = (u: User) => {
      const id = Number(u.id);
      writeData(`data/users/${id}`, { ...u, id, updatedAt: Date.now() });
  };

  const deleteInstitution = (institutionId: number) => writeData(`data/users/${Number(institutionId)}`, null);

  const handleLogout = () => { 
      if (hasUnsavedChanges) {
          alert('⚠️ Warning: You have unsaved changes.');
          return;
      }
      setCurrentUser(null); 
      setHasUnsavedChanges(false);
      localStorage.removeItem(CURRENT_USER_KEY); 
  };

  const handleLogin = (user: User) => { 
      const cleanUser = { ...user, id: Number(user.id) };
      setCurrentUser(cleanUser); 
      localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(cleanUser)); 
  };

  // Enforce password change if PIN is 123
  const isMandatoryPasswordChange = currentUser?.role === UserRole.INSTITUTION && currentUser?.pin === '123';

  return (
    <AppContext.Provider value={{
      users: data.users, reports: data.reports,
      addReport, updateReport, deleteReport, 
      deleteAllReports: async () => { writeData('data/reports', null); },
      deleteAllData: async () => writeData('data', { users: { '1': { ...INITIAL_USERS[0], id: 1, updatedAt: Date.now() } } }),
      loadMockData: () => {
          writeData('data', { users: MOCK_USERS.map(u => ({...u, id: Number(u.id)})), reports: MOCK_REPORTS });
      },
      customLogo, setCustomLogo: (l) => { setCustomLogoState(l); writeData('config/customLogo', l); },
      addInstitution, updateInstitution, deleteInstitution, importFullBackup: (d) => writeData('data', d),
      supervisorPassword, setSupervisorPassword: (p) => { setSupervisorPasswordState(p); writeData('config/supervisorPassword', p); },
      logout: handleLogout, isLoading, initiateLogoutCheck: handleLogout, appName, setAppName: (n) => { setAppNameState(n); writeData('config/appName', n); },
      darkMode, toggleDarkMode: () => setDarkMode(!darkMode), 
      firebaseConnectionStatus, 
      firebaseConfig: firebaseConfigState, 
      setFirebaseConfig: (c) => setFirebaseConfigState(c),
      isDistributable, isPublishedConnected, currentUser,
      students: data.students, 
      halaqas: data.halaqas, 
      evaluations: data.evaluations,
      updateEvaluation: (e) => writeData(`data/evaluations/${Number(e.id)}`, e), 
      deleteEvaluation: (id) => writeData(`data/evaluations/${Number(id)}`, null),
      addEvaluation: (e) => { const nid = getNextId(data.evaluations); writeData(`data/evaluations/${nid}`, {...e, id: nid}); },
      setLastUsedWeek,
      maghribAttendances: data.maghribAttendances,
      addMaghribAttendance: (a) => { const nid = a.id || getNextId(data.maghribAttendances); writeData(`data/maghribAttendances/${nid}`, {...a, id: nid}); },
      deleteMaghribAttendance: (id) => writeData(`data/maghribAttendances/${Number(id)}`, null),
      maghribPassword, 
      setMaghribPassword: (p) => { setMaghribPasswordState(p); writeData('config/maghribPassword', p); },
      immunizationPassword,
      setImmunizationPassword: (p) => { setImmunizationPasswordState(p); writeData('config/immunizationPassword', p); },
      setHasUnsavedChanges
    }}>
      <div className={`h-screen flex flex-col transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-green-50 text-gray-900'}`}>
          {isDistributable && !firebaseConfigState && !isPublishedConnected && <FirebaseSetupWizard onConfigSave={setFirebaseConfigState} />}
          {!currentUser ? (
              <LoginScreen onLogin={handleLogin} />
          ) : (
              <div className="flex flex-col h-full">
                  <Header 
                      user={currentUser} 
                      onShowHelp={() => setShowHelpModal(true)} 
                      onInitiateLogoutCheck={handleLogout} 
                      onShowMobileInstallModal={() => setShowMobileInstallModal(true)} 
                      onShowChangePassword={() => setShowChangePasswordModal(true)} 
                  />
                  <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                      {currentUser.role === UserRole.SUPERVISOR && <SupervisorDashboard />}
                      {currentUser.role === UserRole.IMMUNIZATION && <ImmunizationDashboard />}
                      {currentUser.role === UserRole.INSTITUTION && <InstitutionDashboard institutionId={currentUser.id} />}
                  </main>
              </div>
          )}
          {showHelpModal && <HelpModal onClose={() => setShowHelpModal(false)} />}
          {showMobileInstallModal && <MobileInstallModal onClose={() => setShowMobileInstallModal(false)} />}
          {(showChangePasswordModal || isMandatoryPasswordChange) && currentUser && (
            <ChangePasswordModal 
                onClose={() => setShowChangePasswordModal(false)} 
                isMandatory={isMandatoryPasswordChange}
                currentStoredPassword={
                    currentUser.role === UserRole.SUPERVISOR ? supervisorPassword : 
                    currentUser.role === UserRole.IMMUNIZATION ? immunizationPassword :
                    (currentUser.pin || '123')
                }
                onSave={(p) => {
                    if (currentUser.role === UserRole.SUPERVISOR) {
                        setSupervisorPasswordState(p); 
                        writeData('config/supervisorPassword', p);
                    } else if (currentUser.role === UserRole.IMMUNIZATION) {
                        setImmunizationPasswordState(p);
                        writeData('config/immunizationPassword', p);
                    } else if (currentUser.role === UserRole.INSTITUTION) {
                        const updatedUser = { ...currentUser, id: Number(currentUser.id), pin: p, updatedAt: Date.now() };
                        updateInstitution(updatedUser);
                        setCurrentUser(updatedUser);
                        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updatedUser));
                    }
                }} 
            />
          )}
      </div>
    </AppContext.Provider>
  );
};

