                    <div className="flex justify-between items-center mb-4">
                        <h4 className="text-lg font-bold text-gray-800 dark:text-gray-200">Statistics</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-1 text-xs w-auto">
