    }

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Institution Import', 'This will add or update institutions and population data based on the Excel sheets. Are you sure?',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'binary' });

                        // 1. Process Institutions Sheet
                        const instSheet = workbook.Sheets['Institutions'] || workbook.Sheets[workbook.SheetNames[0]];
                        const instJson = XLSX.utils.sheet_to_json(instSheet);

                        const tempImportedInstitutions: any[] = [];
                        let addedCount = 0;
                        let updatedCount = 0;

                        instJson.forEach((row: any) => {
                            const rawId = Number(row['id'] || row['InstitutionId']);
                            const willayat = (row['willayat'] || row['State'])?.toString().trim();
                            const name = (row['name of Institution'] || row['Institution'] || row['Name'])?.toString().trim();

                            if (!name) return;

                            let existingInst = users.find(u => 
                                (u.id === rawId && !isNaN(rawId)) || 
                                (u.role === UserRole.INSTITUTION && u.name.toLowerCase() === name.toLowerCase())
                            );

                            if (existingInst) {
                                const updated = { 
                                    ...existingInst, 
                                    name: name,
                                    state: willayat || existingInst.state,
                                    updatedAt: Date.now() 
                                };
                                updateInstitution(updated);
                                tempImportedInstitutions.push(updated);
                                updatedCount++;
                            } else {
                                // For new institutions, addInstitution generates a new ID.
                                // We'll need the system-generated ID to link population later.
                                // Note: addInstitution in AppContext handles state updates.
                                addInstitution(name, willayat, {});
                                addedCount++;
                                // We'll try to find it again in the updated context later or just assume the next steps link by name
                            }
                        });

                        // 2. Process Population Sheet
                        const popSheet = workbook.Sheets['Population'];
                        if (popSheet) {
                            const popJson = XLSX.utils.sheet_to_json(popSheet);
                            popJson.forEach((row: any) => {
                                const instId = Number(row['InstitutionId'] || row['id']);
                                const year = Number(row['year']);
                                const populationCount = Number(row['population']);

                                if (isNaN(instId) || isNaN(year) || isNaN(populationCount)) return;

                                // Link population to existing or newly added institution
                                // For newly added ones (where rawId might not match current system ID), 
                                // we match by name if we can't find by ID.
                                const institution = users.find(u => u.id === instId);
                                if (institution) {
                                    const updatedPop = { 
                                        ...(institution.population || {}), 
                                        [year]: populationCount 
                                    };
                                    updateInstitution({ ...institution, population: updatedPop, updatedAt: Date.now() });
                                }
                            });
                        }

                        let resultMsg = `Import completed. `;
                        if (addedCount > 0) resultMsg += `✅ Added ${addedCount} institution(s). `;
                        if (updatedCount > 0) resultMsg += `🔄 Updated ${updatedCount} existing record(s).`;
                        if (addedCount === 0 && updatedCount === 0) resultMsg = '⚠️ No valid records found to import.';

                        setMessage({ type: 'success', text: resultMsg });

                    } catch (error) {
                        console.error(error);
                        setMessage({ type: 'error', text: 'Failed to process file. Ensure headers match the template.' });
                    }
                };
                reader.readAsBinaryString(file);
            }
        );
