declare const XLSX: any;

export const exportSheetTemplate = (fileName: string) => {
    // 1. Sheet: Institutions
    const instHeaders = [
        ['id', 'willayat', 'name of Institution']
    ];
    const instData = [
        [2, 'Ibri', 'Sample Health Center A'],
        [3, 'Yanqul', 'Sample Hospital B']
    ];
    const wsInstitutions = XLSX.utils.aoa_to_sheet([...instHeaders, ...instData]);

    // 2. Sheet: Population
    const popHeaders = [
        ['InstitutionId', 'year', 'population']
    ];
    const popData = [
        [2, 2024, 1200],
        [2, 2025, 1250],
        [3, 2024, 850]
    ];
    const wsPopulation = XLSX.utils.aoa_to_sheet([...popHeaders, ...popData]);

    // Simple styling
    const applyStyle = (ws: any) => {
        if (!ws['!ref']) return;
        const range = XLSX.utils.decode_range(ws['!ref']);
        // Set columns width
        ws['!cols'] = Array(range.e.c + 1).fill({ wch: 25 });
    };

    applyStyle(wsInstitutions);
    applyStyle(wsPopulation);

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, wsInstitutions, 'Institutions');
    XLSX.utils.book_append_sheet(wb, wsPopulation, 'Population');

    XLSX.writeFile(wb, `${fileName}.xlsx`);
};

import { FullBackupData, UserRole, MonthlyReport } from '../types';
declare const XLSX: any;

// Fields that are calculated automatically and should not be exported
const CALCULATED_FIELDS = new Set([
    'target_population',
    'p4_tdap_target_total_pregnant',
    'p4_tdap_given_total_pregnant',
    'p4_ae_events', // Often calculated if linked
    'targetMonth'
]);

const isCalculatedOrEmpty = (key: string, value: any): boolean => {
    if (value === null || value === undefined || value === '') return true;
    if (CALCULATED_FIELDS.has(key)) return true;
    // Exclude dynamic flu totals and coverage
    if (key.startsWith('p4_flu_target_total_')) return true;
    if (key.startsWith('p4_flu_given_total_')) return true;
    if (key.startsWith('p4_flu_coverage_')) return true;
    // Exclude used vials calculated sums
    if (key.startsWith('p4_used_vials_doses_used_')) return true;
    // Exclude anything that looks like a percentage string
    if (typeof value === 'string' && value.includes('%')) return true;

    return false;
};

const getUniqueKeys = (data: any[], preferredOrder: string[] = []) => {
    const keys = new Set<string>();
    data.forEach(item => {
        if (!item) return;
        Object.keys(item).forEach(k => {
            if (!isCalculatedOrEmpty(k, item[k])) {
                keys.add(k);
            }
        });
    });

    const sortedKeys: string[] = [];
    preferredOrder.forEach(k => {
        if (keys.has(k)) {
            sortedKeys.push(k);
            keys.delete(k);
        }
    });

    return [...sortedKeys, ...Array.from(keys).sort()];
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    // 1. Institutions Sheet
    const userKeys = ['id', 'name', 'role', 'state', 'pin', 'updatedAt'];
    let usersHeaders = getUniqueKeys(data.users, userKeys);
    usersHeaders = usersHeaders.filter(h => h !== 'population');

    const usersData = data.users.map(u => {
        const row: any = {};
        usersHeaders.forEach(h => {
            row[h] = (u as any)[h] ?? '';
        });
        return row;
    });
    const wsUsers = XLSX.utils.json_to_sheet(usersData, { header: usersHeaders });
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions');

    // 2. Population Data Sheet
    const popRows: any[] = [];
    data.users.filter(u => u.role === UserRole.INSTITUTION).forEach(inst => {
        const populations = inst.population || {};
        Object.entries(populations).forEach(([year, count]) => {
            if (count !== undefined && count !== null) {
                popRows.push({
                    institutionId: Number(inst.id),
                    year: Number(year),
                    population: Number(count)
                });
            }
        });
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows, { header: ['institutionId', 'year', 'population'] });
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. Monthly Reports Sheet (Cleaned)
    if (data.reports && data.reports.length > 0) {
        const reportPreferredKeys = ['id', 'institutionId', 'year', 'month', 'entryPerson', 'updatedAt'];
        const reportHeaders = getUniqueKeys(data.reports, reportPreferredKeys);

        const cleanedReports = data.reports.map(r => {
            const row: any = {};
            reportHeaders.forEach(h => {
                if (!isCalculatedOrEmpty(h, r[h])) {
                    row[h] = r[h];
                }
            });
            return row;
        });

        const wsReports = XLSX.utils.json_to_sheet(cleanedReports, { header: reportHeaders });
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. Settings Sheet
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Supervisor Password', data.supervisorPassword || ''],
        ['Immunization Dept Password', data.immunizationPassword || ''],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_CLEAN_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'binary' });
                const imported: Partial<FullBackupData> = { 
                    users: [], reports: [], students: [], halaqas: [], evaluations: [] 
                };

                // Import Users
                if (workbook.Sheets['Institutions']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Institutions']);
                    imported.users = rows.map((r: any) => ({
                        ...r,
                        id: Number(r.id),
                        name: String(r.name || '').trim(),
                        role: r.role || UserRole.INSTITUTION,
                        updatedAt: r.updatedAt ? Number(r.updatedAt) : Date.now(),
                        pin: r.pin ? String(r.pin) : '123',
                        population: {},
                    })).filter(u => !isNaN(u.id));
                }

                // Import Population
                if (workbook.Sheets['Population_Data'] && imported.users) {
                    const popRows = XLSX.utils.sheet_to_json(workbook.Sheets['Population_Data']);
                    popRows.forEach((row: any) => {
                        const instId = Number(row.institutionId || row.id);
                        const user = imported.users?.find(u => Number(u.id) === instId);
                        if (user) {
                            if (!user.population) user.population = {};
                            user.population[Number(row.year)] = Number(row.population);
                        }
                    });
                }

                // Import Reports
                if (workbook.Sheets['Monthly_Reports']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Monthly_Reports']);
                    imported.reports = rows.map((r: any) => {
                        const report = { ...r };
                        ['id', 'institutionId', 'year', 'month', 'updatedAt'].forEach(k => {
                            if (report[k]) report[k] = Number(report[k]);
                        });
                        return report as MonthlyReport;
                    }).filter(r => !isNaN(Number(r.id)));
                }

                // Settings
                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row && row[0] === 'Application Name') imported.appName = row[1];
                        if (row && row[0] === 'Supervisor Password') imported.supervisorPassword = String(row[1]);
                    });
                }

                resolve(imported as FullBackupData);
            } catch (err) { 
                reject(new Error("Failed to import. Check file format.")); 
            }
        };
        reader.readAsBinaryString(file);
    });
};

