export const Settings: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { 
        users, addInstitution, updateInstitution, 
        reports, appName, setAppName, firebaseConfig, setFirebaseConfig,
        isDistributable, isPublishedConnected, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
        importFullBackup: handleImportFullBackupFile
    } = context;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => Promise<void>; }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });
    const [isProcessing, setIsProcessing] = useState(false);

    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : '');

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                const data = event.target?.result;
                const workbook = XLSX.read(data, { type: 'binary' });

                // 1. Process Institutions Sheet
                const instSheet = workbook.Sheets['Institutions'] || workbook.Sheets[workbook.SheetNames[0]];
                const instJson = XLSX.utils.sheet_to_json(instSheet);

                // Collect population data if available in the second sheet
                const popSheet = workbook.Sheets['Population'];
                const popJson = popSheet ? XLSX.utils.sheet_to_json(popSheet) : [];

                let addedCount = 0;
                let updatedCount = 0;

                // Process each row in the institution sheet
                for (const row of instJson as any[]) {
                    const rawId = Number(row['id']);
                    const willayat = (row['willayat'])?.toString().trim();
                    const name = (row['name of Institution'])?.toString().trim();

                    if (!name) continue;

                    // Match by ID or Name
                    let existing = users.find(u => (u.id === rawId && !isNaN(rawId)) || (u.role === UserRole.INSTITUTION && u.name.toLowerCase() === name.toLowerCase()));

                    // Extract population for this specific institution from the other sheet
                    const currentInstPop: { [year: number]: number } = {};
                    popJson.forEach((pRow: any) => {
                        const pId = Number(pRow['InstitutionId']);
                        if (pId === rawId || (existing && pId === existing.id)) {
                            currentInstPop[Number(pRow['year'])] = Number(pRow['population']);
                        }
                    });

                    if (existing) {
                        // Update existing
                        updateInstitution({
                            ...existing,
                            name: name,
                            state: willayat || existing.state,
                            population: { ...existing.population, ...currentInstPop },
                            updatedAt: Date.now()
                        });
                        updatedCount++;
                    } else {
                        // Add new
                        addInstitution(name, willayat, currentInstPop);
                        addedCount++;
                    }
                }

                setMessage({ type: 'success', text: `Import successful. ✅ Added: ${addedCount}, 🔄 Updated: ${updatedCount}.` });
            } catch (error) {
                setMessage({ type: 'error', text: 'Error processing Excel file. Please use the provided template.' });
            }
        };
        reader.readAsBinaryString(file);
        e.target.value = '';
    };

    // ... Keep other helper functions (handleSaveAppName, etc.)
    const handleSaveAppName = () => { setAppName(appNameInput); setMessage({type: 'success', text: 'Name saved.'}); };

    return (
        <div className="bg-white p-6 rounded-xl shadow-lg dark:bg-gray-800">
            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300 border-b pb-2">Settings & Data Management</h3>

            {message && <div className={`p-4 mb-6 rounded-lg text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{message.text}</div>}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Section 1: Template & Import */}
                <div className="bg-gray-50 dark:bg-gray-700/50 p-6 rounded-2xl border-2 border-dashed border-gray-200 dark:border-gray-600">
                    <h4 className="font-bold text-lg mb-4 dark:text-gray-200">Step 1: Institutions Setup</h4>
                    <div className="space-y-3">
                        <button onClick={() => exportSheetTemplate('EPI_Template')} className="w-full py-3 bg-white dark:bg-gray-800 border-2 border-green-600 text-green-700 dark:text-green-400 rounded-xl font-bold hover:bg-green-50 transition-all">
                            1. Download Excel Template
                        </button>
                        <label className="block w-full py-3 bg-green-600 text-white text-center rounded-xl font-bold cursor-pointer hover:bg-green-700 shadow-md">
                            2. Import Institutions & Population
                            <input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" />
                        </label>
                    </div>
                </div>

                {/* Section 2: Full Backup */}
                <div className="bg-blue-50 dark:bg-blue-900/20 p-6 rounded-2xl border border-blue-200 dark:border-blue-800">
                    <h4 className="font-bold text-lg mb-4 text-blue-900 dark:text-blue-300">Step 2: Backup System</h4>
                    <div className="space-y-3">
                        <button onClick={() => exportFullBackup(context as any, 'EPI_Backup')} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md">
                            Export Clean Backup (No sums/empty)
                        </button>
                        <label className="block w-full py-3 bg-white dark:bg-gray-800 border-2 border-blue-600 text-blue-700 dark:text-blue-400 text-center rounded-xl font-bold cursor-pointer">
                            Restore Full Backup
                            <input type="file" accept=".xlsx" onChange={(e) => {
                                const f = e.target.files?.[0];
                                if(f) importFullBackup(f).then(handleImportFullBackupFile);
                            }} className="hidden" />
                        </label>
                    </div>
                </div>
            </div>

            <div className="mt-8 pt-6 border-t dark:border-gray-700">
                <h4 className="font-bold text-lg mb-4 dark:text-gray-200">Customization</h4>
                <div className="flex gap-2">
