import { FullBackupData, UserRole, MonthlyReport } from '../types';
declare const XLSX: any;

/**
 * الحقول التي هي نواتج حسابية بحتة ولا يقبل النظام تعديلها يدوياً
 * هذه هي الحقول الوحيدة التي سيتم استبعادها
 */
const STRICTLY_CALCULATED_NON_EDITABLE = new Set([
    'p4_tdap_target_total_pregnant',
    'p4_tdap_given_total_pregnant',
    'targetMonth' // نص مشتق من التاريخ فقط
]);

const isCalculatedOrEmpty = (key: string, value: any): boolean => {
    // استبعاد القيم الفارغة تماماً
    if (value === null || value === undefined || value === '') return true;

    // استبعاد الحقول الحسابية البحتة
    if (STRICTLY_CALCULATED_NON_EDITABLE.has(key)) return true;

    // استبعاد مجاميع الإنفلونزا التلقائية
    if (key.startsWith('p4_flu_target_total_')) return true;
    if (key.startsWith('p4_flu_given_total_')) return true;

    // استبعاد نصوص النسب المئوية (دائماً تشتق عند العرض)
    if (key.startsWith('p4_flu_coverage_')) return true;
    if (typeof value === 'string' && value.includes('%')) return true;

    // استبعاد نواتج ضرب جرعات القوارير (تُحسب لحظياً)
    if (key.startsWith('p4_used_vials_doses_used_')) return true;

    return false;
};

const getUniqueKeys = (data: any[], preferredOrder: string[] = []) => {
    const keys = new Set<string>();
    data.forEach(item => {
        if (!item) return;
        Object.keys(item).forEach(k => {
            if (!isCalculatedOrEmpty(k, item[k])) {
                keys.add(k);
            }
        });
    });

    // التأكد من شمول حقل التعديل اليدوي للحفاظ على استقلالية الحقول
    keys.add('manuallyEditedFields');

    const sortedKeys: string[] = [];
    preferredOrder.forEach(k => {
        if (keys.has(k)) {
            sortedKeys.push(k);
            keys.delete(k);
        }
    });

    return [...sortedKeys, ...Array.from(keys).sort()];
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    // 1. ورقة المؤسسات
    const userKeys = ['id', 'name', 'role', 'state', 'pin', 'updatedAt'];
