                    })).filter(u => !isNaN(u.id));
                }

                // استيراد السكان
                if (workbook.Sheets['Population_Data'] && imported.users) {
                    const popRows = XLSX.utils.sheet_to_json(workbook.Sheets['Population_Data']);
                    popRows.forEach((row: any) => {
                        const instId = Number(row.institutionId || row.id);
