                        ['id', 'institutionId', 'year', 'month', 'updatedAt'].forEach(k => {
                            if (report[k]) report[k] = Number(report[k]);
                        });
                        // استعادة مصفوفة الحقول المعدلة يدوياً
                        if (report.manuallyEditedFields) {
                            report.manuallyEditedFields = String(report.manuallyEditedFields).split(',').filter(Boolean);
