                            report.manuallyEditedFields = [];
                        }
                        return report as MonthlyReport;
                    }).filter(r => !isNaN(Number(r.id)));
                }

                // استيراد الإعدادات
                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row && row[0] === 'Application Name') imported.appName = row[1];
                        if (row && row[0] === 'Supervisor Password') imported.supervisorPassword = String(row[1]);
                        if (row && row[0] === 'Immunization Dept Password') imported.immunizationPassword = String(row[1]);
                    });
                }

                resolve(imported as FullBackupData);
            } catch (err) { 
                reject(new Error("Failed to import backup. Please check the file format.")); 
            }
        };
        reader.readAsBinaryString(file);
    });
};

