    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions');

    // 2. ورقة السكان
    const popRows: any[] = [];
    data.users.filter(u => u.role === UserRole.INSTITUTION).forEach(inst => {
        if (inst.population) {
            Object.entries(inst.population).forEach(([year, count]) => {
                popRows.push({ institutionId: inst.id, year, population: count });
            });
        }
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows);
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. ورقة التقارير (حقول خام + حقول قابلة للتعديل فقط)
    if (data.reports && data.reports.length > 0) {
        const cleanedReports = data.reports.map(r => {
            const row: any = {};
            Object.keys(r).forEach(key => {
                if (key === 'manuallyEditedFields') {
                    row[key] = Array.isArray(r[key]) ? r[key].join(',') : '';
                } else if (!isStrictlyCalculatedOrEmpty(key, r[key])) {
                    row[key] = r[key];
                }
            });
            return row;
        });
        const wsReports = XLSX.utils.json_to_sheet(cleanedReports);
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. الإعدادات
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Supervisor Password', data.supervisorPassword || ''],
        ['Immunization Dept Password', data.immunizationPassword || ''],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_CLEAN_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'binary' });
                const imported: Partial<FullBackupData> = { users: [], reports: [] };

                if (workbook.Sheets['Institutions']) {
                    imported.users = XLSX.utils.sheet_to_json(workbook.Sheets['Institutions']).map((r: any) => ({
                        ...r, id: Number(r.id), population: {}
                    }));
                }

                if (workbook.Sheets['Population_Data'] && imported.users) {
                    XLSX.utils.sheet_to_json(workbook.Sheets['Population_Data']).forEach((row: any) => {
                        const user = imported.users?.find(u => u.id === Number(row.institutionId));
                        if (user) user.population[Number(row.year)] = Number(row.population);
                    });
                }

                if (workbook.Sheets['Monthly_Reports']) {
                    imported.reports = XLSX.utils.sheet_to_json(workbook.Sheets['Monthly_Reports']).map((r: any) => {
                        const report = { ...r };
                        ['id', 'institutionId', 'year', 'month', 'updatedAt'].forEach(k => { if(report[k]) report[k] = Number(report[k]); });
                        if (report.manuallyEditedFields) report.manuallyEditedFields = String(report.manuallyEditedFields).split(',').filter(Boolean);
                        return report as MonthlyReport;
                    });
                }

                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Application Name') imported.appName = row[1];
                        if (row[0] === 'Supervisor Password') imported.supervisorPassword = String(row[1]);
                        if (row[0] === 'Immunization Dept Password') imported.immunizationPassword = String(row[1]);
                    });
                }
                resolve(imported as FullBackupData);
            } catch (err) { reject(new Error("Import failed.")); }
        };
        reader.readAsBinaryString(file);
    });
};

