export const Settings: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { 
        users, addInstitution, updateInstitution, 
        appName, setAppName, firebaseConfig, setFirebaseConfig,
        isDistributable, isPublishedConnected, deleteAllReports, deleteAllData,
        importFullBackup: handleImportFullBackupFile
    } = context;

    const [activeSettingsView, setActiveSettingsView] = useState<'main' | 'customization'>('main'); 
    const [message, setMessage] = useState<{type: 'success' | 'error' | 'warning', text: string} | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');
    const [appNameInput, setAppNameInput] = useState<string>(appName);
    const [firebaseConfigInput, setFirebaseConfigInput] = useState<string>(firebaseConfig ? JSON.stringify(firebaseConfig, null, 2) : '');

    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => Promise<void>; }>({ 
        isOpen: false, title: '', message: '', onConfirm: async () => {} 
    });

    const confirmAction = (title: string, message: string, onConfirm: () => Promise<void>) => {
        setConfirmationModal({ isOpen: true, title, message, onConfirm });
    };

    const handleConfirm = async () => {
        setIsProcessing(true);
        try { await confirmationModal.onConfirm(); }
        finally {
            setIsProcessing(false);
            setConfirmationModal({ ...confirmationModal, isOpen: false });
        }
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Import', 'This will add or update institutions and population data from the Excel sheets. Continue?', async () => {
            const reader = new FileReader();
            reader.onload = async (event) => {
                try {
                    const data = event.target?.result;
                    const workbook = XLSX.read(data, { type: 'binary' });

                    const instSheet = workbook.Sheets['Institutions'] || workbook.Sheets[workbook.SheetNames[0]];
                    const instJson = XLSX.utils.sheet_to_json(instSheet);
                    const popSheet = workbook.Sheets['Population'];
                    const popJson = popSheet ? XLSX.utils.sheet_to_json(popSheet) : [];

                    let added = 0; let updated = 0;
                    for (const row of instJson as any[]) {
                        const rawId = Number(row['id']);
                        const name = row['name of Institution']?.toString().trim();
                        const willayat = row['willayat']?.toString().trim();
                        if (!name) continue;

                        let existing = users.find(u => (u.id === rawId && !isNaN(rawId)) || (u.role === UserRole.INSTITUTION && u.name.toLowerCase() === name.toLowerCase()));

                        const currentInstPop: { [year: number]: number } = {};
                        popJson.forEach((pRow: any) => {
                            if (Number(pRow['InstitutionId']) === rawId || (existing && Number(pRow['InstitutionId']) === existing.id)) {
                                currentInstPop[Number(pRow['year'])] = Number(pRow['population']);
                            }
                        });

                        if (existing) {
                            updateInstitution({ ...existing, name, state: willayat || existing.state, population: { ...existing.population, ...currentInstPop }, updatedAt: Date.now() });
                            updated++;
                        } else {
                            addInstitution(name, willayat, currentInstPop);
                            added++;
                        }
                    }
                    setMessage({ type: 'success', text: `Import completed. ✅ Added: ${added}, 🔄 Updated: ${updated}.` });
                } catch (err) { setMessage({ type: 'error', text: 'Error reading Excel file.' }); }
            };
            reader.readAsBinaryString(file);
        });
        e.target.value = '';
    };

    const handleCopyHtml = async (type: 'empty' | 'connected') => {
        const config = type === 'empty' ? null : firebaseConfig;
        const html = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
        if (navigator.clipboard) {
            await navigator.clipboard.writeText(html);
            setCopyState(type);
            setTimeout(() => setCopyState('idle'), 3000);
            setMessage({ type: 'success', text: 'HTML code copied to clipboard!' });
        }
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} hideDefaultCloseButton={isProcessing}>
                    <p className="text-center font-bold text-lg py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4">
                        <button onClick={() => setConfirmationModal({...confirmationModal, isOpen: false})} className="px-6 py-2 bg-gray-200 rounded-lg">Cancel</button>
                        <button onClick={handleConfirm} className="px-6 py-2 bg-red-600 text-white rounded-lg">{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
            )}

            <div className="flex border-b mb-6 dark:border-gray-700">
                <button onClick={() => setActiveSettingsView('main')} className={`px-4 py-2 font-bold ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-400' : 'text-gray-500'}`}>Main Settings</button>
                <button onClick={() => setActiveSettingsView('customization')} className={`px-4 py-2 font-bold ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-400' : 'text-gray-500'}`}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{message.text}</div>}

            {activeSettingsView === 'main' && (
                <div className="space-y-8 animate-fade-in">
                    {/* Data Management Section */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="bg-gray-50 dark:bg-gray-700/50 p-6 rounded-2xl border-2 border-dashed border-gray-200 dark:border-gray-600">
                            <h4 className="font-bold text-lg mb-4 dark:text-gray-200">Step 1: Institutions Setup</h4>
                            <div className="space-y-3">
                                <button onClick={() => exportSheetTemplate('EPI_Template')} className="w-full py-3 bg-white dark:bg-gray-800 border-2 border-green-600 text-green-700 dark:text-green-400 rounded-xl font-bold hover:bg-green-50">
                                    1. Download Excel Template (2 Sheets)
                                </button>
                                <label className="block w-full py-3 bg-green-600 text-white text-center rounded-xl font-bold cursor-pointer hover:bg-green-700">
                                    2. Import from Excel
                                    <input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" />
                                </label>
                            </div>
                        </div>

                        <div className="bg-blue-50 dark:bg-blue-900/20 p-6 rounded-2xl border border-blue-200">
                            <h4 className="font-bold text-lg mb-4 text-blue-900 dark:text-blue-300">Step 2: Backup System</h4>
                            <div className="space-y-3">
                                <button onClick={() => exportFullBackup(context as any, 'EPI_Backup')} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700">
                                    💾 Export Clean Backup (No Sums)
                                </button>
                                <label className="block w-full py-3 bg-white dark:bg-gray-800 border-2 border-blue-600 text-blue-700 dark:text-blue-300 text-center rounded-xl font-bold cursor-pointer">
                                    📂 Restore Full Backup
                                    <input type="file" accept=".xlsx" onChange={(e) => {
                                        const f = e.target.files?.[0];
                                        if(f) importFullBackup(f).then(handleImportFullBackupFile);
                                    }} className="hidden" />
                                </label>
                            </div>
                        </div>
                    </div>

                    {/* Distribution Section */}
                    <div className="bg-indigo-50 dark:bg-indigo-900/20 p-6 rounded-2xl border border-indigo-200">
                        <h4 className="text-xl font-bold text-indigo-900 dark:text-indigo-300 mb-6">Distribute a Copy (Single HTML File)</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-3">
                                <p className="font-bold text-indigo-800 dark:text-indigo-200 border-b pb-2">Blank Version (Setup)</p>
                                <button onClick={() => generateAndDownloadDistributableHtml(context as any, 'empty')} className="w-full py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl font-bold">⬇️ Download HTML</button>
