                                    {copyState === 'empty' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                </button>
                            </div>
                            <div className="space-y-3">
                                <p className="font-bold text-indigo-800 dark:text-indigo-200 border-b pb-2">Connected Version (Snapshot)</p>
                                <button onClick={() => generateAndDownloadDistributableHtml(context as any, 'snapshot')} className="w-full py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl font-bold">⬇️ Download HTML</button>
                                <button onClick={() => handleCopyHtml('connected')} className={`w-full py-3 border rounded-xl font-bold ${copyState === 'connected' ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white'}`}>
                                    {copyState === 'connected' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Danger Zone */}
                    <div className="mt-8 pt-8 border-t dark:border-gray-700">
                        <h5 className="text-red-700 font-bold text-center mb-4">Danger Zone</h5>
                        <div className="flex flex-col sm:flex-row gap-4">
                            <button onClick={() => confirmAction('Delete Reports', 'All monthly reports will be deleted. Continue?', async () => { await deleteAllReports(); setMessage({type: 'success', text: 'All reports deleted.'}); })} className="flex-1 py-3 bg-red-100 text-red-700 rounded-xl font-bold">🗑️ Delete All Reports</button>
