import { FullBackupData, UserRole, MonthlyReport } from '../types';
declare const XLSX: any;

/**
 * الحقول الحسابية البحتة التي لا يمكن للمستخدم تعديلها نهائياً
 * هذه هي الحقول الوحيدة التي يتم استبعادها من التصدير لتوفير المساحة
 */
const NON_EDITABLE_CALCULATED = new Set([
    'p4_tdap_target_total_pregnant',
    'p4_tdap_given_total_pregnant',
    'targetMonth'
]);

const isStrictlyCalculatedOrEmpty = (key: string, value: any): boolean => {
    if (value === null || value === undefined || value === '') return true;

    // استبعاد الحقول المحسوبة غير القابلة للتعديل
    if (NON_EDITABLE_CALCULATED.has(key)) return true;

    // استبعاد نواتج مجاميع الإنفلونزا والنسب المئوية (تُحسب تلقائياً عند العرض)
    if (key.startsWith('p4_flu_target_total_') || key.startsWith('p4_flu_given_total_')) return true;
    if (key.startsWith('p4_flu_coverage_') || (typeof value === 'string' && value.includes('%'))) return true;

    // استبعاد نواتج جرعات القوارير (تُحسب من ضرب الصفوف بالجرعات)
    if (key.startsWith('p4_used_vials_doses_used_')) return true;

    return false;
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    // 1. ورقة المؤسسات
    const usersData = data.users.map(u => ({
        id: u.id,
        name: u.name,
        role: u.role,
        state: u.state || '',
        pin: u.pin || '123',
        updatedAt: u.updatedAt || Date.now()
    }));
    const wsUsers = XLSX.utils.json_to_sheet(usersData);
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions');

    // 2. ورقة السكان
    const popRows: any[] = [];
    data.users.filter(u => u.role === UserRole.INSTITUTION).forEach(inst => {
        if (inst.population) {
            Object.entries(inst.population).forEach(([year, count]) => {
                popRows.push({ institutionId: inst.id, year: Number(year), population: count });
            });
        }
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows);
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. ورقة التقارير (بيانات خام + حقول قابلة للتعديل)
    if (data.reports && data.reports.length > 0) {
        const cleanedReports = data.reports.map(r => {
            const row: any = {};
            Object.keys(r).forEach(key => {
                if (key === 'manuallyEditedFields') {
                    row[key] = Array.isArray(r[key]) ? r[key].join(',') : '';
                } else if (!isStrictlyCalculatedOrEmpty(key, r[key])) {
                    row[key] = r[key];
                }
            });
            return row;
        });
        const wsReports = XLSX.utils.json_to_sheet(cleanedReports);
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. الإعدادات
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Supervisor Password', data.supervisorPassword || ''],
        ['Immunization Dept Password', data.immunizationPassword || ''],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_Full_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'array' });
                const imported: Partial<FullBackupData> = { users: [], reports: [] };

                if (workbook.Sheets['Institutions']) {
                    imported.users = XLSX.utils.sheet_to_json(workbook.Sheets['Institutions']).map((r: any) => ({
                        ...r, id: Number(r.id), population: {}
                    }));
                }

                if (workbook.Sheets['Population_Data'] && imported.users) {
                    XLSX.utils.sheet_to_json(workbook.Sheets['Population_Data']).forEach((row: any) => {
                        const user = imported.users?.find(u => u.id === Number(row.institutionId));
                        if (user) {
                            if (!user.population) user.population = {};
                            user.population[Number(row.year)] = Number(row.population);
                        }
                    });
                }

                if (workbook.Sheets['Monthly_Reports']) {
                    imported.reports = XLSX.utils.sheet_to_json(workbook.Sheets['Monthly_Reports']).map((r: any) => {
                        const report = { ...r };
                        ['id', 'institutionId', 'year', 'month', 'updatedAt'].forEach(k => { 
                            if(report[k]) report[k] = Number(report[k]); 
                        });
                        if (report.manuallyEditedFields) {
                            report.manuallyEditedFields = String(report.manuallyEditedFields).split(',').filter(Boolean);
                        } else {
                            report.manuallyEditedFields = [];
                        }
                        return report as MonthlyReport;
                    });
                }

                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Application Name') imported.appName = row[1];
                        if (row[0] === 'Supervisor Password') imported.supervisorPassword = String(row[1]);
                        if (row[0] === 'Immunization Dept Password') imported.immunizationPassword = String(row[1]);
                    });
                }
                resolve(imported as FullBackupData);
            } catch (err) { reject(new Error("Import failed. Structure invalid.")); }
        };
        reader.readAsArrayBuffer(file);
    });
};

