import { FullBackupData, UserRole, MonthlyReport, User } from '../types';
declare const XLSX: any;

/**
 * وظيفة ديناميكية لاستخراج جميع المفاتيح الفريدة من مجموعة من الكائنات
 */
const getUniqueKeys = (data: any[], preferredOrder: string[] = []) => {
    const keys = new Set<string>();
    data.forEach(item => {
        Object.keys(item).forEach(k => keys.add(k));
    });

    const sortedKeys: string[] = [];
    preferredOrder.forEach(k => {
        if (keys.has(k)) {
            sortedKeys.push(k);
            keys.delete(k);
        }
    });

    return [...sortedKeys, ...Array.from(keys).sort()];
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    // 1. ورقة المؤسسات (فقط الأدوار التي هي مؤسسات)
    const institutionsOnly = data.users.filter(u => u.role === UserRole.INSTITUTION);
    const userKeys = ['id', 'name', 'role', 'state', 'pin'];
    let usersHeaders = getUniqueKeys(institutionsOnly, userKeys);
    usersHeaders = usersHeaders.filter(h => h !== 'population');

    const usersData = institutionsOnly.map(u => {
        const row: any = {};
        usersHeaders.forEach(h => {
            row[h] = (u as any)[h] ?? '';
        });
        return row;
    });
    const wsUsers = XLSX.utils.json_to_sheet(usersData, { header: usersHeaders });
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions_List');

    // 2. ورقة بيانات السكان
    const popRows: any[] = [];
    institutionsOnly.forEach(inst => {
        const populations = inst.population || {};
        Object.entries(populations).forEach(([year, count]) => {
            popRows.push({
                InstitutionId: inst.id,
                year: Number(year),
                population: Number(count)
            });
        });
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows, { header: ['InstitutionId', 'year', 'population'] });
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    // 3. ورقة التقارير الشهرية
    if (data.reports && data.reports.length > 0) {
        const reportPreferredKeys = ['id', 'institutionId', 'year', 'month', 'entryPerson', 'updatedAt', 'targetMonth'];
        const reportHeaders = getUniqueKeys(data.reports, reportPreferredKeys);
        const wsReports = XLSX.utils.json_to_sheet(data.reports, { header: reportHeaders });
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    // 4. ورقة صلاحيات الدخول (جديد)
    const authData = [
        ['Role', 'Access Password / PIN'],
        ['Main Supervisor', data.supervisorPassword || '123'],
        ['Immunization Dept', data.immunizationPassword || '12345']
    ];
    const wsAuth = XLSX.utils.aoa_to_sheet(authData);
    XLSX.utils.book_append_sheet(wb, wsAuth, 'Auth_Credentials');

    // 5. ورقة الإعدادات العامة
    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Custom Logo (Base64)', data.customLogo || ''],
        ['Firebase Config (JSON)', data.firebaseConfig ? JSON.stringify(data.firebaseConfig) : ''],
        ['Is Distributable', data.isDistributable ? 'Yes' : 'No'],
        ['Is Published Connected', data.isPublishedConnected ? 'Yes' : 'No'],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'array' });
                const imported: Partial<FullBackupData> = { 
                    users: [], reports: [], students: [], halaqas: [], evaluations: [] 
                };

                // استيراد المؤسسات
                const instSheet = workbook.Sheets['Institutions_List'] || workbook.Sheets['Users_Institutions'];
                if (instSheet) {
                    const rows = XLSX.utils.sheet_to_json(instSheet);
                    imported.users = rows.map((r: any) => ({
                        ...r,
                        id: Number(r.id),
                        role: UserRole.INSTITUTION, // نضمن أنها مؤسسة
                        population: {},
                    }));
                }

                // إضافة المشرف (دائماً موجود كـ ID 1)
                const supervisor: User = { id: 1, name: 'Main Supervisor', role: UserRole.SUPERVISOR, updatedAt: Date.now() };
                if (imported.users) {
                   imported.users = [supervisor, ...imported.users.filter(u => u.id !== 1)];
                }

                // استيراد بيانات السكان
                const popSheet = workbook.Sheets['Population_Data'];
                if (popSheet && imported.users) {
                    const popRows = XLSX.utils.sheet_to_json(popSheet);
                    popRows.forEach((row: any) => {
                        const instId = Number(row.InstitutionId || row.institutionId);
                        const year = Number(row.year);
                        const count = Number(row.population);
                        const user = imported.users?.find(u => u.id === instId);
                        if (user && !isNaN(year) && !isNaN(count)) {
                            if (!user.population) user.population = {};
                            user.population[year] = count;
                        }
                    });
                }

                // استيراد التقارير
                if (workbook.Sheets['Monthly_Reports']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Monthly_Reports']);
                    imported.reports = rows.map((r: any) => {
                        const report = { ...r };
                        if (report.id) report.id = Number(report.id);
                        if (report.institutionId) report.institutionId = Number(report.institutionId);
                        if (report.year) report.year = Number(report.year);
                        if (report.month) report.month = Number(report.month);
                        if (report.updatedAt) report.updatedAt = Number(report.updatedAt);
                        return report as MonthlyReport;
                    });
                }

                // استيراد كلمات المرور من Auth_Credentials أولاً
                if (workbook.Sheets['Auth_Credentials']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Auth_Credentials'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Main Supervisor') imported.supervisorPassword = String(row[1]);
                        if (row[0] === 'Immunization Dept') imported.immunizationPassword = String(row[1]);
                    });
                }

                // استيراد الإعدادات الأخرى
                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Application Name') imported.appName = row[1];
                        if (row[0] === 'Custom Logo (Base64)') imported.customLogo = row[1];
                        if (!imported.supervisorPassword && row[0] === 'Supervisor Password') imported.supervisorPassword = String(row[1]);
                        if (!imported.immunizationPassword && row[0] === 'Immunization Dept Password') imported.immunizationPassword = String(row[1]);
                        if (row[0] === 'Firebase Config (JSON)') {
                            try { imported.firebaseConfig = JSON.parse(row[1]); } catch(e){}
                        }
                    });
                }

                if (!imported.supervisorPassword) imported.supervisorPassword = '123';
                if (!imported.immunizationPassword) imported.immunizationPassword = '12345';

                resolve(imported as FullBackupData);
            } catch (err) { 
                console.error(err);
                reject(new Error("Error parsing backup file.")); 
            }
        };
        reader.readAsArrayBuffer(file);
    });
};

