                    setMessage({ type: 'error', text: error.message || 'Failed to import file.' });
                }
                e.target.value = '';
            }
        );
    };

    const handleSaveAppName = () => {
        if (!appNameInput.trim()) {
            setMessage({ type: 'error', text: 'Program name cannot be empty.' });
            return;
        }
        setAppName(appNameInput.trim());
        setMessage({ type: 'success', text: 'Program name saved successfully.' });
    };

    const handleResetAppName = () => {
        confirmAction('Confirm Resetting Program Name', 'Are you sure you want to reset the program name to its default?',
            async () => { 
                setAppName(DEFAULT_APP_NAME);
                setMessage({ type: 'success', text: 'Default program name has been restored.' });
            }
        );
    };

    const handleSaveFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        try {
            const parsedConfig = JSON.parse(firebaseConfigInput);
            if (!parsedConfig.apiKey || !parsedConfig.databaseURL || !parsedConfig.projectId || !parsedConfig.authDomain) {
                setMessage({ type: 'error', text: 'Ensure Firebase config is correct and contains apiKey, databaseURL, projectId, authDomain.' });
                return;
            }
            setFirebaseConfig(parsedConfig);
            setMessage({ type: 'success', text: 'Firebase config saved successfully. Reconnecting now.' });
        } catch (e) {
            setMessage({ type: 'error', text: 'Invalid JSON format for Firebase config. Please check the text.' });
        }
    };

    const handleClearFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        confirmAction('Confirm Clearing Firebase Config', 'Are you sure you want to clear Firebase settings? The app will switch to local mode and will not connect to the cloud database.',
            async () => {
                setFirebaseConfig(null);
                setMessage({ type: 'success', text: 'Firebase config cleared. The app is now in local mode.' });
            }
        );
    };

    const handleDownloadDistributableEmpty = async () => {
        try {
            setMessage({ type: 'success', text: 'Preparing single HTML file (New App)...' });
            await generateAndDownloadDistributableHtml({ ...context, users: context.users, reports: [], students: [], halaqas: [], evaluations: [], firebaseConfig: null }, 'empty');
            setMessage({ type: 'success', text: '✅ Single HTML file downloaded successfully.' });
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleDownloadDistributableConnected = async () => {
        try {
            setMessage({ type: 'success', text: 'Preparing single HTML file (With Data)...' });
            await generateAndDownloadDistributableHtml({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: firebaseConfig }, 'snapshot');
            setMessage({ type: 'success', text: '✅ Single HTML file with data downloaded successfully.' });
        } catch (e) { setMessage({ type: 'error', text: 'Error creating the version.' }); }
    };

    const handleCopyHtml = async (type: 'empty' | 'connected') => {
        try {
            const config = type === 'empty' ? null : firebaseConfig;
            const htmlString = await getDistributableHtmlString({ ...context, users: context.users, reports: context.reports, students: [], halaqas: [], evaluations: [], firebaseConfig: config }, type === 'empty' ? 'empty' : 'snapshot');
            const success = await copyToClipboard(htmlString);
            if (success) {
                setCopyState(type);
                setTimeout(() => setCopyState('idle'), 3000);
                setMessage({ type: 'success', text: `✅ HTML code for the ${type === 'empty' ? 'blank' : 'connected'} version copied successfully.` });
            }
        } catch (e) {
            setMessage({ type: 'error', text: 'Failed to copy code.' });
        }
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => {
                e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); 
            }, 250); 
        }
    };

    return (
        <div className="bg-white p-6 sm:p-8 rounded-xl shadow-lg dark:bg-gray-800">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={handleCancel} hideDefaultCloseButton={isProcessing}>
                    <p className="dark:text-gray-200 text-center text-lg font-bold py-4">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-4 mt-4 pt-4 border-t dark:border-gray-700">
                        <button onClick={handleCancel} disabled={isProcessing} className={`px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>Cancel</button>
                        <button onClick={handleConfirm} disabled={isProcessing} className={`px-6 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}>{isProcessing ? 'Processing...' : 'Confirm'}</button>
                    </div>
                </Modal>
            )}

            <h3 className="text-2xl font-bold text-green-900 mb-6 dark:text-green-300">Settings</h3>

            <div className="flex flex-wrap border-b border-gray-200 mb-6 dark:border-gray-700">
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'main' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('main')}>Main Settings</button>
                <button className={`px-4 py-2 font-medium text-sm sm:text-base focus:outline-none sm:whitespace-nowrap transition-colors ${activeSettingsView === 'customization' ? 'text-green-700 border-b-2 border-green-700 dark:text-green-300 dark:border-green-400' : 'text-gray-500 hover:text-green-700 dark:text-gray-400 dark:hover:text-green-300'}`} onClick={() => setActiveSettingsView('customization')}>Customization</button>
            </div>

            {message && <div className={`p-4 mb-6 rounded-lg whitespace-pre-line text-center font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' : message.type === 'error' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200'}`}>{message.text}</div>}

            {activeSettingsView === 'main' && (
                <div className="space-y-8 animate-fade-in">
                    {isDistributable && !isPublishedConnected && (
                         <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                            <h4 className="text-lg font-semibold text-indigo-900 mb-4 dark:text-indigo-200">Firebase Configuration</h4>
                            <p className="text-sm text-indigo-700 mb-4 dark:text-indigo-300">
                                Link this app to your own Firebase database.
                            </p>
                            <label htmlFor="firebase-config" className="block text-sm font-medium text-gray-700 mb-1 dark:text-gray-200">Firebase Config (JSON Object)</label>
                            <textarea
                                id="firebase-config"
                                ref={firebaseConfigTextAreaRef}
                                value={firebaseConfigInput}
                                onChange={(e) => setFirebaseConfigInput(e.target.value)}
                                className="input-style w-full font-mono text-xs"
                                rows={8}
                                onFocus={handleInputFocus}
                            ></textarea>
                            <div className="flex gap-3 mt-4">
                                <button onClick={handleSaveFirebaseConfig} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors">Save Firebase Config</button>
                                <button onClick={handleClearFirebaseConfig} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors">Clear Config</button>
                            </div>
                        </div>
                    )}

                     <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200">Data Management</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2 dark:border-gray-500">Import & Export</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={handleDownloadImportTemplate} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors dark:bg-gray-600 dark:border-gray-500 dark:text-gray-200 dark:hover:bg-gray-500">📄 Download Template (Excel)</button>
                                    <button onClick={handleExportPopulationAndInstitutions} className="w-full text-left px-4 py-2 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors dark:bg-gray-600 dark:border-gray-500 dark:text-gray-200 dark:hover:bg-gray-500">📤 Export Population & Institution</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-green-50 border border-green-300 rounded-md hover:bg-green-100 transition-colors dark:bg-green-900/30 dark:border-green-800 dark:text-green-200 dark:hover:bg-green-800">📥 Import from Excel<input type="file" accept=".xlsx, .xls" onChange={handleFileImport} className="hidden" /></label>
                                </div>
                            </div>
                            <div className="space-y-4">
                                <h5 className="font-medium text-gray-700 dark:text-gray-300 border-b pb-2 dark:border-gray-500">Full Backup</h5>
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => handleExportFullBackup(false)} className="w-full text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 transition-colors dark:bg-blue-900 dark:border-blue-800 dark:text-blue-200 dark:hover:bg-blue-800">💾 Export Full Backup</button>
                                    <label className="w-full cursor-pointer text-left px-4 py-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-md hover:bg-blue-100 transition-colors dark:bg-blue-900 dark:border-blue-800 dark:text-blue-200 dark:hover:bg-blue-800">📂 Restore from Backup<input type="file" accept=".xlsx" onChange={handleImportFullBackup} className="hidden" /></label>
                                </div>
                            </div>
                         </div>
                        <div className="mt-8 pt-6 border-t border-gray-300 dark:border-gray-500">
                            <h5 className="font-medium text-red-700 mb-4 dark:text-red-400 text-center">Danger Zone</h5>
                            <div className="flex flex-col sm:flex-row gap-4">
                                <button onClick={handleDeleteReports} className="flex-1 px-4 py-3 bg-red-100 text-red-700 border border-red-200 rounded-md hover:bg-red-200 transition-colors font-semibold dark:bg-red-900 dark:border-red-800 dark:text-red-200 dark:hover:bg-red-800">🗑️ Delete All Reports</button>
                                <button onClick={handleDeleteAllData} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors font-semibold shadow-sm">⚠️ Reset Entire Program</button>
                            </div>
                        </div>
                    </div>

                    <div className="bg-indigo-50 p-6 rounded-lg border border-indigo-200 dark:bg-indigo-900/30 dark:border-indigo-800">
                        <h4 className="text-lg font-semibold text-indigo-900 mb-2 dark:text-indigo-200">Distribute a Copy (Single HTML File)</h4>
                        <p className="text-sm text-indigo-700 mb-6 dark:text-indigo-300">Download a single self-contained HTML file that works immediately.</p>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300 border-b border-indigo-100 pb-2">Blank Version (New App)</p>
                                <div className="flex flex-col gap-3">
                                    <button onClick={handleDownloadDistributableEmpty} className="w-full px-4 py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl hover:bg-indigo-50 transition-all font-bold shadow-sm flex items-center justify-center gap-2">
                                        ⬇️ Download .html File
                                    </button>
                                    <button onClick={() => handleCopyHtml('empty')} className={`w-full px-4 py-3 border rounded-xl transition-all font-bold flex items-center justify-center gap-2 ${copyState === 'empty' ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-indigo-600 text-white border-indigo-700 hover:bg-indigo-700 shadow-sm'}`}>
                                        {copyState === 'empty' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                    </button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300 border-b border-indigo-100 pb-2">Connected Version (With Data)</p>
                                <div className="flex flex-col gap-3">
                                    <button onClick={handleDownloadDistributableConnected} className="w-full px-4 py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl hover:bg-indigo-50 transition-all font-bold shadow-sm flex items-center justify-center gap-2">
                                        ⬇️ Download .html File
                                    </button>
                                    <button onClick={() => handleCopyHtml('connected')} className={`w-full px-4 py-3 border rounded-xl transition-all font-bold flex items-center justify-center gap-2 ${copyState === 'connected' ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-indigo-600 text-white border-indigo-700 hover:bg-indigo-700 shadow-sm'}`}>
                                        {copyState === 'connected' ? '✅ Copied!' : '📋 Copy HTML Code'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeSettingsView === 'customization' && (
                <div className="animate-fade-in space-y-8">
                    <div className="bg-gray-50 p-6 rounded-lg border border-gray-200 dark:bg-gray-700 dark:border-gray-600">
                        <h4 className="text-lg font-semibold text-gray-800 mb-4 dark:text-gray-200 text-center">Program Name</h4>
                        <div className="flex flex-col sm:flex-row gap-3">
                            <input ref={appNameInputRef} type="text" value={appNameInput} onChange={(e) => setAppNameInput(e.target.value)} className="input-style flex-grow" onFocus={handleInputFocus}/>
                            <button onClick={handleSaveAppName} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 transition-colors">Save Name</button>
                            <button onClick={handleResetAppName} className="px-6 py-2 bg-gray-200 text-gray-700 rounded-lg font-bold hover:bg-gray-300 transition-colors dark:bg-gray-600 dark:text-gray-200 dark:hover:bg-gray-500">Restore Default</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

declare const XLSX: any;

export const exportSheetTemplate = (fileName: string) => {
    // 1. Institutions Sheet
    const instHeaders = [
        ['id', 'willayat', 'name of Institution']
    ];
    // Example row
    const instData = [
        [2, 'Willayat Name', 'Sample Health Center']
    ];
    const wsInst = XLSX.utils.aoa_to_sheet([...instHeaders, ...instData]);

    // 2. Population Sheet
    const popHeaders = [
        ['InstitutionId', 'year', 'population']
    ];
    // Example row
    const popData = [
        [2, 2024, 1500]
    ];
    const wsPop = XLSX.utils.aoa_to_sheet([...popHeaders, ...popData]);

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, wsInst, 'Institutions');
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population');

    // Formatting
    const wscols = [{ wch: 15 }, { wch: 25 }, { wch: 35 }];
    wsInst['!cols'] = wscols;
    wsPop['!cols'] = [{ wch: 15 }, { wch: 10 }, { wch: 15 }];

    XLSX.writeFile(wb, `${fileName}.xlsx`);
};

import React, { useState, useContext, useMemo, useRef } from 'react';
import { AppContext } from '../App';
import { UserRole, User } from '../types';
import Modal from './Modal';
import { isSmartMatch } from '../utils/searchUtils';

const StudentManagement: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { users, addInstitution, updateInstitution, deleteInstitution } = context;

    const [newInstitutionName, setNewInstitutionName] = useState('');
    const [newStateName, setNewStateName] = useState(''); 
    const [editingInstitution, setEditingInstitution] = useState<User | null>(null);
    const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

    // Population Modal State
    const [selectedInstitutionForPop, setSelectedInstitutionForPop] = useState<User | null>(null);
    const [popYear, setPopYear] = useState<number>(new Date().getFullYear());
    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newStateName.trim()) { showMessage('⚠️ Please enter the Wilayat name.', true); return; }
        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) successfully.`);
            }
        } else { showMessage('⚠️ Please enter at least one institution name.', true); }
    };

    const handleUpdateInstitution = (institution: User, newName: string, newState: string) => {
        if (!newState.trim() || !newName.trim()) {
            showMessage('⚠️ Name and Wilayat cannot be empty.', true);
            return;
        }
        // الربط المباشر مع سجل المؤسسة في قاعدة البيانات مع الحفاظ على باقي البيانات (الرقم السري والسكان)
        updateInstitution({ 
            ...institution, 
            name: newName.trim(), 
            state: newState.trim(),
            updatedAt: Date.now() 
        });
        setEditingInstitution(null);
        showMessage('✅ Institution updated successfully.');
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Deletion',
            message: `Are you sure you want to delete "${institution.name}"? This action is permanent.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;
        const updatedPopulation = {
            ...(selectedInstitutionForPop.population || {}),
            [popYear]: Number(popCount)
        };
        updateInstitution({ 
            ...selectedInstitutionForPop, 
            population: updatedPopulation,
            updatedAt: Date.now()
        });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population saved.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => { e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-6 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-4 text-base font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-5 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-5 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700">Confirm</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-3">
                        <div className="flex gap-2 items-end">
                            <div className="flex-1">
                                <label className="block text-xs font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style py-1.5">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-xs font-bold mb-1">Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style py-1.5" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-1 px-4 bg-green-600 text-white rounded-lg font-bold h-[42px] text-sm">Save</button>
                        </div>
                        <div className="mt-2 border-t pt-2 dark:border-gray-700">
                            <div className="max-h-40 overflow-y-auto">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-sm">
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b dark:border-gray-600 last:border-0">
                                                    <td className="py-2 font-bold">{year}</td>
                                                    <td className="py-2 text-right font-mono">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-sm text-center">No data recorded</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print min-h-[40px]">
                <h3 className="text-2xl font-extrabold text-green-900 dark:text-green-300">Institution Management</h3>
                {message && (
                    <span className={`text-xs font-bold px-3 py-1 rounded-full animate-pulse ${message.isError ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 space-y-6">
                    <div className="bg-white rounded-2xl shadow-md border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-6 border-b dark:border-gray-700 bg-gray-50/50">
                            <form onSubmit={handleAddInstitution} className="flex flex-col gap-4">
                                <div className="flex flex-col sm:flex-row gap-3">
                                    <input type="text" value={newStateName} onChange={(e) => setNewStateName(e.target.value)} placeholder="Wilayat Name *" className="input-style sm:w-1/3" list="states-list" required />
                                    <datalist id="states-list">{uniqueStates.map(s => <option key={s} value={s} />)}</datalist>
                                    <textarea ref={newInstitutionInputRef} value={newInstitutionName} onChange={(e) => setNewInstitutionName(e.target.value)} placeholder="Enter institution names (one per line)..." className="input-style flex-grow" rows={1} onFocus={handleInputFocus} required />
                                </div>
                                <button type="submit" className="self-end px-8 py-2.5 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95">Add Institutions</button>
                            </form>
                        </div>

                        <div className="p-6 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
