import React, { useState, useContext, useMemo, useRef, useEffect } from 'react';
import { AppContext } from '../App';
import { UserRole } from '../types';

declare const XLSX: any;

const ENGLISH_MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

export const ReportsTable: React.FC = () => {
  const context = useContext(AppContext);
  if (!context) return null;
  const { reports, users } = context;

  const lastMonthDate = new Date();
  lastMonthDate.setMonth(lastMonthDate.getMonth() - 1);
  const defaultMonth = lastMonthDate.getMonth() + 1;
  const defaultYear = lastMonthDate.getFullYear();

  const [selectedYear, setSelectedYear] = useState<string>(String(defaultYear));
  const [selectedState, setSelectedState] = useState<string>('all');
  const [selectedInstitutionId, setSelectedInstitutionId] = useState<string>('all');
  const [selectedMonths, setSelectedMonths] = useState<number[]>([defaultMonth]);

  const availableYears = useMemo(() => {
      const years = Array.from(new Set(reports.map(r => r.year)));
      if (!years.includes(defaultYear)) years.push(defaultYear);
      return years.sort((a, b) => b - a).map(String);
  }, [reports, defaultYear]);

  const availableStates = useMemo(() => {
    return Array.from(new Set(users.filter(u => u.role === UserRole.INSTITUTION && u.state).map(u => u.state))).sort() as string[];
  }, [users]);

  const toggleMonth = (m: number) => {
      setSelectedMonths(prev => prev.includes(m) ? (prev.length === 1 ? prev : prev.filter(x => x !== m)) : [...prev, m].sort((a, b) => a - b));
  };

  const aggregatedData = useMemo(() => {
    let targetInstitutions = users.filter(u => u.role === UserRole.INSTITUTION);
    if (selectedState !== 'all') targetInstitutions = targetInstitutions.filter(u => u.state === selectedState);
    if (selectedInstitutionId !== 'all') targetInstitutions = targetInstitutions.filter(u => u.id.toString() === selectedInstitutionId);

    const states = Array.from(new Set(targetInstitutions.map(u => u.state || 'Unspecified'))).sort();
    const dataRows: any[] = [];

    const createEmptyRow = () => ({
        totalPopulation: 0, total_on_register: 0, target_population: 0,
        tp_bcg: 0, tp_opv1: 0, tp_hexa1: 0, tp_penta1: 0, tp_pcv1: 0, tp_rota1: 0,
        '14m_0_target': 0, '14m_0_vaccinated': 0, '20m_0_target': 0, '20m_0_vaccinated': 0, '26m_0_target': 0, '26m_0_vaccinated': 0
    });

    let grandTotals: any = createEmptyRow();

    states.forEach(state => {
        const stateInstitutions = targetInstitutions.filter(u => (u.state || 'Unspecified') === state);
        const stateInstIds = stateInstitutions.map(u => u.id);
        const stateReports = reports.filter(r => 
            stateInstIds.includes(r.institutionId) &&
            r.year === parseInt(selectedYear) &&
            selectedMonths.includes(r.month)
        );

        const statePopulation = stateInstitutions.reduce((sum, inst) => sum + (inst.population?.[parseInt(selectedYear)] || 0), 0);
        const row: any = { stateName: state, ...createEmptyRow(), totalPopulation: statePopulation };

        stateReports.forEach(r => {
            row.total_on_register += Number(r.total_on_register || 0);
            row.target_population += Number(r.target_population || 0);
            ['tp_bcg', 'tp_opv1', 'tp_hexa1', 'tp_penta1', 'tp_pcv1', 'tp_rota1'].forEach(k => { row[k] += Number(r[k] || 0); });
            ['14m_0_target', '14m_0_vaccinated', '20m_0_target', '20m_0_vaccinated', '26m_0_target', '26m_0_vaccinated'].forEach(k => { row[k] += Number(r[k] || 0); });
        });

        Object.keys(grandTotals).forEach(key => { grandTotals[key] += row[key]; });
        dataRows.push(row);
    });

    return { rows: dataRows, totals: grandTotals };
  }, [users, reports, selectedYear, selectedMonths, selectedState, selectedInstitutionId]);

  const calcPerc = (num: number, den: number) => (!den || den === 0) ? 0 : Math.round((num / den) * 100);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-xl dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
      <div className="no-print mb-8 space-y-6">
          <div className="flex justify-between items-center border-b pb-4 dark:border-gray-700">
            <h3 className="text-xl font-bold text-green-900 dark:text-green-300">Immunization Data Reports</h3>
            <button onClick={handlePrint} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md transition-all">Print Preview / PDF</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-50 dark:bg-gray-700 p-4 rounded-xl">
              <div>
                  <label className="text-xs font-bold text-gray-500 mb-1 block">Year</label>
                  <select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)} className="input-style py-1 text-sm font-bold">
                      {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                  </select>
              </div>
              <div>
                  <label className="text-xs font-bold text-gray-500 mb-1 block">Willayat</label>
                  <select value={selectedState} onChange={(e) => setSelectedState(e.target.value)} className="input-style py-1 text-sm font-bold">
                      <option value="all">All Willayats</option>
                      {availableStates.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
              </div>
              <div className="md:col-span-2">
                  <label className="text-xs font-bold text-gray-500 mb-1 block">Months</label>
                  <div className="flex flex-wrap gap-1">
                      {ENGLISH_MONTHS.map((m, idx) => (
                          <button key={idx} onClick={() => toggleMonth(idx + 1)} className={`px-2 py-1 rounded text-[10px] font-bold border transition-colors ${selectedMonths.includes(idx + 1) ? 'bg-green-600 text-white border-green-700' : 'bg-white text-gray-600 border-gray-200 dark:bg-gray-800 dark:border-gray-600'}`}>{m.substring(0,3)}</button>
                      ))}
                  </div>
              </div>
          </div>
      </div>

      <div className="overflow-x-auto rounded-xl border border-gray-300 dark:border-gray-600 shadow-inner">
        <table className="min-w-full border-collapse text-[10px]">
          <thead className="bg-green-800 text-white">
            <tr>
              <th className="border border-green-700 p-2">DISTRICT / WILLAYAT</th>
              <th className="border border-green-700 p-1">Total Population</th>
              <th className="border border-green-700 p-1">Live Birth</th>
              <th className="border border-green-700 p-1">Surv. Infants</th>
              <th colSpan={2} className="border border-green-700 p-1">BCG</th>
              <th colSpan={2} className="border border-green-700 p-1">OPV1</th>
              <th colSpan={2} className="border border-green-700 p-1">Hexa 1</th>
              <th colSpan={2} className="border border-green-700 p-1">Penta 3</th>
              <th colSpan={2} className="border border-green-700 p-1">PCV-1</th>
              <th colSpan={2} className="border border-green-700 p-1">Rota 1</th>
            </tr>
            <tr className="bg-green-700">
              <th colSpan={4}></th>
              {Array.from({ length: 6 }).map((_, i) => (
                  <React.Fragment key={i}>
                      <th className="border border-green-600 p-0.5 min-w-[30px]">Doses</th>
                      <th className="border border-green-600 p-0.5 min-w-[30px]">%</th>
                  </React.Fragment>
              ))}
            </tr>
          </thead>
          <tbody>
            {aggregatedData.rows.map((row) => (
              <tr key={row.stateName} className="odd:bg-white even:bg-green-50/30 dark:odd:bg-gray-800 dark:even:bg-gray-800/50">
                <td className="border border-gray-300 p-2 font-bold text-center dark:text-gray-100">{row.stateName}</td>
                <td className="border border-gray-300 p-1 text-center font-mono">{row.totalPopulation.toLocaleString()}</td>
                <td className="border border-gray-300 p-1 text-center">{row.total_on_register}</td>
                <td className="border border-gray-300 p-1 text-center">{row.target_population}</td>
                {['tp_bcg', 'tp_opv1', 'tp_hexa1', 'tp_penta1', 'tp_pcv1', 'tp_rota1'].map(k => {
                    const val = row[k];
                    const den = (k === 'tp_bcg' || k === 'tp_hbv1') ? row.total_on_register : row.target_population;
                    const perc = calcPerc(val, den);
                    return (
                        <React.Fragment key={k}>
                            <td className="border border-gray-300 p-1 text-center">{val}</td>
                            <td className={`border border-gray-300 p-1 text-center font-bold ${perc > 100 ? 'text-red-600' : 'text-blue-700'}`}>{perc}%</td>
                        </React.Fragment>
                    );
                })}
              </tr>
            ))}
            <tr className="bg-green-100 dark:bg-green-900/50 font-black text-xs">
                <td className="border border-gray-400 p-2 text-center uppercase">Grand Total</td>
                <td className="border border-gray-400 p-1 text-center">{aggregatedData.totals.totalPopulation.toLocaleString()}</td>
                <td className="border border-gray-400 p-1 text-center">{aggregatedData.totals.total_on_register}</td>
                <td className="border border-gray-400 p-1 text-center">{aggregatedData.totals.target_population}</td>
                {['tp_bcg', 'tp_opv1', 'tp_hexa1', 'tp_penta1', 'tp_pcv1', 'tp_rota1'].map(k => {
                    const val = aggregatedData.totals[k];
                    const den = (k === 'tp_bcg' || k === 'tp_hbv1') ? aggregatedData.totals.total_on_register : aggregatedData.totals.target_population;
                    const perc = calcPerc(val, den);
                    return (
                        <React.Fragment key={k}>
                            <td className="border border-gray-400 p-1 text-center">{val}</td>
                            <td className="border border-gray-400 p-1 text-center text-blue-800">{perc}%</td>
                        </React.Fragment>
                    );
                })}
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

