        };
        updateInstitution({ 
            ...selectedInstitutionForPop, 
            population: updatedPopulation,
            updatedAt: Date.now()
        });
        setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
        setPopCount('');
        showMessage('✅ Population saved.');
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => { e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

