export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          if (!savedUser) return null;
          const user = JSON.parse(savedUser);
          return { ...user, id: Number(user.id) }; 
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS.map(u => ({ ...u, id: Number(u.id) })), 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).compressedEmbeddedAppData) {
      try {
        const compressedBytes = base64ToBytes((window as any).compressedEmbeddedAppData);
        const zip = await JSZip.loadAsync(compressedBytes);
        const file = zip.file("data.json");
        if (file) {
          const jsonString = await file.async('string');
          loadedConfig = JSON.parse(jsonString);
        }
      } catch (e) { console.error(e); }
    } else if ((window as any).embeddedAppData) {
       try {
           loadedConfig = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob((window as any).embeddedAppData), c => c.charCodeAt(0))));
       } catch(e) { console.error(e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: deduplicateById((loadedConfig.users || INITIAL_USERS).map(u => ({ ...u, id: Number(u.id) }))),
        reports: deduplicateById((loadedConfig.reports || []).map(r => ({ ...r, id: Number(r.id), institutionId: Number(r.institutionId) }))),
        students: [],
        halaqas: [],
        evaluations: [],
        maghribAttendances: [],
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          setFirebaseConfigState(loadedConfig.firebaseConfig || HARDCODED_FIREBASE_CONFIG);
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: [],
            halaqas: [],
            evaluations: [],
            customLogo, supervisorPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            setData(prev => ({
              ...prev,
              users: val.users ? deduplicateById(Object.values(val.users).map((u:any) => ({...u, id: Number(u.id)}))) : INITIAL_USERS.map(u => ({ ...u, id: Number(u.id) })),
              reports: val.reports ? deduplicateById(Object.values(val.reports).map((r:any) => ({...r, id: Number(r.id), institutionId: Number(r.institutionId)}))) : [],
            }));
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    const parts = path.split('/');
    setData(prev => {
        if (parts[0] === 'data') {
            if (parts.length === 1) return { ...prev, ...value };
            const collection = parts[1] as keyof typeof data;

            if (parts.length === 3) {
                const itemId = Number(parts[2]);
                const list = [...(prev[collection] as any[])];
                if (value === null) {
                    return { ...prev, [collection]: list.filter(i => Number(i.id) !== itemId) };
                }
                const index = list.findIndex(i => Number(i.id) === itemId);
                const newItem = { ...value, id: itemId };
                if (index > -1) {
                    list[index] = newItem;
                } else {
                    list.push(newItem);
                }
                return { ...prev, [collection]: deduplicateById(list) };
            } 
            else if (parts.length === 2 && value === null) {
                return { ...prev, [collection]: collection === 'users' ? INITIAL_USERS : [] };
            }
            else if (parts.length === 2 && typeof value === 'object') {
                // تفعيل دعم التحديث الجماعي للمجموعات
                return { ...prev, [collection]: deduplicateById(Object.values(value).map((v: any) => ({...v, id: Number(v.id)}))) };
            }
        }
        return prev;
    });
  };

  const addReport = (rep: any) => {
      const newId = Date.now() + Math.floor(Math.random() * 1000);
      writeData(`data/reports/${newId}`, { ...rep, id: newId, updatedAt: Date.now() });
  };

  const updateReport = (rep: any) => writeData(`data/reports/${Number(rep.id)}`, { ...rep, id: Number(rep.id), updatedAt: Date.now() });
  const deleteReport = (id: number) => writeData(`data/reports/${Number(id)}`, null);

  const addInstitution = (n: string, state?: string, population?: { [year: number]: number }) => {
      // استخدام معرف زمني فريد جداً لمنع التصادم
      const newId = Date.now() + Math.floor(Math.random() * 1000);
      const newUser = { id: newId, name: n, state: state || null, role: UserRole.INSTITUTION, pin: '123', population: population || {}, updatedAt: Date.now() };
      writeData(`data/users/${newId}`, newUser);
  };

  const updateInstitution = (u: User) => {
      const id = Number(u.id);
      // التحديث يتم للمسار المحدد فقط لضمان عدم حذف الآخرين
      writeData(`data/users/${id}`, { ...u, id, updatedAt: Date.now() });
      if (currentUser && currentUser.id === id) {
          const updated = { ...u, id };
          setCurrentUser(updated);
          localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updated));
      }
  };

  const deleteInstitution = (institutionId: number) => writeData(`data/users/${Number(institutionId)}`, null);

  const handleLogout = () => { 
      if (hasUnsavedChanges) {
          if (!window.confirm('⚠️ تحذير: لديك تغييرات غير محفوظة. هل أنت متأكد من الخروج؟')) return;
      }
      setCurrentUser(null); 
      setHasUnsavedChanges(false);
      localStorage.removeItem(CURRENT_USER_KEY); 
  };

  const handleLogin = (user: User) => { 
      const cleanUser = { ...user, id: Number(user.id) };
      setCurrentUser(cleanUser); 
      localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(cleanUser)); 
  };

  const isMandatoryPasswordChange = currentUser?.role === UserRole.INSTITUTION && currentUser?.pin === '123';

  return (
    <AppContext.Provider value={{
      users: data.users, reports: data.reports,
      addReport, updateReport, deleteReport, 
      deleteAllReports: async () => { writeData('data/reports', null); },
      deleteAllData: async () => {
          writeData('data/reports', null);
          writeData('data/users', null);
      },
      loadMockData: () => {
          const mockObj = MOCK_USERS.reduce((acc, u) => ({...acc, [u.id]: u}), {});
          writeData('data/users', mockObj);
          writeData('data/reports', {});
      },
      customLogo, setCustomLogo: (l) => { setCustomLogoState(l); writeData('config/customLogo', l); },
      addInstitution, updateInstitution, deleteInstitution, importFullBackup: (d) => writeData('data', d),
      supervisorPassword, setSupervisorPassword: (p) => { setSupervisorPasswordState(p); writeData('config/supervisorPassword', p); },
      logout: handleLogout, isLoading, initiateLogoutCheck: handleLogout, appName, setAppName: (n) => { setAppNameState(n); writeData('config/appName', n); },
      darkMode, toggleDarkMode: () => setDarkMode(!darkMode), 
      firebaseConnectionStatus, 
      firebaseConfig: firebaseConfigState, 
      setFirebaseConfig: (c) => setFirebaseConfigState(c),
      isDistributable, isPublishedConnected, currentUser,
      students: [], 
      halaqas: [], 
      evaluations: [],
      updateEvaluation: () => {}, 
      deleteEvaluation: () => {},
      addEvaluation: () => {},
      setLastUsedWeek: () => {},
      maghribAttendances: [],
      addMaghribAttendance: () => {},
      deleteMaghribAttendance: () => {},
      maghribPassword: '', 
      setMaghribPassword: () => {},
      immunizationPassword,
      setImmunizationPassword: (p) => { setImmunizationPasswordState(p); writeData('config/immunizationPassword', p); },
      setHasUnsavedChanges
    }}>
      <div className={`h-screen flex flex-col transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-green-50 text-gray-900'}`}>
          {isDistributable && !firebaseConfigState && !isPublishedConnected && <FirebaseSetupWizard onConfigSave={setFirebaseConfigState} />}
          {!currentUser ? (
              <LoginScreen onLogin={handleLogin} />
          ) : (
              <div className="flex flex-col h-full">
                  <Header 
                      user={currentUser} 
                      onShowHelp={() => setShowHelpModal(true)} 
                      onInitiateLogoutCheck={handleLogout} 
                      onShowMobileInstallModal={() => setShowMobileInstallModal(true)} 
                      onShowChangePassword={() => setShowChangePasswordModal(true)} 
                  />
                  <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                      {currentUser.role === UserRole.SUPERVISOR && <SupervisorDashboard />}
                      {currentUser.role === UserRole.IMMUNIZATION && <ImmunizationDashboard />}
                      {currentUser.role === UserRole.INSTITUTION && <InstitutionDashboard institutionId={currentUser.id} />}
                  </main>
              </div>
          )}
          {showHelpModal && <HelpModal onClose={() => setShowHelpModal(false)} />}
          {showMobileInstallModal && <MobileInstallModal onClose={() => setShowMobileInstallModal(false)} />}
          {(showChangePasswordModal || isMandatoryPasswordChange) && currentUser && (
            <ChangePasswordModal 
                onClose={() => setShowChangePasswordModal(false)} 
                isMandatory={isMandatoryPasswordChange}
                currentStoredPassword={
                    currentUser.role === UserRole.SUPERVISOR ? supervisorPassword : 
                    currentUser.role === UserRole.IMMUNIZATION ? immunizationPassword :
                    (currentUser.pin || '123')
                }
                onSave={(p) => {
                    if (currentUser.role === UserRole.SUPERVISOR) {
                        setSupervisorPasswordState(p); 
                        writeData('config/supervisorPassword', p);
                    } else if (currentUser.role === UserRole.IMMUNIZATION) {
                        setImmunizationPasswordState(p);
                        writeData('config/immunizationPassword', p);
                    } else if (currentUser.role === UserRole.INSTITUTION) {
                        const updatedUser = { ...currentUser, id: Number(currentUser.id), pin: p, updatedAt: Date.now() };
                        updateInstitution(updatedUser);
                    }
                }} 
            />
          )}
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState, useContext, useMemo, useRef } from 'react';
import { AppContext } from '../App';
import { UserRole, User } from '../types';
import Modal from './Modal';
import { isSmartMatch } from '../utils/searchUtils';

const StudentManagement: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { users, addInstitution, updateInstitution, deleteInstitution } = context;

    const [newInstitutionName, setNewInstitutionName] = useState('');
    const [newStateName, setNewStateName] = useState(''); 
    const [editingInstitution, setEditingInstitution] = useState<User | null>(null);
    const [editName, setEditName] = useState('');
    const [editState, setEditState] = useState('');
    const [institutionSearchTerm, setInstitutionSearchTerm] = useState('');

    // Population Modal State
    const [selectedInstitutionForPop, setSelectedInstitutionForPop] = useState<User | null>(null);
    const [popYear, setPopYear] = useState<number>(new Date().getFullYear());
    const [popCount, setPopCount] = useState<number | ''>('');
    const [selectedStatYear, setSelectedStatYear] = useState<number>(new Date().getFullYear());

    const newInstitutionInputRef = useRef<HTMLTextAreaElement>(null);
    const institutionSearchInputRef = useRef<HTMLInputElement>(null);

    const [message, setMessage] = useState<{ text: string, isError?: boolean } | null>(null);
    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION).sort((a,b) => (a.state || '').localeCompare(b.state || '', 'en') || a.name.localeCompare(b.name, 'en')), [users]);

    const filteredInstitutions = useMemo(() => {
        if (!institutionSearchTerm.trim()) return institutions;
        return institutions.filter(t => isSmartMatch(t.name, institutionSearchTerm) || isSmartMatch(t.state || '', institutionSearchTerm));
    }, [institutions, institutionSearchTerm]);

    const stateStatistics = useMemo(() => {
        const stats: { [state: string]: number } = {};
        institutions.forEach(inst => {
            const state = inst.state || 'Unspecified';
            const count = inst.population?.[selectedStatYear] || 0;
            stats[state] = (stats[state] || 0) + count;
        });
        return Object.entries(stats).sort((a, b) => b[1] - a[1]); 
    }, [institutions, selectedStatYear]);

    const showMessage = (text: string, isError: boolean = false) => {
        setMessage({ text, isError });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleAddInstitution = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newStateName.trim()) { showMessage('⚠️ Please enter the Wilayat name.', true); return; }
        if (newInstitutionName.trim()) {
            const names = newInstitutionName.split('\n').filter(name => name.trim() !== '');
            const stateToSave = newStateName.trim();
            if (names.length > 0) {
                names.forEach(name => addInstitution(name.trim(), stateToSave));
                setNewInstitutionName('');
                setNewStateName(''); 
                showMessage(`✅ Added ${names.length} institution(s) successfully.`);
            }
        } else { showMessage('⚠️ Please enter at least one institution name.', true); }
    };

    const startEditing = (institution: User) => {
        setEditingInstitution(institution);
        setEditName(institution.name);
        setEditState(institution.state || '');
    };

    const handleUpdateInstitution = () => {
        if (!editingInstitution) return;
        if (!editState.trim() || !editName.trim()) {
            showMessage('⚠️ Name and Wilayat cannot be empty.', true);
            return;
        }

        // جلب البيانات الأصلية من القائمة الحالية لضمان عدم فقدان أي حقول أخرى
        const original = users.find(u => u.id === editingInstitution.id);
        if (original) {
            updateInstitution({ 
                ...original, 
                name: editName.trim(), 
                state: editState.trim(),
                updatedAt: Date.now() 
            });
            setEditingInstitution(null);
            showMessage('✅ Institution updated successfully.');
        }
    };

    const handleInstitutionDelete = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Confirm Deletion',
            message: `Are you sure you want to delete "${institution.name}"? This action is permanent.`,
            onConfirm: () => {
                deleteInstitution(institution.id);
                setConfirmationModal(prev => ({ ...prev, isOpen: false }));
                showMessage('🗑️ Institution deleted.');
            }
        });
    };

    const handleSavePopulation = () => {
        if (!selectedInstitutionForPop || popCount === '') return;

        const original = users.find(u => u.id === selectedInstitutionForPop.id);
        if (original) {
            const updatedPopulation = {
                ...(original.population || {}),
                [popYear]: Number(popCount)
            };
            updateInstitution({ 
                ...original, 
                population: updatedPopulation,
                updatedAt: Date.now()
            });
            setSelectedInstitutionForPop(prev => prev ? ({ ...prev, population: updatedPopulation }) : null); 
            setPopCount('');
            showMessage('✅ Population saved.');
        }
    };

    const handleInputFocus = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        if (window.innerWidth < 768) { 
            setTimeout(() => { e.target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 250); 
        }
    };

    const uniqueStates = Array.from(new Set(institutions.map(i => i.state).filter(Boolean)));

    return (
        <div className="space-y-6 animate-fade-in">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} hideDefaultCloseButton={true}>
                    <p className="py-4 text-base font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal(prev => ({ ...prev, isOpen: false }))} className="px-5 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-5 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700">Confirm</button>
                    </div>
                </Modal>
            )}

            {selectedInstitutionForPop && (
                <Modal title={`Population: ${selectedInstitutionForPop.name}`} onClose={() => setSelectedInstitutionForPop(null)}>
                    <div className="space-y-3">
                        <div className="flex gap-2 items-end">
                            <div className="flex-1">
                                <label className="block text-xs font-bold mb-1">Year</label>
                                <select value={popYear} onChange={e => setPopYear(Number(e.target.value))} className="input-style py-1.5">
                                    {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                            <div className="flex-1">
                                <label className="block text-xs font-bold mb-1">Count</label>
                                <input type="number" value={popCount} onChange={e => setPopCount(e.target.value === '' ? '' : Number(e.target.value))} className="input-style py-1.5" placeholder="0" />
                            </div>
                            <button onClick={handleSavePopulation} className="py-1 px-4 bg-green-600 text-white rounded-lg font-bold h-[42px] text-sm">Save</button>
                        </div>
                        <div className="mt-2 border-t pt-2 dark:border-gray-700">
                            <div className="max-h-40 overflow-y-auto">
                                {selectedInstitutionForPop.population && Object.keys(selectedInstitutionForPop.population).length > 0 ? (
                                    <table className="w-full text-sm">
                                        <tbody>
                                            {Object.entries(selectedInstitutionForPop.population).map(([year, count]) => (
                                                <tr key={year} className="border-b dark:border-gray-600 last:border-0">
                                                    <td className="py-2 font-bold">{year}</td>
                                                    <td className="py-2 text-right font-mono">{count.toLocaleString()}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                ) : <p className="text-gray-400 text-sm text-center">No data recorded</p>}
                            </div>
                        </div>
                    </div>
                </Modal>
            )}

            <div className="flex justify-between items-center no-print min-h-[40px]">
                <h3 className="text-2xl font-extrabold text-green-900 dark:text-green-300">Institution Management</h3>
                {message && (
                    <span className={`text-xs font-bold px-3 py-1 rounded-full animate-pulse ${message.isError ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>
                        {message.text}
                    </span>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 space-y-6">
                    <div className="bg-white rounded-2xl shadow-md border border-gray-100 dark:bg-gray-800 dark:border-gray-700 overflow-hidden">
                        <div className="p-6 border-b dark:border-gray-700 bg-gray-50/50">
                            <form onSubmit={handleAddInstitution} className="flex flex-col gap-4">
                                <div className="flex flex-col sm:flex-row gap-3">
                                    <input type="text" value={newStateName} onChange={(e) => setNewStateName(e.target.value)} placeholder="Wilayat Name *" className="input-style sm:w-1/3" list="states-list" required />
                                    <datalist id="states-list">{uniqueStates.map(s => <option key={s} value={s} />)}</datalist>
                                    <textarea ref={newInstitutionInputRef} value={newInstitutionName} onChange={(e) => setNewInstitutionName(e.target.value)} placeholder="Enter institution names (one per line)..." className="input-style flex-grow" rows={1} onFocus={handleInputFocus} required />
                                </div>
                                <button type="submit" className="self-end px-8 py-2.5 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-md active:scale-95">Add Institutions</button>
                            </form>
                        </div>

                        <div className="p-6 bg-white dark:bg-gray-800 border-t dark:border-gray-700">
                            <div className="relative mb-6">
                                <input ref={institutionSearchInputRef} type="text" placeholder="Search by name or Wilayat..." value={institutionSearchTerm} onChange={(e) => setInstitutionSearchTerm(e.target.value)} className="input-style w-full pl-12" onFocus={handleInputFocus} />
                                <svg className="absolute left-4 top-3.5 h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[600px] overflow-y-auto custom-scrollbar">
                                {filteredInstitutions.map(institution => {
                                    const isEditing = editingInstitution?.id === institution.id;
                                    return (
                                        <div key={institution.id} className="p-5 bg-gray-50 rounded-2xl border border-gray-200 dark:bg-gray-700/50 dark:border-gray-600 hover:shadow-lg transition-all group flex flex-col justify-between">
                                            {isEditing ? (
                                                <div className="space-y-3 animate-fade-in">
                                                    <input type="text" value={editState} onChange={e => setEditState(e.target.value)} placeholder="Wilayat" className="input-style text-sm py-2" required />
                                                    <input type="text" value={editName} onChange={e => setEditName(e.target.value)} placeholder="Institution Name" className="input-style text-sm py-2" required />
                                                    <div className="flex gap-2">
                                                        <button onClick={handleUpdateInstitution} className="flex-1 bg-green-600 text-white py-2 rounded-lg font-bold text-sm shadow-sm hover:bg-green-700">Save</button>
                                                        <button onClick={() => setEditingInstitution(null)} className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg font-bold text-sm hover:bg-gray-300">Cancel</button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <>
                                                    <div className="mb-4">
                                                        <span className="text-[10px] text-indigo-600 dark:text-indigo-400 font-black bg-indigo-50 dark:bg-indigo-900/40 px-2 py-0.5 rounded inline-block mb-1">{institution.state || 'No Wilayat'}</span>
                                                        <p className="font-extrabold text-gray-800 dark:text-gray-100 text-lg leading-tight">{institution.name}</p>
                                                    </div>
                                                    <div className="flex justify-between items-center mt-3 pt-4 border-t dark:border-gray-600">
                                                        <button onClick={() => setSelectedInstitutionForPop(institution)} className="text-xs font-bold bg-white text-green-700 border border-green-200 px-3 py-1.5 rounded-lg hover:bg-green-50 transition-colors dark:bg-gray-800 dark:border-green-800 dark:text-green-400">
                                                            👥 Population ({institution.population?.[new Date().getFullYear()]?.toLocaleString() || 0})
                                                        </button>
                                                        <div className="flex gap-2">
                                                            <button onClick={() => startEditing(institution)} className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-all dark:bg-blue-900/30 dark:text-blue-400">
                                                                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                                                            </button>
                                                            <button onClick={() => handleInstitutionDelete(institution)} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-all dark:bg-red-900/30 dark:text-red-400">
                                                                <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                                            </button>
                                                        </div>
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-2xl shadow-md border border-gray-100 dark:bg-gray-800 p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h4 className="text-lg font-bold text-gray-800 dark:text-gray-200">State Statistics</h4>
                        <select value={selectedStatYear} onChange={e => setSelectedStatYear(Number(e.target.value))} className="input-style py-1 text-xs w-auto">
                            {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                    <div className="space-y-3 max-h-[600px] overflow-y-auto">
                        {stateStatistics.map(([state, count], index) => (
                            <div key={state} className={`p-3 rounded-xl flex justify-between items-center ${index % 2 === 0 ? 'bg-green-50/50' : 'bg-gray-50/30'}`}>
                                <span className="font-bold text-gray-700 dark:text-gray-300 text-sm truncate max-w-[140px]">{state}</span>
                                <span className="font-mono font-black text-green-800 text-lg">{count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

