export const MonthlyEntryForm: React.FC<MonthlyEntryFormProps> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { reports, addReport, updateReport, users, setHasUnsavedChanges } = context;

    const [activeInstitutionId, setActiveInstitutionId] = useState<number | undefined>(institutionId);
    const [instSearchTerm, setInstSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [justDeletedId, setJustDeletedId] = useState<number | null>(null);

    useEffect(() => { if (!allowInstitutionSelection && institutionId) setActiveInstitutionId(institutionId); }, [institutionId, allowInstitutionSelection]);

    const activeInstitution = useMemo(() => users.find(u => u.id === activeInstitutionId), [users, activeInstitutionId]);

    const availableInstitutions = useMemo(() => {
        return users
            .filter(u => u.role === UserRole.INSTITUTION)
            .filter(u => isSmartMatch(u.name, instSearchTerm))
            .sort((a, b) => a.name.localeCompare(b.name, 'en'));
    }, [users, instSearchTerm]);

    const now = new Date();
    const [selectedYear, setSelectedYear] = useState<number>(() => now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(() => now.getMonth() === 0 ? 12 : now.getMonth());

    const [formData, setFormData] = useState<Record<string, string | number>>({});
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [activeTab, setActiveTab] = useState(1);
    const formRef = useRef<HTMLDivElement>(null);
    const [submitMessage, setSubmitMessage] = useState<string | null>(null);

    const [hasUserTypedNumber, setHasUserTypedNumber] = useState(false);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [isFormLoaded, setIsFormLoaded] = useState(false);
    const [isPristine, setIsPristine] = useState(true); // لضمان عدم تفعيل الحساب التلقائي عند التحميل الأول

    const autoCalculatedFields = useMemo(() => new Set([
        'target_population',
        'tp_bcg', 'tp_hbv1', 'tp_hexa1', 'tp_rota1', 'tp_pcv1',
        'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2',
        'tp_penta1', 'tp_opv2',
        'defaulter_incorrect_address',
        'defaulter_not_found',
        'defaulter_refused',
        'tp_fully_immunized',
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length }, (_, i) => `${g.monthKey}_${i}_target`)),
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length }, (_, i) => `${g.monthKey}_${i}_vaccinated`))
    ]), []);

    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const currentReport = useMemo(() => {
        if (!activeInstitutionId) return undefined;
        return reports.find(r => r.institutionId === activeInstitutionId && r.year === selectedYear && r.month === selectedMonth);
    }, [reports, activeInstitutionId, selectedYear, selectedMonth]);

    const targetMonthString = useMemo(() => {
        const reportingDate = new Date(selectedYear, selectedMonth - 1, 1);
        reportingDate.setMonth(reportingDate.getMonth() - 8);
        return `${MONTHS_AR[reportingDate.getMonth()]} ${reportingDate.getFullYear()}`;
    }, [selectedYear, selectedMonth]);

    const isNavigationBlocked = useMemo(() => hasUserTypedNumber && !formData.recorder_name, [hasUserTypedNumber, formData.recorder_name]);

    useEffect(() => {
        setHasUnsavedChanges(isNavigationBlocked);
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isNavigationBlocked) {
                const message = 'You have unsaved changes. Please enter "Name of Recorder" to save before leaving.';
                e.preventDefault(); e.returnValue = message; return message;
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isNavigationBlocked, setHasUnsavedChanges]);

    useEffect(() => {
        setIsFormLoaded(false);
        setIsPristine(true); // نعود للحالة النقية عند تبديل التقرير

        if (!activeInstitutionId) {
            setFormData({}); setManuallyEditedFields(new Set()); setHasUserTypedNumber(false); setIsFormLoaded(true);
            return;
        }

        if (justDeletedId && currentReport && currentReport.id === justDeletedId) return;
        if (justDeletedId && (!currentReport || currentReport.id !== justDeletedId)) setJustDeletedId(null);

        if (currentReport) {
            const { institution_name, state, ...rest } = currentReport;
            setFormData({ ...rest, recorder_name: currentReport.entryPerson });
            // عند التحميل، نعتبر جميع الحقول "معدلة يدوياً" لحماية أرقام النسخة الاحتياطية
            const fieldsFromData = new Set<string>(currentReport.manuallyEditedFields || []);
            Object.keys(rest).forEach(k => {
                if (typeof rest[k] === 'number') fieldsFromData.add(k);
            });
            setManuallyEditedFields(fieldsFromData);
            setHasUserTypedNumber(Object.keys(currentReport).length > 10);
        } else {
            setHasUserTypedNumber(false); setManuallyEditedFields(new Set()); setFormData({ recorder_name: '' });
        }
        setIsFormLoaded(true);
    }, [currentReport, activeInstitutionId, justDeletedId]);

    const getAllFocusableInputs = useCallback((): Array<HasDataset> => {
        if (!formRef.current) return [];
        const containerId = activeTab === 1 ? 'page-1-content' : 'page-2-content';
        const visibleContainer = document.getElementById(containerId);
        if (!visibleContainer) return [];
        const selector = 'input[data-local-row][data-local-col]:not([readonly]), textarea[data-local-row][data-local-col]:not([readonly])';
        let allInputs = Array.from(visibleContainer.querySelectorAll(selector)) as Array<HasDataset>;
        allInputs.sort((a, b) => {
            const aRow = parseInt(a.dataset.localRow || '0'), aCol = parseInt(a.dataset.localCol || '0');
            const bRow = parseInt(b.dataset.localRow || '0'), bCol = parseInt(b.dataset.localCol || '0');
            if (activeTab === 2) return aRow !== bRow ? aRow - bRow : aCol - bCol;
            const aMajor = (a.closest('[data-major-col]') as HasDataset)?.dataset.majorCol === 'left' ? 0 : 1;
            const bMajor = (b.closest('[data-major-col]') as HasDataset)?.dataset.majorCol === 'left' ? 0 : 1;
            if (aMajor !== bMajor) return aMajor - bMajor;
            return aMajor === 0 ? (aRow !== bRow ? aRow - bRow : aCol - bCol) : (aCol !== bCol ? aCol - bCol : aRow - bRow);
        });
        return allInputs;
    }, [activeTab]);

    // --- التأثيرات الحسابية (تفعيلها فقط إذا لم يكن التقرير في حالة "نقية" أي بعد أول تعديل) ---

    useEffect(() => {
        if (!isFormLoaded || isPristine || manuallyEditedFields.has('target_population')) return;
        const total = normalizeValueForComparison(formData.total_on_register);
        const died = normalizeValueForComparison(formData.children_died);
        const trans = normalizeValueForComparison(formData.children_transferred);
        const left = normalizeValueForComparison(formData.children_left_country);
        const newTarget = Math.max(0, (Number(total || 0)) - (Number(died || 0)) - (Number(trans || 0)) - (Number(left || 0)));
        if (normalizeValueForComparison(formData.target_population) !== newTarget) {
            setFormData(prev => ({ ...prev, target_population: newTarget }));
        }
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.children_died, formData.children_transferred, formData.children_left_country, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const total = normalizeValueForComparison(formData.total_on_register);
        const mainT = normalizeValueForComparison(formData.target_population);
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            ['tp_bcg', 'tp_hbv1'].forEach(k => {
                if (!manuallyEditedFields.has(k) && normalizeValueForComparison(updated[k]) !== total) { updated[k] = total; changed = true; }
            });
            ['tp_hexa1', 'tp_rota1', 'tp_pcv1', 'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2', 'tp_penta1', 'tp_opv2'].forEach(k => {
                if (!manuallyEditedFields.has(k) && normalizeValueForComparison(updated[k]) !== mainT) { updated[k] = mainT; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const mainT = normalizeValueForComparison(formData.target_population);
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            ['defaulter_incorrect_address', 'defaulter_not_found', 'defaulter_refused', 'tp_fully_immunized'].forEach(k => {
                if (!manuallyEditedFields.has(k) && normalizeValueForComparison(updated[k]) !== mainT) { updated[k] = mainT; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.target_population, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            [{ prefix: '14m', count: 5 }, { prefix: '20m', count: 4 }, { prefix: '26m', count: 2 }].forEach(g => {
                const tSrc = normalizeValueForComparison(prev[`${g.prefix}_0_target`]);
                const vSrc = normalizeValueForComparison(prev[`${g.prefix}_0_vaccinated`]);
                for (let i = 1; i < g.count; i++) {
                    const tk = `${g.prefix}_${i}_target`, vk = `${g.prefix}_${i}_vaccinated`;
                    if (!manuallyEditedFields.has(tk) && normalizeValueForComparison(updated[tk]) !== tSrc) { updated[tk] = tSrc; changed = true; }
                    if (!manuallyEditedFields.has(vk) && normalizeValueForComparison(updated[vk]) !== vSrc) { updated[vk] = vSrc; changed = true; }
                }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData['14m_0_target'], formData['14m_0_vaccinated'], formData['20m_0_target'], formData['20m_0_vaccinated'], formData['26m_0_target'], formData['26m_0_vaccinated'], manuallyEditedFields]);

    // --- الحسابات الجبرية الصرف (تظل نشطة لأنها غير قابلة للتعديل اليدوي) ---

    useEffect(() => {
        if (!isFormLoaded) return;
        const tO = Number(formData.p4_tdap_target_omani_pregnant || 0), tN = Number(formData.p4_tdap_target_non_omani_pregnant || 0);
        const gO = Number(formData.p4_tdap_given_omani_pregnant || 0), gN = Number(formData.p4_tdap_given_non_omani_pregnant || 0);
        setFormData(prev => {
            const updated = {...prev}; let changed = false;
            if (updated.p4_tdap_target_total_pregnant !== tO + tN) { updated.p4_tdap_target_total_pregnant = tO + tN; changed = true; }
            if (updated.p4_tdap_given_total_pregnant !== gO + gN) { updated.p4_tdap_given_total_pregnant = gO + gN; changed = true; }
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData.p4_tdap_target_omani_pregnant, formData.p4_tdap_target_non_omani_pregnant, formData.p4_tdap_given_omani_pregnant, formData.p4_tdap_given_non_omani_pregnant]);

    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = {...prev}; let changed = false;
            influenzaCriteria.forEach((_, idx) => {
                const tTot = Number(updated[`p4_flu_target_omani_${idx}`] || 0) + Number(updated[`p4_flu_target_non_omani_${idx}`] || 0);
                const gTot = Number(updated[`p4_flu_given_omani_${idx}`] || 0) + Number(updated[`p4_flu_given_non_omani_${idx}`] || 0);
                if (updated[`p4_flu_target_total_${idx}`] !== tTot) { updated[`p4_flu_target_total_${idx}`] = tTot; changed = true; }
                if (updated[`p4_flu_given_total_${idx}`] !== gTot) { updated[`p4_flu_given_total_${idx}`] = gTot; changed = true; }
                let cov = tTot > 0 ? ((gTot / tTot) * 100).toFixed(1) + '%' : '';
                if (updated[`p4_flu_coverage_${idx}`] !== cov) { updated[`p4_flu_coverage_${idx}`] = cov; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        setIsPristine(false); // بمجرد التعديل، نسمح بتفعيل الحساب التلقائي للحقول غير المحمية
        if (autoCalculatedFields.has(name)) setManuallyEditedFields(prev => new Set(prev).add(name));
        if ((e.target as HTMLInputElement).type === 'number' && value.trim() !== '') setHasUserTypedNumber(true);
        setFormData(prev => ({ ...prev, [name]: type === 'number' ? normalizeValueForComparison(value) : value }));
        setSaveStatus('idle');
    };

    useEffect(() => {
        if (justDeletedId) return;
        const timer = setTimeout(() => {
            if (saveStatus === 'idle' && Object.keys(formData).length > 2 && activeInstitutionId && formData.recorder_name) {
                setSaveStatus('saving');
                const reportToSave: any = {
                    institutionId: activeInstitutionId, year: selectedYear, month: selectedMonth,
                    entryPerson: formData.recorder_name as string || '', updatedAt: Date.now(), targetMonth: targetMonthString,
                    ...formData, manuallyEditedFields: Array.from(manuallyEditedFields)
                };
                if (currentReport) { reportToSave.id = currentReport.id; updateReport(reportToSave); }
                else { addReport(reportToSave); }
                setSaveStatus('saved');
            }
        }, 2000);
        return () => clearTimeout(timer);
    }, [formData, saveStatus, currentReport, addReport, updateReport, activeInstitutionId, selectedYear, selectedMonth, targetMonthString, justDeletedId, manuallyEditedFields]);

    const handleInputKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const inputs = getAllFocusableInputs();
            const currentIndex = inputs.indexOf(e.target as HasDataset);
            if (currentIndex === -1) return;
            const nextInput = inputs[currentIndex + 1] || inputs[0];
            if (nextInput) nextInput.focus();
        }
    }, [getAllFocusableInputs]);

    const handleExportExcel = () => {
        const data = { ...formData, institution_name: activeInstitution?.name, reporting_month: `${MONTHS_AR[selectedMonth - 1]} ${selectedYear}` };
        const ws = XLSX.utils.json_to_sheet([data]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, `Report`);
        XLSX.writeFile(wb, `EPI_${activeInstitution?.name}_${selectedMonth}_${selectedYear}.xlsx`);
    };

    const handlePrint = () => {
        const createPrintableClone = (sourceId: string) => {
            const source = document.getElementById(sourceId);
            if (!source) return null;
            const clone = source.cloneNode(true) as HTMLElement;
            clone.style.display = 'block'; 
            const sourceInputs = source.querySelectorAll('input, textarea, select');
            const cloneInputs = clone.querySelectorAll('input, textarea, select');
            for(let i=0; i<sourceInputs.length; i++) {
                const s = sourceInputs[i] as HTMLInputElement;
                const c = cloneInputs[i] as HTMLInputElement;
                const span = document.createElement('span');
                span.className = 'data-cell-pdf';
                span.innerText = s.value;
                if (c.parentNode) c.parentNode.replaceChild(span, c);
            }
            return clone;
        };
        const p1 = createPrintableClone('page-1-content'), p2 = createPrintableClone('page-2-content');
        if (!p1 || !p2) return;
        const win = window.open('', '_blank');
        if (!win) return;
        win.document.write(`
            <!DOCTYPE html><html><head><meta charset="UTF-8"><title>EPI Report</title><link href="https://cdn.tailwindcss.com" rel="stylesheet"><style>
            @page { size: A3 portrait; margin: 1cm; } body { font-family: sans-serif; background: white; width: 100%; margin: 0; }
            #pdf-p2 { page-break-before: always; margin-top: 1cm; } .ph { margin-bottom: 1rem; border-bottom: 2px solid #000; text-align: center; }
            table { border-collapse: collapse; width: 100%; font-size: 11px; } table, th, td { border: 1.5px solid #000; }
            th { background-color: #f2f2f2 !important; padding: 4px; } td { text-align: center; padding: 4px; }
            .data-cell-pdf { font-size: 11px; font-weight: 500; } #page-1-grid-container { display: grid !important; grid-template-columns: 1fr 1fr !important; gap: 1cm !important; }
            .no-print { display: none !important; }
            </style></head><body>
            <div class="ph"><h1>EPI Report - ${activeInstitution?.name}</h1><p>${MONTHS_AR[selectedMonth - 1]} ${selectedYear}</p></div>
            ${p1.innerHTML}<div id="pdf-p2">${p2.innerHTML}</div></body></html>
        `);
        win.document.close(); setTimeout(() => win.print(), 800);
    };

    const handleDeleteReport = () => {
        if (!currentReport) return;
        setConfirmationModal({
            isOpen: true, title: 'Confirm Report Deletion', message: 'Are you sure you want to delete this report? This action cannot be undone.',
            onConfirm: () => {
                setJustDeletedId(currentReport.id); context.deleteReport(currentReport.id);
                setFormData({ recorder_name: '' });
                setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: () => {} });
                setSubmitMessage('Report deleted'); setTimeout(() => setSubmitMessage(null), 3000);
            }
        });
    };

    if (!activeInstitutionId && !allowInstitutionSelection) return <div>Invalid Configuration</div>;

    return (
        <div className="bg-white dark:bg-gray-800 shadow-md flex flex-col rounded-xl overflow-hidden">
            {confirmationModal.isOpen && (
                <Modal title={confirmationModal.title} onClose={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} hideDefaultCloseButton={true}>
                    <p className="py-4 text-lg font-bold text-red-800 dark:text-red-400 text-center">{confirmationModal.message}</p>
                    <div className="flex justify-center gap-3 pt-4 border-t dark:border-gray-700">
                        <button onClick={() => setConfirmationModal({ ...confirmationModal, isOpen: false })} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold hover:bg-gray-300">Cancel</button>
                        <button onClick={confirmationModal.onConfirm} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold hover:bg-red-700 shadow-md transition-all active:scale-95">Confirm Delete</button>
                    </div>
                </Modal>
            )}

            <header className="bg-white dark:bg-gray-900 border-b p-4 dark:border-gray-700">
                <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                    <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100 flex items-center gap-2">
                        Immunization Data Entry
                        {saveStatus === 'saving' && <span className="text-xs text-blue-500 animate-pulse">(Saving...)</span>}
                        {saveStatus === 'saved' && <span className="text-xs text-green-500">(Saved)</span>}
                    </h1>
                    <div className="flex gap-2">
                        <select value={selectedMonth} onChange={e => setSelectedMonth(Number(e.target.value))} className="input-style w-32 py-1 text-base font-bold">
                            {MONTHS_AR.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
                        </select>
                        <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="input-style w-24 py-1 text-base font-bold">
                            {[2024, 2025, 2026, 2027, 2028].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 bg-gray-50 dark:bg-gray-800 overflow-x-auto">
                <div className="flex justify-center mb-6">
                    <div className="bg-white dark:bg-gray-700 rounded-lg shadow p-1 flex">
                        <button onClick={() => setActiveTab(1)} className={`px-6 py-2 rounded-md font-semibold transition-colors ${activeTab === 1 ? 'bg-blue-600 text-white' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-600'}`}>Page 1</button>
                        <button onClick={() => setActiveTab(2)} className={`px-6 py-2 rounded-md font-semibold transition-colors ${activeTab === 2 ? 'bg-blue-600 text-white' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-600'}`}>Page 2</button>
                    </div>
                </div>

                <div ref={formRef} className="bg-white dark:bg-gray-900 p-4 shadow-sm min-w-[800px]">
                    <div id="page-1-content" style={{ display: activeTab === 1 ? 'block' : 'none' }}>
                        <div id="page-1-grid-container" className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <div className="flex flex-col gap-6" data-major-col="left">
                                <div className="space-y-4">
                                    <div className="flex items-center gap-2 bg-amber-50 dark:bg-amber-900/20 border border-black dark:border-gray-600 p-2 relative">
                                        <label className="font-bold whitespace-nowrap text-base dark:text-gray-200">Name of Institution:</label>
                                        {allowInstitutionSelection ? (
                                            <div className="relative w-full">
                                                <div className="w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 p-2 rounded cursor-pointer flex justify-between items-center" onClick={() => setIsDropdownOpen(!isDropdownOpen)}>
                                                    <span className={`truncate text-lg font-bold ${!activeInstitution ? 'text-gray-400' : 'text-gray-900 dark:text-gray-100'}`}>{activeInstitution?.name || 'Select Institution...'}</span>
                                                    <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                                                </div>
                                                {isDropdownOpen && (
                                                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 shadow-lg max-h-60 rounded overflow-hidden flex flex-col">
                                                        <input type="text" placeholder="Search..." value={instSearchTerm} onChange={(e) => setInstSearchTerm(e.target.value)} className="p-2 border-b border-gray-200 dark:border-gray-700 outline-none w-full dark:bg-gray-800 dark:text-gray-200" autoFocus />
                                                        <div className="overflow-y-auto flex-1">
                                                            {availableInstitutions.map(inst => (
                                                                <div key={inst.id} className={`p-2 hover:bg-green-50 dark:hover:bg-green-800/50 cursor-pointer dark:text-gray-200 ${activeInstitutionId === inst.id ? 'bg-green-100 dark:bg-green-900/50 font-bold' : ''}`} onClick={() => { setActiveInstitutionId(inst.id); setIsDropdownOpen(false); setInstSearchTerm(''); }}>{inst.name}</div>
                                                            ))}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        ) : <div className="w-full p-2 bg-gray-100 dark:bg-gray-700 rounded text-lg font-bold border border-gray-200 dark:border-gray-600 dark:text-gray-100 text-center">{activeInstitution?.name}</div>}
                                    </div>
                                    <div className={`flex items-center gap-2 border border-black dark:border-gray-600 p-2 transition-colors ${!formData.recorder_name && isNavigationBlocked ? 'bg-red-50 dark:bg-red-900/50 border-red-500' : 'bg-amber-50 dark:bg-amber-900/20'}`}>
                                        <label className="font-bold whitespace-nowrap text-base dark:text-gray-200">Name of Recorder <span className="text-red-600">*</span>:</label>
                                        <FormInput type="text" name="recorder_name" value={formData.recorder_name || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={0} data-local-col={0} />
                                    </div>
                                    <table className="w-full border-collapse border border-black dark:border-gray-600 bg-amber-50 dark:bg-amber-900/20">
                                        <tbody>
                                            <tr><TdCell colSpan={2} className="font-bold bg-amber-100 dark:bg-amber-900/40 text-left">Target month</TdCell><TdCell className="bg-gray-100 dark:bg-gray-700 font-bold text-lg">{targetMonthString}</TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold bg-amber-100 dark:bg-amber-900/40 text-left">Total on Register</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="total_on_register" value={formData.total_on_register || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={1} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold bg-amber-100 dark:bg-amber-900/40 text-left">Children who have died</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_died" value={formData.children_died || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={2} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold bg-amber-100 dark:bg-amber-900/40 text-left">Transferred out</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_transferred" value={formData.children_transferred || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={3} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold bg-amber-100 dark:bg-amber-900/40 text-left">Left country</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_left_country" value={formData.children_left_country || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={4} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-left">TARGET POPULATION</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="target_population" value={formData.target_population || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={5} data-local-col={0} /></TdCell></tr>
                                            {vaccineRows.map((row, idx) => (
                                                <tr key={row.name}><TdCell colSpan={2} className="text-left bg-amber-100 dark:bg-amber-900/40 font-bold">{row.label}</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={row.name} value={formData[row.name] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={6 + idx} data-local-col={0} /></TdCell></tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                                <table className="w-full border-collapse border border-black dark:border-gray-600 bg-white dark:bg-gray-900">
                                    <thead className="bg-amber-100 dark:bg-amber-900/40"><tr><th className="border border-black p-1 text-left">TARGET POPULATION for:</th><th>Target pop</th><th>Vaccinated</th><th>Remarks</th></tr></thead>
                                    {page2Groups.map((g, gIdx) => (
                                        <tbody key={g.monthKey}>
                                            <tr><th colSpan={4} className="border border-black p-1 text-left bg-amber-200 dark:bg-amber-800/50 font-bold">{g.monthKey}</th></tr>
                                            {g.items.map((v, idx) => (
                                                <tr key={idx}>
                                                    <TdCell className="text-left font-bold">{v}</TdCell>
                                                    <TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={`${g.monthKey}_${idx}_target`} value={formData[`${g.monthKey}_${idx}_target`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={21 + (gIdx * 10) + idx} data-local-col={0} /></TdCell>
                                                    <TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={`${g.monthKey}_${idx}_vaccinated`} value={formData[`${g.monthKey}_${idx}_vaccinated`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={21 + (gIdx * 10) + idx} data-local-col={1} /></TdCell>
                                                    <TdCell className="bg-white dark:bg-gray-800"><FormInput type="text" name={`${g.monthKey}_${idx}_remarks`} value={formData[`${g.monthKey}_${idx}_remarks`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={21 + (gIdx * 10) + idx} data-local-col={2} /></TdCell>
                                                </tr>
                                            ))}
                                        </tbody>
                                    ))}
                                </table>
                            </div>
                            <div data-major-col="right" className="flex flex-col gap-6">
                                <table className="w-full border-collapse border border-black dark:border-gray-600 bg-amber-50 dark:bg-amber-900/20">
                                    <thead><tr><th colSpan={3} className="bg-amber-200 dark:bg-amber-800/50 p-1 font-bold">Child Immunization Doses</th></tr></thead>
                                    <tbody>
                                        {childImmunizationDataDefinition.map((item, idx) => {
                                            const base = 2 + (idx * 5);
                                            if (item.type === 'normal') {
                                                return (<tr key={item.key}><TdCell className="text-left font-bold">{item.label}</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={`p3_child_${item.key}_le1_su`} value={formData[`p3_child_${item.key}_le1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={base} data-local-col={0} /></TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={`p3_child_${item.key}_gt1_su`} value={formData[`p3_child_${item.key}_gt1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={base} data-local-col={2} /></TdCell></tr>);
                                            }
                                            return null;
                                        })}
                                    </tbody>
                                </table>
                                <div className="border border-black dark:border-gray-600 p-2 bg-amber-50 dark:bg-amber-900/10">
                                    <label className="font-bold block mb-2">General Notes:</label>
                                    <SimpleRichTextEditor value={formData.general_notes as string || ''} onChange={(v) => { setIsPristine(false); setFormData(prev => ({ ...prev, general_notes: v })); }} />
                                </div>
                            </div>
                        </div>
                    </div>
                    <div id="page-2-content" style={{ display: activeTab === 2 ? 'block' : 'none' }}>
                        <table className="w-full border-collapse border border-black dark:border-gray-600 bg-white dark:bg-gray-900 text-sm">
                            <thead><tr><th colSpan={4} className="bg-amber-200 dark:bg-amber-800/50 p-1 font-bold text-xl">Influenza doses</th></tr></thead>
                            <tbody>
                                {influenzaCriteria.map((l, idx) => (
                                    <tr key={idx}><td className="border border-black p-1 font-bold text-left">{l}</td><td className="p-0"><FormInput type="number" name={`p4_flu_target_omani_${idx}`} value={formData[`p4_flu_target_omani_${idx}`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={idx} data-local-col={0} /></td><td className="p-0"><FormInput type="number" name={`p4_flu_given_omani_${idx}`} value={formData[`p4_flu_given_omani_${idx}`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={idx} data-local-col={1} /></td><td className="p-1 bg-gray-100 dark:bg-gray-700 font-bold text-xl">{formData[`p4_flu_coverage_${idx}`] || '0%'}</td></tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </main>
            <footer className="bg-white dark:bg-gray-900 p-4 border-t dark:border-gray-700 flex justify-between items-center">
                <div className="flex gap-2">
                    {currentReport && <button onClick={handleDeleteReport} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold shadow hover:bg-red-700">Delete</button>}
                    <button onClick={handlePrint} className="px-6 py-2 bg-gray-700 text-white rounded-lg font-bold shadow hover:bg-gray-800">Print / PDF</button>
                    <button onClick={handleExportExcel} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold shadow hover:bg-blue-700">Excel</button>
                    <button onClick={() => { setIsPristine(false); setSaveStatus('idle'); }} className="px-8 py-2 bg-green-700 text-white rounded-lg font-bold shadow-lg hover:bg-green-800">Manual Save</button>
                </div>
            </footer>
        </div>
    );
};

