const normalizeValueForComparison = (value: string | number | undefined | null): number | '' => {
    if (value === undefined || value === null || value === '') return '';
    const num = Number(value);
    return !isNaN(num) ? num : '';
};

const TdCell: React.FC<{ 
    children?: React.ReactNode, 
    className?: string, 
    colSpan?: number, 
    rowSpan?: number, 
    text?: string 
}> = ({ children, className = '', colSpan, rowSpan, text }) => (
    <td 
        className={`border border-black dark:border-gray-600 p-0.5 text-center align-middle text-base font-medium ${className}`} 
        colSpan={colSpan} 
        rowSpan={rowSpan}
    >
        {children || text}
    </td>
);

const FormInput = React.forwardRef<HTMLInputElement | HTMLTextAreaElement, { 
    type: 'number' | 'text' | 'textarea', 
    name: string, 
    value: any, 
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void, 
    placeholder?: string, 
    'data-local-row': number,
    'data-local-col': number,
    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => void,
    readOnly?: boolean,
    className?: string
}>(({ type, name, value, onChange, placeholder, onKeyDown, readOnly, className = '', ...props }, ref) => {
    const handleFocus = (event: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => event.target.select();
    const commonProps = {
        ref,
        name,
        value: value || '',
        onChange,
        onFocus: handleFocus,
        onKeyDown,
        placeholder: readOnly ? '' : (placeholder || ''),
        readOnly,
        className: `w-full h-full text-center outline-none border-none p-1 focus:bg-yellow-100 dark:focus:bg-yellow-900/50 text-lg font-bold dark:text-gray-200 ${readOnly ? 'bg-gray-100 dark:bg-gray-700' : 'bg-white dark:bg-gray-800'} ${className}`,
        autoComplete: 'off' as const,
        ...props
    };
    if (type === 'textarea') return <textarea {...commonProps} ref={ref as React.Ref<HTMLTextAreaElement>} rows={3} className={`${commonProps.className} resize-y`} />;
    return <input {...commonProps} ref={ref as React.Ref<HTMLInputElement>} type={type} />;
});
FormInput.displayName = 'FormInput';

const SimpleRichTextEditor: React.FC<{ value: string; onChange: (val: string) => void }> = ({ value, onChange }) => {
    const editorRef = useRef<HTMLDivElement>(null);
    const handleCommand = (command: string, val: string | undefined = undefined) => {
        document.execCommand(command, false, val);
        if (editorRef.current) {
            editorRef.current.focus();
            onChange(editorRef.current.innerHTML);
        }
    };
    const handleInput = () => { if (editorRef.current) onChange(editorRef.current.innerHTML); };
    useEffect(() => {
        if (editorRef.current && editorRef.current.innerHTML !== value) {
             if (document.activeElement !== editorRef.current) editorRef.current.innerHTML = value || '';
        }
    }, [value]);
    return (
        <div className="border border-gray-300 dark:border-gray-600 rounded-md overflow-hidden bg-white dark:bg-gray-800 w-full h-full flex flex-col">
            <div className="flex gap-1 bg-gray-100 dark:bg-gray-700 p-1 border-b dark:border-gray-600 no-print">
                <button type="button" onClick={() => handleCommand('bold')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded font-bold">B</button>
                <button type="button" onClick={() => handleCommand('italic')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded italic">I</button>
                <button type="button" onClick={() => handleCommand('underline')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded underline">U</button>
            </div>
            <div
                ref={editorRef}
                contentEditable
                className="p-2 outline-none flex-grow overflow-y-auto text-left min-h-[100px] text-base text-gray-800 dark:text-gray-200"
                onInput={handleInput}
                onKeyDown={(e) => { if (e.key === 'Enter') e.stopPropagation(); }}
                style={{ direction: 'ltr' }}
            />
        </div>
    );
};

export const MonthlyEntryForm: React.FC<{ institutionId?: number; allowInstitutionSelection?: boolean; }> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;
    const { reports, addReport, updateReport, users, setHasUnsavedChanges } = context;
    const [activeInstitutionId, setActiveInstitutionId] = useState<number | undefined>(institutionId);
    const [instSearchTerm, setInstSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [justDeletedId, setJustDeletedId] = useState<number | null>(null);

    const activeInstitution = useMemo(() => users.find(u => u.id === activeInstitutionId), [users, activeInstitutionId]);
    const availableInstitutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION && isSmartMatch(u.name, instSearchTerm)).sort((a, b) => a.name.localeCompare(b.name, 'en')), [users, instSearchTerm]);
    const now = new Date();
    const [selectedYear, setSelectedYear] = useState<number>(() => now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(() => now.getMonth() === 0 ? 12 : now.getMonth());

    const [formData, setFormData] = useState<Record<string, string | number>>({});
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [activeTab, setActiveTab] = useState(1);
    const formRef = useRef<HTMLDivElement>(null);
    const [hasUserTypedNumber, setHasUserTypedNumber] = useState(false);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [isFormLoaded, setIsFormLoaded] = useState(false);
    const [isPristine, setIsPristine] = useState(true);

    const currentReport = useMemo(() => activeInstitutionId ? reports.find(r => r.institutionId === activeInstitutionId && r.year === selectedYear && r.month === selectedMonth) : undefined, [reports, activeInstitutionId, selectedYear, selectedMonth]);
    const targetMonthString = useMemo(() => {
        const reportingDate = new Date(selectedYear, selectedMonth - 1, 1);
        reportingDate.setMonth(reportingDate.getMonth() - 8);
        return `${MONTHS_AR[reportingDate.getMonth()]} ${reportingDate.getFullYear()}`;
    }, [selectedYear, selectedMonth]);

    const isNavigationBlocked = useMemo(() => hasUserTypedNumber && !formData.recorder_name, [hasUserTypedNumber, formData.recorder_name]);

    useEffect(() => {
        setHasUnsavedChanges(isNavigationBlocked);
    }, [isNavigationBlocked, setHasUnsavedChanges]);

    useEffect(() => {
        setIsFormLoaded(false);
        setIsPristine(true);
        if (!activeInstitutionId) { setFormData({}); setManuallyEditedFields(new Set()); setHasUserTypedNumber(false); setIsFormLoaded(true); return; }
        if (justDeletedId && currentReport && currentReport.id === justDeletedId) return;

        if (currentReport) {
            setFormData({ ...currentReport, recorder_name: currentReport.entryPerson });
            const savedManualFields = new Set<string>(currentReport.manuallyEditedFields || []);
            // حماية تلقائية لكل القيم الرقمية الموجودة أصلاً
            Object.keys(currentReport).forEach(key => {
                if (typeof currentReport[key] === 'number') savedManualFields.add(key);
            });
            setManuallyEditedFields(savedManualFields);
            setHasUserTypedNumber(true);
        } else {
            setFormData({ recorder_name: '' });
            setManuallyEditedFields(new Set());
            setHasUserTypedNumber(false);
        }
        setIsFormLoaded(true);
    }, [currentReport, activeInstitutionId, justDeletedId]);

    const getAllFocusableInputs = useCallback((): Array<HasDataset> => {
        if (!formRef.current) return [];
        const container = document.getElementById(activeTab === 1 ? 'page-1-content' : 'page-2-content');
        if (!container) return [];
        return Array.from(container.querySelectorAll('input[data-local-row], textarea[data-local-row]')) as Array<HasDataset>;
    }, [activeTab]);

    // --- المعادلات التلقائية (تتوقف إذا كان التقرير "نقياً" أي مستورد ولم يُعدل بعد) ---

    useEffect(() => {
        if (!isFormLoaded || isPristine || manuallyEditedFields.has('target_population')) return;
        const total = Number(formData.total_on_register || 0);
        const dead = Number(formData.children_died || 0);
        const trans = Number(formData.children_transferred || 0);
        const left = Number(formData.children_left_country || 0);
        const newTarget = Math.max(0, total - dead - trans - left);
        if (formData.target_population !== newTarget) setFormData(prev => ({ ...prev, target_population: newTarget }));
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.children_died, formData.children_transferred, formData.children_left_country, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const total = Number(formData.total_on_register || 0);
        const mainT = Number(formData.target_population || 0);
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            ['tp_bcg', 'tp_hbv1'].forEach(k => { if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== total) { updated[k] = total; changed = true; } });
            ['tp_hexa1', 'tp_rota1', 'tp_pcv1', 'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2', 'tp_penta1', 'tp_opv2'].forEach(k => { if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== mainT) { updated[k] = mainT; changed = true; } });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    // --- حسابات النسب والمجاميع (تظل فعالة لأنها غير قابلة للإدخال) ---
    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = {...prev}; let changed = false;
            influenzaCriteria.forEach((_, idx) => {
                const totalT = Number(updated[`p4_flu_target_omani_${idx}`] || 0) + Number(updated[`p4_flu_target_non_omani_${idx}`] || 0);
                const totalG = Number(updated[`p4_flu_given_omani_${idx}`] || 0) + Number(updated[`p4_flu_given_non_omani_${idx}`] || 0);
                if (updated[`p4_flu_target_total_${idx}`] !== totalT) { updated[`p4_flu_target_total_${idx}`] = totalT; changed = true; }
                if (updated[`p4_flu_given_total_${idx}`] !== totalG) { updated[`p4_flu_given_total_${idx}`] = totalG; changed = true; }
                const cov = totalT > 0 ? ((totalG / totalT) * 100).toFixed(1) + '%' : '';
                if (updated[`p4_flu_coverage_${idx}`] !== cov) { updated[`p4_flu_coverage_${idx}`] = cov; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        setIsPristine(false); // أي تعديل يكسر حالة "النقاء" ويسمح بالمعادلات للحقول غير المحمية
        if (type === 'number') {
            setHasUserTypedNumber(true);
            setManuallyEditedFields(prev => new Set(prev).add(name));
        }
        setFormData(prev => ({ ...prev, [name]: type === 'number' ? normalizeValueForComparison(value) : value }));
        setSaveStatus('idle');
    };

    useEffect(() => {
        if (justDeletedId) return;
        const timer = setTimeout(() => {
            if (saveStatus === 'idle' && Object.keys(formData).length > 2 && activeInstitutionId && formData.recorder_name) {
                setSaveStatus('saving');
                const reportToSave: any = {
                    institutionId: activeInstitutionId, year: selectedYear, month: selectedMonth,
                    entryPerson: formData.recorder_name, updatedAt: Date.now(), targetMonth: targetMonthString,
                    ...formData, manuallyEditedFields: Array.from(manuallyEditedFields)
                };
                if (currentReport) { reportToSave.id = currentReport.id; updateReport(reportToSave); }
                else { addReport(reportToSave); }
                setSaveStatus('saved');
            }
        }, 2000);
        return () => clearTimeout(timer);
    }, [formData, saveStatus, currentReport, activeInstitutionId, selectedYear, selectedMonth, manuallyEditedFields]);

    const handleInputKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const inputs = getAllFocusableInputs();
            const idx = inputs.indexOf(e.target as HasDataset);
            if (idx > -1 && inputs[idx+1]) (inputs[idx+1] as HTMLElement).focus();
        }
    }, [getAllFocusableInputs]);

    return (
        <div className="bg-white dark:bg-gray-800 shadow-md flex flex-col rounded-xl overflow-hidden">
            <header className="bg-white dark:bg-gray-900 border-b p-4">
                <div className="flex justify-between items-center">
                    <h1 className="text-xl font-bold dark:text-white">Immunization Data Entry
                        {saveStatus === 'saving' && <span className="text-xs text-blue-500 ml-2 animate-pulse">(Saving...)</span>}
                        {saveStatus === 'saved' && <span className="text-xs text-green-500 ml-2">(Saved)</span>}
                    </h1>
                    <div className="flex gap-2">
                        <select value={selectedMonth} onChange={e => setSelectedMonth(Number(e.target.value))} className="input-style w-32 py-1 font-bold">
                            {MONTHS_AR.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
                        </select>
                        <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="input-style w-24 py-1 font-bold">
                            {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 bg-gray-50 dark:bg-gray-800 overflow-x-auto">
                <div className="flex justify-center mb-6">
                    <div className="bg-white dark:bg-gray-700 rounded-lg shadow p-1 flex">
                        <button onClick={() => setActiveTab(1)} className={`px-6 py-2 rounded-md font-semibold ${activeTab === 1 ? 'bg-blue-600 text-white' : 'dark:text-gray-200'}`}>Page 1</button>
                        <button onClick={() => setActiveTab(2)} className={`px-6 py-2 rounded-md font-semibold ${activeTab === 2 ? 'bg-blue-600 text-white' : 'dark:text-gray-200'}`}>Page 2</button>
                    </div>
                </div>

                <div ref={formRef} className="bg-white dark:bg-gray-900 p-4 shadow-sm min-w-[800px]">
                    <div id="page-1-content" style={{ display: activeTab === 1 ? 'block' : 'none' }}>
                        <div className="grid grid-cols-2 gap-6">
                            <div className="space-y-4">
                                <div className="flex items-center gap-2 bg-amber-50 dark:bg-amber-900/20 border border-black p-2">
                                    <label className="font-bold whitespace-nowrap dark:text-white">Institution:</label>
                                    {allowInstitutionSelection ? (
                                        <select value={activeInstitutionId} onChange={e => setActiveInstitutionId(Number(e.target.value))} className="w-full bg-white dark:bg-gray-800 dark:text-white p-1 border font-bold">
                                            {availableInstitutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                                        </select>
                                    ) : <div className="font-bold dark:text-white">{activeInstitution?.name}</div>}
                                </div>
                                <div className={`flex items-center gap-2 border border-black p-2 ${!formData.recorder_name && isNavigationBlocked ? 'bg-red-100' : 'bg-amber-50'}`}>
                                    <label className="font-bold whitespace-nowrap">Recorder Name *:</label>
                                    <FormInput type="text" name="recorder_name" value={formData.recorder_name || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={0} data-local-col={0} />
                                </div>
                                <table className="w-full border-collapse border border-black">
                                    <tbody>
                                        <tr className="bg-amber-100"><TdCell colSpan={2} className="text-left font-bold">Target month</TdCell><TdCell className="bg-gray-100 font-bold">{targetMonthString}</TdCell></tr>
                                        <tr><TdCell colSpan={2} className="text-left font-bold">Total on Register</TdCell><TdCell><FormInput type="number" name="total_on_register" value={formData.total_on_register || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={1} data-local-col={0} /></TdCell></tr>
                                        <tr><TdCell colSpan={2} className="text-left font-bold">Children who have died</TdCell><TdCell><FormInput type="number" name="children_died" value={formData.children_died || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={2} data-local-col={0} /></TdCell></tr>
                                        <tr><TdCell colSpan={2} className="text-left font-bold">Transferred out</TdCell><TdCell><FormInput type="number" name="children_transferred" value={formData.children_transferred || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={3} data-local-col={0} /></TdCell></tr>
                                        <tr><TdCell colSpan={2} className="text-left font-bold">Left country</TdCell><TdCell><FormInput type="number" name="children_left_country" value={formData.children_left_country || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={4} data-local-col={0} /></TdCell></tr>
                                        <tr className="bg-amber-200"><TdCell colSpan={2} className="text-left font-bold">TARGET POPULATION</TdCell><TdCell><FormInput type="number" name="target_population" value={formData.target_population || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={5} data-local-col={0} /></TdCell></tr>
                                        {vaccineRows.map((r, i) => (
                                            <tr key={r.name}><TdCell colSpan={2} className="text-left font-bold">{r.label}</TdCell><TdCell><FormInput type="number" name={r.name} value={formData[r.name] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={6+i} data-local-col={0} /></TdCell></tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            <div className="space-y-4">
                                <table className="w-full border-collapse border border-black">
                                    <thead className="bg-amber-200 font-bold"><tr><th>Child Immunization</th><th><=1yr</th><th>>1yr</th></tr></thead>
                                    <tbody>
                                        {childImmunizationDataDefinition.map((item, idx) => {
                                            if (item.type !== 'normal') return null;
                                            return <tr key={item.key}><TdCell className="text-left font-bold">{item.label}</TdCell><TdCell><FormInput type="number" name={`p3_child_${item.key}_le1_su`} value={formData[`p3_child_${item.key}_le1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={100+idx} data-local-col={0} /></TdCell><TdCell><FormInput type="number" name={`p3_child_${item.key}_gt1_su`} value={formData[`p3_child_${item.key}_gt1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={100+idx} data-local-col={1} /></TdCell></tr>;
                                        })}
                                    </tbody>
                                </table>
                                <div className="border border-black p-2 bg-amber-50"><label className="font-bold mb-2 block">General Notes:</label>
                                    <SimpleRichTextEditor value={formData.general_notes as string || ''} onChange={v => setFormData(p => ({...p, general_notes: v}))} />
                                </div>
                            </div>
                        </div>
                    </div>
                    <div id="page-2-content" style={{ display: activeTab === 2 ? 'block' : 'none' }}>
                        <table className="w-full border-collapse border border-black bg-white">
                            <thead><tr className="bg-amber-200 font-bold text-lg"><th colSpan={4} className="p-2">Influenza Doses</th></tr><tr className="bg-amber-100"><th>Criteria</th><th>Target (Total)</th><th>Given (Total)</th><th>Coverage %</th></tr></thead>
                            <tbody>
                                {influenzaCriteria.map((l, i) => (
                                    <tr key={i}>
                                        <TdCell className="text-left font-bold">{l}</TdCell>
                                        <TdCell className="bg-gray-100">{formData[`p4_flu_target_total_${i}`] || 0}</TdCell>
                                        <TdCell className="bg-gray-100">{formData[`p4_flu_given_total_${i}`] || 0}</TdCell>
                                        <TdCell className="bg-blue-50 font-bold text-xl">{formData[`p4_flu_coverage_${i}`] || '0%'}</TdCell>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </main>
            <footer className="p-4 border-t bg-white dark:bg-gray-900 flex justify-end gap-2">
                <button onClick={() => { setIsPristine(false); setSaveStatus('idle'); }} className="px-8 py-2 bg-green-700 text-white rounded-lg font-bold shadow hover:bg-green-800">Save Changes</button>
            </footer>
        </div>
    );
};

import { FullBackupData, UserRole, MonthlyReport, User } from '../types';
declare const XLSX: any;

const getUniqueKeys = (data: any[], preferredOrder: string[] = []) => {
    const keys = new Set<string>();
    data.forEach(item => {
        Object.keys(item).forEach(k => keys.add(k));
    });
    const sortedKeys: string[] = [];
    preferredOrder.forEach(k => {
        if (keys.has(k)) {
            sortedKeys.push(k);
            keys.delete(k);
        }
    });
    return [...sortedKeys, ...Array.from(keys).sort()];
};

export const exportFullBackup = (data: FullBackupData, fileName: string) => {
    const wb = XLSX.utils.book_new();

    const institutionsOnly = data.users.filter(u => u.role === UserRole.INSTITUTION);
    const userKeys = ['id', 'name', 'role', 'state', 'pin'];
    let usersHeaders = getUniqueKeys(institutionsOnly, userKeys);
    usersHeaders = usersHeaders.filter(h => h !== 'population');

    const usersData = institutionsOnly.map(u => {
        const row: any = {};
        usersHeaders.forEach(h => {
            row[h] = (u as any)[h] ?? '';
        });
        return row;
    });
    const wsUsers = XLSX.utils.json_to_sheet(usersData, { header: usersHeaders });
    XLSX.utils.book_append_sheet(wb, wsUsers, 'Institutions_List');

    const popRows: any[] = [];
    institutionsOnly.forEach(inst => {
        const populations = inst.population || {};
        Object.entries(populations).forEach(([year, count]) => {
            popRows.push({
                InstitutionId: inst.id,
                year: Number(year),
                population: Number(count)
            });
        });
    });
    const wsPop = XLSX.utils.json_to_sheet(popRows, { header: ['InstitutionId', 'year', 'population'] });
    XLSX.utils.book_append_sheet(wb, wsPop, 'Population_Data');

    if (data.reports && data.reports.length > 0) {
        const reportPreferredKeys = ['id', 'institutionId', 'year', 'month', 'entryPerson', 'updatedAt', 'targetMonth', 'manuallyEditedFields'];
        const reportHeaders = getUniqueKeys(data.reports, reportPreferredKeys);
        const reportsExportData = data.reports.map(r => ({
            ...r,
            manuallyEditedFields: Array.isArray(r.manuallyEditedFields) ? JSON.stringify(r.manuallyEditedFields) : r.manuallyEditedFields
        }));
        const wsReports = XLSX.utils.json_to_sheet(reportsExportData, { header: reportHeaders });
        XLSX.utils.book_append_sheet(wb, wsReports, 'Monthly_Reports');
    }

    const authData = [
        ['Role', 'Access Password / PIN'],
        ['Main Supervisor', data.supervisorPassword || '123'],
        ['Immunization Dept', data.immunizationPassword || '12345']
    ];
    const wsAuth = XLSX.utils.aoa_to_sheet(authData);
    XLSX.utils.book_append_sheet(wb, wsAuth, 'Auth_Credentials');

    const settingsRows = [
        ['Setting Name', 'Value'],
        ['Application Name', data.appName || ''],
        ['Backup Date', new Date().toLocaleString()]
    ];
    const wsSettings = XLSX.utils.aoa_to_sheet(settingsRows);
    XLSX.utils.book_append_sheet(wb, wsSettings, 'App_Settings');

    XLSX.writeFile(wb, `${fileName}_${new Date().toISOString().split('T')[0]}.xlsx`);
};

export const importFullBackup = (file: File): Promise<FullBackupData> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = XLSX.read(data, { type: 'array' });
                const imported: Partial<FullBackupData> = { 
                    users: [], reports: [], students: [], halaqas: [], evaluations: [] 
                };

                const instSheet = workbook.Sheets['Institutions_List'] || workbook.Sheets['Institutions'] || workbook.Sheets[workbook.SheetNames[0]];
                let parsedUsers: User[] = [];
                if (instSheet) {
                    const rows = XLSX.utils.sheet_to_json(instSheet);
                    parsedUsers = rows.filter((r:any) => r.name || r.Name || r['name of Institution']).map((r: any, index) => {
                        const idValue = r.id || r.Id || r.InstitutionId || (Date.now() + index);
                        return {
                            ...r,
                            id: Number(idValue),
                            name: (r.name || r.Name || r['name of Institution'] || '').toString().trim(),
                            state: (r.state || r.State || r.willayat || '').toString().trim(),
                            role: r.role || UserRole.INSTITUTION,
                            population: {}, 
                            updatedAt: r.updatedAt || Date.now()
                        };
                    });
                }

                // حماية حساب المشرف بـ ID عالي جداً لمنع التداخل مع ID 1 للمؤسسات
                const existingSupervisor = parsedUsers.find(u => u.role === UserRole.SUPERVISOR);
                if (!existingSupervisor) {
                    const defaultSupervisor: User = { 
                        id: 999999, // ID ثابت وعالي جداً
                        name: 'Main Supervisor', 
                        role: UserRole.SUPERVISOR, 
                        updatedAt: Date.now() 
                    };
                    parsedUsers.push(defaultSupervisor);
                }
                imported.users = parsedUsers;

                const popSheet = workbook.Sheets['Population_Data'] || workbook.Sheets['Population'];
                if (popSheet && imported.users) {
                    const popRows = XLSX.utils.sheet_to_json(popSheet);
                    popRows.forEach((row: any) => {
                        const instId = Number(row.InstitutionId || row.institutionId || row.id);
                        const year = Number(row.year || row.Year);
                        const count = Number(row.population || row.Population);
                        const user = imported.users?.find(u => u.id === instId);
                        if (user && !isNaN(year) && !isNaN(count)) {
                            if (!user.population) user.population = {};
                            user.population[year] = count;
                        }
                    });
                }

                const reportSheet = workbook.Sheets['Monthly_Reports'] || workbook.Sheets['Reports'];
                if (reportSheet) {
                    const rows = XLSX.utils.sheet_to_json(reportSheet);
                    imported.reports = rows.map((r: any) => {
                        const report = { ...r };
                        ['id', 'institutionId', 'year', 'month', 'updatedAt'].forEach(k => {
                            if(report[k] !== undefined) report[k] = Number(report[k]);
                        });
                        // استعادة قائمة الحقول المعدلة يدوياً
                        if (typeof report.manuallyEditedFields === 'string') {
                            try { report.manuallyEditedFields = JSON.parse(report.manuallyEditedFields); } catch(e) { report.manuallyEditedFields = []; }
                        }
                        return report as MonthlyReport;
                    });
                }

                if (workbook.Sheets['Auth_Credentials']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['Auth_Credentials'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Main Supervisor') imported.supervisorPassword = String(row[1]);
                        if (row[0] === 'Immunization Dept') imported.immunizationPassword = String(row[1]);
                    });
                }

                if (workbook.Sheets['App_Settings']) {
                    const rows = XLSX.utils.sheet_to_json(workbook.Sheets['App_Settings'], { header: 1 }) as any[][];
                    rows.forEach(row => {
                        if (row[0] === 'Application Name') imported.appName = row[1];
                    });
                }

                resolve(imported as FullBackupData);
            } catch (err) { 
                console.error("Import Error:", err);
                reject(new Error("Error parsing backup file.")); 
            }
        };
        reader.readAsArrayBuffer(file);
    });
};

