const SimpleRichTextEditor: React.FC<{ value: string; onChange: (val: string) => void }> = ({ value, onChange }) => {
    const editorRef = useRef<HTMLDivElement>(null);

    const handleCommand = (command: string, value: string | undefined = undefined) => {
        document.execCommand(command, false, value);
        if (editorRef.current) {
            editorRef.current.focus();
            onChange(editorRef.current.innerHTML);
        }
    };

    const handleInput = () => {
        if (editorRef.current) {
            onChange(editorRef.current.innerHTML);
        }
    };

    useEffect(() => {
        if (editorRef.current && editorRef.current.innerHTML !== value) {
             if (document.activeElement !== editorRef.current) {
                 editorRef.current.innerHTML = value || '';
             }
        }
    }, [value]);

    return (
        <div className="border border-gray-300 dark:border-gray-600 rounded-md overflow-hidden bg-white dark:bg-gray-800 w-full h-full flex flex-col">
            <div className="flex gap-1 bg-gray-100 dark:bg-gray-700 p-1 border-b dark:border-gray-600 no-print">
                <button type="button" onClick={() => handleCommand('bold')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded font-bold" title="Bold">B</button>
                <button type="button" onClick={() => handleCommand('italic')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded italic" title="Italic">I</button>
                <button type="button" onClick={() => handleCommand('underline')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded underline" title="Underline">U</button>
                <div className="w-[1px] bg-gray-300 dark:bg-gray-500 mx-1"></div>
                <button type="button" onClick={() => handleCommand('insertUnorderedList')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded" title="Bullet List">• List</button>
                <button type="button" onClick={() => handleCommand('insertOrderedList')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded" title="Number List">1. List</button>
            </div>
            <div
                ref={editorRef}
                contentEditable
                className="p-2 outline-none flex-grow overflow-y-auto text-left min-h-[100px] text-base text-gray-800 dark:text-gray-200"
                onInput={handleInput}
                onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                        e.stopPropagation();
                    }
                }}
                style={{ direction: 'ltr' }}
            />
        </div>
    );
};

interface MonthlyEntryFormProps {
  institutionId?: number; 
  allowInstitutionSelection?: boolean; 
}

export const MonthlyEntryForm: React.FC<MonthlyEntryFormProps> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { reports, addReport, updateReport, users, setHasUnsavedChanges } = context;
    const [activeInstitutionId, setActiveInstitutionId] = useState<number | undefined>(institutionId);
    const [instSearchTerm, setInstSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [justDeletedId, setJustDeletedId] = useState<number | null>(null);

    useEffect(() => {
        if (!allowInstitutionSelection && institutionId) {
            setActiveInstitutionId(institutionId);
        }
    }, [institutionId, allowInstitutionSelection]);

    const activeInstitution = useMemo(() => users.find(u => u.id === activeInstitutionId), [users, activeInstitutionId]);
    const availableInstitutions = useMemo(() => {
        return users
            .filter(u => u.role === UserRole.INSTITUTION)
            .filter(u => isSmartMatch(u.name, instSearchTerm))
            .sort((a, b) => a.name.localeCompare(b.name, 'en'));
    }, [users, instSearchTerm]);

    const now = new Date();
    const [selectedYear, setSelectedYear] = useState<number>(() => now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(() => now.getMonth() === 0 ? 12 : now.getMonth());

    const [formData, setFormData] = useState<Record<string, string | number>>({});
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [activeTab, setActiveTab] = useState(1);
    const formRef = useRef<HTMLDivElement>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitMessage, setSubmitMessage] = useState<string | null>(null);

    const [hasUserTypedNumber, setHasUserTypedNumber] = useState(false);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [isFormLoaded, setIsFormLoaded] = useState(false);
    const [isPristine, setIsPristine] = useState(true); // New: Blocks initial auto-calculations

    const autoCalculatedFields = useMemo(() => new Set([
        'target_population',
        'tp_bcg', 'tp_hbv1', 'tp_hexa1', 'tp_rota1', 'tp_pcv1',
        'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2',
        'tp_penta1', 'tp_opv2',
        'defaulter_incorrect_address',
        'defaulter_not_found',
        'defaulter_refused',
        'tp_fully_immunized',
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length }, (_, i) => `${g.monthKey}_${i}_target`)),
        ...page2Groups.flatMap(g => Array.from({ length: g.items.length }, (_, i) => `${g.monthKey}_${i}_vaccinated`))
    ]), []);

    const [confirmationModal, setConfirmationModal] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
    }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const currentReport = useMemo(() => {
        if (!activeInstitutionId) return undefined;
        return reports.find(r => r.institutionId === activeInstitutionId && r.year === selectedYear && r.month === selectedMonth);
    }, [reports, activeInstitutionId, selectedYear, selectedMonth]);

    const targetMonth = useMemo(() => {
        const reportingDate = new Date(selectedYear, selectedMonth - 1, 1);
        reportingDate.setMonth(reportingDate.getMonth() - 8);
        return `${MONTHS_AR[reportingDate.getMonth()]} ${reportingDate.getFullYear()}`;
    }, [selectedYear, selectedMonth]);

    const isNavigationBlocked = useMemo(() => hasUserTypedNumber && !formData.recorder_name, [hasUserTypedNumber, formData.recorder_name]);

    useEffect(() => {
        setHasUnsavedChanges(isNavigationBlocked);
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isNavigationBlocked) {
                const message = 'لديك بيانات غير محفوظة. الرجاء إدخال "اسم المُسجل" للحفظ قبل الخروج.';
                e.preventDefault(); e.returnValue = message; return message;
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isNavigationBlocked, setHasUnsavedChanges]);

    useEffect(() => {
        setIsFormLoaded(false);
        setIsPristine(true); // Return to pristine state when loading a report

        if (!activeInstitutionId) {
            setFormData({}); setManuallyEditedFields(new Set()); setHasUserTypedNumber(false); setIsFormLoaded(true);
            return;
        }

        if (justDeletedId && currentReport && currentReport.id === justDeletedId) return;
        if (justDeletedId && (!currentReport || currentReport.id !== justDeletedId)) setJustDeletedId(null);

        if (currentReport) {
            setFormData({
                ...currentReport,
                institution_name: activeInstitution?.name || '',
                target_month: currentReport.targetMonth || targetMonth,
                recorder_name: currentReport.entryPerson,
            });
            // Automatically protect all numeric values from existing report
            const fieldsFromData = new Set<string>(currentReport.manuallyEditedFields || []);
            Object.keys(currentReport).forEach(key => {
                if (typeof currentReport[key] === 'number') fieldsFromData.add(key);
            });
            setManuallyEditedFields(fieldsFromData);
            setHasUserTypedNumber(Object.keys(currentReport).length > 10);
        } else {
            setHasUserTypedNumber(false);
            setManuallyEditedFields(new Set()); 
            setFormData({
                institution_name: activeInstitution?.name || '',
                target_month: targetMonth,
                recorder_name: '',
            });
        }

        setIsFormLoaded(true);
    }, [currentReport, activeInstitution, targetMonth, activeInstitutionId, justDeletedId]);

    const getAllFocusableInputs = useCallback((): Array<HasDataset> => {
        if (!formRef.current) return [];
        const container = document.getElementById(activeTab === 1 ? 'page-1-content' : 'page-2-content');
        if (!container) return [];
        return Array.from(container.querySelectorAll('input[data-local-row]:not([readonly]), textarea[data-local-row]:not([readonly])')) as Array<HasDataset>;
    }, [activeTab]);

    // --- Auto-Calculation Effects (Protected by isPristine) ---

    useEffect(() => {
        if (!isFormLoaded || isPristine || manuallyEditedFields.has('target_population')) return;
        const total = Number(formData.total_on_register || 0);
        const dead = Number(formData.children_died || 0);
        const trans = Number(formData.children_transferred || 0);
        const left = Number(formData.children_left_country || 0);
        const newTarget = Math.max(0, total - dead - trans - left);
        if (formData.target_population !== newTarget) setFormData(prev => ({ ...prev, target_population: newTarget }));
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.children_died, formData.children_transferred, formData.children_left_country, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const total = Number(formData.total_on_register || 0);
        const mainT = Number(formData.target_population || 0);
        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;
            ['tp_bcg', 'tp_hbv1'].forEach(k => {
                if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== total) { updated[k] = total; changed = true; }
            });
            ['tp_hexa1', 'tp_rota1', 'tp_pcv1', 'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2', 'tp_penta1', 'tp_opv2'].forEach(k => {
                if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== mainT) { updated[k] = mainT; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const mainT = Number(formData.target_population || 0);
        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;
            ['defaulter_incorrect_address', 'defaulter_not_found', 'defaulter_refused', 'tp_fully_immunized'].forEach(k => {
                if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== mainT) { updated[k] = mainT; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.target_population, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;
            [{ p: '14m', c: 5 }, { p: '20m', c: 4 }, { p: '26m', c: 2 }].forEach(g => {
                const tSrc = normalizeValueForComparison(prev[`${g.p}_0_target`]);
                const vSrc = normalizeValueForComparison(prev[`${g.p}_0_vaccinated`]);
                for (let i = 1; i < g.c; i++) {
                    const tk = `${g.p}_${i}_target`, vk = `${g.p}_${i}_vaccinated`;
                    if (!manuallyEditedFields.has(tk) && normalizeValueForComparison(updated[tk]) !== tSrc) { updated[tk] = tSrc; changed = true; }
                    if (!manuallyEditedFields.has(vk) && normalizeValueForComparison(updated[vk]) !== vSrc) { updated[vk] = vSrc; changed = true; }
                }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData['14m_0_target'], formData['14m_0_vaccinated'], formData['20m_0_target'], formData['20m_0_vaccinated'], formData['26m_0_target'], formData['26m_0_vaccinated'], manuallyEditedFields]);

    // --- Read-Only Derived Calculations (Stay Reactive) ---

    useEffect(() => {
        if (!isFormLoaded) return;
        const tO = Number(formData.p4_tdap_target_omani_pregnant || 0), tN = Number(formData.p4_tdap_target_non_omani_pregnant || 0);
        const gO = Number(formData.p4_tdap_given_omani_pregnant || 0), gN = Number(formData.p4_tdap_given_non_omani_pregnant || 0);
        setFormData(prev => {
            const updated = {...prev};
            let changed = false;
            if (updated.p4_tdap_target_total_pregnant !== tO + tN) { updated.p4_tdap_target_total_pregnant = tO + tN; changed = true; }
            if (updated.p4_tdap_given_total_pregnant !== gO + gN) { updated.p4_tdap_given_total_pregnant = gO + gN; changed = true; }
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData.p4_tdap_target_omani_pregnant, formData.p4_tdap_target_non_omani_pregnant, formData.p4_tdap_given_omani_pregnant, formData.p4_tdap_given_non_omani_pregnant]);

    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = {...prev};
            let changed = false;
            influenzaCriteria.forEach((_, idx) => {
                const totalT = Number(updated[`p4_flu_target_omani_${idx}`] || 0) + Number(updated[`p4_flu_target_non_omani_${idx}`] || 0);
                const totalG = Number(updated[`p4_flu_given_omani_${idx}`] || 0) + Number(updated[`p4_flu_given_non_omani_${idx}`] || 0);
                if (updated[`p4_flu_target_total_${idx}`] !== totalT) { updated[`p4_flu_target_total_${idx}`] = totalT; changed = true; }
                if (updated[`p4_flu_given_total_${idx}`] !== totalG) { updated[`p4_flu_given_total_${idx}`] = totalG; changed = true; }
                let cov = totalT > 0 ? ((totalG / totalT) * 100).toFixed(1) + '%' : '';
                if (updated[`p4_flu_coverage_${idx}`] !== cov) { updated[`p4_flu_coverage_${idx}`] = cov; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = { ...prev };
            let changed = false;
            usedVialsVaccines.forEach(v => {
                const mono = Number(prev[`p4_used_vials_${v}_0`] || 0), d10 = Number(prev[`p4_used_vials_${v}_1`] || 0), d20 = Number(prev[`p4_used_vials_${v}_2`] || 0);
                const sum = (mono * 1) + (d10 * 10) + (d20 * 20);
                if (sum > 0 && updated[`p4_used_vials_doses_used_${v}`] !== sum) { updated[`p4_used_vials_doses_used_${v}`] = sum; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        setIsPristine(false); // Any interaction breaks the pristine state
        if (autoCalculatedFields.has(name)) setManuallyEditedFields(prev => new Set(prev).add(name));
        if ((e.target as HTMLInputElement).type === 'number' && value.trim() !== '') setHasUserTypedNumber(true);
        setFormData(prev => ({ ...prev, [name]: type === 'number' ? normalizeValueForComparison(value) : value }));
        setSaveStatus('idle');
    };

    useEffect(() => {
        if (justDeletedId) return;
        const timer = setTimeout(() => {
            if (saveStatus === 'idle' && Object.keys(formData).length > 3 && activeInstitutionId && formData.recorder_name) {
                setSaveStatus('saving');
