                    institutionId: activeInstitutionId, year: selectedYear, month: selectedMonth,
                    entryPerson: formData.recorder_name as string || '', updatedAt: Date.now(), targetMonth,
                    ...formData, manuallyEditedFields: Array.from(manuallyEditedFields)
                };
                if (currentReport) { reportToSave.id = currentReport.id; updateReport(reportToSave); }
                else { addReport(reportToSave); }
                setSaveStatus('saved');
            }
        }, 2000);
        return () => clearTimeout(timer);
    }, [formData, saveStatus, currentReport, addReport, updateReport, activeInstitutionId, selectedYear, selectedMonth, targetMonth, justDeletedId, manuallyEditedFields]);

    const handleInputKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const inputs = getAllFocusableInputs();
            const idx = inputs.indexOf(e.target as HasDataset);
            if (idx > -1 && inputs[idx + 1]) (inputs[idx + 1] as HTMLElement).focus();
        }
    }, [getAllFocusableInputs]);

    const handleExportExcel = () => {
        const data = { ...formData, institution_name: activeInstitution?.name, reporting_month: `${MONTHS_AR[selectedMonth - 1]} ${selectedYear}` };
        const ws = XLSX.utils.json_to_sheet([data]);
        const wb = XLSX.utils.book_new();
