        XLSX.writeFile(wb, `EPI_${activeInstitution?.name}_${selectedMonth}_${selectedYear}.xlsx`);
    };

    const handlePrint = () => {
        const createPrintableClone = (sourceId: string) => {
            const source = document.getElementById(sourceId);
            if (!source) return null;
            const clone = source.cloneNode(true) as HTMLElement;
            clone.style.display = 'block'; 
            const sourceInputs = source.querySelectorAll('input, textarea, select');
            const cloneInputs = clone.querySelectorAll('input, textarea, select');
            for(let i=0; i<sourceInputs.length; i++) {
                const s = sourceInputs[i] as HTMLInputElement, c = cloneInputs[i] as HTMLInputElement;
                const span = document.createElement('span'); span.className = 'data-cell-pdf'; span.innerText = s.value;
                if (c.parentNode) c.parentNode.replaceChild(span, c);
            }
            return clone;
        };
        const p1 = createPrintableClone('page-1-content'), p2 = createPrintableClone('page-2-content');
        if (!p1 || !p2) return;
        const win = window.open('', '_blank');
        if (!win) return;
        win.document.write(`
            <!DOCTYPE html><html><head><meta charset="UTF-8"><title>EPI Report</title><link href="https://cdn.tailwindcss.com" rel="stylesheet"><style>
            @page { size: A3 portrait; margin: 1cm; } body { background: white; margin: 0; }
