    if (value === undefined || value === null || value === '') return '';
    const num = Number(value);
    return !isNaN(num) ? num : '';
};

const TdCell: React.FC<{ 
    children?: React.ReactNode, 
    className?: string, 
    colSpan?: number, 
    rowSpan?: number, 
    text?: string 
}> = ({ children, className = '', colSpan, rowSpan, text }) => (
    <td 
        className={`border border-black dark:border-gray-600 p-0.5 text-center align-middle text-base font-medium ${className}`} 
        colSpan={colSpan} 
        rowSpan={rowSpan}
    >
        {children || text}
    </td>
);

const FormInput = React.forwardRef<HTMLInputElement | HTMLTextAreaElement, { 
    type: 'number' | 'text' | 'textarea', 
    name: string, 
    value: any, 
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void, 
    placeholder?: string, 
    'data-local-row': number,
    'data-local-col': number,
    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => void,
    readOnly?: boolean,
    className?: string
}>(({ type, name, value, onChange, placeholder, onKeyDown, readOnly, className = '', ...props }, ref) => {
    const handleFocus = (event: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => event.target.select();

    const commonProps = {
        ref,
        name,
        value: value || '',
        onChange,
        onFocus: handleFocus,
        onKeyDown,
        placeholder: readOnly ? '' : (placeholder || ''),
        readOnly,
        className: `w-full h-full text-center outline-none border-none p-1 focus:bg-yellow-100 dark:focus:bg-yellow-900/50 text-lg font-bold dark:text-gray-200 ${readOnly ? 'bg-gray-100 dark:bg-gray-700' : 'bg-white dark:bg-gray-800'} ${className}`,
        autoComplete: 'off' as const,
        ...props
    };

    if (type === 'textarea') return <textarea {...commonProps} ref={ref as React.Ref<HTMLTextAreaElement>} rows={3} className={`${commonProps.className} resize-y`} />;
    return <input {...commonProps} ref={ref as React.Ref<HTMLInputElement>} type={type} />;
});
FormInput.displayName = 'FormInput';

const SimpleRichTextEditor: React.FC<{ value: string; onChange: (val: string) => void }> = ({ value, onChange }) => {
    const editorRef = useRef<HTMLDivElement>(null);
    const handleCommand = (command: string, val: string | undefined = undefined) => {
        document.execCommand(command, false, val);
        if (editorRef.current) { editorRef.current.focus(); onChange(editorRef.current.innerHTML); }
    };
    const handleInput = () => { if (editorRef.current) onChange(editorRef.current.innerHTML); };
    useEffect(() => {
        if (editorRef.current && editorRef.current.innerHTML !== value) {
             if (document.activeElement !== editorRef.current) editorRef.current.innerHTML = value || '';
        }
    }, [value]);
    return (
        <div className="border border-gray-300 dark:border-gray-600 rounded-md overflow-hidden bg-white dark:bg-gray-800 w-full h-full flex flex-col">
            <div className="flex gap-1 bg-gray-100 dark:bg-gray-700 p-1 border-b dark:border-gray-600 no-print">
                <button type="button" onClick={() => handleCommand('bold')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded font-bold">B</button>
                <button type="button" onClick={() => handleCommand('italic')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded italic">I</button>
                <button type="button" onClick={() => handleCommand('underline')} className="p-1 min-w-[24px] hover:bg-gray-200 dark:hover:bg-gray-600 rounded underline">U</button>
            </div>
            <div
                ref={editorRef} contentEditable
                className="p-2 outline-none flex-grow overflow-y-auto text-left min-h-[100px] text-base text-gray-800 dark:text-gray-200"
                onInput={handleInput} onKeyDown={(e) => { if (e.key === 'Enter') e.stopPropagation(); }}
                style={{ direction: 'ltr' }}
            />
        </div>
    );
};

export const MonthlyEntryForm: React.FC<{ institutionId?: number; allowInstitutionSelection?: boolean; }> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;
    const { reports, addReport, updateReport, users, setHasUnsavedChanges } = context;

    const [activeInstitutionId, setActiveInstitutionId] = useState<number | undefined>(institutionId);
    const [instSearchTerm, setInstSearchTerm] = useState('');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [justDeletedId, setJustDeletedId] = useState<number | null>(null);

    const activeInstitution = useMemo(() => users.find(u => u.id === activeInstitutionId), [users, activeInstitutionId]);
    const availableInstitutions = useMemo(() => users.filter(u => u.role === UserRole.INSTITUTION && isSmartMatch(u.name, instSearchTerm)).sort((a, b) => a.name.localeCompare(b.name, 'en')), [users, instSearchTerm]);

    const now = new Date();
    const [selectedYear, setSelectedYear] = useState<number>(() => now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear());
    const [selectedMonth, setSelectedMonth] = useState<number>(() => now.getMonth() === 0 ? 12 : now.getMonth());

    const [formData, setFormData] = useState<Record<string, string | number>>({});
    const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    const [activeTab, setActiveTab] = useState(1);
    const formRef = useRef<HTMLDivElement>(null);
    const [hasUserTypedNumber, setHasUserTypedNumber] = useState(false);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [isFormLoaded, setIsFormLoaded] = useState(false);
    const [isPristine, setIsPristine] = useState(true);

    const [confirmationModal, setConfirmationModal] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void; }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const currentReport = useMemo(() => activeInstitutionId ? reports.find(r => r.institutionId === activeInstitutionId && r.year === selectedYear && r.month === selectedMonth) : undefined, [reports, activeInstitutionId, selectedYear, selectedMonth]);
    const targetMonthString = useMemo(() => {
        const reportingDate = new Date(selectedYear, selectedMonth - 1, 1);
        reportingDate.setMonth(reportingDate.getMonth() - 8);
        return `${MONTHS_AR[reportingDate.getMonth()]} ${reportingDate.getFullYear()}`;
    }, [selectedYear, selectedMonth]);

    useEffect(() => { setHasUnsavedChanges(hasUserTypedNumber && !formData.recorder_name); }, [hasUserTypedNumber, formData.recorder_name, setHasUnsavedChanges]);

    useEffect(() => {
        setIsFormLoaded(false); setIsPristine(true);
        if (!activeInstitutionId) { setFormData({}); setManuallyEditedFields(new Set()); setHasUserTypedNumber(false); setIsFormLoaded(true); return; }
        if (justDeletedId && currentReport && currentReport.id === justDeletedId) return;

        if (currentReport) {
            setFormData({ ...currentReport, recorder_name: currentReport.entryPerson });
            const fieldsFromData = new Set<string>(currentReport.manuallyEditedFields || []);
            Object.keys(currentReport).forEach(k => { if (typeof currentReport[k] === 'number') fieldsFromData.add(k); });
            setManuallyEditedFields(fieldsFromData); setHasUserTypedNumber(true);
        } else {
            setFormData({ recorder_name: '' }); setManuallyEditedFields(new Set()); setHasUserTypedNumber(false);
        }
        setIsFormLoaded(true);
    }, [currentReport, activeInstitutionId, justDeletedId]);

    // --- المعادلات التلقائية (محمية بـ isPristine) ---

    useEffect(() => {
        if (!isFormLoaded || isPristine || manuallyEditedFields.has('target_population')) return;
        const total = Number(formData.total_on_register || 0);
        const dead = Number(formData.children_died || 0);
        const trans = Number(formData.children_transferred || 0);
        const left = Number(formData.children_left_country || 0);
        const newTarget = Math.max(0, total - dead - trans - left);
        if (formData.target_population !== newTarget) setFormData(prev => ({ ...prev, target_population: newTarget }));
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.children_died, formData.children_transferred, formData.children_left_country, manuallyEditedFields]);

    useEffect(() => {
        if (!isFormLoaded || isPristine) return;
        const total = Number(formData.total_on_register || 0);
        const mainT = Number(formData.target_population || 0);
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            ['tp_bcg', 'tp_hbv1'].forEach(k => { if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== total) { updated[k] = total; changed = true; } });
            ['tp_hexa1', 'tp_rota1', 'tp_pcv1', 'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2', 'tp_penta1', 'tp_opv2'].forEach(k => { if (!manuallyEditedFields.has(k) && Number(updated[k] || 0) !== mainT) { updated[k] = mainT; changed = true; } });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, isPristine, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    // --- حسابات المجاميع والنسب (تظل فعالة آلياً) ---

    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = {...prev}; let changed = false;
            influenzaCriteria.forEach((_, idx) => {
                const totalT = Number(updated[`p4_flu_target_omani_${idx}`] || 0) + Number(updated[`p4_flu_target_non_omani_${idx}`] || 0);
                const totalG = Number(updated[`p4_flu_given_omani_${idx}`] || 0) + Number(updated[`p4_flu_given_non_omani_${idx}`] || 0);
                if (updated[`p4_flu_target_total_${idx}`] !== totalT) { updated[`p4_flu_target_total_${idx}`] = totalT; changed = true; }
                if (updated[`p4_flu_given_total_${idx}`] !== totalG) { updated[`p4_flu_given_total_${idx}`] = totalG; changed = true; }
                const cov = totalT > 0 ? ((totalG / totalT) * 100).toFixed(1) + '%' : '';
                if (updated[`p4_flu_coverage_${idx}`] !== cov) { updated[`p4_flu_coverage_${idx}`] = cov; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    useEffect(() => {
        if (!isFormLoaded) return;
        setFormData(prev => {
            const updated = { ...prev }; let changed = false;
            usedVialsVaccines.forEach(v => {
                const mono = Number(prev[`p4_used_vials_${v}_0`] || 0), d10 = Number(prev[`p4_used_vials_${v}_1`] || 0), d20 = Number(prev[`p4_used_vials_${v}_2`] || 0);
                const sum = (mono * 1) + (d10 * 10) + (d20 * 20);
                if (sum > 0 && updated[`p4_used_vials_doses_used_${v}`] !== sum) { updated[`p4_used_vials_doses_used_${v}`] = sum; changed = true; }
            });
            return changed ? updated : prev;
        });
    }, [isFormLoaded, formData]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        setIsPristine(false);
        if (type === 'number') { setHasUserTypedNumber(true); setManuallyEditedFields(prev => new Set(prev).add(name)); }
        setFormData(prev => ({ ...prev, [name]: type === 'number' ? normalizeValueForComparison(value) : value }));
        setSaveStatus('idle');
    };

    useEffect(() => {
        if (justDeletedId) return;
        const timer = setTimeout(() => {
            if (saveStatus === 'idle' && Object.keys(formData).length > 2 && activeInstitutionId && formData.recorder_name) {
                setSaveStatus('saving');
                const reportToSave: any = {
                    institutionId: activeInstitutionId, year: selectedYear, month: selectedMonth,
                    entryPerson: formData.recorder_name, updatedAt: Date.now(), targetMonth: targetMonthString,
                    ...formData, manuallyEditedFields: Array.from(manuallyEditedFields)
                };
                if (currentReport) { reportToSave.id = currentReport.id; updateReport(reportToSave); }
                else { addReport(reportToSave); }
                setSaveStatus('saved');
            }
        }, 2000);
        return () => clearTimeout(timer);
    }, [formData, saveStatus, currentReport, activeInstitutionId, selectedYear, selectedMonth, targetMonthString, manuallyEditedFields]);

    const handleInputKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const container = document.getElementById(activeTab === 1 ? 'page-1-content' : 'page-2-content');
            const inputs = Array.from(container?.querySelectorAll('input[data-local-row]:not([readonly])') || []);
            const idx = inputs.indexOf(e.target as any);
            if (idx > -1 && inputs[idx+1]) (inputs[idx+1] as HTMLElement).focus();
        }
    }, [activeTab]);

    return (
        <div className="bg-white dark:bg-gray-800 shadow-md flex flex-col rounded-xl overflow-hidden">
            <header className="bg-white dark:bg-gray-900 border-b p-4">
                <div className="flex justify-between items-center">
                    <h1 className="text-xl font-bold dark:text-white">Immunization Data Entry
                        {saveStatus === 'saving' && <span className="text-xs text-blue-500 ml-2 animate-pulse">(Saving...)</span>}
                        {saveStatus === 'saved' && <span className="text-xs text-green-500 ml-2">(Saved)</span>}
                    </h1>
                    <div className="flex gap-2">
                        <select value={selectedMonth} onChange={e => setSelectedMonth(Number(e.target.value))} className="input-style w-32 py-1 font-bold">
                            {MONTHS_AR.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
                        </select>
                        <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="input-style w-24 py-1 font-bold">
                            {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 bg-gray-50 dark:bg-gray-800 overflow-x-auto">
                <div className="flex justify-center mb-6 no-print">
                    <div className="bg-white dark:bg-gray-700 rounded-lg shadow p-1 flex">
                        <button onClick={() => setActiveTab(1)} className={`px-6 py-2 rounded-md font-semibold ${activeTab === 1 ? 'bg-blue-600 text-white' : 'dark:text-gray-200'}`}>Page 1</button>
                        <button onClick={() => setActiveTab(2)} className={`px-6 py-2 rounded-md font-semibold ${activeTab === 2 ? 'bg-blue-600 text-white' : 'dark:text-gray-200'}`}>Page 2</button>
                    </div>
                </div>

                <div ref={formRef} className="bg-white dark:bg-gray-900 p-4 shadow-sm min-w-[1000px]">
                    <div id="page-1-content" style={{ display: activeTab === 1 ? 'block' : 'none' }}>
                        <div className="grid grid-cols-2 gap-8">
                            {/* العمود الأيسر */}
                            <div className="space-y-6">
                                <div className="flex items-center gap-2 bg-amber-50 dark:bg-amber-900/20 border border-black p-2">
                                    <label className="font-bold whitespace-nowrap dark:text-white">Institution:</label>
