                                                <span className="font-bold">{activeInstitution?.name || 'Select...'}</span>
                                            </div>
                                            {isDropdownOpen && (
                                                <div className="absolute z-50 w-full mt-1 bg-white border shadow-lg max-h-40 overflow-auto">
                                                    {availableInstitutions.map(i => <div key={i.id} onClick={() => { setActiveInstitutionId(i.id); setIsDropdownOpen(false); }} className="p-2 hover:bg-gray-100 cursor-pointer font-bold">{i.name}</div>)}
