declare const JSZip: any;

const base64ToBytes = (base64: string): Uint8Array => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

function deduplicateById<T extends { id: number | string; updatedAt?: number; role?: UserRole }>(items: T[]): T[] {
  const map = new Map<number, T>();
  items.forEach((item, index) => {
    let id = Number(item.id);
    if (isNaN(id)) id = Date.now() + index;

    const existing = map.get(id);
    if (!existing) {
        map.set(id, { ...item, id });
    } else {
        if (item.role === UserRole.INSTITUTION && existing.role === UserRole.SUPERVISOR) {
            map.set(id, { ...item, id });
        } else if ((item.updatedAt || 0) >= (existing.updatedAt || 0)) {
            map.set(id, { ...item, id });
        }
    }
  });
  return Array.from(map.values());
}

