                                                    <TdCell colSpan={2}><FormInput type="number" name={`p3_child_${item.key}_gt1_su`} value={formData[`p3_child_${item.key}_gt1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={150+idx} data-local-col={0} /></TdCell>
                                                ) : (
                                                    <>
                                                        <TdCell><FormInput type="number" name={`p3_child_${item.key}_le1_su`} value={formData[`p3_child_${item.key}_le1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={200+idx} data-local-col={0} /></TdCell>
                                                        <TdCell><FormInput type="number" name={`p3_child_${item.key}_gt1_su`} value={formData[`p3_child_${item.key}_gt1_su`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={200+idx} data-local-col={1} /></TdCell>
