                            </table>

                            <table className="w-full border-collapse border border-black bg-white text-sm">
                                <thead><tr className="bg-amber-200 font-bold"><th colSpan={5} className="p-2 text-center text-xl">Used Vials Table</th></tr><tr className="bg-amber-100"><th>Vaccine</th><th>Mono (Doses)</th><th>10 Doses (Vials)</th><th>20 Doses (Vials)</th><th>Total Doses</th></tr></thead>
                                <tbody>
                                    {usedVialsVaccines.map((v, i) => (
                                        <tr key={i}>
                                            <TdCell className="font-bold">{v}</TdCell>
                                            <TdCell><FormInput type="number" name={`p4_used_vials_${v}_0`} value={formData[`p4_used_vials_${v}_0`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={300+i} data-local-col={0} /></TdCell>
                                            <TdCell><FormInput type="number" name={`p4_used_vials_${v}_1`} value={formData[`p4_used_vials_${v}_1`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={300+i} data-local-col={1} /></TdCell>
                                            <TdCell><FormInput type="number" name={`p4_used_vials_${v}_2`} value={formData[`p4_used_vials_${v}_2`] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={300+i} data-local-col={2} /></TdCell>
                                            <TdCell className="bg-gray-100 font-bold">{formData[`p4_used_vials_doses_used_${v}`] || 0}</TdCell>
                                        </tr>
