    if (selectedInstitutionId !== 'all') targetInstitutions = targetInstitutions.filter(u => u.id.toString() === selectedInstitutionId);

    const states = Array.from(new Set(targetInstitutions.map(u => u.state || 'Unspecified'))).sort();
