                          <button key={idx} onClick={() => toggleMonth(idx + 1)} className={`px-2 py-1 rounded text-[10px] font-bold border transition-colors ${selectedMonths.includes(idx + 1) ? 'bg-green-600 text-white border-green-700' : 'bg-white text-gray-600 border-gray-200 dark:bg-gray-800 dark:border-gray-600'}`}>{m.substring(0,3)}</button>
