import React, { useState, useContext, useMemo } from 'react';
import { AppContext } from './App';
import { UserRole } from './types';
import { renderCell } from './utils/exportWord'; 
import { exportToExcel } from './utils/exportExcel'; 
import { exportToWord } from './utils/exportWord'; 

interface CombinedDataItem {
  studentId: number;
  studentName: string;
  halaqaId: number;
  halaqaName: string;
  institutionId: number;
  institutionName: string;
}

export const OverviewTable: React.FC = () => {
  const context = useContext(AppContext);
  if (!context) return null;

  const { students, halaqas, users } = context;

  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: keyof CombinedDataItem; direction: 'ascending' | 'descending' } | null>(null);

  const combinedData = useMemo(() => {
    return (students || []).map(student => {
      const halaqa = halaqas.find(h => h.id === student.halaqaId);
      const institution = halaqa ? users.find(u => u.id === halaqa.institutionId && u.role === UserRole.INSTITUTION) : null;
      return {
        studentId: student.id,
        studentName: student.name,
        halaqaId: halaqa?.id || 0,
        halaqaName: halaqa?.name || 'غير معروف',
        institutionId: institution?.id || 0,
        institutionName: institution?.name || 'غير معين',
      };
    });
  }, [students, halaqas, users]);

  const filteredAndSortedData = useMemo(() => {
    let sortableItems = [...combinedData];
    if (searchTerm.trim()) {
      const searchLower = searchTerm.toLowerCase();
      sortableItems = sortableItems.filter(item =>
        item.studentName.toLowerCase().includes(searchLower) ||
        item.halaqaName.toLowerCase().includes(searchLower) ||
        item.institutionName.toLowerCase().includes(searchLower)
      );
    }
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) return sortConfig.direction === 'ascending' ? -1 : 1;
        if (a[sortConfig.key] > b[sortConfig.key]) return sortConfig.direction === 'ascending' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [combinedData, searchTerm, sortConfig]);

  const requestSort = (key: keyof CombinedDataItem) => {
    let direction: 'ascending' | 'descending' = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-xl dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold text-green-900 dark:text-green-300">نظرة عامة على البيانات</h3>
        <input 
            type="text" 
            placeholder="بحث..." 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            className="input-style w-full max-w-xs py-2 text-sm"
        />
      </div>
      <div className="overflow-x-auto rounded-xl border border-gray-200 dark:border-gray-700">
        <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
          <thead className="bg-gray-50 dark:bg-gray-900">
            <tr>
              {['studentName', 'halaqaName', 'institutionName'].map(key => (
                <th key={key} onClick={() => requestSort(key as keyof CombinedDataItem)} className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase tracking-wider cursor-pointer hover:text-green-600 transition-colors">
                  {key === 'studentName' ? 'اسم الطالب' : key === 'halaqaName' ? 'الحلقة' : 'المؤسسة'}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200 dark:bg-gray-800 dark:divide-gray-700">
            {filteredAndSortedData.map(item => (
              <tr key={item.studentId} className="hover:bg-green-50/30 transition-colors">
                <td className="px-4 py-3 whitespace-nowrap text-sm font-medium text-gray-900 dark:text-white">{item.studentName}</td>
                <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500 dark:text-gray-300">{item.halaqaName}</td>
                <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500 dark:text-gray-300">{item.institutionName}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

