                    .print-header { margin-bottom: 1rem; padding-bottom: 1rem; border-bottom: 2px solid #000; text-align: center; }

                    table { border-collapse: collapse; width: 100%; margin-bottom: 1rem; font-size: 11px; table-layout: auto; }
                    table, th, td { border: 1.5px solid #000; }
                    th { background-color: #f2f2f2 !important; font-weight: bold; text-align: center; padding: 4px; }
                    td { text-align: center; vertical-align: middle; padding: 4px; }

                    .data-cell-pdf { 
                        display: block; 
                        min-height: 1.2em; 
                        font-size: 11px; 
                        padding: 2px;
                        text-align: center;
                        font-weight: 500;
                    }

                    .bg-amber-50 { background-color: #fffbeb !important; }
