type View = 'reports' | 'management' | 'settings' | 'overview' | 'passwords';

const NavButton: React.FC<{
  view: View; 
  label: string; 
  isActive: boolean; 
  onClick: (view: View) => void 
}> = ({view, label, isActive, onClick}) => {
    return (
        <button
          onClick={() => onClick(view)}
          className={`px-4 py-2 text-sm font-bold rounded-lg transition-all whitespace-nowrap ${
              isActive 
              ? 'bg-green-700 text-white shadow-md transform scale-105' 
              : 'bg-white text-gray-700 hover:bg-gray-100 border border-gray-200 dark:bg-gray-700 dark:text-gray-200 dark:border-gray-600 dark:hover:bg-gray-600'
          }`}
        >
            {label}
        </button>
    )
}

export const SupervisorDashboard: React.FC = () => {
  const context = useContext(AppContext);
