    return <div className="dark:text-gray-200 text-center py-20 font-bold">Loading data...</div>;
  }

  return (
    <div>
      {/* Sticky Dashboard Header Section */}
      {/* We use negative margins to pull this header to the edges of the parent 'main' container padding */}
      <div className="sticky top-0 z-30 bg-green-50 dark:bg-slate-950 -mx-4 -mt-4 sm:-mx-6 sm:-mt-6 lg:-mx-8 lg:-mt-8 border-b border-green-200 dark:border-gray-800 shadow-sm no-print mb-8">

        {/* Inner Content Container - matches typical padding but reduced top padding to minimize gap */}
        <div className="px-4 sm:px-6 lg:px-8 py-4 sm:py-5 lg:py-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
            <div>
                <h2 className="text-3xl font-extrabold text-green-900 dark:text-green-400">Supervisor Dashboard</h2>
                <p className="text-base font-medium text-gray-600 dark:text-gray-400">Overview of reports and management.</p>
            </div>
            </div>

            <nav className="flex flex-nowrap overflow-x-auto scrollbar-hidden gap-3 pb-1">
                <NavButton view="reports" label="Primary Reports" isActive={activeView === 'reports'} onClick={setActiveView} />
                <NavButton view="management" label="Management" isActive={activeView === 'management'} onClick={setActiveView} />
                <NavButton view="passwords" label="Passwords" isActive={activeView === 'passwords'} onClick={setActiveView} />
                <NavButton view="settings" label="Settings" isActive={activeView === 'settings'} onClick={setActiveView} />
                <NavButton view="overview" label="Data Overview" isActive={activeView === 'overview'} onClick={setActiveView} />
            </nav>
        </div>
      </div>

      {/* Scrollable Content Area */}
      <div className="space-y-8 pb-12">
        {activeView === 'reports' && (
            <div className="space-y-8 animate-fade-in">
              <div className="no-print">
                <DashboardStats />
              </div>
              <ReportsTable />
            </div>
        )}

        {activeView === 'management' && (
          <div className="animate-fade-in">
            <StudentManagement />
          </div>
        )}

        {activeView === 'passwords' && (
          <div className="animate-fade-in">
            <PasswordManagement />
          </div>
        )}

        {activeView === 'settings' && (
          <div className="animate-fade-in">
            <Settings />
          </div>
        )}

        {activeView === 'overview' && (
          <div className="animate-fade-in">
            <OverviewTable />
          </div>
        )}
      </div>
    </div>
  );
};

