const PasswordManagement: React.FC = () => {
    const context = useContext(AppContext);
    if (!context) return null;

    const { users, updateInstitution, immunizationPassword, setImmunizationPassword } = context;
    const [searchTerm, setSearchTerm] = useState('');
    const [confirmationModal, setConfirmationModal] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: () => void;
    }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

    const institutions = users.filter(u => u.role === UserRole.INSTITUTION);
    const filteredInstitutions = institutions.filter(i => isSmartMatch(i.name, searchTerm));

    const handleResetInstitutionPin = (institution: User) => {
        setConfirmationModal({
            isOpen: true,
            title: 'Reset PIN Confirmation',
            message: `Are you sure you want to reset the PIN for "${institution.name}" to the default "123"?`,
            onConfirm: () => {
                updateInstitution({
                    ...institution,
                    pin: '123',
                    updatedAt: Date.now()
                });
                setConfirmationModal({ isOpen: false, title: '', message: '', onConfirm: () => {} });
            }
        });
    };

    const handleResetImmunizationPassword = () => {
        setConfirmationModal({
            isOpen: true,
            title: 'Reset Password Confirmation',
