    const [month, setMonth] = useState<number>(new Date().getMonth() + 1);

    const [formData, setFormData] = useState<Partial<MonthlyReport>>({});
    const [isFormLoaded, setIsFormLoaded] = useState(false);
    const [lastChangedField, setLastChangedField] = useState<string | null>(null);
    const [manuallyEditedFields, setManuallyEditedFields] = useState<Set<string>>(new Set());
    const [message, setMessage] = useState<{text: string, type: 'success'|'error'} | null>(null);

    // Initialize/Load Data
    useEffect(() => {
        if (!selectedInstitutionId) return;

        setIsFormLoaded(false);
        const existing = reports.find(r => r.institutionId === selectedInstitutionId && r.year === year && r.month === month);

        if (existing) {
            setFormData({ ...existing });
            setManuallyEditedFields(new Set(Object.keys(existing))); // Assume existing data is "manually edited" to prevent auto-fill overwrite on load
        } else {
            setFormData({
                entryPerson: currentUser?.name || '',
            });
            setManuallyEditedFields(new Set());
        }
        setLastChangedField(null);
        // Small timeout to allow state to settle before enabling auto-fill logic
        setTimeout(() => setIsFormLoaded(true), 100);
    }, [selectedInstitutionId, year, month, reports, currentUser]);


    // Auto-fill Vaccine Targets, Defaulters, and Fully Immunized
    useEffect(() => {
        if (!isFormLoaded) return;

        // A. Source: Total on Register (Birth Targets)
        if (lastChangedField === 'total_on_register') {
            const totalOnRegister = normalizeValueForComparison(formData.total_on_register);
            setFormData(prev => {
                const updated = { ...prev };
                let changed = false;
                ['tp_bcg', 'tp_hbv1'].forEach(key => {
                     // Check manual edit flag as backup, but the primary guard is lastChangedField
                    if (!manuallyEditedFields.has(key) && normalizeValueForComparison(updated[key]) !== totalOnRegister) {
                        updated[key] = totalOnRegister;
                        changed = true;
                    }
                });
                return changed ? updated : prev;
            });
        }

        // B. Source: Target Population (Vaccines + Defaulters + Fully Immunized)
        if (lastChangedField === 'target_population') {
            const mainTarget = normalizeValueForComparison(formData.target_population);
            setFormData(prev => {
                const updated = { ...prev };
                let changed = false;

                const keysToSync = [
                    // Vaccines
                    'tp_hexa1', 'tp_rota1', 'tp_pcv1',
                    'tp_hexa2', 'tp_rota2', 'tp_opv1', 'tp_pcv2',
                    'tp_penta1', 'tp_opv2',
                    // Defaulters
                    'defaulter_incorrect_address',
                    'defaulter_not_found',
                    'defaulter_refused',
                    // Fully Immunized
                    'tp_fully_immunized'
                ];

                keysToSync.forEach(key => {
                    if (!manuallyEditedFields.has(key) && normalizeValueForComparison(updated[key]) !== mainTarget) {
                        updated[key] = mainTarget;
                        changed = true;
                    }
                });
                return changed ? updated : prev;
            });
        }
    }, [isFormLoaded, lastChangedField, formData.total_on_register, formData.target_population, manuallyEditedFields]);

    const handleChange = (key: string, val: string) => {
        const numVal = val === '' ? '' : Number(val);
        setFormData(prev => ({ ...prev, [key]: numVal }));
        setLastChangedField(key);
        setManuallyEditedFields(prev => new Set(prev).add(key));
    };

    const handleSave = () => {
        if (!selectedInstitutionId) {
            setMessage({ text: 'Please select an institution', type: 'error' });
            return;
        }

        const reportToSave: MonthlyReport = {
            id: formData.id || Date.now(),
            institutionId: Number(selectedInstitutionId),
            year,
            month,
            entryPerson: formData.entryPerson || '',
            updatedAt: Date.now(),
            ...formData
        };

        if (formData.id) {
            updateReport(reportToSave);
            setMessage({ text: 'Report updated successfully', type: 'success' });
        } else {
            addReport(reportToSave);
            setMessage({ text: 'Report created successfully', type: 'success' });
        }

        setTimeout(() => setMessage(null), 3000);
    };

    return (
       <div className="bg-white p-6 rounded-2xl shadow-lg dark:bg-gray-800 animate-fade-in">
          {/* Header Controls */}
          <div className="flex flex-col sm:flex-row gap-4 mb-6">
             <div className="flex-1">
                <label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Year</label>
                <select value={year} onChange={e => setYear(Number(e.target.value))} className="input-style">
                   {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
             </div>
             <div className="flex-1">
                <label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Month</label>
                <select value={month} onChange={e => setMonth(Number(e.target.value))} className="input-style">
                   {MONTHS_AR.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
                </select>
             </div>
             {allowInstitutionSelection && (
                 <div className="flex-[2]">
                    <label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Institution</label>
                    <select value={selectedInstitutionId} onChange={e => setSelectedInstitutionId(Number(e.target.value))} className="input-style">
                        <option value="">Select...</option>
                        {users.filter(u => u.role === UserRole.INSTITUTION).map(u => (
                            <option key={u.id} value={u.id}>{u.name}</option>
                        ))}
                    </select>
                 </div>
             )}
          </div>

          {message && <div className={`p-3 mb-4 rounded-lg text-sm font-bold ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>{message.text}</div>}

          {/* Form Content */}
          {selectedInstitutionId ? (
              <div className="space-y-8">
                  <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">Targets</h4>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                          <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Total on Register</label><input type="number" value={formData.total_on_register || ''} onChange={e => handleChange('total_on_register', e.target.value)} className="input-style" /></div>
                          <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Target Population</label><input type="number" value={formData.target_population || ''} onChange={e => handleChange('target_population', e.target.value)} className="input-style" /></div>
                      </div>
                  </div>

                  <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">Main EPI Vaccines</h4>
                      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-5 gap-3">
                          {['tp_bcg', 'tp_opv1', 'tp_opv2', 'tp_hexa1', 'tp_hexa2', 'tp_penta1', 'tp_pcv1', 'tp_rota1', 'tp_rota2', 'tp_pcv2'].map(k => (
                              <div key={k}><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400 uppercase">{k.replace('tp_', '')}</label><input type="number" value={formData[k] || ''} onChange={e => handleChange(k, e.target.value)} className="input-style" /></div>
                          ))}
                      </div>
                  </div>

                  <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">14 Months</h4>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                         {['14m_0_target', '14m_1_vaccinated', '14m_0_vaccinated', '14m_2_vaccinated'].map(k => (
                             <div key={k}><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">{k.replace(/_/g, ' ')}</label><input type="number" value={formData[k] || ''} onChange={e => handleChange(k, e.target.value)} className="input-style" /></div>
                         ))}
                         {['14m_3_target', '14m_3_vaccinated', '14m_4_vaccinated'].map(k => (
                             <div key={k}><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">{k.replace(/_/g, ' ')}</label><input type="number" value={formData[k] || ''} onChange={e => handleChange(k, e.target.value)} className="input-style" /></div>
                         ))}
                      </div>
                  </div>

                  <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">20 & 26 Months</h4>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                         {['20m_0_target', '20m_0_vaccinated', '20m_3_vaccinated', '20m_2_vaccinated', '20m_1_vaccinated'].map(k => (
                             <div key={k}><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">{k.replace(/_/g, ' ')}</label><input type="number" value={formData[k] || ''} onChange={e => handleChange(k, e.target.value)} className="input-style" /></div>
                         ))}
                         {['26m_0_target', '26m_1_vaccinated', '26m_0_vaccinated'].map(k => (
                             <div key={k}><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">{k.replace(/_/g, ' ')}</label><input type="number" value={formData[k] || ''} onChange={e => handleChange(k, e.target.value)} className="input-style" /></div>
                         ))}
                      </div>
                  </div>

                  {/* Influenza Section */}
                   <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">Influenza</h4>
                      <div className="overflow-x-auto">
                        <table className="min-w-full text-xs">
                           <thead>
                              <tr>
                                 <th className="text-left dark:text-gray-300">Category</th>
                                 <th className="text-left dark:text-gray-300">Target (Omani)</th><th className="text-left dark:text-gray-300">Target (Non-Omani)</th>
                                 <th className="text-left dark:text-gray-300">Given (Omani)</th><th className="text-left dark:text-gray-300">Given (Non-Omani)</th>
                              </tr>
                           </thead>
                           <tbody>
                              {influenzaCriteria.map((cat, idx) => (
                                 <tr key={idx}>
                                    <td className="font-bold p-1 dark:text-gray-300">{cat}</td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_flu_target_omani_${idx}`] || ''} onChange={e => handleChange(`p4_flu_target_omani_${idx}`, e.target.value)} /></td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_flu_target_non_omani_${idx}`] || ''} onChange={e => handleChange(`p4_flu_target_non_omani_${idx}`, e.target.value)} /></td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_flu_given_omani_${idx}`] || ''} onChange={e => handleChange(`p4_flu_given_omani_${idx}`, e.target.value)} /></td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_flu_given_non_omani_${idx}`] || ''} onChange={e => handleChange(`p4_flu_given_non_omani_${idx}`, e.target.value)} /></td>
                                 </tr>
                              ))}
                           </tbody>
                        </table>
                      </div>
                  </div>

                  {/* Tdap Section */}
                   <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">Tdap (Pregnant)</h4>
                      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                         <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Target Omani</label><input type="number" value={formData.p4_tdap_target_omani_pregnant || ''} onChange={e => handleChange('p4_tdap_target_omani_pregnant', e.target.value)} className="input-style" /></div>
                         <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Target Non-Omani</label><input type="number" value={formData.p4_tdap_target_non_omani_pregnant || ''} onChange={e => handleChange('p4_tdap_target_non_omani_pregnant', e.target.value)} className="input-style" /></div>
                         <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Given Omani</label><input type="number" value={formData.p4_tdap_given_omani_pregnant || ''} onChange={e => handleChange('p4_tdap_given_omani_pregnant', e.target.value)} className="input-style" /></div>
                         <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Given Non-Omani</label><input type="number" value={formData.p4_tdap_given_non_omani_pregnant || ''} onChange={e => handleChange('p4_tdap_given_non_omani_pregnant', e.target.value)} className="input-style" /></div>
                         <div><label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Pregnant Col1</label><input type="number" value={formData.p4_tdap_pregnant_col1 || ''} onChange={e => handleChange('p4_tdap_pregnant_col1', e.target.value)} className="input-style" /></div>
                      </div>
                  </div>

                  {/* Other Vaccines Section */}
                   <div className="bg-gray-50 p-4 rounded-xl dark:bg-gray-700/50">
                      <h4 className="font-bold text-green-800 dark:text-green-300 mb-3 border-b dark:border-gray-600 pb-2">Other Vaccines</h4>
                       <div className="overflow-x-auto">
                        <table className="min-w-full text-xs">
                           <thead>
                              <tr>
                                 <th className="text-left dark:text-gray-300">Vaccine</th>
                                 <th className="text-left dark:text-gray-300">Admin</th><th className="text-left dark:text-gray-300">Usable</th><th className="text-left dark:text-gray-300">Doses</th>
                              </tr>
                           </thead>
                           <tbody>
                              {otherEpiKeys.map((key) => (
                                 <tr key={key}>
                                    <td className="font-bold p-1 capitalize dark:text-gray-300">{key.replace(/_/g, ' ')}</td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_other_${key}_admin`] || ''} onChange={e => handleChange(`p4_other_${key}_admin`, e.target.value)} /></td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_other_${key}_usable`] || ''} onChange={e => handleChange(`p4_other_${key}_usable`, e.target.value)} /></td>
                                    <td className="p-1"><input type="number" className="input-style w-20" value={formData[`p4_other_${key}_doses`] || ''} onChange={e => handleChange(`p4_other_${key}_doses`, e.target.value)} /></td>
                                 </tr>
                              ))}
                           </tbody>
                        </table>
                      </div>
                  </div>

                  <div>
                     <label className="block text-xs font-bold text-gray-500 mb-1 dark:text-gray-400">Recorder Name</label>
                     <input type="text" value={formData.entryPerson || ''} onChange={e => { setFormData(p => ({...p, entryPerson: e.target.value})); setLastChangedField('entryPerson'); }} className="input-style" />
                  </div>

                  <button onClick={handleSave} className="w-full py-4 bg-green-700 text-white font-bold rounded-xl shadow-lg hover:bg-green-800 transition-all">Save Report</button>
              </div>
          ) : (
             <div className="text-center py-10 text-gray-500 dark:text-gray-400">Please select an institution to start.</div>
          )}
       </div>
    );
};

