<content>< ![CDATA[import React, { useState, useContext, useEffect, useMemo, useRef , useCallback } from 'react';
import { AppContext } from '../App';
import { MONTHS_AR }  from '../constants';
import { MonthlyReport, UserRole } from '../types';
