import React, { useState, useContext, useEffect } from 'react';
import { AppContext } from '../App';
import { UserRole, MonthlyReport } from '../types';
import { MONTHS_AR } from '../constants';

interface MonthlyEntryFormProps {
    institutionId?: number;
    allowInstitutionSelection?: boolean;
}

const TdCell: React.FC<React.TdHTMLAttributes<HTMLTableCellElement>> = ({ className, children, ...props }) => (
    <td className={`border border-gray-400 p-1 text-center ${className || ''}`} {...props}>
        {children}
    </td>
);

const FormInput: React.FC<React.InputHTMLAttributes<HTMLInputElement>> = ({ className, ...props }) => (
    <input
        className={`w-full h-full bg-transparent text-center focus:outline-none focus:bg-yellow-100 transition-colors p-1 text-sm ${className || ''}`}
        {...props}
    />
);

export const MonthlyEntryForm: React.FC<MonthlyEntryFormProps> = ({ institutionId, allowInstitutionSelection = false }) => {
    const context = useContext(AppContext);
    if (!context) return null;
    const { users, reports, addReport, updateReport } = context;

    const [selectedInstId, setSelectedInstId] = useState<number>(institutionId || 0);
    const [year, setYear] = useState<number>(new Date().getFullYear());
    const [month, setMonth] = useState<number>(new Date().getMonth() + 1);
    const [formData, setFormData] = useState<Partial<MonthlyReport>>({});
    const [saveMessage, setSaveMessage] = useState<{ text: string; type: 'success' | 'error' } | null>(null);

    // Initialize selectedInstId if not provided but only one available or default
    useEffect(() => {
        if (!institutionId && allowInstitutionSelection) {
             const insts = users.filter(u => u.role === UserRole.INSTITUTION);
             if (insts.length > 0 && selectedInstId === 0) setSelectedInstId(insts[0].id);
        } else if (institutionId) {
            setSelectedInstId(institutionId);
        }
    }, [institutionId, allowInstitutionSelection, users]);

    // Load existing data
    useEffect(() => {
        if (!selectedInstId) return;
        const existingReport = reports.find(r => r.institutionId === selectedInstId && r.year === year && r.month === month);
        if (existingReport) {
            setFormData(existingReport);
        } else {
            setFormData({});
        }
    }, [selectedInstId, year, month, reports]);

    // Update target population based on institution settings
    useEffect(() => {
        if (!selectedInstId) return;
        const inst = users.find(u => u.id === selectedInstId);
        if (inst && inst.population && inst.population[year]) {
            setFormData(prev => ({ ...prev, target_population: inst.population![year] }));
        }
    }, [selectedInstId, year, users]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value, type } = e.target;
        const val = type === 'number' ? (value === '' ? 0 : Number(value)) : value;
        setFormData(prev => ({ ...prev, [name]: val }));
    };

    const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        // Placeholder for grid navigation logic
    };

    const handleSave = () => {
        if (!selectedInstId) {
            setSaveMessage({ text: 'Please select an institution.', type: 'error' });
            return;
        }

        const reportToSave = {
            ...formData,
            institutionId: selectedInstId,
            year,
            month,
            entryPerson: formData.entryPerson || 'Unknown', 
            updatedAt: Date.now()
        } as MonthlyReport;

        if (formData.id) {
            updateReport(reportToSave);
        } else {
            addReport(reportToSave);
        }
        setSaveMessage({ text: 'Report saved successfully!', type: 'success' });
        setTimeout(() => setSaveMessage(null), 3000);
    };

    const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

    const influenzaCriteria = [
        'Pregnant', 'Pilgrims/Umrah', 'Elderly', "HCW's", 'DM', 'HTN', 'Asthma', 
        'Children 24 months', 'Immunocompromised', 'Others'
    ];

    const otherEpiKeys = [
        'yellow_fever', 'typhoid_20', 'typhoid_mono', 'meningococcal', 
        'rabies_300', 'rabies_750', 'anti_rabies', 'hepb_adult', 'ppd', 
        'ipv', 'mmr', 'varicella', 'tdap', 'others'
    ];
    const otherEpiLabels = [
        'Yellow Fever', 'Typhoid (20 doses)', 'Typhoid (Mono)', 'Meningococcal', 
        'Rabies (300 IU)', 'Rabies (750 IU)', 'Anti-Rabies', 'Hep-B Adult', 'PPD', 
        'IPV', 'MMR', 'Varicella', 'Tdap', 'Others'
    ];

    if (!context) return <div>Loading...</div>;

    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg dark:bg-gray-800 border border-gray-100 dark:border-gray-700">
            <div className="flex flex-col md:flex-row gap-4 mb-6 items-end no-print">
                {allowInstitutionSelection && (
                    <div className="flex-1">
                        <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">Institution</label>
                        <select value={selectedInstId} onChange={e => setSelectedInstId(Number(e.target.value))} className="input-style">
                            {institutions.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                        </select>
                    </div>
                )}
                <div className="w-32">
                    <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">Year</label>
                    <select value={year} onChange={e => setYear(Number(e.target.value))} className="input-style">
                        {[2023, 2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                </div>
                <div className="w-32">
                    <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">Month</label>
                    <select value={month} onChange={e => setMonth(Number(e.target.value))} className="input-style">
                        {MONTHS_AR.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
                    </select>
                </div>
                 <div className="flex-1">
                    <label className="block text-sm font-bold text-gray-700 dark:text-gray-200 mb-1">Name of Recorder</label>
                    <input type="text" name="entryPerson" value={formData.entryPerson || ''} onChange={handleInputChange} className="input-style" placeholder="Your Name" />
                </div>
                <button onClick={handleSave} className="px-6 py-2.5 bg-green-600 text-white font-bold rounded-xl shadow-md hover:bg-green-700 transition-all">Save Report</button>
            </div>

            {saveMessage && (
                <div className={`p-4 mb-4 rounded-lg font-bold text-center ${saveMessage.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                    {saveMessage.text}
                </div>
            )}

            <div className="overflow-x-auto">
                {/* Main EPI Table */}
                <h3 className="text-lg font-bold text-green-800 dark:text-green-300 mb-2 mt-4">Main EPI Report</h3>
                <table className="min-w-full border-collapse border border-gray-400 text-xs">
                    <tbody>
                         {/* Row 1: Target Population */}
                        <tr>
                            <TdCell colSpan={2} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 text-left text-base">
                                TARGET POPULATION
                            </TdCell>
                            <TdCell className="bg-white dark:bg-gray-800">
                                <FormInput 
                                    type="number" 
                                    name="target_population" 
                                    value={formData.target_population || ''} 
                                    onChange={handleInputChange} 
                                    onKeyDown={handleInputKeyDown} 
                                    readOnly={true}
                                    className="bg-gray-200 dark:bg-gray-700 font-bold text-black dark:text-white pointer-events-none"
                                />
                            </TdCell>
                        </tr>
                        {/* Row 2: Total on Register */}
                        <tr>
                            <TdCell colSpan={2} className="bg-blue-100 dark:bg-blue-900/50 font-bold text-black dark:text-gray-200 text-left">
                                Total on Register
                            </TdCell>
                            <TdCell className="bg-white dark:bg-gray-800">
                                <FormInput type="number" name="total_on_register" value={formData.total_on_register || ''} onChange={handleInputChange} />
                            </TdCell>
                        </tr>

                        {/* Vaccine Rows */}
                        {[
                            { label: 'BCG', key: 'tp_bcg' },
                            { label: 'OPV 1', key: 'tp_opv1' },
                            { label: 'OPV 2', key: 'tp_opv2' },
                            { label: 'Hexa 1', key: 'tp_hexa1' },
                            { label: 'Hexa 2', key: 'tp_hexa2' },
                            { label: 'Penta 1', key: 'tp_penta1' },
                            { label: 'PCV 1', key: 'tp_pcv1' },
                            { label: 'Rota 1', key: 'tp_rota1' },
                            { label: 'Rota 2', key: 'tp_rota2' },
                            { label: 'PCV 2', key: 'tp_pcv2' },
                        ].map(item => (
                            <tr key={item.key}>
                                <TdCell colSpan={2} className="text-left font-medium bg-gray-50 dark:bg-gray-700">{item.label}</TdCell>
                                <TdCell><FormInput type="number" name={item.key} value={formData[item.key] || ''} onChange={handleInputChange} /></TdCell>
                            </tr>
                        ))}

                        {/* 14 Months Section */}
                         <tr><TdCell colSpan={3} className="bg-gray-200 dark:bg-gray-600 h-2"></TdCell></tr>
                         <tr>
                            <TdCell rowSpan={3} className="bg-purple-100 dark:bg-purple-900/30 font-bold align-middle">14 Months</TdCell>
                            <TdCell className="text-left">MMR1 Target</TdCell>
                            <TdCell><FormInput type="number" name="14m_0_target" value={formData['14m_0_target'] || ''} onChange={handleInputChange} /></TdCell>
                        </tr>
                        <tr>
                            <TdCell className="text-left">Varicella</TdCell>
                            <TdCell><FormInput type="number" name="14m_1_vaccinated" value={formData['14m_1_vaccinated'] || ''} onChange={handleInputChange} /></TdCell>
                        </tr>
                        <tr>
                            <TdCell className="text-left">MMR 1 (Given)</TdCell>
                            <TdCell><FormInput type="number" name="14m_0_vaccinated" value={formData['14m_0_vaccinated'] || ''} onChange={handleInputChange} /></TdCell>
                        </tr>
                        <tr>
                             <TdCell rowSpan={1} className="bg-purple-100 dark:bg-purple-900/30 font-bold align-middle"></TdCell>
                             <TdCell className="text-left">Vit A1</TdCell>
                             <TdCell><FormInput type="number" name="14m_2_vaccinated" value={formData['14m_2_vaccinated'] || ''} onChange={handleInputChange} /></TdCell>
                        </tr>

                        {/* PCV/Penta Booster Section */}
                        <tr><TdCell colSpan={3} className="bg-gray-200 dark:bg-gray-600 h-2"></TdCell></tr>
                        <tr>
                            <TdCell rowSpan={3} className="bg-indigo-100 dark:bg-indigo-900/30 font-bold align-middle">Booster 1</TdCell>
                            <TdCell className="text-left">PCV Target</TdCell>
                            <TdCell><FormInput type="number" name="14m_3_target" value={formData['14m_3_target'] || ''} onChange={handleInputChange} /></TdCell>
                        </tr>
                        <tr>
                            <TdCell className="text-left">PCV Booster</TdCell>
                            <TdCell><FormInput type="number" name="14m_3_vaccinated" value={formData['14m_3_vaccinated'] || ''} onChange={handleInputChange} /></TdCell>
