                        <button 
                            type="button"
                            onClick={handleSubmitReport} 
                            disabled={isSubmitting || (!activeInstitutionId && allowInstitutionSelection)} 
                            className="bg-green-700 text-white px-8 py-3 rounded shadow-lg font-bold hover:bg-green-800 disabled:bg-gray-400 disabled:cursor-not-allowed flex-1 sm:flex-none"
                        >
                            {isSubmitting ? 'Saving...' : (currentReport ? 'Update Data' : 'Save New Data')}
                        </button>

                        <button 
                            type="button"
                            onClick={handleExportExcel} 
                            disabled={!activeInstitutionId && allowInstitutionSelection}
                            className="bg-blue-600 text-white px-5 py-3 rounded shadow-md hover:bg-blue-700 flex-1 sm:flex-none disabled:bg-gray-400 disabled:cursor-not-allowed"
                        >
                            Excel
                        </button>

                        <button 
                            type="button"
                            onClick={handlePrint}
