        if (!window.confirm('Are you sure you want to save/update this report?')) return;

        setIsSubmitting(true);
        setSubmitMessage('Saving report...');

        if (currentReport) {
            const reportToSave: MonthlyReport = {
                id: currentReport.id,
                institutionId: activeInstitutionId!,
                year: selectedYear,
                month: selectedMonth,
                entryPerson: formData.recorder_name as string,
                updatedAt: Date.now(),
                targetMonth,
                ...formData,
                manuallyEditedFields: Array.from(manuallyEditedFields)
            };
            updateReport(reportToSave);
        } else {
            const reportToSave: Omit<MonthlyReport, 'id' | 'updatedAt'> = {
                institutionId: activeInstitutionId!,
                year: selectedYear,
                month: selectedMonth,
                entryPerson: formData.recorder_name as string,
                targetMonth,
                ...formData,
                manuallyEditedFields: Array.from(manuallyEditedFields)
            };
            addReport(reportToSave);
        }

        setTimeout(() => {
            setIsSubmitting(false);
            setSubmitMessage('Saved successfully!');
            setTimeout(() => setSubmitMessage(null), 3000);
        }, 1000);
