export const initializeFirebase = async (firebaseConfig: any) => { // Made async to ensure returns Promise and catches sync errors
  // Safe check for global firebase object
  if (typeof firebase === 'undefined') {
      console.warn("Firebase SDK not loaded.");
      throw new Error("Firebase SDK not loaded. Please check your internet connection.");
  }

  // Ensure we have a valid config to attempt initialization
  if (!firebaseConfig || !firebaseConfig.apiKey) {
      throw new Error("Firebase configuration is incomplete. Cannot connect.");
  }

  try {
    // If an app is already initialized, delete it to re-initialize with new config
    if (firebase.apps && firebase.apps.length > 0) {
      const existingApp = firebase.app();
      // Only delete if the existing app's config is different to avoid unnecessary disconnections
      // (simple check by apiKey as a proxy)
      if (existingApp.options.apiKey !== firebaseConfig.apiKey) {
          await existingApp.delete();
          console.log("Existing Firebase app deleted due to config change. Re-initializing...");
          app = firebase.initializeApp(firebaseConfig);
          db = firebase.database();
          return { db, app };
      } else {
          // If config is the same, just return existing instances
          db = firebase.database(); // Ensure db is set if app already existed but db was null
          return { db: firebase.database(), app: existingApp };
      }
    }

    app = firebase.initializeApp(firebaseConfig);
    db = firebase.database();
    return { db, app };

  } catch (error) {
    console.error("Firebase initialization error:", error);
    db = null;
    app = null;
    throw new Error("Firebase initialization failed. Please check the configuration data.");
  }
};

export const getDb = () => {
  if (!db) {
    // This can happen if the app tries to access db before config is set.
    // The UI should ideally prevent this, but this is a safeguard.
    // console.warn("Firebase DB not initialized.");
    return null;
  }
  return db;
};

export const disconnectFirebase = async () => {
    if (app) {
        try {
            await app.delete();
            db = null;
            app = null;
            console.log("Firebase app disconnected.");
        } catch(e) {
            console.error("Error disconnecting firebase:", e);
        }
    }
};

