// الحصول على مرجع لقاعدة البيانات
const database = firebase.database();

// مثال على إضافة بيانات
function addData() {
  const newData = {
    username: "user1",
    email: "user1@example.com",
    message: "مرحبًا، هذا اختبار!"
  };

  // إضافة البيانات إلى قاعدة البيانات بشكل غير متزامن
  database.ref('messages/').push(newData)
    .then(() => {
      console.log("تم إضافة البيانات بنجاح!");
    })
    .catch((error) => {
      console.error("حدث خطأ: " + error);
    });
}

