  maghribAttendances: MaghribAttendance[];
  addMaghribAttendance: (att: any) => void;
  deleteMaghribAttendance: (id: number) => void;
  maghribPassword: string;
  setMaghribPassword: (p: string) => void;

  immunizationPassword: string;
  setImmunizationPassword: (p: string) => void;

  setHasUnsavedChanges: (hasChanges: boolean) => void;
}

export const AppContext = createContext<AppContextType | null>(null);

const THEME_KEY = 'halaqaTheme_v2';
// Updated key to force refresh of local config and ensure new Firebase URL is used
const LOCAL_STORAGE_DATA_KEY = 'halaqaAppData_local_cache_v3';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
      try {
          const savedUser = localStorage.getItem(CURRENT_USER_KEY);
          if (!savedUser) return null;
          const user = JSON.parse(savedUser);
          return { ...user, id: Number(user.id) }; 
      } catch (e) { return null; }
  });

  const [data, setData] = useState<{
    users: User[];
    reports: MonthlyReport[];
    students: Student[];
    halaqas: Halaqa[];
    evaluations: Evaluation[];
    maghribAttendances: MaghribAttendance[];
    deletedItems: DeletedItem[];
  }>({ 
    users: INITIAL_USERS.map(u => ({ ...u, id: Number(u.id) })), 
    reports: [], 
    students: [], 
    halaqas: [], 
    evaluations: [], 
    maghribAttendances: [],
    deletedItems: [] 
  });

  const [supervisorPassword, setSupervisorPasswordState] = useState<string>('123');
  const [maghribPassword, setMaghribPasswordState] = useState<string>('123456');
  const [immunizationPassword, setImmunizationPasswordState] = useState<string>('12345');
  const [customLogo, setCustomLogoState] = useState<string | null>(null);
  const [appName, setAppNameState] = useState<string>(DEFAULT_APP_NAME);

  const [darkMode, setDarkMode] = useState<boolean>(() => {
    const saved = localStorage.getItem(THEME_KEY);
    return saved === 'dark';
  });

  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting'>('disconnected');
  const [isDistributable, setIsDistributable] = useState(false);
  const [isPublishedConnected, setIsPublishedConnected] = useState(false);

  const [showHelpModal, setShowHelpModal] = useState(false);
  const [showMobileInstallModal, setShowMobileInstallModal] = useState(false);
  const [showChangePasswordModal, setShowChangePasswordModal] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  useEffect(() => {
    const root = window.document.documentElement;
    if (darkMode) {
      root.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      root.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [darkMode]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    let loadedConfig: FullBackupData | null = null;

    if ((window as any).compressedEmbeddedAppData) {
      try {
        const compressedBytes = base64ToBytes((window as any).compressedEmbeddedAppData);
        const zip = await JSZip.loadAsync(compressedBytes);
        const file = zip.file("data.json");
        if (file) {
          const jsonString = await file.async('string');
          loadedConfig = JSON.parse(jsonString);
        }
      } catch (e) { console.error(e); }
    } else if ((window as any).embeddedAppData) {
       try {
           loadedConfig = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob((window as any).embeddedAppData), c => c.charCodeAt(0))));
       } catch(e) { console.error(e); }
    }

    if (!loadedConfig) {
        const localData = localStorage.getItem(LOCAL_STORAGE_DATA_KEY);
        if (localData) { try { loadedConfig = JSON.parse(localData); } catch (e) {} }
    }

    if (loadedConfig) {
      setData({
        users: deduplicateById((loadedConfig.users || INITIAL_USERS).map(u => ({ ...u, id: Number(u.id) }))),
        reports: deduplicateById((loadedConfig.reports || []).map(r => ({ ...r, id: Number(r.id), institutionId: Number(r.institutionId) }))),
        students: [],
        halaqas: [],
        evaluations: [],
        maghribAttendances: [],
        deletedItems: loadedConfig.deletedItems || [],
      });
      setAppNameState(loadedConfig.appName || DEFAULT_APP_NAME);
      setCustomLogoState(loadedConfig.customLogo || null);
      setSupervisorPasswordState(loadedConfig.supervisorPassword || '123');
      setImmunizationPasswordState(loadedConfig.immunizationPassword || '12345');

      if (loadedConfig.isDistributable) {
          setIsDistributable(true);
          setIsPublishedConnected(!!loadedConfig.isPublishedConnected);
          setFirebaseConfigState(loadedConfig.firebaseConfig || null);
      } else {
          // FORCE hardcoded config for standard app to prevent stale config from localStorage
          setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
      }
    } else {
        setFirebaseConfigState(HARDCODED_FIREBASE_CONFIG);
    }
    setIsLoading(false);
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!isLoading) {
        const dataToSave: FullBackupData = {
            users: data.users, 
            reports: data.reports,
            students: [],
            halaqas: [],
            evaluations: [],
            customLogo, supervisorPassword, immunizationPassword, appName,
            isDistributable, isPublishedConnected, firebaseConfig: firebaseConfigState
        };
        localStorage.setItem(LOCAL_STORAGE_DATA_KEY, JSON.stringify(dataToSave));
    }
  }, [data, appName, customLogo, supervisorPassword, immunizationPassword, firebaseConfigState, isDistributable, isPublishedConnected, isLoading]);

  useEffect(() => {
    if (!firebaseConfigState) {
        setFirebaseConnectionStatus('disconnected');
        return;
    }

    setFirebaseConnectionStatus('connecting');
    initializeFirebase(firebaseConfigState).then(firebaseInstance => {
        const db = firebaseInstance.db;
        db.ref('data').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            setData(prev => ({
              ...prev,
              users: val.users ? deduplicateById(Object.values(val.users).map((u:any) => ({...u, id: Number(u.id)}))) : INITIAL_USERS.map(u => ({ ...u, id: Number(u.id) })),
              reports: val.reports ? deduplicateById(Object.values(val.reports).map((r:any) => ({...r, id: Number(r.id), institutionId: Number(r.institutionId)}))) : [],
            }));
          }
        });
        db.ref('config').on('value', (snapshot: any) => {
          const val = snapshot.val();
          if (val) {
            if(val.appName) setAppNameState(val.appName);
            if(val.customLogo !== undefined) setCustomLogoState(val.customLogo);
            if(val.supervisorPassword) setSupervisorPasswordState(val.supervisorPassword);
            if(val.immunizationPassword) setImmunizationPasswordState(val.immunizationPassword);
          }
        });
        setFirebaseConnectionStatus('connected');
      }).catch(() => setFirebaseConnectionStatus('error'));
  }, [firebaseConfigState]);

  const writeData = (path: string, value: any) => {
    const db = getDb();
    if (db) db.ref(path).set(value);

    const parts = path.split('/');
    setData(prev => {
        if (parts[0] === 'data') {
            if (parts.length === 1) return { ...prev, ...value };
            const collection = parts[1] as keyof typeof data;

            if (parts.length === 3) {
                const itemId = Number(parts[2]);
                const list = [...(prev[collection] as any[])];
                if (value === null) {
                    return { ...prev, [collection]: list.filter(i => Number(i.id) !== itemId) };
                }
                const index = list.findIndex(i => Number(i.id) === itemId);
                const newItem = { ...value, id: itemId };
                if (index > -1) {
                    list[index] = newItem;
                } else {
                    list.push(newItem);
                }
                return { ...prev, [collection]: deduplicateById(list) };
            } 
            else if (parts.length === 2 && value === null) {
                return { ...prev, [collection]: collection === 'users' ? INITIAL_USERS : [] };
            }
            else if (parts.length === 2 && typeof value === 'object' && value !== null) {
                return { ...prev, [collection]: deduplicateById(Object.values(value).map((v: any) => ({...v, id: Number(v.id)}))) };
            }
        }
        return prev;
    });
  };

  const addReport = (rep: any) => {
      const newId = Date.now() + Math.floor(Math.random() * 1000);
