/**
 * Smartly parses a string to extract Firebase configuration.
 * It handles JSON strings, JavaScript object literals, and "const firebaseConfig = ..." snippets.
 */
export const parseFirebaseConfigString = (input: string): any => {
    if (!input || !input.trim()) return null;

    // 1. Try JSON.parse first (fastest)
    try {
        return JSON.parse(input);
    } catch (e) {
        // If JSON fails, proceed to Regex extraction
    }

    const config: any = {};
    const keys = [
        'apiKey', 
        'authDomain', 
        'databaseURL', 
        'projectId', 
        'storageBucket', 
        'messagingSenderId', 
        'appId', 
        'measurementId'
    ];

    // Regex looks for: key + optional colon + quotes + value + quotes
    // Handles: apiKey: "value", "apiKey": "value", apiKey = "value"
    let foundAny = false;
    keys.forEach(key => {
        // Matches: key followed by optional quotes/spaces/colon/equals, capturing the value inside quotes
        const regex = new RegExp(`${key}["']?\\s*[:=]\\s*["']([^"']+)["']`);
        const match = input.match(regex);
        if (match && match[1]) {
            config[key] = match[1];
            foundAny = true;
        }
    });

    if (foundAny && config.apiKey) {
        return config;
    }

    throw new Error("Could not extract valid Firebase configuration.");
};

export const initializeFirebase = async (firebaseConfig: any) => { 
  if (typeof firebase === 'undefined') {
      console.warn("Firebase SDK not loaded.");
      throw new Error("Firebase SDK not loaded. Check internet connection.");
  }

  if (!firebaseConfig || !firebaseConfig.apiKey) {
      throw new Error("Firebase configuration incomplete.");
  }

  try {
    // Check if any app is already initialized
    if (firebase.apps && firebase.apps.length > 0) {
      const existingApp = firebase.app(); // Get the default app

      // Check if the existing app has the same config (simplified check via apiKey)
      if (existingApp.options.apiKey !== firebaseConfig.apiKey) {
          await existingApp.delete(); // Delete if config is different
          app = firebase.initializeApp(firebaseConfig);
      } else {
          app = existingApp;
      }
    } else {
      app = firebase.initializeApp(firebaseConfig);
    }

    // Use app-specific database instance
    db = app.database();

    // Initialize Auth and sign in anonymously if available
    // We use app.auth() to ensure it's tied to the specific app instance
    if (firebase.auth) {
        auth = app.auth();
        try {
            await auth.signInAnonymously();
            console.log("Signed in anonymously");
        } catch (authError: any) {
            // Log but don't throw. 
            // 'auth/configuration-not-found' means Auth isn't enabled in console. 
            // App should still try to work (e.g. if Rules are public).
            console.warn("Anonymous auth warning:", authError.code || authError.message);
        }
    } else {
        console.warn("Firebase Auth SDK not loaded.");
    }

    return { db, app, auth };

  } catch (error) {
    console.error("Firebase initialization error:", error);
    throw error;
  }
};

export const getDb = () => {
  // Return the db instance if it exists, or try to get it from the default app
  if (!db && firebase.apps.length > 0) {
      db = firebase.app().database();
  }
  return db;
};

export const disconnectFirebase = async () => {
    if (app) {
        try {
            await app.delete();
            db = null;
            app = null;
            auth = null;
        } catch(e) {
            console.error("Error disconnecting:", e);
        }
    }
};

