                        <h4 className="text-lg font-semibold text-indigo-900 mb-2 dark:text-indigo-200">Distribute a Copy (Single HTML File)</h4>
                        <p className="text-sm text-indigo-700 mb-6 dark:text-indigo-300">Download a single self-contained HTML file that works immediately.</p>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-4">
                                <p className="font-bold text-indigo-800 dark:text-indigo-300 border-b border-indigo-100 pb-2">Blank Version (New App)</p>
                                <div className="flex flex-col gap-3">
                                    <button onClick={handleDownloadDistributableEmpty} className="w-full px-4 py-3 bg-white text-indigo-700 border border-indigo-300 rounded-xl hover:bg-indigo-50 transition-all font-bold shadow-sm flex items-center justify-center gap-2">
                                        ⬇️ Download .html File
                                    </button>
                                    <button onClick={() => handleCopyHtml('empty')} className={`w-full px-4 py-3 border rounded-xl transition-all font-bold flex items-center justify-center gap-2 ${copyState === 'empty' ? 'bg-green-600 text-white border-green-700 shadow-md' : 'bg-indigo-600 text-white border-indigo-700 hover:bg-indigo-700 shadow-sm'}`}>
