      title: string;
      message: string;
      onConfirm: () => Promise<void>; 
    }>({ isOpen: false, title: '', message: '', onConfirm: async () => {} });

    const [isProcessing, setIsProcessing] = useState(false); 
    const [copyState, setCopyState] = useState<'idle' | 'empty' | 'connected'>('idle');

    const { 
        customLogo, setCustomLogo, deleteAllReports, deleteAllData, loadMockData,
