    const handleResetAppName = () => {
        confirmAction('Confirm Resetting Program Name', 'Are you sure you want to reset the program name to its default?',
            async () => { 
                setAppName(DEFAULT_APP_NAME);
                setMessage({ type: 'success', text: 'Default program name has been restored.' });
            }
        );
    };

    const handleSaveFirebaseConfig = () => {
        if (!setFirebaseConfig) return;
        try {
            // Using smart parser
            const parsedConfig = parseFirebaseConfigString(firebaseConfigInput);

            if (!parsedConfig || !parsedConfig.apiKey || !parsedConfig.databaseURL) {
                setMessage({ type: 'error', text: 'Could not extract valid Firebase config. Please paste the full code snippet.' });
