const fetchFileContent = async (path: string): Promise<string> => {
    try {
        const response = await fetch(path);
        if (!response.ok) return '';
        return await response.text();
    } catch (e) {
        return '';
    }
};

export const getDistributableHtmlString = async (
    appData: FullBackupData,
    exportType: 'empty' | 'snapshot'
): Promise<string> => {
    // 1. جلب هيكل الصفحة الحالي
    let htmlString = document.documentElement.outerHTML;

    // 2. تنظيف الصفحة من السكربتات المدمجة سابقاً ومن مخلفات التطوير بأسلوب أكثر شمولاً
    htmlString = htmlString.replace(/<script type="text\/javascript">window\.(compressedEmbeddedAppData|embeddedAppData|bundledFiles|__IS_DISTRIBUTED__)\s*=\s*.*?;\s*<\/script>/gs, '');
    htmlString = htmlString.replace(/<script src="\/@react-refresh".*?><\/script>/g, '');
    htmlString = htmlString.replace(/<script type="module" src="\/@vite\/client"><\/script>/g, '');
    htmlString = htmlString.replace(/<div id="react-error-overlay">.*?<\/div>/g, '');

    // NEW: Clean content of root div to ensure fresh render and smaller file size
    htmlString = htmlString.replace(/<div id="root">[\s\S]*?<\/div>/, '<div id="root"></div>');

    // 3. تجهيز بيانات التطبيق بدقة بناءً على النوع المطلوب
    let appDataForEmbedding: FullBackupData;
    if (exportType === 'empty') {
      appDataForEmbedding = {
        users: INITIAL_USERS, 
        reports: [], 
        students: [], 
        halaqas: [], 
        evaluations: [],
        customLogo: null, 
        supervisorPassword: '123', 
        immunizationPassword: '12345',
        appName: appData.appName || "EPI Manager", 
        isDistributable: true, 
        isPublishedConnected: false, 
        firebaseConfig: null,
      };
    } else {
      appDataForEmbedding = { 
          ...appData, 
          isDistributable: true, 
          isPublishedConnected: true 
      };
    }

    // 4. ضغط البيانات ودمجها كـ Base64
    const jsonDataString = JSON.stringify(appDataForEmbedding);
    const zip = new JSZip();
    zip.file("data.json", jsonDataString);
    const compressedBytes = await zip.generateAsync({ 
        type: "uint8array", 
        compression: "DEFLATE", 
        compressionOptions: { level: 9 } 
    });
    const encodedCompressedData = bytesToBase64(compressedBytes);

    // Inject flag + data
    const dataScript = `
    <script type="text/javascript">
      window.__IS_DISTRIBUTED__ = true;
      window.compressedEmbeddedAppData = '${encodedCompressedData}';
    </script>`;

    // 5. جمع كافة ملفات المصدر (TSX/TS) وتشفيرها لمنع تداخلها مع المتصفح
    let bundledModulesHtml = '';
    for (const path of SOURCE_FILES) {
        const content = await fetchFileContent(path);
        if (content) {
            bundledModulesHtml += `<script type="text/babel" data-type="module" data-path="${path}">\n${escapeScriptTags(content)}\n</script>\n`;
        }
    }

    // 6. حقن البيانات والسكربتات قبل نهاية وسم الجسم
    const bodyEnd = '</body>';
    const injection = `\n${dataScript}\n${bundledModulesHtml}\n`;

    if (htmlString.includes(bodyEnd)) {
        htmlString = htmlString.replace(bodyEnd, `${injection}${bodyEnd}`);
    } else {
        htmlString += injection;
    }

    // 7. تحديث عنوان الصفحة
    if (appDataForEmbedding.appName) {
        htmlString = htmlString.replace(/<title>.*?<\/title>/, `<title>${appDataForEmbedding.appName}</title>`);
    }

    // 8. استبدال نقطة الدخول (Entry Point) بمحمل Babel (esm.sh/run)
    htmlString = htmlString.replace(
        /<script type="module" src="index.tsx"><\/script>/,
        `<script type="module" src="https://esm.sh/run"></script>`
    );

    return htmlString;
};

export const generateAndDownloadDistributableHtml = async (appData: FullBackupData, exportType: 'empty' | 'snapshot') => {
    try {
        const html = await getDistributableHtmlString(appData, exportType);

        const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        const fileName = `${appData.appName || 'EPI'}_${exportType === 'empty' ? 'Setup' : 'Snapshot'}.html`.replace(/\s+/g, '_');
        a.download = fileName;

        document.body.appendChild(a);
        a.click();

        setTimeout(() => {
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
        }, 100);

        return true;
    } catch (e: any) { 
        console.error("HTML Generation Error:", e);
        alert("Error generating Single HTML file: " + e.message);
        return false;
    }
};

