    const handleExportPopulationAndInstitutions = () => {
        const institutions = users.filter(u => u.role === UserRole.INSTITUTION);

        // 1. Institutions Sheet
        const instRows = institutions.map(i => ({
            id: i.id,
            willayat: i.state || '',
            'name of Institution': i.name
        }));

        // 2. Population Sheet
        const popRows: any[] = [];
        institutions.forEach(inst => {
            const populations = inst.population || {};
            const years = Object.keys(populations).map(Number).sort((a,b) => a-b);

            if (years.length > 0) {
                years.forEach(y => {
                    popRows.push({
                        InstitutionId: inst.id,
                        year: y,
                        population: populations[y]
                    });
                });
            } else {
                popRows.push({
                    InstitutionId: inst.id,
                    year: new Date().getFullYear(),
                    population: 0
                });
            }
        });

        const wb = XLSX.utils.book_new();
        const wsInst = XLSX.utils.json_to_sheet(instRows);
        const wsPop = XLSX.utils.json_to_sheet(popRows);

        XLSX.utils.book_append_sheet(wb, wsInst, 'Institutions');
        XLSX.utils.book_append_sheet(wb, wsPop, 'Population');

        XLSX.writeFile(wb, `Institutions_and_Population_Data.xlsx`);
        setMessage({ type: 'success', text: '✅ Institutions and population sheets have been exported.' });
    };

