    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        confirmAction('Confirm Institution Import', 'This will add or update institutions. Name and Wilayat are mandatory. Population data is optional. Continue?',
            async () => { 
                const reader = new FileReader();
                reader.onload = (event) => {
                    try {
                        const data = event.target?.result;
                        const workbook = XLSX.read(data, { type: 'array' });

                        const instSheet = workbook.Sheets['Institutions'] || workbook.Sheets[workbook.SheetNames[0]];
                        const popSheet = workbook.Sheets['Population'];

                        const instJson = XLSX.utils.sheet_to_json(instSheet);
                        const popJson = popSheet ? XLSX.utils.sheet_to_json(popSheet) : [];

                        const excelDataMap = new Map<string, { state?: string, id?: number, populations: Record<number, number> }>();

                        instJson.forEach((row: any) => {
                            const name = (row['name of Institution'] || row['Institution'] || row['Name'])?.toString().trim();
                            const id = row['id'] ? Number(row['id']) : undefined;
                            const willayat = (row['willayat'] || row['State'])?.toString().trim();

                            if (name) {
                                if (!excelDataMap.has(name)) {
                                    excelDataMap.set(name, { state: willayat, id, populations: {} });
                                }
                            }
                        });

                        popJson.forEach((row: any) => {
                            const instId = Number(row['InstitutionId'] || row['institutionId'] || row['id']);
                            const year = Number(row['year'] || row['Year']);
                            const population = Number(row['population'] || row['Population']);

                            if (!isNaN(instId) && !isNaN(year) && !isNaN(population)) {
                                for (let [name, entry] of excelDataMap.entries()) {
                                    if (entry.id === instId) {
                                        entry.populations[year] = population;
                                    }
                                }
                            }
                        });

                        let addedCount = 0;
                        let updatedCount = 0;

                        excelDataMap.forEach((val, name) => {
                            let existingInst;
                            if (val.id) {
                                existingInst = users.find(u => u.id === val.id);
                            } else {
                                existingInst = users.find(u => u.role === UserRole.INSTITUTION && u.name === name);
                            }

                            if (existingInst) {
                                const mergedPopulations = { ...(existingInst.population || {}), ...val.populations };
                                updateInstitution({ 
                                    ...existingInst, 
                                    state: val.state || existingInst.state,
                                    population: mergedPopulations,
                                    updatedAt: Date.now() 
                                });
                                updatedCount++;
                            } else {
                                // حتى لو بيانات السكان خالية، نقوم بإضافة المؤسسة
                                addInstitution(name, val.state, val.populations);
                                addedCount++;
                            }
                        });

                        setMessage({ type: 'success', text: `✅ Added ${addedCount}, 🔄 Updated ${updatedCount} institutions.` });

                    } catch (error) {
                        console.error(error);
                        setMessage({ type: 'error', text: 'Error reading Excel file. Ensure it follows the required format.' });
                    }
                };
                reader.readAsArrayBuffer(file);
            }
        );
        e.target.value = '';
    };

