  });

  // Start with NULL to avoid auto-connecting in blank downloaded versions
  const [firebaseConfigState, setFirebaseConfigState] = useState<any>(null);
  const [firebaseConnectionStatus, setFirebaseConnectionStatus] = useState<'connected' | 'disconnected' | 'error' | 'connecting' | 'restricted'>('disconnected');
