                        <button type="button" onClick={handleExportExcel} disabled={!activeInstitutionId && allowInstitutionSelection} className="bg-blue-600 text-white px-5 py-3 rounded shadow-md hover:bg-blue-700 flex-1 sm:flex-none disabled:bg-gray-400 disabled:cursor-not-allowed">Excel</button>
                        <button type="button" onClick={handlePrint} disabled={!activeInstitutionId && allowInstitutionSelection} className="bg-gray-700 text-white px-5 py-3 rounded shadow-md hover:bg-gray-800 flex-1 sm:flex-none disabled:bg-gray-400 disabled:cursor-not-allowed">PDF (2 Pages)</button>
                    </div>
                </div>
            </footer>
        </div>
    );
};

