                                    </div>
                                    <div className={`flex items-center gap-2 border border-black dark:border-gray-600 p-2 transition-colors ${!formData.recorder_name && isNavigationBlocked ? 'bg-red-50 dark:bg-red-900/50 border-red-500 dark:border-red-600' : 'bg-amber-50 dark:bg-amber-900/20'}`}>
