                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Left country</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_left_country" value={formData.children_left_country || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={4} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 text-left text-base">TARGET POPULATION</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="target_population" value={formData.target_population || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={5} data-local-col={0} readOnly={true} className="bg-gray-200 dark:bg-gray-700 font-bold text-black dark:text-white pointer-events-none" /></TdCell></tr>
                                            {vaccineRows.map((row, index) => ( <tr key={row.name}><TdCell colSpan={2} className="text-left p-1 bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">{row.label}</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={row.name} value={formData[row.name] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={6 + index} data-local-col={0} /></TdCell></tr> ))}
                                            <tr><TdCell rowSpan={3} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 text-left align-middle text-base">Defaulters</TdCell><TdCell className="text-left bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">Incorrect address</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="defaulter_incorrect_address" value={formData.defaulter_incorrect_address || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={17} data-local-col={0} /></TdCell></tr>
