                                            <tr><TdCell className="text-left bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">Refused</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="defaulter_refused" value={formData.defaulter_refused || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={19} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 p-1 text-left text-base">TARGET POPULATION fully immunized</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="tp_fully_immunized" value={formData.tp_fully_immunized || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={20} data-local-col={0} /></TdCell></tr>
