                                                            {availableInstitutions.length === 0 && ( <div className="p-2 text-gray-500 dark:text-gray-400 text-center text-sm">لم يتم العثور على نتائج</div> )}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        ) : ( <input type="text" value={activeInstitution?.name || ''} readOnly className="w-full text-center bg-gray-200 dark:bg-gray-700 text-lg font-bold p-1 dark:text-gray-200" /> )}
                                    </div>
                                    <div className={`flex items-center gap-2 border border-black dark:border-gray-600 p-2 transition-colors ${!formData.recorder_name && isNavigationBlocked ? 'bg-red-50 dark:bg-red-900/50 border-red-500 dark:border-red-600' : 'bg-amber-50 dark:bg-amber-900/20'}`}>
