                                        <FormInput type="text" name="recorder_name" value={formData.recorder_name || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={0} data-local-col={0} placeholder={!formData.recorder_name && isNavigationBlocked ? "مطلوب للحفظ" : ""} className={!formData.recorder_name && isNavigationBlocked ? "bg-red-50 placeholder-red-400 font-bold" : ""} />
                                    </div>
                                    <p className="text-[10px] p-2 border border-black dark:border-gray-600 text-left print-tiny-text dark:text-gray-300">{textFields.assessment}</p>
                                    <p className="text-[10px] p-2 border border-black dark:border-gray-600 text-left print-tiny-text dark:text-gray-300">{textFields.coverage}</p>
                                    <table className="w-full border-collapse border border-black dark:border-gray-600 bg-amber-50 dark:bg-amber-900/20">
                                        <tbody>
                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Target month</TdCell><TdCell className="bg-white dark:bg-gray-800"><input value={targetMonth} readOnly className="w-full text-center bg-gray-200 dark:bg-gray-700 text-lg font-bold p-1 dark:text-gray-200" /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Total on Register</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="total_on_register" value={formData.total_on_register || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={1} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Children who have died</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_died" value={formData.children_died || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={2} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Transferred out</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_transferred" value={formData.children_transferred || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={3} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="font-bold text-black dark:text-gray-200 bg-amber-100 dark:bg-amber-900/40 text-left text-base">Left country</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="children_left_country" value={formData.children_left_country || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={4} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell colSpan={2} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 text-left text-base">TARGET POPULATION</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="target_population" value={formData.target_population || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={5} data-local-col={0} readOnly={true} className="bg-gray-200 dark:bg-gray-700 font-bold text-black dark:text-white pointer-events-none" /></TdCell></tr>
                                            {vaccineRows.map((row, index) => ( <tr key={row.name}><TdCell colSpan={2} className="text-left p-1 bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">{row.label}</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name={row.name} value={formData[row.name] || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={6 + index} data-local-col={0} /></TdCell></tr> ))}
                                            <tr><TdCell rowSpan={3} className="bg-amber-200 dark:bg-amber-800/50 font-bold text-black dark:text-gray-200 text-left align-middle text-base">Defaulters</TdCell><TdCell className="text-left bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">Incorrect address</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="defaulter_incorrect_address" value={formData.defaulter_incorrect_address || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={17} data-local-col={0} /></TdCell></tr>
                                            <tr><TdCell className="text-left bg-amber-100 dark:bg-amber-900/40 font-bold text-black dark:text-gray-200 text-base">Not found</TdCell><TdCell className="bg-white dark:bg-gray-800"><FormInput type="number" name="defaulter_not_found" value={formData.defaulter_not_found || ''} onChange={handleInputChange} onKeyDown={handleInputKeyDown} data-local-row={18} data-local-col={0} /></TdCell></tr>
