                                                            <span className="text-lg">{group.monthKey}: {group.items.join(', ')}</span>
                                                            <div className="flex items-center gap-2 bg-white/80 dark:bg-black/30 p-2 rounded-lg no-print shadow-sm border border-gray-300">
                                                                <span className="text-[11px] font-black uppercase text-green-800 dark:text-green-400">Target Month:</span>
                                                                <div className="flex gap-2">
                                                                    <select 
                                                                        name={`${group.monthKey}_target_month`} 
                                                                        value={formData[`${group.monthKey}_target_month`] || ''} 
