                    </div>
                </div>

                <div ref={formRef} className="bg-white dark:bg-gray-900 p-4 shadow-sm min-w-[800px]">
                    <div id="page-1-content" style={{ display: activeTab === 1 ? 'block' : 'none' }}>
                        <div id="page-1-grid-container" className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <div className="flex flex-col gap-6" data-major-col="left">
                                <div className="space-y-4">
                                    <div className="flex items-center gap-2 bg-amber-50 dark:bg-amber-900/20 border border-black dark:border-gray-600 p-2 relative">
                                        <label className="font-bold whitespace-nowrap text-base dark:text-gray-200">Name of Institution:</label>
                                        {allowInstitutionSelection ? (
                                            <div className="relative w-full">
                                                <div className="w-full border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 p-2 rounded cursor-pointer flex justify-between items-center" onClick={() => setIsDropdownOpen(!isDropdownOpen)}>
                                                    <span className={`truncate text-lg font-bold ${!activeInstitution ? 'text-gray-400' : 'text-gray-900 dark:text-gray-100'}`}>{activeInstitution?.name || 'Select Institution...'}</span>
                                                    <svg className="w-4 h-4 ml-2 dark:text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                                                </div>
                                                {isDropdownOpen && (
                                                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-900 border border-gray-300 dark:border-gray-700 shadow-lg max-h-60 rounded overflow-hidden flex flex-col">
                                                        <input type="text" placeholder="Search..." value={instSearchTerm} onChange={(e) => setInstSearchTerm(e.target.value)} className="p-2 border-b border-gray-200 dark:border-gray-700 outline-none w-full text-base dark:bg-gray-800 dark:text-gray-200" autoFocus />
                                                        <div className="overflow-y-auto flex-1">
