                        <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))} className="input-style w-24 py-1 text-base font-bold">{[2023, 2024, 2025, 2026, 2027, 2028].map(y => <option key={y} value={y}>{y}</option>)}</select>
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 bg-gray-50 dark:bg-gray-800 overflow-x-auto">
                <div className="flex justify-center mb-6">
                    <div className="bg-white dark:bg-gray-700 rounded-lg shadow p-1 flex">
                        <button onClick={() => setActiveTab(1)} className={`px-6 py-2 rounded-md font-semibold transition-colors ${activeTab === 1 ? 'bg-blue-600 text-white' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-600'}`}>Page 1</button>
                        <button onClick={() => setActiveTab(2)} className={`px-6 py-2 rounded-md font-semibold transition-colors ${activeTab === 2 ? 'bg-blue-600 text-white' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-600'}`}>Page 2</button>
                    </div>
                </div>

                <div ref={formRef} className="bg-white dark:bg-gray-900 p-4 shadow-sm min-w-[800px]">
                    <div id="page-1-content" style={{ display: activeTab === 1 ? 'block' : 'none' }}>
                        <div id="page-1-grid-container" className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <div className="flex flex-col gap-6" data-major-col="left">
                                <div className="space-y-4">
                                    <div className="flex items-center gap-2 bg-amber-50 dark:bg-amber-900/20 border border-black dark:border-gray-600 p-2 relative">
                                        <label className="font-bold whitespace-nowrap text-base dark:text-gray-200">Name of Institution:</label>
